/**
 * Security Test Examples for app.js
 * These tests demonstrate common security vulnerabilities and how to test for them
 * 
 * Usage: jest security_test_examples.js
 */

const request = require('supertest');
const jwt = require('jsonwebtoken');

// Mock app - replace with actual app import
// const app = require('./app_secure');

describe('Security Tests for Express App', () => {

  const JWT_SECRET = 'test-secret';

  // Helper to generate valid JWT
  const generateToken = (payload = {}) => {
    return jwt.sign({
      id: 1,
      role: 'user',
      ...payload
    }, JWT_SECRET, { expiresIn: '1h' });
  };

  describe('Authentication & Authorization', () => {

    test('Should reject unauthenticated requests to protected endpoints', async () => {
      // Missing authorization header
      const res = await request(app)
        .get('/users')
        .expect(401);

      expect(res.body).toHaveProperty('error');
      expect(res.body.code).toBe('NO_TOKEN');
    });

    test('Should reject malformed authorization headers', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', 'InvalidFormat token123')
        .expect(401);

      expect(res.body.code).toBe('INVALID_FORMAT');
    });

    test('Should reject expired tokens', async () => {
      const expiredToken = jwt.sign(
        { id: 1, role: 'user' },
        JWT_SECRET,
        { expiresIn: '-1h' } // Expired
      );

      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${expiredToken}`)
        .expect(401);

      expect(res.body.code).toBe('TOKEN_EXPIRED');
    });

    test('Should reject invalid tokens', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer invalid.token.here')
        .expect(403);

      expect(res.body.code).toBe('INVALID_TOKEN');
    });

    test('Should accept valid authentication token', async () => {
      const token = generateToken({ id: 1, role: 'user' });

      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      expect(Array.isArray(res.body)).toBe(true);
    });
  });

  describe('Input Validation & Injection Prevention', () => {

    test('Should handle XSS attempts in query parameters', async () => {
      const token = generateToken();

      const res = await request(app)
        .get('/users?name=<script>alert("xss")</script>')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      // Should not contain unescaped script tags
      expect(JSON.stringify(res.body)).not.toContain('<script>');
    });

    test('Should reject overly large payloads', async () => {
      const token = generateToken();
      const largePayload = 'x'.repeat(11000); // Exceeds 10kb limit

      const res = await request(app)
        .post('/users')
        .set('Authorization', `Bearer ${token}`)
        .send({ data: largePayload })
        .expect(413); // Payload Too Large
    });

    test('Should sanitize MongoDB injection attempts', async () => {
      const token = generateToken();

      const res = await request(app)
        .get('/users?filter={"$gt":""}')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      // Should safely handle the input
      expect(res.status).toBeLessThan(500);
    });
  });

  describe('Rate Limiting', () => {

    test('Should enforce rate limiting on protected endpoints', async () => {
      const token = generateToken();

      // Make multiple requests
      for (let i = 0; i < 101; i++) {
        const res = await request(app)
          .get('/users')
          .set('Authorization', `Bearer ${token}`);

        // After 100 requests, should get 429
        if (i >= 100) {
          expect(res.status).toBe(429);
        }
      }
    });

    test('Should return rate limit info in headers', async () => {
      const token = generateToken();

      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      expect(res.headers).toHaveProperty('ratelimit-limit');
      expect(res.headers).toHaveProperty('ratelimit-remaining');
    });
  });

  describe('Security Headers', () => {

    test('Should include Content-Security-Policy header', async () => {
      const res = await request(app)
        .get('/health')
        .expect(200);

      expect(res.headers).toHaveProperty('content-security-policy');
      expect(res.headers['content-security-policy']).toContain("default-src 'self'");
    });

    test('Should include X-Content-Type-Options header', async () => {
      const res = await request(app)
        .get('/health')
        .expect(200);

      expect(res.headers['x-content-type-options']).toBe('nosniff');
    });

    test('Should include X-Frame-Options header', async () => {
      const res = await request(app)
        .get('/health')
        .expect(200);

      expect(res.headers['x-frame-options']).toBe('DENY');
    });

    test('Should include Strict-Transport-Security header', async () => {
      const res = await request(app)
        .get('/health')
        .expect(200);

      expect(res.headers).toHaveProperty('strict-transport-security');
      expect(res.headers['strict-transport-security']).toContain('31536000');
    });

    test('Should not expose X-Powered-By header', async () => {
      const res = await request(app)
        .get('/health')
        .expect(200);

      expect(res.headers['x-powered-by']).toBeUndefined();
    });
  });

  describe('CORS Configuration', () => {

    test('Should allow requests from configured origins', async () => {
      const res = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000')
        .expect(200);

      expect(res.headers['access-control-allow-origin']).toBe('http://localhost:3000');
    });

    test('Should reject requests from unauthorized origins', async () => {
      const res = await request(app)
        .get('/health')
        .set('Origin', 'http://malicious-site.com')
        .expect(200); // Request succeeds but CORS header not added

      expect(res.headers['access-control-allow-origin']).toBeUndefined();
    });

    test('Should not allow credentials from disallowed origins', async () => {
      const res = await request(app)
        .get('/health')
        .set('Origin', 'http://malicious-site.com')
        .set('Cookie', 'sessionid=abc123');

      // Should not set Access-Control-Allow-Credentials
      expect(res.headers['access-control-allow-credentials']).not.toBe('true');
    });
  });

  describe('Sensitive Data Exposure', () => {

    test('Should not expose email to non-admin users', async () => {
      const token = generateToken({ role: 'user' });

      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      expect(res.body[0]).not.toHaveProperty('email');
    });

    test('Should expose email only to admin users', async () => {
      const token = generateToken({ role: 'admin' });

      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`)
        .expect(200);

      expect(res.body[0]).toHaveProperty('email');
    });

    test('Should not expose sensitive error details in production', async () => {
      // This would need NODE_ENV=production
      const res = await request(app)
        .get('/invalid-endpoint')
        .expect(404);

      // In production, shouldn't have stack trace
      if (process.env.NODE_ENV === 'production') {
        expect(res.body).not.toHaveProperty('stack');
      }
    });
  });

  describe('Error Handling', () => {

    test('Should handle 404 errors gracefully', async () => {
      const res = await request(app)
        .get('/nonexistent')
        .expect(404);

      expect(res.body).toHaveProperty('error');
      expect(res.body.error).toBe('Endpoint not found');
    });

    test('Should not expose stack traces for 500 errors', async () => {
      // Assuming you have an error-triggering endpoint in tests
      const res = await request(app)
        .get('/error-trigger')
        .expect(500);

      if (process.env.NODE_ENV === 'production') {
        expect(res.body).not.toHaveProperty('stack');
      }
    });
  });

  describe('HTTP Methods Security', () => {

    test('Should not allow inappropriate HTTP methods', async () => {
      const token = generateToken();

      const res = await request(app)
        .delete('/health')
        .set('Authorization', `Bearer ${token}`);

      // Should return 405 or 404
      expect([404, 405]).toContain(res.status);
    });
  });

  describe('Information Disclosure', () => {

    test('Should not expose internal server information', async () => {
      const res = await request(app)
        .get('/health')
        .expect(200);

      expect(res.headers['server']).toBeUndefined();
      expect(res.headers['x-powered-by']).toBeUndefined();
    });

    test('Should not expose timestamp in health endpoint', async () => {
      const res = await request(app)
        .get('/health')
        .expect(200);

      // Timestamp should not be exposed (could aid in timing attacks)
      expect(res.body.timestamp).toBeUndefined();
    });
  });
});
