// Secure version of app.js with security best practices implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const winston = require('winston');
require('dotenv').config();

const app = express();

// ==================== CONFIGURATION ====================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key-change-in-production';

// Validate critical environment variables in production
if (NODE_ENV === 'production' && !process.env.JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is required in production');
}

// ==================== LOGGING SETUP ====================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5,
    }),
  ],
});

// Add console transport in development
if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ==================== SECURITY MIDDLEWARE ====================

// 1. Helmet - Set security HTTP headers
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
    frameSrc: ["'none'"],
  },
}));
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true,
}));
app.use(helmet.referrerPolicy({ policy: 'strict-origin-when-cross-origin' }));
app.use(helmet.noSniff());

// 2. CORS Configuration - Only allow specified origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',')
    : NODE_ENV === 'production' 
      ? ['https://yourdomain.com'] 
      : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};
app.use(cors(corsOptions));

// 3. Body Parser with size limits - Prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Rate Limiting - Prevent brute force and DoS attacks
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn({
      event: 'rate_limit_exceeded',
      ip: req.ip,
      url: req.url,
    });
    res.status(429).json({ error: 'Too many requests' });
  },
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many failed requests, please try again later.',
});

app.use(generalLimiter);

// ==================== REQUEST LOGGING ====================
app.use((req, res, next) => {
  // Don't log sensitive paths
  if (!['/health'].includes(req.path)) {
    logger.info({
      method: req.method,
      url: req.path,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      timestamp: new Date().toISOString(),
    });
  }
  next();
});

// ==================== AUTHENTICATION MIDDLEWARE ====================
const authMiddleware = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader) {
      logger.warn({
        event: 'missing_auth_token',
        ip: req.ip,
        url: req.url,
      });
      return res.status(401).json({ 
        error: 'Missing authentication token',
        code: 'NO_TOKEN'
      });
    }

    const parts = authHeader.split(' ');
    if (parts.length !== 2 || parts[0] !== 'Bearer') {
      return res.status(401).json({ 
        error: 'Invalid token format',
        code: 'INVALID_FORMAT'
      });
    }

    const token = parts[1];
    const decoded = jwt.verify(token, JWT_SECRET);

    // Attach user info to request
    req.user = decoded;
    next();
  } catch (err) {
    logger.warn({
      event: 'invalid_token',
      error: err.message,
      ip: req.ip,
      url: req.url,
    });

    const status = err.name === 'TokenExpiredError' ? 401 : 403;
    const code = err.name === 'TokenExpiredError' ? 'TOKEN_EXPIRED' : 'INVALID_TOKEN';

    return res.status(status).json({ 
      error: err.message,
      code
    });
  }
};

// ==================== PUBLIC ROUTES ====================

/**
 * Health check endpoint
 * GET /health
 * Public endpoint - No authentication required
 * Returns: { status: 'ok', environment: string }
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok',
    environment: NODE_ENV,
  });
});

// ==================== PROTECTED ROUTES ====================

/**
 * Get users endpoint
 * GET /users
 * Protected endpoint - Requires authentication
 * Returns: Array of user objects (sensitive data filtered)
 */
app.get('/users', authMiddleware, (req, res) => {
  try {
    // In a real application, fetch from database
    let users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    // Admin users can see email addresses
    if (req.user.role === 'admin') {
      users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];
    }

    logger.info({
      event: 'users_retrieved',
      userId: req.user.id,
      userRole: req.user.role,
      count: users.length,
    });

    res.json(users);
  } catch (err) {
    logger.error({
      event: 'users_retrieval_error',
      error: err.message,
      userId: req.user.id,
    });

    res.status(500).json({ error: 'Internal server error' });
  }
});

// ==================== 404 HANDLER ====================
app.use((req, res, next) => {
  const error = new Error('Endpoint not found');
  error.status = 404;
  logger.warn({
    event: 'endpoint_not_found',
    method: req.method,
    url: req.url,
    ip: req.ip,
  });
  next(error);
});

// ==================== ERROR HANDLING MIDDLEWARE ====================
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = err.message || 'Internal Server Error';

  // Log error
  logger.error({
    event: 'request_error',
    status,
    message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
  });

  // Prepare response - don't expose stack traces in production
  const response = {
    error: message,
    code: err.code || 'INTERNAL_ERROR',
    ...(NODE_ENV !== 'production' && { stack: err.stack }),
  };

  res.status(status).json(response);
});

// ==================== SERVER STARTUP ====================
const server = app.listen(PORT, () => {
  logger.info({
    event: 'server_started',
    port: PORT,
    environment: NODE_ENV,
    timestamp: new Date().toISOString(),
  });
});

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    event: 'unhandled_rejection',
    reason: reason.message || reason,
    stack: reason.stack,
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

