// Production-ready app with proper secrets management
// Uses AWS Secrets Manager (but pattern works for Azure, GCP, Vault)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const winston = require('winston');

const app = express();

// ==================== SECRETS MANAGEMENT ====================

/**
 * Abstract Secrets Manager Interface
 * Can be implemented with AWS, Azure, GCP, Vault, etc.
 */
class SecretsManager {
  constructor(provider = 'aws') {
    this.provider = provider;
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  /**
   * Get secret with caching
   */
  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    // Fetch from provider
    let value;
    switch (this.provider) {
      case 'aws':
        value = await this.getFromAWS(secretName);
        break;
      case 'azure':
        value = await this.getFromAzure(secretName);
        break;
      case 'gcp':
        value = await this.getFromGCP(secretName);
        break;
      case 'vault':
        value = await this.getFromVault(secretName);
        break;
      default:
        throw new Error(`Unknown secrets provider: ${this.provider}`);
    }

    // Cache the value
    this.cache.set(secretName, {
      value,
      timestamp: Date.now()
    });

    return value;
  }

  /**
   * AWS Secrets Manager Implementation
   */
  async getFromAWS(secretName) {
    try {
      const AWS = require('aws-sdk');
      const secretsManager = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const data = await secretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      return data.SecretString;
    } catch (err) {
      logger.error('AWS Secrets Manager error', {
        secretName,
        error: err.message,
        code: err.code
      });
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Azure Key Vault Implementation
   */
  async getFromAzure(secretName) {
    try {
      const { SecretClient } = require("@azure/keyvault-secrets");
      const { DefaultAzureCredential } = require("@azure/identity");

      const credential = new DefaultAzureCredential();
      const client = new SecretClient(
        `https://${process.env.VAULT_NAME}.vault.azure.net`,
        credential
      );

      const secret = await client.getSecret(secretName);
      return secret.value;
    } catch (err) {
      logger.error('Azure Key Vault error', {
        secretName,
        error: err.message
      });
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Google Cloud Secret Manager Implementation
   */
  async getFromGCP(secretName) {
    try {
      const secretManager = require('@google-cloud/secret-manager');
      const client = new secretManager.SecretManagerServiceClient();

      const projectId = process.env.GCP_PROJECT_ID;
      const name = client.secretVersionPath(projectId, secretName, 'latest');

      const [version] = await client.accessSecretVersion({ name });
      return version.payload.data.toString('utf8');
    } catch (err) {
      logger.error('GCP Secret Manager error', {
        secretName,
        error: err.message
      });
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * HashiCorp Vault Implementation
   */
  async getFromVault(secretName) {
    try {
      const vault = require('node-vault');
      const client = vault({
        endpoint: process.env.VAULT_ADDR || 'https://vault.company.com',
        token: process.env.VAULT_TOKEN
      });

      const secret = await client.read(`secret/data/${secretName}`);
      return secret.data.data;
    } catch (err) {
      logger.error('Vault error', {
        secretName,
        error: err.message
      });
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Force refresh of cached secret
   * (Useful for testing or manual rotation)
   */
  async refreshSecret(secretName) {
    this.cache.delete(secretName);
    return this.getSecret(secretName);
  }

  /**
   * Clear all cached secrets
   */
  clearCache() {
    this.cache.clear();
  }
}

// ==================== CONFIGURATION ====================

const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = process.env.PORT || 3000;

// Initialize logger first (before secrets)
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({
      filename: 'logs/error.log',
      level: 'error',
      maxsize: 5242880,
      maxFiles: 5,
    }),
    new winston.transports.File({
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5,
    }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Initialize secrets manager based on environment
const secretsProvider = process.env.SECRETS_PROVIDER || 'aws';
const secretsManager = new SecretsManager(secretsProvider);

logger.info('Initialized secrets manager', { provider: secretsProvider });

// ==================== SECRETS LOADING ====================

/**
 * Load all required secrets at startup
 * In development: use fallback values
 * In production: REQUIRE secrets from manager
 */
async function loadSecrets() {
  try {
    let secrets = {
      jwtSecret: null,
      allowedOrigins: null,
      logLevel: null,
      databaseUrl: null,
    };

    if (NODE_ENV === 'production') {
      // Production: Load from secrets manager (required)
      logger.info('Loading secrets from manager', { provider: secretsProvider });

      secrets.jwtSecret = await secretsManager.getSecret(
        process.env.SECRET_NAME_JWT || 'prod/jwt-secret'
      );
      secrets.databaseUrl = await secretsManager.getSecret(
        process.env.SECRET_NAME_DB || 'prod/db-password'
      );
      secrets.allowedOrigins = await secretsManager.getSecret(
        process.env.SECRET_NAME_ORIGINS || 'prod/allowed-origins'
      );

      if (!secrets.jwtSecret || !secrets.databaseUrl) {
        throw new Error('Critical secrets not available from manager');
      }

      logger.info('Secrets loaded successfully from manager');
    } else if (NODE_ENV === 'test') {
      // Test: Use test-specific values
      logger.info('Using test secrets');
      secrets.jwtSecret = 'test-jwt-secret-key-12345678';
      secrets.databaseUrl = 'postgresql://test:test@localhost:5432/testdb';
      secrets.allowedOrigins = 'http://localhost:3000,http://localhost:3001';
    } else {
      // Development: Use dotenv with fallbacks
      // .env.local should be in .gitignore
      require('dotenv').config({ path: '.env.local' });

      secrets.jwtSecret = process.env.JWT_SECRET || 'dev-secret-not-real-12345678';
      secrets.databaseUrl = process.env.DATABASE_URL || 'postgresql://dev:dev@localhost:5432/devdb';
      secrets.allowedOrigins = process.env.ALLOWED_ORIGINS || 'http://localhost:3000';

      if (secrets.jwtSecret.startsWith('dev-')) {
        logger.warn('Using development secrets - DO NOT USE IN PRODUCTION');
      }
    }

    return secrets;
  } catch (err) {
    logger.error('Failed to load secrets', {
      error: err.message,
      environment: NODE_ENV
    });
    throw err;
  }
}

// ==================== MIDDLEWARE ====================

app.use(helmet());
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  handler: (req, res) => {
    logger.warn('Rate limit exceeded', { ip: req.ip });
    res.status(429).json({ error: 'Too many requests' });
  },
});
app.use(limiter);

// ==================== AUTHENTICATION ====================

let currentSecrets = null;

/**
 * JWT verification middleware
 * Uses cached secret from secrets manager
 */
const authMiddleware = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader) {
      return res.status(401).json({
        error: 'Missing authentication token',
        code: 'NO_TOKEN'
      });
    }

    const parts = authHeader.split(' ');
    if (parts.length !== 2 || parts[0] !== 'Bearer') {
      return res.status(401).json({
        error: 'Invalid token format',
        code: 'INVALID_FORMAT'
      });
    }

    // Verify using secret from secrets manager
    const token = parts[1];
    const decoded = jwt.verify(token, currentSecrets.jwtSecret);

    req.user = decoded;
    next();
  } catch (err) {
    logger.warn('Authentication error', {
      error: err.message,
      ip: req.ip
    });

    const status = err.name === 'TokenExpiredError' ? 401 : 403;
    res.status(status).json({
      error: err.message,
      code: err.name === 'TokenExpiredError' ? 'TOKEN_EXPIRED' : 'INVALID_TOKEN'
    });
  }
};

// ==================== ROUTES ====================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    environment: NODE_ENV
  });
});

app.get('/users', authMiddleware, (req, res) => {
  try {
    let users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    if (req.user.role === 'admin') {
      users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];
    }

    logger.info('Users retrieved', {
      userId: req.user.id,
      role: req.user.role
    });

    res.json(users);
  } catch (err) {
    logger.error('Error retrieving users', {
      error: err.message
    });
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ==================== ERROR HANDLING ====================

app.use((req, res, next) => {
  const error = new Error('Endpoint not found');
  error.status = 404;
  next(error);
});

app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = err.message || 'Internal Server Error';

  logger.error('Request error', {
    status,
    message,
    url: req.url,
    method: req.method
  });

  res.status(status).json({
    error: message,
    code: err.code || 'INTERNAL_ERROR',
    ...(NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ==================== SERVER STARTUP ====================

async function startServer() {
  try {
    // Load secrets before starting server
    currentSecrets = await loadSecrets();

    // Start server
    const server = app.listen(PORT, () => {
      logger.info('Server started', {
        port: PORT,
        environment: NODE_ENV,
        secretsProvider: secretsProvider
      });
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM received, shutting down gracefully');
      server.close(() => {
        logger.info('Server closed');
        process.exit(0);
      });
    });

    process.on('unhandledRejection', (reason, promise) => {
      logger.error('Unhandled rejection', {
        reason: reason?.message || reason,
        stack: reason?.stack
      });
    });

  } catch (err) {
    logger.error('Failed to start server', {
      error: err.message,
      stack: err.stack
    });
    process.exit(1);
  }
}

// Start the server
if (require.main === module) {
  startServer();
}

module.exports = { app, SecretsManager, loadSecrets };
