/**
 * SECURE SECRETS MANAGEMENT IMPLEMENTATION
 * This file demonstrates proper secret handling for production applications
 */

const express = require('express');
require('dotenv').config();

const app = express();

// ============================================================
// OPTION 1: AWS SECRETS MANAGER (Production Recommended)
// ============================================================

class AWSSecretsManager {
  constructor() {
    this.AWS = require('aws-sdk');
    this.secretsManager = new this.AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    try {
      // Check cache first
      if (this.cache[secretName] && 
          Date.now() - this.cache[secretName].timestamp < this.cacheTTL) {
        console.log(`[Cache HIT] Secret: ${secretName}`);
        return this.cache[secretName].value;
      }

      console.log(`[Cache MISS] Fetching secret: ${secretName}`);

      const data = await this.secretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      let secretValue;
      if (data.SecretString) {
        secretValue = JSON.parse(data.SecretString);
      } else {
        secretValue = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache[secretName] = {
        value: secretValue,
        timestamp: Date.now()
      };

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret "${secretName}":`, error.message);

      // Fail securely - don't expose secrets in error
      throw new Error('Failed to retrieve required configuration');
    }
  }

  invalidateCache(secretName) {
    delete this.cache[secretName];
    console.log(`[Cache INVALIDATED] Secret: ${secretName}`);
  }
}

// ============================================================
// OPTION 2: HASHICORP VAULT
// ============================================================

class VaultSecretsManager {
  constructor() {
    this.vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN
    });
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(path) {
    try {
      if (this.cache[path] && 
          Date.now() - this.cache[path].timestamp < this.cacheTTL) {
        return this.cache[path].value;
      }

      const secret = await this.vault.read(path);
      const secretValue = secret.data.data;

      this.cache[path] = {
        value: secretValue,
        timestamp: Date.now()
      };

      return secretValue;
    } catch (error) {
      console.error(`Vault error for path "${path}":`, error.message);
      throw new Error('Failed to retrieve required configuration');
    }
  }

  invalidateCache(path) {
    delete this.cache[path];
  }
}

// ============================================================
// OPTION 3: AZURE KEY VAULT
// ============================================================

class AzureKeyVaultSecretsManager {
  constructor() {
    this.SecretClient = require('@azure/keyvault-secrets').SecretClient;
    this.DefaultAzureCredential = require('@azure/identity').DefaultAzureCredential;

    const credential = new this.DefaultAzureCredential();
    this.client = new this.SecretClient(
      `https://${process.env.VAULT_NAME}.vault.azure.net/`,
      credential
    );
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    try {
      if (this.cache[secretName] && 
          Date.now() - this.cache[secretName].timestamp < this.cacheTTL) {
        return this.cache[secretName].value;
      }

      const secret = await this.client.getSecret(secretName);
      const secretValue = secret.value;

      this.cache[secretName] = {
        value: secretValue,
        timestamp: Date.now()
      };

      return secretValue;
    } catch (error) {
      console.error(`Key Vault error for secret "${secretName}":`, error.message);
      throw new Error('Failed to retrieve required configuration');
    }
  }

  invalidateCache(secretName) {
    delete this.cache[secretName];
  }
}

// ============================================================
// ENVIRONMENT-AWARE SECRETS MANAGER FACTORY
// ============================================================

class SecretsManagerFactory {
  static create() {
    const environment = process.env.NODE_ENV || 'development';

    if (environment === 'production') {
      const provider = process.env.SECRETS_PROVIDER || 'aws';

      switch (provider.toLowerCase()) {
        case 'aws':
          console.log('Using AWS Secrets Manager');
          return new AWSSecretsManager();
        case 'vault':
          console.log('Using HashiCorp Vault');
          return new VaultSecretsManager();
        case 'azure':
          console.log('Using Azure Key Vault');
          return new AzureKeyVaultSecretsManager();
        default:
          throw new Error(`Unknown secrets provider: ${provider}`);
      }
    } else {
      // Development: Use env file with fallback
      console.log('Using .env file (development mode)');
      return new DevelopmentSecretsManager();
    }
  }
}

// ============================================================
// DEVELOPMENT SECRETS MANAGER (Fallback)
// ============================================================

class DevelopmentSecretsManager {
  constructor() {
    this.secrets = process.env;
  }

  async getSecret(secretName) {
    const value = this.secrets[secretName];

    if (!value) {
      throw new Error(`Secret not found in environment: ${secretName}`);
    }

    console.warn(`⚠️  Using secret from environment: ${secretName} (DEV ONLY)`);
    return value;
  }

  invalidateCache(secretName) {
    // No-op for development
  }
}

// ============================================================
// SECRET CONFIGURATION VALIDATOR
// ============================================================

class SecretsValidator {
  constructor(requiredSecrets) {
    this.required = requiredSecrets;
    this.validated = {};
  }

  async validate(secretsManager) {
    console.log('Validating required secrets...');

    for (const secretName of this.required) {
      try {
        const secret = await secretsManager.getSecret(secretName);

        if (!secret) {
          throw new Error(`Secret "${secretName}" is empty`);
        }

        this.validated[secretName] = '✓ Loaded';
        console.log(`✓ Secret loaded: ${secretName}`);
      } catch (error) {
        console.error(`✗ Failed to load secret: ${secretName}`);
        throw error;
      }
    }

    return true;
  }

  getStatus() {
    return this.validated;
  }
}

// ============================================================
// APPLICATION INITIALIZATION
// ============================================================

let secretsManager;
const requiredSecrets = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'JWT_SECRET'
];

async function initializeApp() {
  try {
    // 1. Create secrets manager based on environment
    secretsManager = SecretsManagerFactory.create();

    // 2. Validate all required secrets are available
    const validator = new SecretsValidator(requiredSecrets);
    await validator.validate(secretsManager);

    console.log('\n✓ All secrets validated and loaded successfully\n');

    // 3. Start the application
    const port = process.env.PORT || 3000;
    app.listen(port, () => {
      console.log(`Server running securely on port ${port}`);
      console.log(`Environment: ${process.env.NODE_ENV}`);
      console.log(`Secrets Provider: ${process.env.SECRETS_PROVIDER || 'aws'}`);
    });

  } catch (error) {
    console.error('❌ Failed to initialize application:', error.message);
    process.exit(1);
  }
}

// ============================================================
// MIDDLEWARE: SECURE SECRET ACCESS
// ============================================================

// Middleware to attach secrets to request context
app.use(async (req, res, next) => {
  try {
    // Load secrets on-demand with caching
    req.secrets = {
      get: async (secretName) => {
        return await secretsManager.getSecret(secretName);
      }
    };
    next();
  } catch (error) {
    res.status(500).json({ error: 'Configuration error' });
  }
});

// ============================================================
// EXAMPLE ROUTES WITH SECURE SECRET ACCESS
// ============================================================

// Protected route that accesses database
app.get('/health', async (req, res) => {
  try {
    // Note: Never log actual secrets!
    console.log('Health check endpoint accessed');
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      secretsLoaded: true
    });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Route that uses a secret (example)
app.post('/process-payment', async (req, res) => {
  try {
    // Get secret safely
    const stripeKey = await req.secrets.get('STRIPE_SECRET_KEY');

    // Use the key (never log it!)
    console.log('Processing payment with Stripe');

    // ... payment processing logic ...

    res.json({ status: 'success' });
  } catch (error) {
    console.error('Payment processing error:', error.message);
    res.status(500).json({ error: 'Payment processing failed' });
  }
});

// ============================================================
// GRACEFUL SHUTDOWN
// ============================================================

process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  // Clear sensitive data
  secretsManager.cache = {};
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  secretsManager.cache = {};
  process.exit(0);
});

// ============================================================
// EXPORT FOR TESTING
// ============================================================

module.exports = {
  app,
  SecretsManagerFactory,
  AWSSecretsManager,
  VaultSecretsManager,
  AzureKeyVaultSecretsManager,
  SecretsValidator,
  initializeApp
};

// Start the application
if (require.main === module) {
  initializeApp();
}

