## STEP 2: Choose and Implement Secrets Manager

### OPTION A: AWS Secrets Manager (Recommended for AWS users)

#### Installation
```bash
npm install aws-sdk
```

#### Implementation
```javascript
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache for secrets (with TTL)
let secretsCache = {};
const CACHE_TTL = 3600000; // 1 hour

async function getSecret(secretName) {
  const now = Date.now();

  // Return cached secret if not expired
  if (secretsCache[secretName] && now - secretsCache[secretName].timestamp < CACHE_TTL) {
    return secretsCache[secretName].value;
  }

  try {
    const response = await secretsManager.getSecretValue({
      SecretId: secretName,
    }).promise();

    let secretValue;
    if ('SecretString' in response) {
      secretValue = JSON.parse(response.SecretString);
    } else {
      secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    // Cache the secret
    secretsCache[secretName] = {
      value: secretValue,
      timestamp: now
    };

    return secretValue;
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error);
    throw error;
  }
}

// Usage in app
async function initializeApp() {
  const dbConfig = await getSecret('prod/database');
  const apiKeys = await getSecret('prod/api-keys');

  const app = express();
  // Initialize with secrets...
  return app;
}

module.exports = { getSecret, initializeApp };
```

#### Setup Secrets in AWS
```bash
# Create database secret
aws secretsmanager create-secret \
  --name prod/database \
  --secret-string '{
    "username": "admin",
    "password": "new-secure-password",
    "host": "db.internal",
    "port": 5432,
    "database": "production"
  }' \
  --region us-east-1

# Create API keys secret
aws secretsmanager create-secret \
  --name prod/api-keys \
  --secret-string '{
    "stripe_key": "sk_live_...",
    "anthropic_key": "sk-ant-...",
    "logfire_token": "..."
  }' \
  --region us-east-1

# List all secrets
aws secretsmanager list-secrets --region us-east-1

# Rotate secret
aws secretsmanager rotate-secret \
  --secret-id prod/database \
  --rotation-rules '{"AutomaticallyAfterDays": 30}' \
  --region us-east-1
```

