  --member=serviceAccount:my-app@project.iam.gserviceaccount.com \
  --role=roles/secretmanager.secretAccessor
```

#### Implementation
```javascript
const secretManager = require('@google-cloud/secret-manager');

const client = new secretManager.SecretManagerServiceClient();

async function getSecret(secretName, projectId = process.env.GCP_PROJECT_ID) {
  const name = client.secretVersionPath(projectId, secretName, 'latest');

  try {
    const [version] = await client.accessSecretVersion({ name });
    const payload = version.payload.data.toString('utf8');
    return JSON.parse(payload);
  } catch (error) {
    console.error(`Failed to retrieve secret: ${secretName}`, error);
    throw error;
  }
}

module.exports = { getSecret };
```

