});
```

**Recommended Fix:**
```javascript
const https = require('https');
const fs = require('fs');

// For production, use proper SSL certificates
const httpsOptions = {
  key: fs.readFileSync('path/to/private-key.pem'),
  cert: fs.readFileSync('path/to/certificate.pem')
};

https.createServer(httpsOptions, app).listen(3000, () => {
  console.log('Server running securely on port 3000');
});
```

---

### 2. **No Security Headers**
**Severity:** HIGH
**Category:** OWASP Top 10 - A01:2021 - Broken Access Control

**Issue:**
Missing critical HTTP security headers that protect against:
- Cross-Site Scripting (XSS)
- Clickjacking attacks
- MIME type sniffing
- Referrer policy leaks

**Recommended Fix:**
```javascript
const helmet = require('helmet');

app.use(helmet()); // Adds security headers automatically

// Or manually for more control:
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});
```

---

### 3. **No Authentication/Authorization**
**Severity:** CRITICAL
**Category:** OWASP Top 10 - A07:2021 - Identification and Authentication Failures

**Issue:**
The `/users` endpoint exposes sensitive user data (names, emails) without any authentication mechanism. Anyone can access this endpoint.

**Recommended Fix:**
```javascript
// Install: npm install jsonwebtoken express-jwt

const jwt = require('jsonwebtoken');
const expressJwt = require('express-jwt');

const SECRET_KEY = process.env.JWT_SECRET || 'your-secret-key';

// Middleware to verify JWT
const verifyToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, SECRET_KEY);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};

// Apply to protected routes
app.get('/users', verifyToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

