/**
 * SECURE SECRETS MANAGEMENT IMPLEMENTATION
 * 
 * This demonstrates best practices for handling secrets in Node.js applications
 * Never commit .env files to version control
 */

// ============================================================================
// OPTION 1: AWS SECRETS MANAGER (Recommended for AWS deployments)
// ============================================================================

const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: 'us-east-1' });

class AWSSecretsProvider {
  constructor() {
    this.secrets = null;
  }

  async loadSecrets(secretName) {
    try {
      const data = await client.getSecretValue({ SecretId: secretName }).promise();

      if ('SecretString' in data) {
        this.secrets = JSON.parse(data.SecretString);
        return this.secrets;
      } else {
        throw new Error('Binary secrets not supported');
      }
    } catch (error) {
      console.error('Failed to load secrets from AWS Secrets Manager:', error);
      throw error;
    }
  }

  getSecret(key) {
    if (!this.secrets) {
      throw new Error('Secrets not loaded. Call loadSecrets() first.');
    }
    return this.secrets[key];
  }

  async rotateSecrets(secretName) {
    // AWS handles rotation automatically
    console.log('Retrieving rotated secrets from AWS Secrets Manager...');
    return await this.loadSecrets(secretName);
  }
}

// ============================================================================
// OPTION 2: HASHICORP VAULT (For multi-cloud/on-premise deployments)
// ============================================================================

const vault = require('node-vault');

class VaultSecretsProvider {
  constructor(options = {}) {
    this.client = vault({
      endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: process.env.VAULT_TOKEN
    });
  }

  async loadSecrets(secretPath) {
    try {
      const response = await this.client.read(secretPath);
      return response.data.data;
    } catch (error) {
      console.error('Failed to load secrets from Vault:', error);
      throw error;
    }
  }

  getSecret(key, secrets) {
    if (!secrets || !secrets[key]) {
      throw new Error(`Secret not found: ${key}`);
    }
    return secrets[key];
  }

  async renew() {
    try {
      await this.client.request({
        method: 'PUT',
        path: '/auth/token/renew-self'
      });
    } catch (error) {
      console.error('Failed to renew Vault token:', error);
      throw error;
    }
  }
}

// ============================================================================
// OPTION 3: AZURE KEY VAULT (For Azure deployments)
// ============================================================================

const { SecretClient } = require("@azure/keyvault-secrets");
const { DefaultAzureCredential } = require("@azure/identity");

class AzureKeyVaultProvider {
  constructor() {
    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(
      `https://${process.env.KEYVAULT_NAME}.vault.azure.net/`,
      credential
    );
  }

  async getSecret(secretName) {
    try {
      const secret = await this.client.getSecret(secretName);
      return secret.value;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  async getAllSecrets(secretNames) {
    const secrets = {};
    for (const name of secretNames) {
      secrets[name] = await this.getSecret(name);
    }
    return secrets;
  }
}

// ============================================================================
// OPTION 4: GOOGLE CLOUD SECRET MANAGER
// ============================================================================

const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

class GoogleCloudSecretsProvider {
  constructor(projectId) {
    this.client = new SecretManagerServiceClient();
    this.projectId = projectId;
  }

  async getSecret(secretId, version = 'latest') {
    try {
      const name = this.client.secretVersionPath(
        this.projectId,
        secretId,
        version
      );
      const [version_] = await this.client.accessSecretVersion({ name });
      return version_.payload.data.toString('utf8');
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretId}:`, error);
      throw error;
    }
  }
}

// ============================================================================
// OPTION 5: ENVIRONMENT VARIABLES ONLY (Least secure, use with CI/CD)
// ============================================================================

class EnvironmentVariablesProvider {
  constructor(requiredVars = []) {
    this.requiredVars = requiredVars;
    this.validateRequired();
  }

  validateRequired() {
    const missing = this.requiredVars.filter(
      variable => !process.env[variable]
    );

    if (missing.length > 0) {
      throw new Error(
        `Missing required environment variables: ${missing.join(', ')}`
      );
    }
  }

  getSecret(key) {
    const value = process.env[key];
    if (!value) {
      throw new Error(`Secret not found: ${key}`);
    }
    return value;
  }

  getAllSecrets() {
    return this.requiredVars.reduce((acc, key) => {
      acc[key] = process.env[key];
      return acc;
    }, {});
  }
}

// ============================================================================
// FACTORY PATTERN - Choose Provider Based on Environment
// ============================================================================

function getSecretsProvider() {
  const provider = process.env.SECRETS_PROVIDER || 'env';

  switch (provider.toLowerCase()) {
    case 'aws':
      return new AWSSecretsProvider();
    case 'vault':
      return new VaultSecretsProvider();
    case 'azure':
      return new AzureKeyVaultProvider();
    case 'gcp':
      return new GoogleCloudSecretsProvider(process.env.GCP_PROJECT_ID);
    case 'env':
    default:
      return new EnvironmentVariablesProvider([
        'DATABASE_URL',
        'AWS_ACCESS_KEY_ID',
        'AWS_SECRET_ACCESS_KEY',
        'ANTHROPIC_API_KEY',
        'STRIPE_SECRET_KEY',
        'LOGFIRE_TOKEN',
        'JWT_SECRET'
      ]);
  }
}

// ============================================================================
// SECURE APP INITIALIZATION
// ============================================================================

const express = require('express');

async function createSecureApp() {
  const app = express();

  // Load secrets based on environment
  const secretsProvider = getSecretsProvider();

  // For AWS Secrets Manager
  if (process.env.SECRETS_PROVIDER === 'aws') {
    await secretsProvider.loadSecrets(
      process.env.AWS_SECRET_NAME || 'prod/app-secrets'
    );
  }

  // Store secrets provider in app context (don't expose to routes)
  app.use((req, res, next) => {
    // Make secrets available only to internal handlers, never to client
    req.app.locals.secretsProvider = secretsProvider;
    next();
  });

  // Example: Use secrets securely
  app.get('/health', (req, res) => {
    // NEVER log secrets
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  });

  // Example: Access secrets in route
  app.get('/api/data', (req, res) => {
    try {
      const dbUrl = secretsProvider.getSecret('DATABASE_URL');
      // Use dbUrl to connect to database
      // NEVER return it to client
      res.json({ success: true });
    } catch (error) {
      console.error('Error accessing secrets:', error);
      res.status(500).json({ error: 'Internal Server Error' });
    }
  });

  return app;
}

// ============================================================================
// DOTENV FALLBACK (Development ONLY - with proper security)
// ============================================================================

const dotenv = require('dotenv');
const path = require('path');

function loadSecretsFromEnv() {
  // Only in development, never in production
  if (process.env.NODE_ENV !== 'production') {
    const envFile = process.env.ENV_FILE || '.env.local';

    // Check that .env file is not committed
    // Add to .gitignore:
    // .env
    // .env.*.local

    dotenv.config({ path: path.resolve(process.cwd(), envFile) });

    console.warn(
      'WARNING: Loading secrets from .env file (Development only)'
    );
  }
}

// ============================================================================
// SECRETS ROTATION HELPER
// ============================================================================

class SecretsRotationManager {
  constructor(provider, rotationIntervalMs = 86400000) { // 24 hours
    this.provider = provider;
    this.rotationIntervalMs = rotationIntervalMs;
  }

  start() {
    setInterval(async () => {
      try {
        console.log('Rotating secrets...');
        if (this.provider.rotateSecrets) {
          await this.provider.rotateSecrets();
          console.log('Secrets rotated successfully');
        }
      } catch (error) {
        console.error('Failed to rotate secrets:', error);
        // Don't crash app on rotation failure
      }
    }, this.rotationIntervalMs);
  }
}

// ============================================================================
// SECURE LOGGING HELPER
// ============================================================================

function sanitizeForLogging(obj) {
  const secretPatterns = [
    'PASSWORD',
    'SECRET',
    'KEY',
    'TOKEN',
    'API_KEY',
    'CREDENTIAL'
  ];

  const sanitized = JSON.parse(JSON.stringify(obj));

  for (const key in sanitized) {
    if (secretPatterns.some(pattern => key.toUpperCase().includes(pattern))) {
      sanitized[key] = '[REDACTED]';
    }
  }

  return sanitized;
}

// Export providers and utilities
module.exports = {
  AWSSecretsProvider,
  VaultSecretsProvider,
  AzureKeyVaultProvider,
  GoogleCloudSecretsProvider,
  EnvironmentVariablesProvider,
  getSecretsProvider,
  createSecureApp,
  loadSecretsFromEnv,
  SecretsRotationManager,
  sanitizeForLogging
};
