const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const cors = require('cors');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Set security HTTP headers
app.use(helmet());

// 2. Implement rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});
app.use(limiter);

// 3. Parse JSON body with size limit to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));

// 4. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 5. CORS configuration - restrict allowed origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// 6. Security logging middleware
app.use((req, res, next) => {
  // Log requests without sensitive data
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path}`);
  next();
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  // Validate query parameters if any
  const { limit = 10, offset = 0 } = req.query;

  // Validate input - ensure they are positive integers
  const validLimit = Math.min(Math.max(parseInt(limit) || 10, 1), 100); // max 100
  const validOffset = Math.max(parseInt(offset) || 0, 0);

  // Return hardcoded data with pagination
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json({
    data: users.slice(validOffset, validOffset + validLimit),
    total: users.length,
    limit: validLimit,
    offset: validOffset,
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource does not exist.'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Don't expose internal error details
  console.error('Error:', err);
  res.status(err.status || 500).json({ 
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'An error occurred'
  });
});

// ============================================
// START SERVER
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
});

module.exports = app;

