// AUTHENTICATION & AUTHORIZATION EXAMPLES
// Add to your secure Express app

const express = require('express');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const rateLimit = require('express-rate-limit');

const app = express();
app.use(express.json());

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

/**
 * Verify JWT token
 * Usage: app.get('/protected', authMiddleware, (req, res) => {...})
 */
const authMiddleware = (req, res, next) => {
  try {
    // Extract token from Authorization header
    const token = req.headers.authorization?.split(' ')[1];

    if (!token) {
      return res.status(401).json({ 
        error: 'Unauthorized',
        message: 'No token provided' 
      });
    }

    // Verify token
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ 
      error: 'Invalid token',
      message: err.message 
    });
  }
};

/**
 * Verify refresh token (more lenient, different secret)
 */
const refreshTokenMiddleware = (req, res, next) => {
  try {
    const token = req.body.refreshToken;

    if (!token) {
      return res.status(401).json({ error: 'Refresh token required' });
    }

    const decoded = jwt.verify(token, process.env.REFRESH_TOKEN_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid refresh token' });
  }
};

// ============================================
// AUTHORIZATION MIDDLEWARE
// ============================================

/**
 * Check if user has required role
 * Usage: app.post('/admin', authMiddleware, authorize('admin'), (req, res) => {...})
 */
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Forbidden',
        message: 'You do not have permission to access this resource' 
      });
    }

    next();
  };
};

/**
 * Check if user owns the resource
 * Usage: app.get('/users/:id', authMiddleware, ownerOnly('userId'), (req, res) => {...})
 */
const ownerOnly = (userIdField) => {
  return (req, res, next) => {
    const resourceUserId = req.params.id;
    const currentUserId = req.user.id;

    if (resourceUserId !== currentUserId) {
      return res.status(403).json({ 
        error: 'Forbidden',
        message: 'You can only access your own resources' 
      });
    }

    next();
  };
};

// ============================================
// RATE LIMITING FOR AUTHENTICATION
// ============================================

// Stricter rate limiting for login attempts (prevent brute force)
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 login attempts
  message: 'Too many login attempts, please try again later',
  skipSuccessfulRequests: true, // Don't count successful attempts
  keyGenerator: (req) => req.body.email || req.ip, // Rate limit by email
});

// ============================================
// HELPER FUNCTIONS
// ============================================

/**
 * Hash password using bcrypt
 * @param {string} password - Plain text password
 * @returns {Promise<string>} - Hashed password
 */
const hashPassword = async (password) => {
  const salt = await bcrypt.genSalt(10);
  return bcrypt.hash(password, salt);
};

/**
 * Compare password with hash
 * @param {string} password - Plain text password
 * @param {string} hash - Hashed password
 * @returns {Promise<boolean>} - True if password matches
 */
const verifyPassword = async (password, hash) => {
  return bcrypt.compare(password, hash);
};

/**
 * Generate JWT token
 * @param {object} user - User object
 * @returns {string} - JWT token
 */
const generateToken = (user) => {
  return jwt.sign(
    { id: user.id, email: user.email, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: process.env.JWT_EXPIRE || '1h' }
  );
};

/**
 * Generate refresh token (longer expiration)
 * @param {object} user - User object
 * @returns {string} - Refresh token
 */
const generateRefreshToken = (user) => {
  return jwt.sign(
    { id: user.id, email: user.email },
    process.env.REFRESH_TOKEN_SECRET,
    { expiresIn: '7d' }
  );
};

// ============================================
// AUTHENTICATION ROUTES
// ============================================

/**
 * Register new user
 * POST /auth/register
 */
app.post('/auth/register', async (req, res) => {
  try {
    const { email, password, name } = req.body;

    // Input validation
    if (!email || !password || !name) {
      return res.status(400).json({ 
        error: 'Missing required fields: email, password, name' 
      });
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({ error: 'Invalid email format' });
    }

    // Validate password strength
    if (password.length < 8) {
      return res.status(400).json({ 
        error: 'Password must be at least 8 characters' 
      });
    }

    // Check if user already exists (in real app, query database)
    // const existingUser = await User.findOne({ email });
    // if (existingUser) {
    //   return res.status(409).json({ error: 'Email already registered' });
    // }

    // Hash password
    const hashedPassword = await hashPassword(password);

    // Create user (in real app, save to database)
    const newUser = {
      id: Math.random().toString(36).substr(2, 9),
      email,
      name,
      password: hashedPassword,
      role: 'user',
      createdAt: new Date(),
    };

    // Generate tokens
    const token = generateToken(newUser);
    const refreshToken = generateRefreshToken(newUser);

    res.status(201).json({
      message: 'User registered successfully',
      user: {
        id: newUser.id,
        email: newUser.email,
        name: newUser.name,
        role: newUser.role,
      },
      token,
      refreshToken,
    });
  } catch (err) {
    console.error('Registration error:', err);
    res.status(500).json({ error: 'Registration failed' });
  }
});

