/**
 * SECRETS MANAGEMENT IMPLEMENTATION
 * Production-ready secrets loader supporting multiple backends
 * Use this instead of relying on .env files in production
 */

const AWS = require('aws-sdk');
const crypto = require('crypto');

// ============================================
// SECRETS LOADER - Multi-Backend Support
// ============================================

class SecretsManager {
  constructor() {
    this.backend = process.env.SECRETS_BACKEND || 'env'; // env, aws, vault, file
    this.secrets = {};
    this.lastRefresh = null;
    this.refreshInterval = process.env.SECRETS_REFRESH_INTERVAL || 3600000; // 1 hour
  }

  /**
   * Load secrets based on configured backend
   */
  async loadSecrets() {
    console.log(`[SECRETS] Loading secrets from ${this.backend} backend...`);

    try {
      switch (this.backend) {
        case 'aws':
          await this.loadFromAWS();
          break;
        case 'vault':
          await this.loadFromVault();
          break;
        case 'file':
          await this.loadFromFile();
          break;
        case 'env':
        default:
          this.loadFromEnv();
      }

      this.lastRefresh = new Date();
      this.validateSecrets();
      console.log('[SECRETS] ✅ Secrets loaded successfully');
    } catch (error) {
      console.error('[SECRETS] ❌ Failed to load secrets:', error.message);
      throw error;
    }
  }

  /**
   * Load from environment variables (.env files via dotenv)
   * Development/Testing only
   */
  loadFromEnv() {
    const requiredSecrets = [
      'JWT_SECRET',
      'REFRESH_TOKEN_SECRET',
      'DATABASE_URL',
      'API_KEY',
    ];

    requiredSecrets.forEach((key) => {
      const value = process.env[key];
      if (!value) {
        console.warn(`[SECRETS] Warning: ${key} not found in environment`);
      }
      this.secrets[key] = value;
    });

    // Flag that we're using .env (insecure in production)
    if (process.env.NODE_ENV === 'production') {
      console.error(
        '[SECRETS] ⚠️  WARNING: Using .env in production is INSECURE!'
      );
      console.error('[SECRETS] ⚠️  Migrate to AWS Secrets Manager or Vault!');
    }
  }

  /**
   * Load from AWS Secrets Manager
   * Production-grade solution
   */
  async loadFromAWS() {
    const secretsManagerClient = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    try {
      const secretName = process.env.AWS_SECRET_NAME || 'my-app/secrets';
      console.log(`[SECRETS] Fetching from AWS: ${secretName}`);

      const response = await secretsManagerClient
        .getSecretValue({ SecretId: secretName })
        .promise();

      if ('SecretString' in response) {
        this.secrets = JSON.parse(response.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(response.SecretBinary, 'base64');
        this.secrets = JSON.parse(buff.toString('ascii'));
      }

      console.log(`[SECRETS] Retrieved ${Object.keys(this.secrets).length} secrets from AWS`);
    } catch (error) {
      console.error('[SECRETS] AWS Secrets Manager error:', error.message);
      throw error;
    }
  }

  /**
   * Load from HashiCorp Vault
   * Multi-cloud solution
   */
  async loadFromVault() {
    try {
      const vaultAddr = process.env.VAULT_ADDR || 'http://127.0.0.1:8200';
      const vaultToken = process.env.VAULT_TOKEN;
      const secretPath = process.env.VAULT_SECRET_PATH || 'secret/data/my-app';

      if (!vaultToken) {
        throw new Error('VAULT_TOKEN environment variable not set');
      }

      console.log(`[SECRETS] Fetching from Vault: ${secretPath}`);

      const https = require('https');
      const response = await fetch(`${vaultAddr}/v1/${secretPath}`, {
        headers: { 'X-Vault-Token': vaultToken },
        agent: new https.Agent({ rejectUnauthorized: false }), // For self-signed certs
      });

      if (!response.ok) {
        throw new Error(`Vault returned ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      this.secrets = data.data.data;

      console.log(`[SECRETS] Retrieved ${Object.keys(this.secrets).length} secrets from Vault`);
    } catch (error) {
      console.error('[SECRETS] Vault error:', error.message);
      throw error;
    }
  }

  /**
   * Load from encrypted file
   * Good for containerized deployments
   */
  async loadFromFile() {
    const fs = require('fs').promises;
    const path = require('path');

    try {
      const secretFile = process.env.SECRETS_FILE || '/run/secrets/app-secrets';
      console.log(`[SECRETS] Loading from file: ${secretFile}`);

      if (!fs.existsSync(secretFile)) {
        throw new Error(`Secrets file not found: ${secretFile}`);
      }

      let content = await fs.readFile(secretFile, 'utf-8');

      // If encrypted, decrypt it
      if (process.env.SECRETS_ENCRYPTED === 'true') {
        content = this.decrypt(content);
      }

      this.secrets = JSON.parse(content);
      console.log(`[SECRETS] Loaded ${Object.keys(this.secrets).length} secrets from file`);
    } catch (error) {
      console.error('[SECRETS] File loading error:', error.message);
      throw error;
    }
  }

  /**
   * Get a secret by key
   * Returns null if not found (don't throw to avoid crashes)
   */
  getSecret(key) {
    const value = this.secrets[key];

    if (!value) {
      console.warn(`[SECRETS] Secret "${key}" not found`);
      return null;
    }

    // Log access (without value)
    this.logSecretAccess(key);

    return value;
  }

  /**
   * Get all secrets (for initialization)
   * Use with caution - don't log the values!
   */
  getAllSecrets() {
    return { ...this.secrets };
  }

  /**
   * Validate that all required secrets are loaded
   */
  validateSecrets() {
    const required = [
      'JWT_SECRET',
      'REFRESH_TOKEN_SECRET',
      'DATABASE_URL',
    ];

    const missing = required.filter((key) => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Validate secret strength
    Object.entries(this.secrets).forEach(([key, value]) => {
      if (typeof value === 'string') {
        if (value.length < 12) {
          console.warn(`[SECRETS] Warning: ${key} is weak (less than 12 chars)`);
        }

        // Flag obvious test values
        if (value.match(/^(test|dummy|fake|changeme|password)/i)) {
          console.warn(`[SECRETS] Warning: ${key} looks like a test value`);
        }
      }
    });
  }

  /**
   * Log secret access (without values)
   */
  logSecretAccess(key) {
    const timestamp = new Date().toISOString();
    const caller = new Error().stack.split('\n')[2].trim();

    // Send to centralized logging (e.g., CloudWatch, ELK)
    if (process.env.LOG_SECRET_ACCESS === 'true') {
      console.log(`[SECURITY] Secret accessed: ${key} at ${timestamp}`);
      // In production, send to: AWS CloudWatch, DataDog, etc.
    }
  }

  /**
   * Refresh secrets at regular intervals
   * Enables key rotation without restarting
   */
  async startAutoRefresh() {
    if (process.env.NODE_ENV !== 'production') {
      return; // Don't auto-refresh in development
    }

    setInterval(async () => {
      try {
        console.log('[SECRETS] Auto-refreshing secrets...');
        await this.loadSecrets();
      } catch (error) {
        console.error('[SECRETS] Auto-refresh failed:', error.message);
        // Don't crash, keep using old secrets
      }
    }, this.refreshInterval);
  }

  /**
   * Encrypt secrets (for file-based storage)
   */
  encrypt(text) {
    const algorithm = 'aes-256-cbc';
    const key = crypto.scryptSync(process.env.ENCRYPTION_PASSWORD || 'default', 'salt', 32);
    const iv = crypto.randomBytes(16);

    const cipher = crypto.createCipheriv(algorithm, key, iv);
    let encrypted = cipher.update(text, 'utf-8', 'hex');
    encrypted += cipher.final('hex');

    return `${iv.toString('hex')}:${encrypted}`;
  }

  /**
   * Decrypt secrets
   */
  decrypt(encryptedText) {
    const algorithm = 'aes-256-cbc';
    const key = crypto.scryptSync(process.env.ENCRYPTION_PASSWORD || 'default', 'salt', 32);
    const [iv, encrypted] = encryptedText.split(':');

    const decipher = crypto.createDecipheriv(algorithm, key, Buffer.from(iv, 'hex'));
    let decrypted = decipher.update(encrypted, 'hex', 'utf-8');
    decrypted += decipher.final('utf-8');

    return decrypted;
  }
}

// ============================================
// SINGLETON INSTANCE
// ============================================

let secretsManager = null;

async function initializeSecrets() {
  secretsManager = new SecretsManager();
  await secretsManager.loadSecrets();

  if (process.env.NODE_ENV === 'production') {
    await secretsManager.startAutoRefresh();
  }

  return secretsManager;
}

function getSecretsManager() {
  if (!secretsManager) {
    throw new Error(
      'Secrets manager not initialized. Call initializeSecrets() first.'
    );
  }
  return secretsManager;
}

// ============================================
// USAGE IN EXPRESS APP
// ============================================

/**
 * Example app.js initialization
 */
const express = require('express');

async function startApp() {
  // Initialize secrets BEFORE creating Express app
  await initializeSecrets();

  const app = express();
  const secrets = getSecretsManager();

  // Use secrets from manager
  const JWT_SECRET = secrets.getSecret('JWT_SECRET');
  const DATABASE_URL = secrets.getSecret('DATABASE_URL');

  // Your routes here...
  app.get('/health', (req, res) => {
    res.json({ status: 'ok' });
  });

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`App listening on port ${PORT}`);
  });
}

// Start app
startApp().catch((error) => {
  console.error('Failed to start app:', error);
  process.exit(1);
});

// ============================================
// EXPORTS
// ===============

