// Secure version with recommendations implemented

const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const mongoSanitize = require('express-mongo-sanitize');
const validator = require('validator');

const app = express();

// 1. SECURITY HEADERS - Helmet middleware
app.use(helmet());

// 2. RATE LIMITING - Prevent brute force and DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3. INPUT PARSING with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. SANITIZATION - Remove NoSQL injection attempts
app.use(mongoSanitize());

// 5. CORS Configuration
const cors = require('cors');
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS || 'http://localhost:3000',
  credentials: true,
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// Stricter limiter for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

// 6. HEALTH CHECK - No sensitive data exposed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// 7. USERS ENDPOINT - With input validation and access control
app.get('/users', authLimiter, validateUserQuery, (req, res) => {
  // In production: check user authentication and authorization
  if (!req.headers.authorization) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Mock data (in production: query database with parameterized queries)
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// 8. USER SEARCH - With proper input validation
app.get('/users/search', authLimiter, (req, res) => {
  const { query } = req.query;

  // Input validation
  if (!query) {
    return res.status(400).json({ error: 'Query parameter required' });
  }

  if (typeof query !== 'string' || query.length > 100) {
    return res.status(400).json({ error: 'Invalid query format' });
  }

  // Sanitize input (remove special characters)
  const sanitized = validator.escape(query);

  // In production: use parameterized queries
  // db.query('SELECT * FROM users WHERE name LIKE ?', [`%${sanitized}%`]);
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
  ];

  res.json(users);
});

// 9. INPUT VALIDATION MIDDLEWARE
function validateUserQuery(req, res, next) {
  // Validate query parameters if present
  if (req.query && Object.keys(req.query).length > 0) {
    for (const [key, value] of Object.entries(req.query)) {
      if (typeof value !== 'string' || value.length > 255) {
        return res.status(400).json({ error: 'Invalid query parameters' });
      }
    }
  }
  next();
}

// 10. ERROR HANDLING - Don't leak sensitive information
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// 11. 404 HANDLER
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

