/**
 * SECURITY MIDDLEWARE EXAMPLES
 * Copy these into your Express app for enhanced security
 */

const express = require('express');
const rateLimit = require('express-rate-limit');
const validator = require('validator');

// ============================================
// 1. INPUT VALIDATION MIDDLEWARE
// ============================================

/**
 * Validates query parameters
 */
function validateQueryParams(req, res, next) {
  if (!req.query || Object.keys(req.query).length === 0) {
    return next();
  }

  for (const [key, value] of Object.entries(req.query)) {
    // Must be string
    if (typeof value !== 'string') {
      return res.status(400).json({ 
        error: 'Invalid parameter type',
        parameter: key 
      });
    }

    // Length check
    if (value.length > 255) {
      return res.status(400).json({ 
        error: 'Parameter too long',
        max: 255,
        received: value.length
      });
    }

    // Whitelist alphanumeric (customize based on your needs)
    if (!/^[a-zA-Z0-9\s\-_@.]*$/.test(value)) {
      return res.status(400).json({ 
        error: 'Invalid characters in parameter',
        parameter: key 
      });
    }
  }

  next();
}

/**
 * Validates request body
 */
function validateBody(schema) {
  return (req, res, next) => {
    if (!req.body) {
      return res.status(400).json({ error: 'Request body required' });
    }

    // Simple validation - use Joi for production
    for (const [field, rules] of Object.entries(schema)) {
      const value = req.body[field];

      if (rules.required && (value === undefined || value === '')) {
        return res.status(400).json({ 
          error: `Field required: ${field}` 
        });
      }

      if (value && rules.type && typeof value !== rules.type) {
        return res.status(400).json({ 
          error: `Invalid type for ${field}: expected ${rules.type}` 
        });
      }

      if (value && rules.maxLength && value.length > rules.maxLength) {
        return res.status(400).json({ 
          error: `Field too long: ${field}` 
        });
      }

      if (value && rules.pattern && !rules.pattern.test(value)) {
        return res.status(400).json({ 
          error: `Invalid format for ${field}` 
        });
      }
    }

    next();
  };
}

// ============================================
// 2. RATE LIMITING MIDDLEWARE
// ============================================

/**
 * General rate limiter - 100 req/15min per IP
 */
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

/**
 * Strict rate limiter - 5 req/15min for sensitive operations
 */
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true, // Don't count successful attempts
  skipFailedRequests: false,
  message: 'Too many attempts, please try again later',
});

/**
 * Very strict for login attempts - 3 req/15min
 */
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 3,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, try again later',
});

/**
 * Custom rate limiter with store (for distributed systems)
 * Install: npm install rate-limit-redis
 */
function createRedisLimiter(client, options = {}) {
  const RedisStore = require('rate-limit-redis');
  return rateLimit({
    store: new RedisStore({
      client,
      prefix: 'rate-limit:',
    }),
    windowMs: options.windowMs || 15 * 60 * 1000,
    max: options.max || 100,
    ...options,
  });
}

// ============================================
// 3. SECURITY HEADERS MIDDLEWARE
// ============================================

/**
 * Custom security headers beyond Helmet
 */
function customSecurityHeaders(req, res, next) {
  // Prevent browser caching of sensitive data
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Clickjacking protection
  res.setHeader('X-Frame-Options', 'DENY');

  // XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Feature policy
  res.setHeader(
    'Permissions-Policy',
    'accelerometer=(), camera=(), geolocation=(), gyroscope=(), magnetometer=(), microphone=(), payment=(), usb=()'
  );

  next();
}

// ============================================
// 4. AUTHENTICATION MIDDLEWARE
// ============================================

/**
 * Simple Bearer token authentication
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // Verify token (you'd use JWT in production)
  try {
    const decoded = verifyToken(token);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

