/**
 * Authorization middleware - check user permissions
 */
function authorize(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Unauthorized' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
}

/**
 * Check if user owns the resource
 */
function canAccessResource(req, res, next) {
  const userId = req.user.id;
  const resourceUserId = parseInt(req.params.userId);

  if (userId !== resourceUserId) {
    return res.status(403).json({ 
      error: 'Cannot access other users\' data' 
    });
  }

  next();
}

// ============================================
// 5. INPUT SANITIZATION MIDDLEWARE
// ============================================

/**
 * Sanitize user input to prevent XSS
 */
function sanitizeInput(req, res, next) {
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        // Remove HTML tags
        req.body[key] = validator.escape(req.body[key]);
        // Trim whitespace
        req.body[key] = req.body[key].trim();
      }
    });
  }

  next();
}

/**
 * Sanitize query parameters
 */
function sanitizeQuery(req, res, next) {
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = validator.escape(req.query[key]).trim();
      }
    });
  }

  next();
}

// ============================================
// 6. ERROR HANDLING MIDDLEWARE
// ============================================

/**
 * Global error handler - always use at the end
 */
function globalErrorHandler(err, req, res, next) {
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Log error
  console.error('Error:', {
    message: err.message,
    stack: isDevelopment ? err.stack : undefined,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Determine status code
  let statusCode = err.status || err.statusCode || 500;
  if (err.name === 'ValidationError') statusCode = 400;
  if (err.name === 'UnauthorizedError') statusCode = 401;
  if (err.name === 'ForbiddenError') statusCode = 403;

  // Don't expose stack trace in production
  const response = {
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }),
  };

  res.status(statusCode).json(response);
}

/**
 * 404 handler
 */
function notFoundHandler(req, res) {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
  });
}

// ============================================
// 7. LOGGING MIDDLEWARE
// ============================================

/**
 * Request logging middleware
 */
function logRequests(req, res, next) {
  const start = Date.now();

  // Log response when it's sent
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      userId: req.user?.id,
    });
  });

  next();
}

/**
 * Audit logging for sensitive operations
 */
function auditLog(action, resource) {
  return (req, res, next) => {
    // Log after response
    res.on('finish', () => {
      console.log({
        type: 'AUDIT',
        timestamp: new Date().toISOString(),
        action,
        resource,
        userId: req.user?.id,
        path: req.path,
        status: res.statusCode,
        ip: req.ip,
      });
    });

    next();
  };
}

