/**
 * SECRETS MANAGEMENT ANALYSIS & RECOMMENDATIONS
 * Current State Analysis of app.js and proposed secure implementations
 */

// ============================================
// CURRENT STATE ANALYSIS
// ============================================

/*
FINDINGS:

1. Original app.js:
   ❌ No secrets management
   ❌ No dotenv configuration
   ❌ No environment variables
   ❌ Hardcoded values

2. app_secure.js (provided example):
   ⚠️ References process.env but NO dotenv.config() call
   ⚠️ No validation of required secrets
   ⚠️ Uses .env files (basic level)
   ⚠️ Still uses process.env directly

3. Critical Issues:
   ❌ Missing JWT_SECRET - using fallback
   ❌ No secrets encryption
   ❌ No secrets rotation mechanism
   ❌ No audit logging for secrets access
   ❌ Single .env file for all environments
   ❌ No secrets manager integration (Vault, AWS Secrets, etc.)
   ❌ Risk of .env files in version control
*/

// ============================================
// PROBLEM 1: Missing dotenv Initialization
// ============================================

console.log('PROBLEM 1: Missing dotenv initialization');
console.log('==========================================');
console.log(`
Current Code:
const PORT = process.env.PORT || 3000;

Problem:
- .env file is never loaded!
- process.env only has shell environment variables
- .env variables won't be available

Result:
- JWT_SECRET will always be undefined
- Uses fallback 'your-secret-key'
- CRITICAL SECURITY RISK
`);

// ============================================
// PROBLEM 2: Using Fallback Secrets
// ============================================

console.log('PROBLEM 2: Using fallback secrets in code');
console.log('==========================================');
console.log(`
Current Code:
const secret = process.env.JWT_SECRET || 'your-secret-key';

Problems:
1. Hardcoded secret in source code
2. Secret visible in version control history
3. Same secret for all deployments
4. Developers can see production secrets
5. No secret rotation possible

Risks:
- If code repo is compromised, production is compromised
- Anyone with repo access has production secrets
- Impossible to rotate secrets without code changes
- Audit trails show developer access to secrets
`);

// ============================================
// PROBLEM 3: Environment File Structure
// ============================================

console.log('PROBLEM 3: Single .env file for all environments');
console.log('=================================================');
console.log(`
Current Structure:
.env (development)
.env (production)  <-- Only one .env per deployment

Issues:
- Developer commits wrong secrets to wrong environment
- Easy to mix up production and development secrets
- No separation of concerns
- Risk of using dev secrets in production or vice versa

Better Structure:
.env.development   (development secrets)
.env.production    (production secrets)
.env.test          (test secrets)
.env.local         (local overrides, NOT in git)
.env.example       (documented, in git)
`);

// ============================================
// PROBLEM 4: No Validation of Required Secrets
// ============================================

console.log('PROBLEM 4: No validation of required secrets');
console.log('=============================================');
console.log(`
Current Code:
const JWT_SECRET = process.env.JWT_SECRET;
// Will be undefined if not set!

Problems:
- Missing secrets silently fail
- Crashes might occur deep in code
- Hard to debug
- No clear error message

Better Approach:
Validate all required secrets on startup
`);

module.exports = {
  analysis: 'See below for secure implementations'
};

/**
 * LEVEL 1: Basic Secrets Management (.env files)
 * Good for development, NOT recommended for production
 */

require('dotenv').config();

// Validate all required secrets on startup
const requiredSecrets = [
  'JWT_SECRET',
  'NODE_ENV',
  'PORT'
];

requiredSecrets.forEach(secret => {
  if (!process.env[secret]) {
    console.error(`❌ FATAL ERROR: Missing required environment variable: ${secret}`);
    process.exit(1);
  }
});

// Validate secret strength
function validateSecretStrength(secretName, secret) {
  if (secret.length < 32) {
    console.warn(`⚠️ WARNING: ${secretName} is less than 32 characters (weak)`);
    if (process.env.NODE_ENV === 'production') {
      console.error(`❌ ERROR: ${secretName} must be at least 32 characters in production`);
      process.exit(1);
    }
  }
}

validateSecretStrength('JWT_SECRET', process.env.JWT_SECRET);

// Configuration with validation
const config = {
  port: parseInt(process.env.PORT, 10) || 3000,
  env: process.env.NODE_ENV || 'development',
  jwt: {
    secret: process.env.JWT_SECRET,
    expiresIn: process.env.JWT_EXPIRATION || '7d'
  },
  database: {
    url: process.env.DATABASE_URL,
    user: process.env.DATABASE_USER,
    password: process.env.DATABASE_PASSWORD
  },
  cors: {
    origins: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',')
  },
  rateLimit: {
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || 900000,
    max: parseInt(process.env.RATE_LIMIT_MAX, 10) || 100
  }
};

// Log non-sensitive configuration
console.log('✅ Configuration loaded successfully');
console.log(`   Environment: ${config.env}`);
console.log(`   Port: ${config.port}`);
console.log(`   CORS Origins: ${config.cors.origins.join(', ')}`);

module.exports = config;

/**
 * LEVEL 2: Intermediate Secrets Management
 * Using dotenv with strict validation and environment-specific configs
 */

require('dotenv').config({
  path: `.env.${process.env.NODE_ENV || 'development'}`
});

// Also load local overrides if they exist
require('dotenv').config({
  path: '.env.local',
  override: false // Don't override already loaded secrets
});

// ============================================
// SECRETS DEFINITIONS & VALIDATION
// ============================================

const SecretsManager = {
  // Define all secrets with metadata
  secrets: {
    JWT_SECRET: {
      required: true,
      minLength: 32,
      description: 'Secret key for JWT signing',
      production: true,
      sensitive: true
    },
    JWT_EXPIRATION: {
      required: false,
      default: '7d',
      description: 'JWT token expiration time',
      sensitive: false
    },
    DATABASE_URL: {
      required: true,
      description: 'Database connection string',
      production: true,
      sensitive: true
    },
    DATABASE_USER: {
      required: true,
      description: 'Database username',
      production: true,
      sensitive: true
    },
    DATABASE_PASSWORD: {
      required: true,
      description: 'Database password',
      production: true,
      sensitive: true
    },
    NODE_ENV: {
      required: true,
      enum: ['development', 'staging', 'production'],
      description: 'Environment type',
      sensitive: false
    },
    PORT: {
      required: false,
      default: 3000,
      description: 'Server port',
      sensitive: false
    },
    ALLOWED_ORIGINS: {
      required: true,
      description: 'CORS allowed origins (comma-separated)',
      sensitive: false
    },
    RATE_LIMIT_MAX: {
      required: false,
      default: 100,
      description: 'Rate limit max requests',
      sensitive: false
    },
    REDIS_URL: {
      required: false,
      description: 'Redis connection URL',
      production: true,
      sensitive: true
    },
    LOG_LEVEL: {
      required: false,
      default: 'info',
      enum: ['debug', 'info', 'warn', 'error'],
      sensitive: false
    },
    SENTRY_DSN: {
      required: false,
      description: 'Sentry error tracking DSN',
      sensitive: true
    }
  },

  // Validate all secrets on startup
  validate() {
    const errors = [];
    const warnings = [];
    const isProduction = process.env.NODE_ENV === 'production';

    Object.entries(this.secrets).forEach(([name, config]) => {
      const value = process.env[name];

      // Check required secrets
      if (config.required && !value) {
        errors.push(`Missing required secret: ${name}`);
      }

      // Check production-only secrets
      if (config.production && isProduction && !value) {
        errors.push(`Production requires: ${name}`);
      }

      // Check minimum length (for secrets)
      if (config.minLength && value && value.length < config.minLength) {
        const level = isProduction ? 'error' : 'warning';
        const msg = `${name} is less than ${config.minLength} characters`;
        if (level === 'error') {
          errors.push(msg);
        } else {
          warnings.push(msg);
        }
      }

      // Check enum values
      if (config.enum && value && !config.enum.includes(value)) {
        errors.push(`${name} must be one of: ${config.enum.join(', ')}`);
      }
    });

    // Report errors
    if (errors.length > 0) {
      console.error('❌ CONFIGURATION ERRORS:');
      errors.forEach(err => console.error(`   - ${err}`));
      process.exit(1);
    }

    // Report warnings
    if (warnings.length > 0) {
      console.warn('⚠️ CONFIGURATION WARNINGS:');
      warnings.forEach(warn => console.warn(`   - ${warn}`));
    }

    return true;
  },

  // Get configuration object
  getConfig() {
    this.validate();

    return {
      env: process.env.NODE_ENV || 'development',
      port: parseInt(process.env.PORT || 3000, 10),

      jwt: {
        secret: process.env.JWT_SECRET,
        expiresIn: process.env.JWT_EXPIRATION || '7d'
      },

      database: {
        url: process.env.DATABASE_URL,
        user: process.env.DATABASE_USER,
        password: process.env.DATABASE_PASSWORD,
        useConnectionPooling: true
      },

      cors: {
        origins: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',').map(o => o.trim())
      },

      rateLimit: {
        windowMs: 15 * 60 * 1000,
        max: parseInt(process.env.RATE_LIMIT_MAX || 100, 10)
      },

      redis: process.env.REDIS_URL ? {
        url: process.env.REDIS_URL,
        enabled: true
      } : {
        enabled: false
      },

      logging: {
        level: process.env.LOG_LEVEL || 'info'
      },

      sentry: process.env.SENTRY_DSN ? {
        dsn: process.env.SENTRY_DSN,
        enabled: true
      } : {
        enabled: false
      }
    };
  },

  // Get secret by name (with audit logging)
  getSecret(name) {
    if (!this.secrets[name]) {
      throw new Error(`Unknown secret: ${name}`);
    }

    const secret = process.env[name];

    if (!secret) {
      console.error(`❌ Secret not found: ${name}`);
      throw new Error(`Secret not found: ${name}`);
    }

    // In production, log access to sensitive secrets
    if (this.secrets[name].sensitive && process.env.NODE_ENV === 'production') {
      // Send to audit logging system
      // auditLogger.log('SECRET_ACCESS', { secret: name, timestamp: new Date() });
    }

    return secret;
  },

  // Print safe configuration (non-sensitive values only)
  printConfig() {
    const config = this.getConfig();

    console.log('✅ Configuration Summary:');
    console.log(`   Environment: ${config.env}`);
    console.log(`   Port: ${config.port}`);
    console.log(`   CORS Origins: ${config.cors.origins.join(', ')}`);
    console.log(`   Rate Limit: ${config.rateLimit.max} requests per 15 minutes`);
    console.log(`   Redis: ${config.redis.enabled ? 'Enabled' : 'Disabled'}`);
    console.log(`   Sentry: ${config.sentry.enabled ? 'Enabled' : 'Disabled'}`);

    // Don't print sensitive secrets!
  }
};

// Validate on require
SecretsManager.validate();

module.exports = SecretsManager;

/**
 * LEVEL 3: Production-Grade Secrets Management
 * Using HashiCorp Vault, AWS Secrets Manager, or Azure Key Vault
 */

// Install: npm install node-vault dotenv
const vault = require('node-vault');

/**
 * Vault Secrets Manager - Enterprise-grade secrets management
 * For HashiCorp Vault or similar services
 */
class VaultSecretsManager {
  constructor() {
    this.client = null;
    this.secrets = {};
    this.lastRefresh = null;
    this.refreshInterval = 3600000; // 1 hour
  }

  /**
   * Initialize connection to Vault
   */
  async initialize() {
    try {
      this.client = vault({
        endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
        token: process.env.VAULT_TOKEN,
        apiVersion: 'v1'
      });

      // Test connection
      await this.client.health();
      console.log('✅ Connected to Vault');

      // Load initial secrets
      await this.refresh();

      // Setup automatic refresh
      this.setupAutoRefresh();

      return true;
    } catch (error) {
      console.error('❌ Failed to connect to Vault:', error.message);
      throw error;
    }
  }

  /**
   * Load all secrets from Vault
   */
