/**
 * AWS Secrets Manager
 */
class AWSSecretsManager {
  constructor() {
    // Install: npm install aws-sdk
    const AWS = require('aws-sdk');
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.secrets = {};
  }

  async initialize() {
    try {
      await this.refresh();
      console.log('✅ Connected to AWS Secrets Manager');
      return true;
    } catch (error) {
      console.error('❌ Failed to connect to AWS Secrets Manager:', error.message);
      throw error;
    }
  }

  async refresh() {
    try {
      const secretName = process.env.AWS_SECRET_NAME;

      if (!secretName) {
        throw new Error('AWS_SECRET_NAME environment variable not set');
      }

      const response = await this.client.getSecretValue({ SecretId: secretName }).promise();

      if (response.SecretString) {
        this.secrets = JSON.parse(response.SecretString);
      } else {
        this.secrets = Buffer.from(response.SecretBinary, 'base64').toString();
      }

      return this.secrets;
    } catch (error) {
      console.error('❌ Failed to fetch from AWS Secrets Manager:', error.message);
      throw error;
    }
  }

  getSecret(name) {
    const secret = this.secrets[name];

    if (!secret) {
      throw new Error(`Secret not found: ${name}`);
    }

    return secret;
  }
}

/**
 * Azure Key Vault
 */
class AzureKeyVaultManager {
  constructor() {
    // Install: npm install @azure/identity @azure/keyvault-secrets
    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(
      process.env.AZURE_KEY_VAULT_URL,
      credential
    );
    this.secrets = {};
  }

  async initialize() {
    try {
      await this.refresh();
      console.log('✅ Connected to Azure Key Vault');
      return true;
    } catch (error) {
      console.error('❌ Failed to connect to Azure Key Vault:', error.message);
      throw error;
    }
  }

  async refresh() {
    try {
      const secretNames = (process.env.AZURE_SECRET_NAMES || '').split(',');

      for (const name of secretNames) {
        const secret = await this.client.getSecret(name.trim());
        this.secrets[name.trim()] = secret.value;
      }

      return this.secrets;
    } catch (error) {
      console.error('❌ Failed to fetch from Azure Key Vault:', error.message);
      throw error;
    }
  }

  getSecret(name) {
    const secret = this.secrets[name];

    if (!secret) {
      throw new Error(`Secret not found: ${name}`);
    }

    return secret;
  }
}

/**
 * Factory function to create appropriate secrets manager
 */
function createSecretsManager() {
  const provider = process.env.SECRETS_PROVIDER || 'dotenv';

  switch (provider) {
    case 'vault':
      return new VaultSecretsManager();

    case 'aws':
      return new AWSSecretsManager();

    case 'azure':
      return new AzureKeyVaultManager();

    default:
      console.warn('⚠️ Using basic dotenv provider. For production, use Vault, AWS Secrets Manager, or Azure Key Vault');
      return require('./config_intermediate.js');
  }
}

module.exports = {
  VaultSecretsManager,
  AWSSecretsManager,
  AzureKeyVaultManager,
  createSecretsManager
};

