    pattern: /sk-ant-[A-Za-z0-9\-_]{48,}/g,
    description: 'Anthropic API Key',
    severity: 'CRITICAL'
  },
};

// Files/paths to exclude
const EXCLUDE_PATHS = [
  'node_modules',
  '.git',
  'dist',
  'build',
  '.env.example', // This is intentionally allowed
  '.gitignore',
  'secrets_detector.js',
  'package-lock.json',
  'yarn.lock',
];

class SecretDetector {
  constructor() {
    this.findings = [];
    this.filesScanned = 0;
    this.secretsFound = 0;
  }

  shouldExclude(filePath) {
    return EXCLUDE_PATHS.some(excludePath => filePath.includes(excludePath));
  }

  scanFile(filePath) {
    try {
      const content = fs.readFileSync(filePath, 'utf8');

      Object.entries(SECRET_PATTERNS).forEach(([key, { pattern, description, severity }]) => {
        let match;
        const regex = new RegExp(pattern);

        while ((match = regex.exec(content)) !== null) {
