            line: lineNumber,
            type: key,
            description,
            severity,
            match: match[0].substring(0, 50) + (match[0].length > 50 ? '...' : '')
          });

          this.secretsFound++;
        }
      });
    } catch (error) {
      if (error.code !== 'EISDIR') {
        console.error(`Error scanning ${filePath}:`, error.message);
      }
    }
  }

  scan(directory = '.') {
