    const files = glob.sync('**/*', {
      cwd: directory,
      nodir: true,
      ignore: EXCLUDE_PATHS.map(p => `**/${p}/**`)
    });

    files.forEach(file => {
      if (!this.shouldExclude(file)) {
        this.scanFile(path.join(directory, file));
        this.filesScanned++;
      }
    });
  }

  report() {
    console.log(`\n📊 SCAN RESULTS`);
    console.log(`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`);
    console.log(`Files scanned: ${this.filesScanned}`);
    console.log(`Secrets found: ${this.secretsFound}\n`);

    if (this.secretsFound === 0) {
      console.log('✅ No secrets detected!\n');
      return 0;
    }

    // Group by severity
    const bySeverity = {
      CRITICAL: [],
      HIGH: [],
      MEDIUM: []
    };

    this.findings.forEach(finding => {
      bySeverity[finding.severity].push(finding);
    });

    // Print critical findings
    if (bySeverity.CRITICAL.length > 0) {
      console.log('🔴 CRITICAL FINDINGS:');
      bySeverity.CRITICAL.forEach(finding => {
        console.log(`  ${finding.file}:${finding.line}`);
        console.log(`    Type: ${finding.type}`);
        console.log(`    Description: ${finding.description}`);
        console.log(`    Match: ${finding.match}\n`);
      });
    }

    // Print high findings
    if (bySeverity.HIGH.length > 0) {
      console.log('🟠 HIGH FINDINGS:');
      bySeverity.HIGH.forEach(finding => {
        console.log(`  ${finding.file}:${finding.line}`);
        console.log(`    Type: ${finding.type}`);
        console.log(`    Description: ${finding.description}\n`);
      });
    }

    return this.secretsFound > 0 ? 1 : 0;
  }

  exportJson(filename = 'secrets-scan-report.json') {
    const report = {
      timestamp: new Date().toISOString(),
      filesScanned: this.filesScanned,
      secretsFound: this.secretsFound,
      findings: this.findings
    };

    fs.writeFileSync(filename, JSON.stringify(report, null, 2));
    console.log(`\n📄 Report exported to ${filename}`);
  }
}

// Run scan
const detector = new SecretDetector();
detector.scan();
const exitCode = detector.report();

// Export JSON report
detector.exportJson();

process.exit(exitCode);

