const express = require('express');
const AWS = require('aws-sdk');
const helmet = require('helmet');
const winston = require('winston');
require('dotenv').config({ path: process.env.NODE_ENV === 'production' ? null : '.env' });

const app = express();

// Setup
const logger = winston.createLogger({ /* ... */ });
const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

// Secrets cache
let secretsCache = {};
let secretsExpiry = 0;

// Security middleware
app.use(helmet());
app.use(express.json({ limit: '10kb' })); // Prevent payload abuse

// Secrets retrieval
async function getSecrets(force = false) {
  const now = Date.now();
  if (!force && secretsCache.keys && now < secretsExpiry) {
    return secretsCache;
  }

  try {
    const result = await secretsManager.getSecretValue({
      SecretId: process.env.SECRETS_ARN
    }).promise();

    secretsCache = JSON.parse(result.SecretString);
    secretsExpiry = now + 3600000;
    return secretsCache;
  } catch (error) {
    if (!secretsCache.keys) throw error;
    return secretsCache;
  }
}

// Initialization
async function initializeApp() {
  try {
    const secrets = await getSecrets();
    const required = ['DATABASE_URL', 'STRIPE_KEY'];
    required.forEach(key => {
      if (!secrets[key]) throw new Error(`Missing: ${key}`);
    });
    logger.info('App initialized');
  } catch (error) {
    logger.error('Init failed:', { error: error.message });
    process.exit(1);
  }
}

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.get('/users', async (req, res) => {
  try {
    const config = await getSecrets();
    // Use config securely
    res.json([]);
  } catch (error) {
    logger.error('Error:', { error: error.message });
    res.status(500).json({ error: 'Internal error' });
  }
});

// Start
initializeApp().then(() => {
  app.listen(process.env.PORT || 3000);
});

module.exports = app;

