// Secure version of the application with security best practices implemented

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const validator = require('validator');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();

// ============================================================
// SECURITY MIDDLEWARE - APPLIED FIRST
// ============================================================

// 1. HELMET: Security HTTP headers (OWASP Top 10 - Injection, XSS)
app.use(helmet());

// 2. CORS: Prevent unauthorized cross-origin requests
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// 3. BODY PARSER with size limits (Prevent DoS attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. DATA SANITIZATION against NoSQL injection (OWASP Top 10 - Injection)
app.use(mongoSanitize());

// 5. RATE LIMITING (OWASP Top 10 - Broken Authentication & DoS)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Apply rate limiting to all requests
app.use(limiter);

// 6. STRICTER RATE LIMITING for sensitive endpoints
const sensitiveEndpointLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Very strict for sensitive operations
  skipSuccessfulRequests: true,
});

// ============================================================
// LOGGING & MONITORING (Security through visibility)
// ============================================================

const requestLogger = (req, res, next) => {
  const timestamp = new Date().toISOString();
  const requestId = uuidv4();

  // Add request ID for tracing
  req.id = requestId;

  console.log(`[${timestamp}] [${requestId}] ${req.method} ${req.path} from ${req.ip}`);

  next();
};

app.use(requestLogger);

// ============================================================
// VALIDATION MIDDLEWARE
// ============================================================

// Input validation helper function
const validateQueryParams = (schema) => {
  return (req, res, next) => {
    const errors = [];

    for (const [key, rules] of Object.entries(schema)) {
      const value = req.query[key];

      if (rules.required && !value) {
        errors.push(`${key} is required`);
        continue;
      }

      if (value) {
        if (rules.type === 'number' && isNaN(value)) {
          errors.push(`${key} must be a number`);
        }
        if (rules.type === 'string' && typeof value !== 'string') {
          errors.push(`${key} must be a string`);
        }
        if (rules.maxLength && value.length > rules.maxLength) {
          errors.push(`${key} must not exceed ${rules.maxLength} characters`);
        }
        if (rules.pattern && !rules.pattern.test(value)) {
          errors.push(`${key} has invalid format`);
        }
      }
    }

    if (errors.length > 0) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors 
      });
    }

    next();
  };
};

// ============================================================
// ROUTES
// ============================================================

/**
 * GET /health
 * Public health check endpoint
 * SECURITY: No sensitive data exposure
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      requestId: req.id
    });
  } catch (error) {
    console.error(`[${req.id}] Health check error:`, error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * GET /users
 * Retrieve user list with pagination and filtering
 * SECURITY IMPROVEMENTS:
 * - Rate limiting applied
 * - Input validation on query parameters
 * - Pagination to prevent data dumps
 * - Output filtering (no sensitive data)
 * - Error handling without stack traces
 */
app.get('/users', 
  validateQueryParams({
    page: { type: 'number', required: false },
    limit: { type: 'number', required: false },
    search: { type: 'string', required: false, maxLength: 100 },
  }),
  (req, res) => {
    try {
      // Parse and validate pagination parameters
      const page = Math.max(1, parseInt(req.query.page) || 1);
      const limit = Math.min(50, Math.max(1, parseInt(req.query.limit) || 10)); // Max 50 per page

      // Sanitize search input
      let searchTerm = req.query.search ? String(req.query.search).trim() : '';

      // Validate search term (prevent special characters that could cause issues)
      if (searchTerm && !validator.isLength(searchTerm, { min: 1, max: 100 })) {
        return res.status(400).json({ 
          error: 'Invalid search parameters',
          requestId: req.id
        });
      }

      // Mock user data (in real app, this would come from database with parameterized queries)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      // Filter based on search term (case-insensitive, safe)
      let filteredUsers = allUsers;
      if (searchTerm) {
        const searchLower = searchTerm.toLowerCase();
        filteredUsers = allUsers.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Apply pagination
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      // Return sanitized response
      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: filteredUsers.length,
          pages: Math.ceil(filteredUsers.length / limit)
        },
        requestId: req.id
      });

    } catch (error) {
      console.error(`[${req.id}] Error fetching users:`, error);
      // Don't expose internal error details to client
      res.status(500).json({ 
        error: 'Failed to fetch users',
        requestId: req.id
      });
    }
  }
);

/**
 * POST /users
 * Create a new user with proper validation
 * SECURITY IMPROVEMENTS:
 * - Strict rate limiting
 * - Input validation and sanitization
 * - No SQL/NoSQL injection
 * - Proper error handling
 * - CSRF protection (via body parser)
 */
app.post('/users',
  sensitiveEndpointLimiter,
  express.json(),
  (req, res) => {
    try {
      const { name, email } = req.body;
      const errors = [];

      // Validate name
      if (!name || typeof name !== 'string') {
        errors.push('Name is required and must be a string');
      } else if (!validator.isLength(name, { min: 1, max: 100 })) {
        errors.push('Name must be between 1 and 100 characters');
      }

      // Validate email
      if (!email || typeof email !== 'string') {
        errors.push('Email is required and must be a string');
      } else if (!validator.isEmail(email)) {
        errors.push('Email must be a valid email address');
      }

      if (errors.length > 0) {
        return res.status(400).json({
          error: 'Validation failed',
          details: errors,
          requestId: req.id
        });
      }

      // Sanitize inputs
      const sanitizedName = validator.trim(validator.escape(name));
      const sanitizedEmail = validator.trim(validator.normalizeEmail(email));

      // In a real app, you would:
      // 1. Use parameterized queries to prevent SQL injection
      // 2. Hash passwords before storing
      // 3. Validate email ownership
      // 4. Check for duplicates

      const newUser = {
        id: Math.max(...[1, 2, 3]) + 1,
        name: sanitizedName,
        email: sanitizedEmail
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
        requestId: req.id
      });

    } catch (error) {
      console.error(`[${req.id}] Error creating user:`, error);
      res.status(500).json({
        error: 'Failed to create user',
        requestId: req.id
      });
    }
  }
);

// ============================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    requestId: req.id
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(`[${req.id}] Unhandled error:`, err);

  // Don't expose internal error details
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message,
    requestId: req.id
  });
});

// ============================================================
// SERVER STARTUP
// ============================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

if (require.main === module) {
  app.listen(PORT, HOST, () => {
    console.log(`Server running on ${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

