/**
 * SECURE SECRETS MANAGEMENT IMPLEMENTATION
 * 
 * This module provides production-ready secrets management using
 * AWS Secrets Manager with fallback support for local development.
 * 
 * Supports:
 * - AWS Secrets Manager (Production)
 * - HashiCorp Vault (Alternative)
 * - Environment Variables (Development only)
 */

const aws = require('aws-sdk');
const NodeVault = require('node-vault');

// ============================================================
// CONFIGURATION
// ============================================================

class SecretsManager {
  constructor(config = {}) {
    this.environment = process.env.NODE_ENV || 'development';
    this.useAWSSecrets = process.env.USE_AWS_SECRETS === 'true';
    this.useVault = process.env.USE_VAULT === 'true';
    this.vaultAddr = process.env.VAULT_ADDR;
    this.vaultToken = process.env.VAULT_TOKEN;
    this.secretsCache = new Map();
    this.cacheExpiry = new Map();
    this.cacheTTL = config.cacheTTL || 60000; // 1 minute

    // Initialize appropriate backend
    if (this.useAWSSecrets) {
      this.secretsClient = new aws.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    } else if (this.useVault) {
      this.vault = new NodeVault({
        endpoint: this.vaultAddr,
        token: this.vaultToken
      });
    }
  }

  /**
   * Get a secret with automatic caching and error handling
   * @param {string} secretName - Name of the secret
   * @param {object} options - Additional options
   * @returns {Promise<object>} Secret value
   */
  async getSecret(secretName, options = {}) {
    // Check cache first
    if (this.secretsCache.has(secretName)) {
      const expiry = this.cacheExpiry.get(secretName);
      if (expiry > Date.now()) {
        console.log(`[SecretsManager] Retrieved '${secretName}' from cache`);
        return this.secretsCache.get(secretName);
      } else {
        this.secretsCache.delete(secretName);
        this.cacheExpiry.delete(secretName);
      }
    }

    try {
      let secretValue;

      if (this.useAWSSecrets) {
        secretValue = await this._getSecretFromAWS(secretName);
      } else if (this.useVault) {
        secretValue = await this._getSecretFromVault(secretName);
      } else {
        secretValue = this._getSecretFromEnv(secretName);
      }

      // Cache the secret
      this.secretsCache.set(secretName, secretValue);
      this.cacheExpiry.set(secretName, Date.now() + this.cacheTTL);

      // Audit log (without exposing the actual secret)
      this._auditLog('SECRET_RETRIEVED', secretName);

      return secretValue;
    } catch (error) {
      console.error(`[SecretsManager] Failed to retrieve secret '${secretName}':`, error.message);
      this._auditLog('SECRET_RETRIEVAL_FAILED', secretName, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Get secret from AWS Secrets Manager
   * @private
   */
  async _getSecretFromAWS(secretName) {
    try {
      const data = await this.secretsClient.getSecretValue({
        SecretId: secretName
      }).promise();

      if (data.SecretString) {
        return JSON.parse(data.SecretString);
      } else {
        return data.SecretBinary;
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found in AWS Secrets Manager: ${secretName}`);
      }
      throw error;
    }
  }

  /**
   * Get secret from HashiCorp Vault
   * @private
   */
  async _getSecretFromVault(secretName) {
    try {
      const response = await this.vault.read(`secret/data/${secretName}`);
      return response.data.data;
    } catch (error) {
      throw new Error(`Failed to retrieve secret from Vault: ${secretName}`);
    }
  }

  /**
   * Get secret from environment variables (Development only)
   * @private
   */
  _getSecretFromEnv(secretName) {
    if (this.environment === 'production') {
      throw new Error(
        'Cannot use environment variables for secrets in production. ' +
        'Please configure AWS Secrets Manager or HashiCorp Vault.'
      );
    }

    const value = process.env[secretName];
    if (!value) {
      throw new Error(`Secret '${secretName}' not found in environment variables`);
    }

    console.warn(`[SecretsManager] WARNING: Using plaintext env variable for '${secretName}' in development`);
    return value;
  }

  /**
   * Audit log for secret access (for compliance)
   * @private
   */
  _auditLog(action, secretName, error = null) {
    const timestamp = new Date().toISOString();
    const caller = this._getCallerInfo();

    const logEntry = {
      timestamp,
      action,
      secretName: secretName, // Log the name, NOT the value
      caller,
      environment: this.environment,
      error: error ? error.message : null
    };

    // In production, send to CloudWatch Logs or similar
    if (this.environment === 'production') {
      // Send to central logging service
      console.log('[AUDIT]', JSON.stringify(logEntry));
    } else {
      console.log('[AUDIT]', logEntry);
    }
  }

  /**
   * Get caller information for audit logs
   * @private
   */
  _getCallerInfo() {
    const stack = new Error().stack.split('\n');
    return stack[3]?.trim() || 'Unknown';
  }

  /**
   * Clear cache for a specific secret or all secrets
   * @param {string} secretName - Optional specific secret to clear
   */
  clearCache(secretName = null) {
    if (secretName) {
      this.secretsCache.delete(secretName);
      this.cacheExpiry.delete(secretName);
      console.log(`[SecretsManager] Cleared cache for '${secretName}'`);
    } else {
      this.secretsCache.clear();
      this.cacheExpiry.clear();
      console.log('[SecretsManager] Cleared all secret caches');
    }
  }

  /**
   * Verify secrets exist before starting application
   * @param {array} requiredSecrets - List of required secret names
   */
  async verifySecrets(requiredSecrets) {
    console.log('[SecretsManager] Verifying required secrets...');
    const missing = [];

    for (const secretName of requiredSecrets) {
      try {
        await this.getSecret(secretName);
        console.log(`✓ Secret '${secretName}' found`);
      } catch (error) {
        console.error(`✗ Secret '${secretName}' missing:`, error.message);
        missing.push(secretName);
      }
    }

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}\n` +
        'Please configure all required secrets before starting the application.'
      );
    }

    console.log('[SecretsManager] All required secrets verified ✓');
  }
}

// ============================================================
// SINGLETON INSTANCE
// ============================================================

let secretsManagerInstance = null;

function getSecretsManager() {
  if (!secretsManagerInstance) {
    secretsManagerInstance = new SecretsManager();
  }
  return secretsManagerInstance;
}

// ============================================================
// HELPER FUNCTIONS
// ============================================================

/**
 * Safely create connection strings without exposing passwords
 */
function createDatabaseURL(secretName) {
  return async () => {
    const secret = await getSecretsManager().getSecret(secretName);
    return `postgres://${secret.username}:${secret.password}@${secret.host}:${secret.port}/${secret.database}`;
  };
}

/**
 * Create AWS client with credentials from secrets manager
 */
async function createAWSClient(secretName, ServiceClass) {
  const secret = await getSecretsManager().getSecret(secretName);
  return new ServiceClass({
    accessKeyId: secret.accessKeyId,
    secretAccessKey: secret.secretAccessKey,
    region: secret.region || 'us-east-1'
  });
}

/**
 * Prevent secrets from appearing in logs
 */
function sanitizeError(error, secrets = []) {
  let message = error.message || String(error);

  for (const secret of secrets) {
    if (typeof secret === 'object') {
      for (const value of Object.values(secret)) {
        if (typeof value === 'string') {
          message = message.replace(new RegExp(value, 'g'), '[REDACTED]');
        }
      }
    } else if (typeof secret === 'string') {
      message = message.replace(new RegExp(secret, 'g'), '[REDACTED]');
    }
  }

  return message;
}

module.exports = {
  SecretsManager,
  getSecretsManager,
  createDatabaseURL,
  createAWSClient,
  sanitizeError
};

/**
 * SECURE APP.JS WITH SECRETS MANAGER INTEGRATION
 * 
 * This is the production-ready version that uses proper secrets management
 * instead of loading secrets from .env files directly.
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
