const { getSecretsManager, sanitizeError } = require('./secrets-manager');

const app = express();
let secretsManager = null;

// ============================================================
// INITIALIZATION
// ============================================================

/**
 * Initialize application with all required secrets
 */
async function initializeApp() {
  try {
    secretsManager = getSecretsManager();

    // Define required secrets for this application
    const requiredSecrets = [
      'database-credentials',
      'jwt-secret',
      'api-keys',
      'encryption-key'
    ];

    // Verify all secrets exist before starting
    await secretsManager.verifySecrets(requiredSecrets);

    console.log('[App] All secrets initialized successfully');
    return true;
  } catch (error) {
    console.error('[App] Fatal error during initialization:', error.message);
    process.exit(1);
  }
}

// ============================================================
// SECURITY MIDDLEWARE
// ============================================================

app.use(helmet());

app.use(cors({
