  algorithms: ['HS256'],
  credentialsRequired: true,
});

// ✅ Authorization middleware
const requireRole = (requiredRole) => {
  return (req, res, next) => {
    if (!req.auth || !req.auth.roles.includes(requiredRole)) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
};

// ✅ Protect endpoint with authentication
app.get('/users', authMiddleware, requireRole('admin'), (req, res) => {
  const userId = req.auth.sub; // Authenticated user ID

  // Only return users if requesting user has admin role
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
