### Step 2: Load Secrets in Application
```javascript
// secure-config.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

class SecretsManager {
  constructor() {
    this.cache = new Map();
  }

  async getSecret(secretId) {
    // Check cache first
    if (this.cache.has(secretId)) {
      return this.cache.get(secretId);
    }

    try {
      const response = await secretsManager.getSecretValue({
        SecretId: secretId
      }).promise();

      let secret = response.SecretString;
      if (response.SecretBinary) {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('utf8');
      }

      const parsedSecret = JSON.parse(secret);

      // Cache for 1 hour
      this.cache.set(secretId, parsedSecret);
      setTimeout(() => this.cache.delete(secretId), 3600000);

      return parsedSecret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretId}:`, error.message);
      throw error;
    }
  }
}

module.exports = new SecretsManager();
```

