    // Load secrets from AWS (NOT from env)
    const appSecrets = await secretsManager.getSecret('app/production/secrets');
    const dbSecrets = await secretsManager.getSecret('app/production/database');

    // Use secrets (never log them!)
    const jwtSecret = appSecrets.ACCESS_TOKEN_SECRET;
    const dbUrl = dbSecrets.DATABASE_URL;

