// =============================================================================

const vaultSecretsManager = {
  async init() {
    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN,
      requestOptions: {
        timeout: 5000
      }
    });
    this.client = vault;
  },

  async getSecret(path) {
    try {
      const response = await this.client.read(path);
      return response.data.data;
    } catch (error) {
      console.error(`Failed to retrieve secret from '${path}':`, error);
      throw error;
    }
  },

  async setSecret(path, data) {
    try {
      const response = await this.client.write(path, { data });
      return response;
    } catch (error) {
      console.error(`Failed to write secret to '${path}':`, error);
      throw error;
    }
  },

  async deleteSecret(path) {
    try {
      const response = await this.client.delete(path);
      return response;
    } catch (error) {
      console.error(`Failed to delete secret at '${path}':`, error);
      throw error;
    }
  }
};

// Usage:
// const secrets = await vaultSecretsManager.getSecret('secret/data/api');
// const JWT_SECRET = secrets.JWT_SECRET;


// =============================================================================
// SOLUTION 3: GOOGLE CLOUD SECRET MANAGER
// =============================================================================

const gcpSecretsManager = {
  async init() {
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
    this.client = new SecretManagerServiceClient();
    this.projectId = process.env.GCP_PROJECT_ID;
  },

  async getSecret(secretId, versionId = 'latest') {
    try {
      const name = this.client.secretVersionPath(
        this.projectId,
        secretId,
        versionId
      );

      const [version] = await this.client.accessSecretVersion({ name });
      const payload = version.payload.data.toString('utf8');

      try {
        return JSON.parse(payload);
      } catch {
        return payload;
      }
    } catch (error) {
      console.error(`Failed to retrieve GCP secret '${secretId}':`, error);
      throw error;
    }
  },

  async createSecret(secretId, secretValue) {
    try {
      const parent = this.client.projectPath(this.projectId);

      const [secret] = await this.client.createSecret({
        parent,
        secretId,
        secret: {
          replication: {
            automatic: {}
          }
        }
      });

      const payload = typeof secretValue === 'string' 
        ? secretValue 
        : JSON.stringify(secretValue);

      await this.client.addSecretVersion({
        parent: secret.name,
        payload: {
          data: Buffer.from(payload, 'utf8')
        }
      });

      return secret;
    } catch (error) {
      console.error(`Failed to create GCP secret '${secretId}':`, error);
      throw error;
    }
  }
};

// Usage:
// const JWT_SECRET = await gcpSecretsManager.getSecret('jwt-secret');


// =============================================================================
// SOLUTION 4: LOCAL ENCRYPTED SECRETS (Development Only)
// =============================================================================

const encryptedSecretsManager = {
  init() {
    const crypto = require('crypto');
    this.crypto = crypto;
    this.encryptionKey = Buffer.from(
      process.env.ENCRYPTION_KEY || '0'.repeat(64),
      'hex'
    );
  },

  encrypt(secret) {
    const iv = this.crypto.randomBytes(16);
    const cipher = this.crypto.createCipheriv('aes-256-cbc', this.encryptionKey, iv);

    let encrypted = cipher.update(
      typeof secret === 'string' ? secret : JSON.stringify(secret),
      'utf8',
      'hex'
    );
    encrypted += cipher.final('hex');

    return `${iv.toString('hex')}:${encrypted}`;
  },

  decrypt(encryptedSecret) {
    const [ivHex, encrypted] = encryptedSecret.split(':');
    const iv = Buffer.from(ivHex, 'hex');
    const decipher = this.crypto.createDecipheriv('aes-256-cbc', this.encryptionKey, iv);

    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    try {
      return JSON.parse(decrypted);
    } catch {
      return decrypted;
    }
  }
};

