// encryptedSecretsManager.init();
// const encrypted = encryptedSecretsManager.encrypt({ jwt: 'secret123' });
// const decrypted = encryptedSecretsManager.decrypt(encrypted);


// =============================================================================
// UNIFIED SECRETS MANAGER (Abstraction Layer)
// =============================================================================

class SecretsManager {
  constructor(provider = process.env.SECRETS_PROVIDER || 'aws') {
    this.provider = provider;
    this.managers = {
      aws: awsSecretsManager,
      vault: vaultSecretsManager,
      gcp: gcpSecretsManager,
      encrypted: encryptedSecretsManager
    };
  }

  async init() {
    const manager = this.managers[this.provider];
    if (!manager) {
      throw new Error(`Unknown secrets provider: ${this.provider}`);
    }
    if (manager.init) {
      await manager.init();
    }
    this.manager = manager;
  }

  async get(secretId) {
    if (!this.manager) {
      await this.init();
    }
    return this.manager.getSecret(secretId);
  }

  async set(secretId, value) {
    if (!this.manager) {
      await this.init();
    }
    if (!this.manager.setSecret && !this.manager.updateSecret) {
      throw new Error(`Provider ${this.provider} does not support writing secrets`);
    }
    const method = this.manager.setSecret || this.manager.updateSecret;
    return method.call(this.manager, secretId, value);
  }

  async delete(secretId) {
    if (!this.manager) {
      await this.init();
    }
    if (!this.manager.deleteSecret) {
      throw new Error(`Provider ${this.provider} does not support deleting secrets`);
    }
    return this.manager.deleteSecret(secretId);
  }
}


