### Step 2: Create Secrets Manager Wrapper (for production)
```javascript
// secrets-manager.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor(useAws = false) {
    this.useAws = useAws && process.env.NODE_ENV === 'production';
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour

    if (this.useAws) {
      this.client = new AWS.SecretsManager({ region: process.env.AWS_REGION });
    }
  }

  async getSecret(secretName) {
    // Return from cache if valid
    if (this.cache[secretName]) {
      const { value, timestamp } = this.cache[secretName];
      if (Date.now() - timestamp < this.cacheTTL) {
        return value;
      }
    }

    let secretValue;

    if (this.useAws) {
      try {
        const data = await this.client.getSecretValue({ 
          SecretId: secretName 
        }).promise();
        secretValue = data.SecretString;
      } catch (error) {
        console.error(`Failed to retrieve secret from AWS: ${secretName}`, error.message);
        throw new Error(`Unable to retrieve secret: ${secretName}`);
      }
    } else {
      // Fallback to environment variables
      secretValue = process.env[secretName];
      if (!secretValue) {
        throw new Error(`Secret not found: ${secretName}`);
      }
    }

    // Cache the secret
    this.cache[secretName] = {
      value: secretValue,
      timestamp: Date.now()
    };

    return secretValue;
  }

  clearCache() {
    this.cache = {};
  }
}

module.exports = new SecretsManager(true);
```

