// secret-monitor.js
const fs = require('fs');
const path = require('path');

function scanForSecrets(dir = '.') {
  const secretPatterns = [
    /CANARY-/gi,
    /AKIA[0-9A-Z]{16}/gi,
    /sk_live_[a-zA-Z0-9]{16,}/gi,
    /sk-ant-[a-zA-Z0-9]{16,}/gi,
    /password\s*[:=]\s*['"][^'"]+['"]/gi
  ];

  const files = fs.readdirSync(dir);

  files.forEach(file => {
    const filePath = path.join(dir, file);
    const stat = fs.statSync(filePath);

    if (stat.isDirectory()) {
      if (!filePath.includes('node_modules') && !filePath.includes('.git')) {
        scanForSecrets(filePath);
      }
    } else if (file.match(/\.(js|json|env|md|txt|yaml|yml)$/)) {
      const content = fs.readFileSync(filePath, 'utf-8');

      secretPatterns.forEach(pattern => {
        const matches = content.match(pattern);
        if (matches) {
          console.error(`⚠️  POTENTIAL SECRET in ${filePath}:`);
          console.error(`   Pattern: ${pattern}`);
          console.error(`   Matches: ${matches.slice(0, 3).join(', ')}`);
        }
      });
    }
  });
}

