**Issue:** The `/users` endpoint exposes sensitive user data without any authentication mechanism.

**Risk Level:** 🔴 **CRITICAL**

**Problems:**
- No authentication required
- Publicly accessible user data (names and emails)
- No authorization checks
- No rate limiting to prevent enumeration attacks

**Recommended Fix:**

```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const app = express();

// Middleware for authentication
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Only return users for authenticated requests
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### **2. ✗ NO SECURITY HEADERS (OWASP A01 - Broken Access Control)**

**Issue:** Missing critical HTTP security headers that protect against common attacks.

**Risk Level:** 🔴 **CRITICAL**

**Problems:**
- No Content Security Policy (CSP)
- No X-Frame-Options (clickjacking vulnerability)
- No X-Content-Type-Options (MIME-type sniffing)
- No Strict-Transport-Security (HSTS)
- No X-XSS-Protection header

**Recommended Fix:**

```javascript
const helmet = require('helmet');

// Add helmet middleware for security headers
app.use(helmet());

// Or manually add headers:
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});
```

---

### **3. ✗ NO INPUT VALIDATION (OWASP A03 - Injection)**

**Issue:** No validation of query parameters or request data, making the app vulnerable to injection attacks.

**Risk Level:** 🔴 **HIGH**

**Problems:**
- GET parameters are not validated
- Potential for parameter pollution attacks
- No type checking on inputs

**Recommended Fix:**

```javascript
const { query, validationResult } = require('express-validator');

app.get('/users', 
  authenticateToken,
  // Validate query parameters
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    // Check validation results
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);
```

