// secrets.js
const AWS = require('aws-sdk');
const path = require('path');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 60 * 60 * 1000; // 1 hour
  }

  /**
   * Retrieve secret with caching
   * @param {string} secretName - Name of secret in Secrets Manager
   * @returns {Promise<Object>} Parsed secret value
   */
  async getSecret(secretName) {
    // Check cache first
    if (this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        console.log(`[CACHE HIT] Secret: ${secretName}`);
        return cached.value;
      }
    }

    try {
      console.log(`[SECRETS MANAGER] Retrieving: ${secretName}`);
      const data = await this.client
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        // Binary secret
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secret = JSON.parse(buff.toString('ascii'));
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      console.log(`[SECRETS MANAGER] Successfully retrieved: ${secretName}`);
      return secret;
    } catch (error) {
      console.error(`[ERROR] Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Unable to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Clear cache (useful for testing or immediate secret rotation)
   */
  clearCache() {
    this.cache.clear();
    console.log('[CACHE] Cleared secrets cache');
  }

  /**
   * Get all required secrets for application startup
   */
  async initializeSecrets() {
    try {
      const [database, aws, stripe, apiKeys] = await Promise.all([
        this.getSecret('prod/database'),
        this.getSecret('prod/aws'),
        this.getSecret('prod/stripe'),
        this.getSecret('prod/api-keys')
      ]);

      return {
        database,
        aws,
        stripe,
        apiKeys
      };
    } catch (error) {
      console.error('Failed to initialize secrets:', error.message);
      process.exit(1);
    }
  }
}

// Export singleton instance
const secretsManager = new SecretsManager();
module.exports = secretsManager;
