vault login <token>
```

### Create Secrets in Vault

```bash
# Enable KV secrets engine
vault secrets enable -path=secret kv-v2

# Create database secret
vault kv put secret/prod/database \
  host="db.internal" \
  port=5432 \
  username="admin" \
  password="NEW_PASSWORD"

# Create AWS credentials
vault kv put secret/prod/aws \
  access_key_id="NEW_KEY" \
  secret_access_key="NEW_SECRET"

# Create Stripe secret
vault kv put secret/prod/stripe \
  secret_key="sk_live_REDACTED"
```

### Node.js Vault Integration

```javascript
// vault-secrets.js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN
});

async function getVaultSecret(path) {
  try {
    const secret = await vault.read(`secret/data${path}`);
    return secret.data.data;
  } catch (error) {
    console.error(`Failed to read secret from ${path}:`, error);
    throw error;
  }
}

// Usage
async function initializeSecrets() {
  const dbCreds = await getVaultSecret('/prod/database');
  const awsCreds = await getVaultSecret('/prod/aws');
  const stripeCreds = await getVaultSecret('/prod/stripe');

  return { dbCreds, awsCreds, stripeCreds };
}

module.exports = { getVaultSecret, initializeSecrets };
```

