/**
 * SECURE APPLICATION IMPLEMENTATION
 * 
 * This shows how to refactor app.js to use proper secrets management
 * instead of .env files or hardcoded values
 */

const express = require('express');
const app = express();

// ============================================================================
// APPROACH 1: AWS Secrets Manager (Recommended)
// ============================================================================

const AWS = require('aws-sdk');

class SecretsProvider {
  constructor() {
    this.secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheTimeout = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache[secretName] && Date.now() - this.cache[secretName].timestamp < this.cacheTimeout) {
      return this.cache[secretName].value;
    }

    try {
      const response = await this.secretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      let secretValue;
      if ('SecretString' in response) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache[secretName] = {
        value: secretValue,
        timestamp: Date.now()
      };

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  async getAllSecrets(secretName) {
    return this.getSecret(secretName);
  }
}

const secretsProvider = new SecretsProvider();

// ============================================================================
// APPROACH 2: Environment Variables (for CI/CD with GitHub Secrets)
// ============================================================================

class EnvSecretsProvider {
  constructor(requiredSecrets) {
    this.requiredSecrets = requiredSecrets;
    this.validateSecrets();
  }

  validateSecrets() {
    const missing = this.requiredSecrets.filter(
      secret => !process.env[secret]
    );

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}. ` +
        `These should be provided via environment variables or secrets manager.`
      );
    }
  }

  getSecret(secretName) {
    const value = process.env[secretName];
    if (!value) {
      throw new Error(`Secret not found: ${secretName}`);
    }
    return value;
  }
}

const envSecretsProvider = new EnvSecretsProvider([
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
]);

// ============================================================================
// APPLICATION INITIALIZATION
// ============================================================================

let secrets = {};

async function initializeApp() {
  try {
    // Choose provider based on environment
    if (process.env.USE_AWS_SECRETS === 'true') {
      console.log('Loading secrets from AWS Secrets Manager...');
      secrets = await secretsProvider.getAllSecrets(
        process.env.SECRET_NAME || 'production/app-secrets'
      );
    } else {
      console.log('Loading secrets from environment variables...');
      secrets = {
        DATABASE_URL: envSecretsProvider.getSecret('DATABASE_URL'),
        AWS_ACCESS_KEY_ID: envSecretsProvider.getSecret('AWS_ACCESS_KEY_ID'),
        AWS_SECRET_ACCESS_KEY: envSecretsProvider.getSecret('AWS_SECRET_ACCESS_KEY'),
        ANTHROPIC_API_KEY: envSecretsProvider.getSecret('ANTHROPIC_API_KEY'),
        STRIPE_SECRET_KEY: envSecretsProvider.getSecret('STRIPE_SECRET_KEY'),
        LOGFIRE_TOKEN: envSecretsProvider.getSecret('LOGFIRE_TOKEN')
      };
    }

    console.log('✓ Secrets loaded successfully');
    return true;
  } catch (error) {
    console.error('✗ Failed to initialize app:', error.message);
    process.exit(1);
  }
}

// ============================================================================
// MIDDLEWARE & SECURITY SETUP
// ============================================================================

const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const winston = require('winston');

// Logging
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Security headers
app.use(helmet());

// CORS
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true
}));

// Rate limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false
}));

// ============================================================================
// ROUTES
// ============================================================================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV 
  });
});

app.get('/users', (req, res) => {
  // This endpoint should require authentication
  // For demo purposes only:
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// Example of using secrets safely
app.post('/send-email', async (req, res) => {
  try {
    // Use secrets without logging them
    const apiKey = secrets.ANTHROPIC_API_KEY;

    // Call external service
    // const result = await anthropic.send({ apiKey, ... });

    res.json({ success: true });
  } catch (error) {
    logger.error('Email send failed:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
  });

  res.status(err.statusCode || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message
  });
});

// ============================================================================
// SERVER START
// ============================================================================

const PORT = process.env.PORT || 3000;

// Ensure secrets are loaded before starting server
if (require.main === module) {
  initializeApp().then(() => {
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });
  });
}

module.exports = { app, initializeApp };
