// config/rotation-tracker.js
const AWS = require('aws-sdk');
const dynamodb = new AWS.DynamoDB.DocumentClient();

class RotationTracker {
  async trackRotation(secretName, status, metadata = {}) {
    const rotationRecord = {
      secretId: secretName,
      status: status, // 'pending', 'in-progress', 'completed', 'failed'
      timestamp: new Date().toISOString(),
      rotatedAt: status === 'completed' ? new Date().toISOString() : null,
      nextRotationDue: this._calculateNextRotationDate(status),
      version: metadata.version || null,
      rotatedBy: metadata.rotatedBy || null,
      notes: metadata.notes || null,
      environment: process.env.NODE_ENV,
    };

    await dynamodb.put({
      TableName: 'credential-rotation-tracker',
      Item: rotationRecord,
    }).promise();

    return rotationRecord;
  }

  _calculateNextRotationDate(status) {
    if (status !== 'completed') return null;

    const rotationInterval = {
      'API_KEY': 90,
      'DATABASE_PASSWORD': 30,
      'JWT_SECRET': 180,
      'AWS_CREDENTIALS': 90,
    };

    const days = rotationInterval['API_KEY']; // Determine based on type
    const nextDate = new Date();
    nextDate.setDate(nextDate.getDate() + days);
    return nextDate.toISOString();
  }

  async getRotationStatus(secretName) {
    const result = await dynamodb.get({
      TableName: 'credential-rotation-tracker',
      Key: { secretId: secretName },
    }).promise();

    return result.Item || null;
  }

  async getExpiredCredentials() {
    // Find all credentials that need rotation
    const result = await dynamodb.scan({
      TableName: 'credential-rotation-tracker',
      FilterExpression: 'nextRotationDue < :now OR #status = :pending',
