// lib/secrets.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: 'us-east-1' });

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Return cached value if fresh
    if (this.cache.has(secretName)) {
      const { value, timestamp } = this.cache.get(secretName);
      if (Date.now() - timestamp < this.cacheTTL) {
        console.log(`[CACHE HIT] Retrieved secret: ${secretName}`);
        return value;
      }
    }

    console.log(`[CACHE MISS] Fetching from AWS Secrets Manager: ${secretName}`);

    try {
      const data = await client.getSecretValue({ SecretId: secretName }).promise();
      const secret = JSON.parse(data.SecretString);

      // Cache it
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now(),
      });

      return secret;
    } catch (error) {
      console.error(`Failed to get secret ${secretName}:`, error);
      throw new Error(`Could not retrieve secret: ${error.message}`);
    }
  }

  // Force refresh (useful after rotation)
  invalidate(secretName) {
    this.cache.delete(secretName);
    console.log(`[CACHE INVALIDATED] ${secretName}`);
  }
}

module.exports = new SecretsManager();
```

