        -d @jwt.json | jq -r '.auth.client_token')
    - export DB_URL=$(curl -s -H "X-Vault-Token: ${VAULT_TOKEN}" 
        "${VAULT_ADDR}/v1/secret/data/prod/database" | jq -r '.data.data.connection_string')
  script:
    - npm run deploy
  only:
    - main
