});

// Graceful shutdown with secret cleanup
process.on('SIGTERM', async () => {
  console.log('Cleaning up secrets from memory...');
  secrets.invalidate('prod/database');
  secrets.invalidate('prod/api-keys');
  process.exit(0);
});

(async () => {
  await bootstrap();
  app.listen(3000, () => {
    console.log('Server running on port 3000 (AWS Secrets Manager enabled)');
  });
})();
