      // Don't expose email unless user is authenticated and authorized
      ...(req.user?.role === 'admin' && { email: u.email })
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        limit,
        offset,
        total: allUsers.length
      }
    });

    // Audit logging
    console.log(`[AUDIT] User ${req.user?.id} accessed users list at ${new Date().toISOString()}`);

  } catch (error) {
    console.error('Error fetching users:', error);
    // Don't expose internal error details to client
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * POST /api/users
 * Create new user with full validation
 * Addresses: A03:2021 – Injection, A07:2021 – Authentication Failures
 */
app.post('/api/users', authenticateToken, (req, res) => {
  try {
    // Input validation
    const name = validateInput(req.body.name, 'string');
    const email = validateInput(req.body.email, 'email');

    if (!name || !email) {
      return res.status(400).json({ 
        error: 'Invalid input',
        details: 'Name (string) and email (valid email) are required'
      });
    }

    // Authorization: Only admins can create users
    if (req.user?.role !== 'admin') {
      return res.status(403).json({ error: 'Only administrators can create users' });
    }

    // Mock data creation - in production use parameterized queries
    const newUser = {
      id: Math.max(...[1, 2]) + 1,
      name,
      email
    };

    // Audit logging
    console.log(`[AUDIT] User ${req.user.id} created new user: ${newUser.id} at ${new Date().toISOString()}`);

    res.status(201).json(newUser);

  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * DELETE /api/users/:id
 * Delete user with authorization
 * Addresses: A01:2021 – Broken Access Control
 */
app.delete('/api/users/:id', authenticateToken, (req, res) => {
  try {
    const userId = validateInput(req.params.id, 'integer');

    if (!userId) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Authorization: Only admins can delete users
    if (req.user?.role !== 'admin') {
      return res.status(403).json({ error: 'Only administrators can delete users' });
    }

    // Mock deletion - in production use parameterized queries
    console.log(`[AUDIT] User ${req.user.id} deleted user: ${userId} at ${new Date().toISOString()}`);

    res.status(204).send();

  } catch (error) {
    console.error('Error deleting user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('[ERROR]', err);
  // Don't expose internal error details
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    // Only include details in development
    ...(process.env.NODE_ENV === 'development' && { details: err.message })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

// Only allow specified hostnames
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

