/**
 * SECURE SECRETS MANAGEMENT SYSTEM
 * 
 * This module provides centralized secrets management with support for:
 * - AWS Secrets Manager (Production)
 * - HashiCorp Vault (On-premises)
 * - Environment variables (Development)
 * - Secure caching with TTL
 * - Audit logging
 * - Automatic rotation detection
 */

const AWS = require('aws-sdk');
const NodeCache = require('node-cache');
const path = require('path');
const fs = require('fs');

/**
 * Secrets Manager Configuration
 */
class SecretsManager {
  constructor(options = {}) {
    this.environment = process.env.NODE_ENV || 'development';
    this.cache = new NodeCache({ stdTTL: 3600 }); // 1 hour cache
    this.auditLog = [];
    this.maxAuditSize = 1000;

    // Configure based on environment
    if (this.environment === 'production') {
      this.useAwsSecretsManager = true;
      this.awsClient = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    } else if (this.environment === 'staging') {
      // Use Vault for staging
      this.useVault = true;
      this.vaultClient = this.initializeVaultClient();
    } else {
      // Use local .env.local for development
      this.useLocalEnv = true;
      this.loadLocalSecrets();
    }
  }

  /**
   * Load secrets based on environment
   */
  async getSecret(secretName, fallbackEnvVar = null) {
    const startTime = Date.now();
    let secret = null;
    let source = null;

    try {
      // Check cache first
      const cachedSecret = this.cache.get(secretName);
      if (cachedSecret) {
        this.logAccess('CACHE_HIT', secretName, Date.now() - startTime);
        return cachedSecret;
      }

      if (this.useAwsSecretsManager) {
        secret = await this.getAwsSecret(secretName);
        source = 'AWS_SECRETS_MANAGER';
      } else if (this.useVault) {
        secret = await this.getVaultSecret(secretName);
        source = 'HASHICORP_VAULT';
      } else if (this.useLocalEnv) {
        secret = this.getLocalSecret(secretName);
        source = 'LOCAL_ENV';
      }

      // Fallback to environment variable if available
      if (!secret && fallbackEnvVar) {
        secret = process.env[fallbackEnvVar];
        source = `ENV_VAR(${fallbackEnvVar})`;

        // Log warning for development
        if (this.environment === 'development') {
          console.warn(`⚠️  Warning: Secret "${secretName}" not found in local store, falling back to ${fallbackEnvVar}`);
        }
      }

      if (!secret) {
        throw new Error(`Secret "${secretName}" not found and no fallback available`);
      }

      // Cache the secret
      this.cache.set(secretName, secret);
      this.logAccess('RETRIEVED', secretName, Date.now() - startTime, source);

      return secret;

    } catch (error) {
      this.logAccess('ERROR', secretName, Date.now() - startTime, null, error.message);
      throw new Error(`Failed to retrieve secret "${secretName}": ${error.message}`);
    }
  }

  /**
   * Get secret from AWS Secrets Manager
   */
  async getAwsSecret(secretName) {
    try {
      const data = await this.awsClient.getSecretValue({ 
        SecretId: secretName 
      }).promise();

      if (data.SecretString) {
        return JSON.parse(data.SecretString);
      } else {
        return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret "${secretName}" not found in AWS Secrets Manager`);
      }
      throw error;
    }
  }

  /**
   * Get secret from HashiCorp Vault
   */
  async getVaultSecret(secretName) {
    const vaultAddr = process.env.VAULT_ADDR || 'http://127.0.0.1:8200';
    const vaultToken = process.env.VAULT_TOKEN;

    if (!vaultToken) {
      throw new Error('VAULT_TOKEN environment variable not set');
    }

    try {
      const fetch = require('node-fetch');
      const response = await fetch(`${vaultAddr}/v1/secret/data/${secretName}`, {
        method: 'GET',
        headers: {
          'X-Vault-Token': vaultToken,
          'Content-Type': 'application/json'
        }
      });

      if (!response.ok) {
        if (response.status === 404) {
          throw new Error(`Secret "${secretName}" not found in Vault`);
        }
        throw new Error(`Vault API error: ${response.statusText}`);
      }

      const data = await response.json();
      return data.data.data;

    } catch (error) {
      throw error;
    }
  }

  /**
   * Get secret from local .env.local file (Development only)
   */
  loadLocalSecrets() {
    const localEnvPath = path.join(process.cwd(), '.env.local');

    if (!fs.existsSync(localEnvPath)) {
      console.warn(`⚠️  .env.local not found at ${localEnvPath}`);
      return;
    }

    const content = fs.readFileSync(localEnvPath, 'utf-8');
    const lines = content.split('\n');

    lines.forEach(line => {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key, value] = trimmed.split('=');
        if (key && value) {
          process.env[key] = value.replace(/^["']|["']$/g, ''); // Remove quotes
        }
      }
    });
  }

  /**
   * Get secret from local environment (fallback)
   */
  getLocalSecret(secretName) {
    // Convert secret name format: "db/password" -> "DB_PASSWORD"
    const envVarName = secretName
      .toUpperCase()
      .replace(/\//g, '_');

    return process.env[envVarName] || null;
  }

  /**
   * Initialize Vault client
   */
  initializeVaultClient() {
    // This would initialize a Vault client library
    // Example using node-vault:
    // const NodeVault = require('node-vault');
    // return NodeVault({ endpoint: process.env.VAULT_ADDR });
    return null;
  }

  /**
   * Log secret access for audit trail
   */
  logAccess(action, secretName, duration, source = null, error = null) {
    const timestamp = new Date().toISOString();
    const caller = this.getCallerInfo();

    const logEntry = {
      timestamp,
      action,
      secretName: this.maskSecretName(secretName), // Don't log full name
      duration: `${duration}ms`,
      source,
      caller,
      userId: process.env.USER_ID || 'system',
      error: error ? error.substring(0, 100) : null
    };

    this.auditLog.push(logEntry);

    // Keep audit log size bounded
    if (this.auditLog.length > this.maxAuditSize) {
      this.auditLog.shift();
    }

    // Log to external audit system in production
    if (this.environment === 'production') {
      this.sendToAuditService(logEntry);
    }

    // Log locally
    if (action === 'ERROR' || action === 'CACHE_HIT') {
      console.log(`[SECRETS] ${action}: ${this.maskSecretName(secretName)}`);
    }
  }

  /**
   * Mask sensitive parts of secret name
   */
  maskSecretName(secretName) {
    if (secretName.includes('password') || secretName.includes('key')) {
      return secretName.replace(/[a-zA-Z0-9]/g, '*');
    }
    return secretName;
  }

  /**
   * Get caller information for audit
   */
  getCallerInfo() {
    const stack = new Error().stack;
    const lines = stack.split('\n');
    return lines[3] ? lines[3].trim() : 'unknown';
  }

  /**
   * Send log to audit service
   */
  async sendToAuditService(logEntry) {
    // Send to CloudWatch Logs, ELK Stack, or similar
    // Example:
    // const params = {
    //   logGroupName: '/app/secrets-audit',
    //   logStreamName: 'access-logs',
    //   logEvents: [{ timestamp: Date.now(), message: JSON.stringify(logEntry) }]
    // };
    // await this.awsClient.putLogEvents(params).promise();
  }

  /**
   * Get audit log
   */
  getAuditLog() {
    return this.auditLog;
  }

  /**
   * Clear cache (useful for testing)
   */
  clearCache() {
    this.cache.flushAll();
  }
}

module.exports = SecretsManager;

/**
 * SECURE APPLICATION WITH PROPER SECRETS MANAGEMENT
 * 
 * This version demonstrates:
 * - Secure secret retrieval from centralized manager
 * - No hardcoded secrets
 * - Environment-specific configuration
 * - Proper error handling without exposing secrets
 * - Audit logging
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const SecretsManager = require('./lib_secrets_manager');

// Initialize secrets manager
const secretsManager = new SecretsManager();

const app = express();

/**
 * Middleware to inject secrets into request context
 * Secrets are accessed per-request, not stored in app state
 */
