#!/usr/bin/env node

/**
 * SECRETS ROTATION TRACKER
 * 
 * Tracks secret rotation metadata WITHOUT exposing secret values
 * Use this to manage rotation schedules and compliance
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class SecretRotationTracker {
  constructor(filename = 'secrets_rotation_audit.json') {
    this.auditFile = filename;
    this.loadAudit();
  }

  loadAudit() {
    if (fs.existsSync(this.auditFile)) {
      this.audit = JSON.parse(fs.readFileSync(this.auditFile, 'utf-8'));
    } else {
      this.audit = { secrets: [], rotations: [] };
    }
  }

  saveAudit() {
    fs.writeFileSync(this.auditFile, JSON.stringify(this.audit, null, 2));
  }

  /**
   * Register a secret for tracking (DO NOT PASS THE SECRET VALUE)
   */
  registerSecret(secretName, secretType, rotationFrequencyDays = 30) {
    const secretId = crypto.createHash('sha256').update(secretName).digest('hex');

    const existing = this.audit.secrets.find(s => s.id === secretId);
    if (existing) {
      console.log(`✓ Secret already registered: ${secretName}`);
      return;
    }

    const secret = {
      id: secretId,
      name: secretName,
      type: secretType, // 'api_key', 'password', 'jwt', 'database_url', etc.
      created: new Date().toISOString(),
      lastRotated: new Date().toISOString(),
      nextRotationDue: this.getNextRotationDate(rotationFrequencyDays),
      rotationFrequencyDays,
      status: 'active', // 'active', 'compromised', 'deprecated'
      rotationCount: 0,
      notes: ''
    };

    this.audit.secrets.push(secret);
    this.saveAudit();
    console.log(`✓ Registered: ${secretName} (${secretType})`);
  }

  /**
   * Log a rotation event (DO NOT PASS THE SECRET VALUE)
   */
  logRotation(secretName, reason = 'scheduled') {
    const secretId = crypto.createHash('sha256').update(secretName).digest('hex');
    const secret = this.audit.secrets.find(s => s.id === secretId);

    if (!secret) {
      throw new Error(`Secret not found: ${secretName}`);
    }

    const rotation = {
      secretId,
      secretName,
      timestamp: new Date().toISOString(),
      reason, // 'scheduled', 'compromised', 'policy_update', 'manual'
      rotatedBy: process.env.USER || 'system',
      rotationNumber: secret.rotationCount + 1,
      verificationStatus: 'pending' // 'pending', 'verified', 'failed'
    };

    secret.lastRotated = new Date().toISOString();
    secret.nextRotationDue = this.getNextRotationDate(secret.rotationFrequencyDays);
    secret.rotationCount += 1;

    this.audit.rotations.push(rotation);
    this.saveAudit();

    console.log(`✓ Logged rotation: ${secretName} (${reason})`);
  }

  /**
   * Mark secret as compromised (for incident response)
   */
  markCompromised(secretName, incidentDetails = '') {
    const secretId = crypto.createHash('sha256').update(secretName).digest('hex');
    const secret = this.audit.secrets.find(s => s.id === secretId);

    if (!secret) {
      throw new Error(`Secret not found: ${secretName}`);
    }

    secret.status = 'compromised';
    secret.notes = `COMPROMISED: ${new Date().toISOString()} - ${incidentDetails}`;

    this.audit.rotations.push({
      secretId,
      secretName,
      timestamp: new Date().toISOString(),
      reason: 'compromised',
      rotatedBy: process.env.USER || 'system',
      incidentDetails,
      verificationStatus: 'critical'
    });

    this.saveAudit();
    console.log(`⚠️  MARKED COMPROMISED: ${secretName}`);
  }

  /**
   * Get rotation schedule report
   */
  getRotationSchedule() {
    const now = new Date();
    const schedule = {
      overdue: [],
      dueThisWeek: [],
      dueThisMonth: [],
      upcoming: []
    };

    this.audit.secrets.forEach(secret => {
      const dueDate = new Date(secret.nextRotationDue);
      const daysUntilDue = Math.floor((dueDate - now) / (1000 * 60 * 60 * 24));

      const item = {
        name: secret.name,
        type: secret.type,
        dueDate: secret.nextRotationDue,
        daysUntilDue,
        lastRotated: secret.lastRotated,
        rotationCount: secret.rotationCount,
        status: secret.status
      };

      if (daysUntilDue < 0) {
        schedule.overdue.push(item);
      } else if (daysUntilDue <= 7) {
        schedule.dueThisWeek.push(item);
      } else if (daysUntilDue <= 30) {
        schedule.dueThisMonth.push(item);
      } else {
        schedule.upcoming.push(item);
      }
    });

    return schedule;
  }

  /**
   * Print rotation schedule
   */
  printSchedule() {
    const schedule = this.getRotationSchedule();

    console.log('\n' + '='.repeat(80));
    console.log('SECRETS ROTATION SCHEDULE');
    console.log('='.repeat(80));

    if (schedule.overdue.length > 0) {
      console.log('\n🔴 OVERDUE FOR ROTATION:');
      schedule.overdue.forEach(item => {
        console.log(`  • ${item.name} (${item.type})`);
        console.log(`    Due: ${item.dueDate} (${item.daysUntilDue} days overdue)`);
        console.log(`    Last rotated: ${item.lastRotated}`);
      });
    }

    if (schedule.dueThisWeek.length > 0) {
      console.log('\n🟠 DUE THIS WEEK:');
      schedule.dueThisWeek.forEach(item => {
        console.log(`  • ${item.name} (${item.type})`);
        console.log(`    Due: ${item.dueDate} (in ${item.daysUntilDue} days)`);
      });
    }

    if (schedule.dueThisMonth.length > 0) {
      console.log('\n🟡 DUE THIS MONTH:');
      schedule.dueThisMonth.forEach(item => {
        console.log(`  • ${item.name} (${item.type})`);
        console.log(`    Due: ${item.dueDate} (in ${item.daysUntilDue} days)`);
      });
    }

    if (schedule.upcoming.length > 0) {
      console.log('\n🟢 UPCOMING (30+ days):');
      schedule.upcoming.slice(0, 5).forEach(item => {
        console.log(`  • ${item.name} (${item.type}) - due in ${item.daysUntilDue} days`);
      });
      if (schedule.upcoming.length > 5) {
        console.log(`  ... and ${schedule.upcoming.length - 5} more`);
      }
    }

    console.log('\n' + '='.repeat(80) + '\n');
  }

  /**
   * Get audit report for compliance
   */
  getComplianceReport() {
    const totalSecrets = this.audit.secrets.length;
    const rotatedInLast30Days = this.audit.rotations.filter(r => {
      const rotationDate = new Date(r.timestamp);
      const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
      return rotationDate > thirtyDaysAgo;
    }).length;

    const compromisedSecrets = this.audit.secrets.filter(s => s.status === 'compromised').length;

    return {
      timestamp: new Date().toISOString(),
      totalSecrets,
      activeSecrets: this.audit.secrets.filter(s => s.status === 'active').length,
      compromisedSecrets,
      totalRotations: this.audit.rotations.length,
      rotationsLast30Days: rotatedInLast30Days,
      complianceStatus: rotatedInLast30Days > 0 ? 'In Progress' : 'Needs Attention'
    };
  }

  /**
   * Print compliance report
   */
  printComplianceReport() {
    const report = this.getComplianceReport();

    console.log('\n' + '='.repeat(80));
    console.log('SECRETS MANAGEMENT COMPLIANCE REPORT');
    console.log('='.repeat(80));
    console.log(`Generated: ${report.timestamp}`);
    console.log(`\nTotal Secrets Under Management: ${report.totalSecrets}`);
    console.log(`Active Secrets: ${report.activeSecrets}`);
    console.log(`Compromised Secrets: ${report.compromisedSecrets}`);
    console.log(`Total Rotations (All Time): ${report.totalRotations}`);
    console.log(`Rotations in Last 30 Days: ${report.rotationsLast30Days}`);
    console.log(`\nCompliance Status: ${report.complianceStatus}`);
    console.log('='.repeat(80) + '\n');
  }

  /**
   * Validation
   */
  getNextRotationDate(frequencyDays) {
    const date = new Date();
    date.setDate(date.getDate() + frequencyDays);
    return date.toISOString();
  }
}

// ============================================================================
// CLI INTERFACE
// ============================================================================

if (require.main === module) {
  const tracker = new SecretRotationTracker();
  const command = process.argv[2];
  const args = process.argv.slice(3);

  switch (command) {
    case 'register':
      if (args.length < 2) {
        console.error('Usage: register <secret-name> <type> [rotation-frequency-days]');
        process.exit(1);
      }
      tracker.registerSecret(args[0], args[1], parseInt(args[2]) || 30);
      break;

    case 'rotate':
      if (args.length < 1) {
        console.error('Usage: rotate <secret-name> [reason]');
        process.exit(1);
      }
      tracker.logRotation(args[0], args[1] || 'scheduled');
      break;

    case 'compromised':
      if (args.length < 1) {
        console.error('Usage: compromised <secret-name> [incident-details]');
        process.exit(1);
      }
      tracker.markCompromised(args[0], args[1] || '');
      break;

    case 'schedule':
      tracker.printSchedule();
      break;

    case 'report':
      tracker.printComplianceReport();
      break;

    case 'list':
      console.log('\nRegistered Secrets:');
      tracker.audit.secrets.forEach(s => {
        console.log(`  • ${s.name} (${s.type}) - ${s.status}`);
        console.log(`    Next rotation due: ${s.nextRotationDue}`);
        console.log(`    Rotations: ${s.rotationCount}`);
      });
      break;

    default:
      console.log(`
Secrets Rotation Tracker

Usage:
  node secret_rotation_tracker.js <command> [args]

Commands:
  register <name> <type> [freq]    Register a new secret for tracking
  rotate <name> [reason]            Log a rotation event
  compromised <name> [details]      Mark secret as compromised
  schedule                          Show rotation schedule
  report                            Show compliance report
  list                              List all tracked secrets

Examples:
  node secret_rotation_tracker.js register "database/password" "database" 30
  node secret_rotation_tracker.js rotate "database/password" "scheduled"
  node secret_rotation_tracker.js compromised "api/stripe" "exposed in logs"
  node secret_rotation_tracker.js schedule
  node secret_rotation_tracker.js report

Note: This tool tracks METADATA only, never handles actual secret values.
      `);
  }
}

module.exports = SecretRotationTracker;

#!/usr/bin/env node

/**
 * SECURE ROTATION REPORT GENERATOR
 * 
 * Generates compliance-ready rotation reports WITHOUT exposing secrets
 * Uses hashes for verification instead of actual values
 */

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

class RotationReportGenerator {
  constructor() {
    this.report = {
      timestamp: new Date().toISOString(),
      version: '1.0',
      entries: []
    };
  }

  /**
   * Add a rotation entry (never receives actual secret values)
   */
  addRotationEntry(options) {
    const {
      secretName,
      type,
      environment,
      rotatedBy,
      reason,
      preRotationTest,
      postRotationTest,
      notes = ''
    } = options;

    const secretId = crypto.createHash('sha256')
      .update(secretName)
      .digest('hex')
      .substring(0, 16);

    const entry = {
      secret_name: secretName,
      secret_id: secretId + '...',
      type,
      environment,
      rotation_timestamp: new Date().toISOString(),
      rotated_by: rotatedBy,
      rotation_reason: reason,

      pre_rotation: {
        status: preRotationTest.accessible ? 'VERIFIED' : 'FAILED',
        accessible: preRotationTest.accessible,
        hash_sha256: (preRotationTest.hash || '').substring(0, 16) + '...',
        format_valid: preRotationTest.formatValid,
        api_test: preRotationTest.apiTest ? 'PASSED' : 'FAILED'
      },

      post_rotation: {
        status: postRotationTest.accessible ? 'VERIFIED' : 'FAILED',
        accessible: postRotationTest.accessible,
        hash_sha256: (postRotationTest.hash || '').substring(0, 16) + '...',
        format_valid: postRotationTest.formatValid,
        api_test: postRotationTest.apiTest ? 'PASSED' : 'FAILED'
      },

      hash_changed: preRotationTest.hash !== postRotationTest.hash,
      notes
    };

    this.report.entries.push(entry);
  }

  /**
   * Generate markdown report
   */
  generateMarkdown() {
    let md = '# Credential Rotation Report\n\n';
    md += `**Generated:** ${this.report.timestamp}\n\n`;
    md += '> ⚠️ This report contains hashed credentials for verification purposes.\n';
    md += '> No plaintext secrets are included. Safe for compliance and auditing.\n\n';

    md += '## Summary\n\n';
    md += `- **Total Rotations:** ${this.report.entries.length}\n`;

    const successful = this.report.entries.filter(
      e => e.post_rotation.status === 'VERIFIED'
    ).length;

    md += `- **Successful:** ${successful}\n`;
    md += `- **Failed:** ${this.report.entries.length - successful}\n`;
    md += `- **Success Rate:** ${((successful / this.report.entries.length) * 100).toFixed(1)}%\n`;

    const allHashesChanged = this.report.entries.every(e => e.hash_changed);
    md += `- **All Hashes Changed:** ${allHashesChanged ? '✅ Yes' : '❌ No'}\n\n`;

    md += '## Rotation Details\n\n';

    this.report.entries.forEach((entry, index) => {
      md += `### ${index + 1}. ${entry.secret_name}\n\n`;
      md += `| Property | Value |\n`;
      md += `|---|---|\n`;
      md += `| Type | ${entry.type} |\n`;
      md += `| Environment | ${entry.environment} |\n`;
      md += `| Rotated By | ${entry.rotated_by} |\n`;
      md += `| Reason | ${entry.rotation_reason} |\n`;
      md += `| Secret ID | ${entry.secret_id} |\n\n`;

      md += `**Pre-Rotation Verification:**\n`;
      md += `- Status: ${entry.pre_rotation.status}\n`;
      md += `- Accessible: ${entry.pre_rotation.accessible ? '✅' : '❌'}\n`;
      md += `- Format Valid: ${entry.pre_rotation.format_valid ? '✅' : '❌'}\n`;
      md += `- API Test: ${entry.pre_rotation.api_test}\n`;
      md += `- Hash: \`${entry.pre_rotation.hash_sha256}\`\n\n`;

      md += `**Post-Rotation Verification:**\n`;
      md += `- Status: ${entry.post_rotation.status}\n`;
      md += `- Accessible: ${entry.post_rotation.accessible ? '✅' : '❌'}\n`;
      md += `- Format Valid: ${entry.post_rotation.format_valid ? '✅' : '❌'}\n`;
      md += `- API Test: ${entry.post_rotation.api_test}\n`;
      md += `- Hash: \`${entry.post_rotation.hash_sha256}\`\n\n`;

      md += `**Rotation Verification:**\n`;
      md += `- Hash Changed: ${entry.hash_changed ? '✅ **YES** (Rotation Confirmed)' : '❌ NO (Failed)'}\n`;

      if (entry.notes) {
        md += `\n**Notes:** ${entry.notes}\n`;
      }

      md += '\n---\n\n';
    });

    md += '## Compliance Notes\n\n';
    md += '✅ No plaintext secrets in this report\n';
    md += '✅ Hash comparison proves rotation occurred\n';
    md += '✅ Safe for version control and email\n';
    md += '✅ Suitable for SOC 2, ISO 27001, PCI-DSS audits\n\n';

    md += '## Next Steps\n\n';
    md += '1. Archive this report in compliance system\n';
    md += '2. Schedule next rotation cycle (30-90 days)\n';
    md += '3. Monitor for authentication failures\n';
    md += '4. Confirm old credentials are deactivated\n';

    return md;
  }

  /**
   * Generate JSON report for programmatic use
   */
  generateJSON() {
    return JSON.stringify(this.report, null, 2);
  }

  /**
   * Save report to file
   */
  saveReport(filename, format = 'markdown') {
    const content = format === 'json' 
      ? this.generateJSON() 
      : this.generateMarkdown();

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-').split('T')[0];
    const outputFile = filename.replace('TIMESTAMP', timestamp);

    fs.writeFileSync(outputFile, content);
    console.log(`✓ Report saved to: ${outputFile}`);
    return outputFile;
  }
}

