```
PORT=3000
NODE_ENV=development
JWT_SECRET=your-secret-key-here-change-in-production
DATABASE_URL=postgresql://user:pass@localhost/dbname
ALLOWED_ORIGINS=https://example.com,https://app.example.com
```

---

### 9. NO SQL/NOSQL INJECTION PROTECTION (SEVERITY: CRITICAL)
**Issue**: If database queries were added, no parameterized query protection shown
**Risk**: OWASP A03:2021 – Injection

**Recommendation**: Always use parameterized queries/prepared statements
```javascript
// BAD - Vulnerable to SQL Injection
app.get('/users/:id', (req, res) => {
  // DON'T DO THIS
  db.query(`SELECT * FROM users WHERE id = ${req.params.id}`, (err, result) => {
    res.json(result);
  });
});

// GOOD - Using parameterized queries
app.get('/users/:id', authenticateToken, (req, res) => {
  db.query('SELECT * FROM users WHERE id = $1', [req.params.id], (err, result) => {
    if (err) {
      securityLogger.error({ error: err, userId: req.user.id });
      return res.status(500).json({ error: 'Database error' });
    }
    res.json(result);
  });
});

// For Mongoose/NoSQL:
app.get('/users/:id', authenticateToken, (req, res) => {
  User.findById(req.params.id, (err, user) => {
    if (err) {
      return res.status(500).json({ error: 'Error fetching user' });
    }
    res.json(user);
  });
});
```

---

### 10. NO SENSITIVE DATA PROTECTION (SEVERITY: HIGH)
**Issue**: Exposing email addresses in plaintext; no data masking for sensitive fields
**Risk**: PII exposure; OWASP A02:2021 – Cryptographic Failures

**Recommendation**: Mask/redact sensitive data
```javascript
app.get('/users', authenticateToken, (req, res) => {
  // Mask email addresses before sending
  const users = [
    { id: 1, name: 'Alice', email: maskEmail('alice@example.com') },
    { id: 2, name: 'Bob', email: maskEmail('bob@example.com') },
  ];
  res.json(users);
});

function maskEmail(email) {
  const [local, domain] = email.split('@');
  const masked = local.substring(0, 2) + '*'.repeat(Math.max(0, local.length - 2)) + '@' + domain;
  return masked;
}

// Or use serialization library
const { Serialize } = require('class-transformer');
// Only expose selected fields in responses
```

