/**
 * Secure Express.js Application Template
 * Implements OWASP Top 10 2021 protections
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { v4: uuidv4 } = require('uuid');
const morgan = require('morgan');
const winston = require('winston');

// ============================================================================
// CONFIGURATION & ENVIRONMENT VARIABLES
// ============================================================================

const config = {
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  jwtSecret: process.env.JWT_SECRET || 'change-me-in-production',
  allowedOrigins: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
};

// Validate critical environment variables in production
if (config.nodeEnv === 'production') {
  if (!process.env.JWT_SECRET || process.env.JWT_SECRET === 'change-me-in-production') {
    throw new Error('JWT_SECRET environment variable must be set and changed in production');
  }
}

// ============================================================================
// LOGGING SETUP
// ============================================================================

const securityLogger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'express-app' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/security.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  securityLogger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// EXPRESS APP INITIALIZATION
// ============================================================================

const app = express();

// ============================================================================
// MIDDLEWARE: REQUEST ID & LOGGING
// ============================================================================

// Add request ID for tracing
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// HTTP request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => securityLogger.info(message),
  },
}));

// ============================================================================
// MIDDLEWARE: SECURITY HEADERS
// ============================================================================

// Helmet.js - Set various HTTP headers for protection
app.use(helmet());

// Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  next();
});

// ============================================================================
// MIDDLEWARE: CORS
// ============================================================================

const corsOptions = {
  origin: (origin, callback) => {
    if (!origin || config.allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      securityLogger.warn({ type: 'CORS_VIOLATION', origin, requestId: req?.id });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
