# Security Best Practices for Express.js Applications

## 1. INPUT VALIDATION & OUTPUT ENCODING

### 1.1 Preventing Injection Attacks (OWASP A03:2021)

**SQL Injection Prevention**
```javascript
// ❌ VULNERABLE - String interpolation
db.query(`SELECT * FROM users WHERE email = '${req.body.email}'`);

// ✅ SECURE - Parameterized queries
db.query('SELECT * FROM users WHERE email = $1', [req.body.email]);

// ✅ SECURE - Using ORM
User.findOne({ email: req.body.email });
```

**NoSQL Injection Prevention**
```javascript
// ❌ VULNERABLE
db.collection('users').find({ $where: req.query.filter });

// ✅ SECURE
db.collection('users').findOne({ email: req.body.email });
```

**Command Injection Prevention**
```javascript
// ❌ VULNERABLE
child_process.exec(`process_file ${req.files.upload.name}`);

// ✅ SECURE
child_process.execFile('process_file', [req.files.upload.name]);
```

### 1.2 XSS Prevention (Output Encoding)

```javascript
const escapeHtml = require('escape-html');
const xss = require('xss');

// Escape HTML characters
const safe = escapeHtml(userInput);

// Full XSS protection
const sanitized = xss(userInput, {
  whiteList: {},
  stripIgnoredTag: true,
});
```

## 2. AUTHENTICATION & AUTHORIZATION

### 2.1 Password Management

```javascript
const bcrypt = require('bcrypt');

// ❌ NEVER store plaintext passwords
db.users.create({ email, password });

// ✅ SECURE - Hash passwords with salt
async function registerUser(email, password) {
  const saltRounds = 12; // Increase for production
  const hashedPassword = await bcrypt.hash(password, saltRounds);
  return db.users.create({ email, password: hashedPassword });
}

// ✅ SECURE - Verify passwords
async function login(email, password) {
  const user = await db.users.findOne({ email });
  const isValid = await bcrypt.compare(password, user.password);
  return isValid ? user : null;
}
```

### 2.2 JWT Best Practices

```javascript
const jwt = require('jsonwebtoken');

// ✅ SECURE - Proper JWT configuration
const token = jwt.sign(
  { 
    id: user.id, 
    email: user.email,
    // ❌ NEVER include sensitive data
    // password: user.password,
  },
  process.env.JWT_SECRET,
  { 
    expiresIn: '24h',
    algorithm: 'HS256',
    issuer: 'myapp',
    audience: 'myapp-users',
  }
);

// ✅ SECURE - Verify JWT properly
jwt.verify(token, process.env.JWT_SECRET, {
  algorithms: ['HS256'],
  issuer: 'myapp',
  audience: 'myapp-users',
});
```

### 2.3 Authorization Checks

```javascript
// ✅ SECURE - Proper authorization
app.delete('/users/:id', authenticateToken, (req, res) => {
  // Only admins or the user themselves can delete
  if (req.user.role !== 'admin' && req.user.id !== req.params.id) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  // Delete user...
});
```

## 3. SECURE DATA TRANSMISSION

### 3.1 HTTPS/TLS Enforcement

```javascript
// ✅ Force HTTPS in production
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect('https://' + req.get('host') + req.url);
  }
  next();
});

// ✅ HSTS Header (already set by Helmet)
// Tells browsers to only use HTTPS for 1 year
app.use(helmet.hsts({ 
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true 
}));
```

### 3.2 Sensitive Header Management

```javascript
// ✅ Hide sensitive headers
app.use(helmet.hidePoweredBy()); // Remove X-Powered-By header
app.use(helmet.noSniff()); // Prevent MIME type sniffing
app.use(helmet.xssFilter()); // Enable XSS protection
app.use(helmet.frameguard({ action: 'deny' })); // Prevent clickjacking

// ✅ Custom headers for security
app.use((req, res, next) => {
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  next();
});
```

## 4. SESSION & COOKIE SECURITY

### 4.1 Secure Cookie Configuration

```javascript
const session = require('express-session');

app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production', // HTTPS only
    httpOnly: true, // Prevent XSS access
    sameSite: 'strict', // CSRF protection
    maxAge: 3600000, // 1 hour
    domain: process.env.COOKIE_DOMAIN,
  },
}));
```

## 5. DEPENDENCY MANAGEMENT

### 5.1 Regular Updates

```bash
# Check for vulnerabilities
npm audit

# Fix automatically
npm audit fix

# Check for outdated packages
npm outdated

# Update packages safely
npm update

# In development: track security advisories
npm install npm-check-updates -g
ncu -u
```

### 5.2 Use Trustworthy Packages

- Check npm package downloads and GitHub stars
- Review package dependencies
- Use `npm ci` for reproducible installs (in CI/CD)
- Lock versions with `package-lock.json`

## 6. SECRETS MANAGEMENT

### 6.1 Environment Variables (NOT in Code)

```javascript
// ❌ NEVER hardcode secrets
const API_KEY = 'sk_live_REDACTED';

// ✅ SECURE - Use environment variables
const API_KEY = process.env.STRIPE_API_KEY;

if (!API_KEY && process.env.NODE_ENV === 'production') {
  throw new Error('STRIPE_API_KEY is required in production');
}
```

### 6.2 .gitignore Configuration

```
# .gitignore
.env
.env.local
.env.*.local
.env.*
node_modules/
logs/
*.log
.DS_Store
secrets/
private_keys/
```

### 6.3 Secrets Vault (Production)

```javascript
// Use AWS Secrets Manager, HashiCorp Vault, or similar
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager();

async function getSecret(secretName) {
  try {
    const data = await client.getSecretValue({ SecretId: secretName }).promise();
    return JSON.parse(data.SecretString);
  } catch (error) {
    throw new Error(`Failed to retrieve secret: ${error.message}`);
  }
}
```

## 7. ERROR HANDLING & LOGGING

### 7.1 Safe Error Messages

```javascript
// ❌ DANGEROUS - Exposes internals
app.use((err, req, res, next) => {
  res.status(500).json({ error: err.message, stack: err.stack });
});

// ✅ SECURE - Safe error messages
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';

  logger.error({
    message: err.message,
    stack: err.stack,
    userId: req.user?.id,
    path: req.path,
  });

  res.status(500).json({
    error: isDev ? err.message : 'Internal Server Error',
    requestId: req.id,
  });
});
```

### 7.2 Security Event Logging

```javascript
const winston = require('winston');

const securityLogger = winston.createLogger({
  format: winston.format.json(),
