```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
});

let cachedSecrets = null;
const CACHE_TTL = 3600000; // 1 hour
let lastCacheTime = 0;

async function getSecrets() {
  // Check cache validity
  if (cachedSecrets && Date.now() - lastCacheTime < CACHE_TTL) {
    return cachedSecrets;
  }

  try {
    const data = await client
      .getSecretValue({
        SecretId: `${process.env.ENVIRONMENT}/app-secrets`,
      })
      .promise();

    let secrets;
    if ('SecretString' in data) {
      secrets = JSON.parse(data.SecretString);
    } else {
      secrets = Buffer.from(data.SecretBinary, 'base64').toString('utf-8');
    }

    cachedSecrets = secrets;
    lastCacheTime = Date.now();

    return secrets;
  } catch (error) {
    console.error('Failed to retrieve secrets:', error);
    throw new Error('Unable to load application secrets');
  }
}

module.exports = { getSecrets };
```

