**Implementation:**

```javascript
// config/vault.js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN,
});

let secretsCache = null;
const CACHE_TTL = 3600000; // 1 hour
let lastFetch = 0;

async function getSecretsFromVault() {
  // Return cached secrets if still valid
  if (secretsCache && Date.now() - lastFetch < CACHE_TTL) {
    console.log('[Vault] Returning cached secrets');
    return secretsCache;
  }

  try {
    console.log('[Vault] Fetching secrets from Vault...');
    const path = `kv/data/app/${process.env.NODE_ENV || 'development'}`;
    const response = await vault.read(path);

    secretsCache = response.data.data;
    lastFetch = Date.now();

    console.log('[Vault] Secrets loaded successfully');
    return secretsCache;
  } catch (error) {
    console.error('[Vault] Error fetching secrets:', error.message);

    // Fallback to .env only in development
    if (process.env.NODE_ENV !== 'production') {
      console.warn('[Vault] Falling back to .env file');
      return process.env;
    }

    throw new Error('Failed to load secrets from Vault');
  }
}

// Implement secret rotation
async function rotateSecrets() {
  console.log('[Vault] Rotating secrets...');
  secretsCache = null;
  return getSecretsFromVault();
}

module.exports = {
  getSecretsFromVault,
  rotateSecrets,
};
```

**Usage in app.js:**

```javascript
const { getSecretsFromVault } = require('./config/vault');

let appSecrets;

// Initialize secrets on startup
async function initializeSecrets() {
  appSecrets = await getSecretsFromVault();

  // Refresh secrets every 30 minutes
  setInterval(async () => {
    try {
      appSecrets = await getSecretsFromVault();
    } catch (error) {
      console.error('Failed to refresh secrets:', error);
    }
  }, 30 * 60 * 1000);
}

app.use((req, res, next) => {
  if (!appSecrets) {
    return res.status(500).json({ error: 'Secrets not initialized' });
  }
  req.secrets = appSecrets;
  next();
});

// Start server
initializeSecrets().then(() => {
  app.listen(3000, () => console.log('Server running'));
});
```

