```javascript
// config/gcp-secrets.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

const client = new SecretManagerServiceClient();

async function getGCPSecrets() {
  const projectId = process.env.GCP_PROJECT_ID;
  const secretName = `projects/${projectId}/secrets/app-secrets/versions/latest`;

  try {
    const [version] = await client.accessSecretVersion({ name: secretName });
    const secretString = version.payload.data.toString('utf8');
    return JSON.parse(secretString);
  } catch (error) {
    console.error('Error accessing GCP Secret Manager:', error);
    throw error;
  }
}

module.exports = { getGCPSecrets };
```

