    logger.warn({ event: 'login_attempt', username, ip: req.ip, reason: 'missing_credentials' });
    return res.status(400).json({ error: 'Username and password required' });
  }

  if (typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input types' });
  }

  // TODO: Implement proper password verification with bcrypt
  // This is simplified for demonstration
  if (username === 'admin' && password === 'password') {
    const token = jwt.sign(
      { userId: 1, username, role: 'admin' },
      secret,
      { expiresIn: '1h' }
    );

    logger.info({ event: 'login_success', username, ip: req.ip });
    return res.json({ token });
  }

  logger.warn({ event: 'login_failure', username, ip: req.ip, reason: 'invalid_credentials' });
  return res.status(401).json({ error: 'Invalid credentials' });
});

// Get CSRF token
app.get('/api/csrf-token', csrfProtection, (req, res) => {
  res.json({ csrfToken: req.csrfToken() });
});

// Get users (Protected endpoint)
app.get('/api/users', verifyToken, [
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('name').optional().isString().trim().isLength({ min: 1, max: 100 }),
], (req, res) => {
  // Validate query parameters
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn({ event: 'invalid_query', errors: errors.array(), path: req.path });
    return res.status(400).json({ errors: errors.array() });
  }

  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
  ];

  // Filter by role - only admins see emails
  let filteredUsers = allUsers;

  if (req.query.id) {
    filteredUsers = filteredUsers.filter(u => u.id === req.query.id);
  }

  if (req.query.name) {
    filteredUsers = filteredUsers.filter(u => u.name.toLowerCase().includes(req.query.name.toLowerCase()));
  }

  // Remove sensitive data based on user role
  if (req.user.role !== 'admin') {
    filteredUsers = filteredUsers.map(u => ({
      id: u.id,
      name: u.name,
    }));
  }

  logger.info({ event: 'users_retrieved', count: filteredUsers.length, userId: req.user.id });
  res.json(filteredUsers);
});

// Create user (Protected, CSRF-protected, ADMIN-only)
app.post('/api/users', verifyToken, csrfProtection, express.json(), (req, res) => {
  // Authorization check
  if (req.user.role !== 'admin') {
    logger.warn({ event: 'unauthorized_access', path: req.path, userId: req.user.id });
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  const { name, email } = req.body;

  // Input validation
  if (!name || !email) {
    return res.status(400).json({ error: 'Name and email required' });
  }

  if (typeof name !== 'string' || name.length > 100) {
    return res.status(400).json({ error: 'Invalid name' });
  }

  if (typeof email !== 'string' || !email.includes('@')) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  logger.info({ event: 'user_created', name, email, userId: req.user.id });
  res.status(201).json({ id: 3, name, email, role: 'user' });
});

// ===================================================================
// ERROR HANDLING
// ===================================================================

// 404 handler
app.use((req, res) => {
  logger.warn({ event: '404', path: req.path, method: req.method });
  res.status(404).json({ error: 'Not found' });
});

// Error handling middleware
app.use((err, req, res, next) => {
  // CSRF token errors
  if (err.code === 'EBADCSRFTOKEN') {
    logger.warn({ event: 'csrf_error', path: req.path, ip: req.ip });
    return res.status(403).json({ error: 'Invalid CSRF token' });
  }

  // JWT errors
  if (err.name === 'UnauthorizedError') {
    logger.warn({ event: 'jwt_error', message: err.message, ip: req.ip });
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Log full error details
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Send generic response to client
  if (process.env.NODE_ENV === 'production') {
    res.status(err.status || 500).json({
      error: 'An error occurred',
    });
  } else {
    res.status(err.status || 500).json({
      error: err.message,
      stack: err.stack,
    });
  }
});

// ===================================================================
// SERVER STARTUP
// ===================================================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  logger.info({ event: 'server_started', port: PORT, env: process.env.NODE_ENV });
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

