/**
 * Secure Configuration Management
 * Loads configuration from environment variables with validation
 * Never hardcodes or logs secrets
 */

require('dotenv').config();

// List of required environment variables
const REQUIRED_VARS = {
  production: [
    'NODE_ENV',
    'PORT',
    'JWT_SECRET',
    'DATABASE_URL',
  ],
  development: [
    'NODE_ENV',
    'PORT',
  ],
  test: [
    'NODE_ENV',
    'PORT',
  ]
};

/**
 * Validate that all required environment variables are set
 */
function validateEnvironment() {
  const nodeEnv = process.env.NODE_ENV || 'development';
  const required = REQUIRED_VARS[nodeEnv] || REQUIRED_VARS.development;
  const missing = [];

  required.forEach(varName => {
    if (!process.env[varName]) {
      missing.push(varName);
    }
  });

  if (missing.length > 0) {
    throw new Error(
      `Missing required environment variables: ${missing.join(', ')}\n` +
      `Please set these in your .env file or environment.\n` +
      `See .env.example for reference.`
    );
  }
}

/**
 * Get a secret securely
 * @param {string} key - The environment variable name
 * @param {string} defaultValue - Optional default (only for non-sensitive vars)
 * @returns {string} The secret value
 */
function getSecret(key, defaultValue = null) {
  const value = process.env[key];

  if (!value && !defaultValue) {
    throw new Error(
      `Secret "${key}" is required but not set. ` +
      `Check your .env file or environment variables.`
    );
  }

  return value || defaultValue;
}

/**
 * Get a configuration value
 * @param {string} key - The configuration key
 * @param {any} defaultValue - Optional default value
 * @returns {any} The configuration value
 */
function getConfig(key, defaultValue = null) {
  const value = process.env[key];
  return value !== undefined ? value : defaultValue;
}

/**
 * Redact sensitive values for logging
 * @param {string} value - The value to redact
 * @param {number} visibleChars - Number of chars to show
 * @returns {string} Redacted value
 */
function redactSecret(value, visibleChars = 4) {
  if (!value || typeof value !== 'string') return '***REDACTED***';
  if (value.length <= visibleChars) return '***';
  return value.substring(0, visibleChars) + '***' + value.slice(-visibleChars);
}

// Validate environment on startup
try {
  validateEnvironment();
} catch (error) {
  console.error('❌ Configuration Error:', error.message);
  process.exit(1);
}

// Configuration object
const config = {
  // Application
  nodeEnv: getConfig('NODE_ENV', 'development'),
  port: parseInt(getConfig('PORT', '3000'), 10),
  isProduction: process.env.NODE_ENV === 'production',
  isDevelopment: process.env.NODE_ENV === 'development',

  // Secrets (note: these throw if not set in required environments)
  jwt: {
    secret: () => getSecret('JWT_SECRET'),
    expiresIn: getConfig('JWT_EXPIRES_IN', '1h'),
  },

  // Database
  database: {
    url: () => getSecret('DATABASE_URL', null),
  },

  // AWS
  aws: {
    region: getConfig('AWS_REGION', 'us-east-1'),
    accessKeyId: () => getSecret('AWS_ACCESS_KEY_ID', null),
    secretAccessKey: () => getSecret('AWS_SECRET_ACCESS_KEY', null),
  },

  // API Keys
  anthropic: {
    apiKey: () => getSecret('ANTHROPIC_API_KEY', null),
  },

  stripe: {
    secretKey: () => getSecret('STRIPE_SECRET_KEY', null),
  },

  // Logging
  logging: {
    level: getConfig('LOG_LEVEL', 'info'),
    token: () => getSecret('LOGFIRE_TOKEN', null),
  },

  // CORS
  cors: {
    allowedOrigins: getConfig('ALLOWED_ORIGINS', 'http://localhost:3000').split(','),
  },
};

/**
 * Log configuration (with secrets redacted)
 * Safe to include in logs without exposing secrets
