### Tier 3: Production (Secrets Manager)

**RECOMMENDED: Use a dedicated secrets manager**

#### Option A: AWS Secrets Manager (Recommended for AWS)

```javascript
// secrets-manager.js - Fetch secrets from AWS Secrets Manager
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

async function getSecret(secretName) {
  try {
    const data = await secretsManager.getSecretValue({ 
      SecretId: secretName 
    }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }

    const buff = Buffer.from(data.SecretBinary, 'base64');
    return buff.toString('ascii');
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw error;
  }
}

module.exports = { getSecret };
```

**Store secrets in AWS Console:**
```bash
aws secretsmanager create-secret \
  --name prod/app/db-credentials \
  --secret-string '{"username":"admin","password":"secure-password-here"}'

aws secretsmanager create-secret \
  --name prod/app/jwt-secret \
  --secret-string '{"secret":"your-jwt-secret-min-32-chars"}'
```

**Usage in app:**
```javascript
const { getSecret } = require('./secrets-manager');

async function initializeApp() {
  const dbCreds = await getSecret('prod/app/db-credentials');
  const jwtConfig = await getSecret('prod/app/jwt-secret');

  const config = {
    database: {
      username: dbCreds.username,
      password: dbCreds.password,
    },
    jwt: {
      secret: jwtConfig.secret,
    }
  };

  return config;
}
```

#### Option B: HashiCorp Vault (Enterprise-Grade)

```javascript
// vault-client.js
const axios = require('axios');

const VAULT_ADDR = process.env.VAULT_ADDR || 'http://localhost:8200';
const VAULT_TOKEN = process.env.VAULT_TOKEN;

async function getSecretFromVault(path) {
  try {
    const response = await axios.get(`${VAULT_ADDR}/v1/${path}`, {
      headers: {
        'X-Vault-Token': VAULT_TOKEN,
      }
    });

    return response.data.data.data;
  } catch (error) {
    console.error(`Error retrieving secret from Vault at ${path}:`, error);
    throw error;
  }
}

module.exports = { getSecretFromVault };
```

