              this.secrets = await loadSecretsFromVault();
            } else if (process.env.AWS_REGION) {
              this.secrets = await loadSecretsFromAWSSecretsManager();
            } else if (process.env.KEY_VAULT_NAME) {
              this.secrets = await loadSecretsFromAzureKeyVault();
            } else {
