      console.log('[CONFIG] ✅ Secrets loaded and validated successfully');
    } catch (error) {
      console.error('[CONFIG] ❌ Failed to initialize configuration:', error.message);
      throw error;
    }
  }

  /**
   * Validate that all required secrets are present
   */
  validate() {
    const requiredSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
      'API_KEY',
    ];

    const missing = requiredSecrets.filter(secret => !this.secrets[secret]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    this.validated = true;
    console.log('[CONFIG] ✅ All required secrets are present');
  }

  /**
   * Get a secret safely
   */
  get(key, defaultValue = null) {
    if (!this.validated) {
      throw new Error('Configuration not validated. Call load() first.');
    }

    const value = this.secrets[key];
    if (!value && defaultValue === null) {
      throw new Error(`Secret not found: ${key}`);
    }

    return value || defaultValue;
  }

  /**
   * Check if a secret exists
   */
  has(key) {
    return this.validated && !!this.secrets[key];
  }
}

