/**
 * SECURE APPLICATION IMPLEMENTATION
 * This file demonstrates security best practices for Express.js
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');

const app = express();

// ============================================================================
// 1. SECURITY HEADERS (Using Helmet)
// ============================================================================
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));

// ============================================================================
// 2. CORS PROTECTION
// ============================================================================
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3001'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
};

app.use(cors(corsOptions));

// ============================================================================
// 3. REQUEST LOGGING
// ============================================================================
morgan.token('user-id', (req) => req.user?.id || 'anonymous');
app.use(morgan(':remote-addr - :user-id [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] - :response-time ms'));

// ============================================================================
// 4. REQUEST SIZE LIMITING
// ============================================================================
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// 5. RATE LIMITING
// ============================================================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Skip health checks
});

// Stricter limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts
  message: 'Too many login attempts, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// ============================================================================
// 6. AUTHENTICATION MIDDLEWARE
// ============================================================================
const SECRET_KEY = process.env.JWT_SECRET || 'your-secret-key-change-in-production';

const authMiddleware = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      error: {
        message: 'No token provided',
        code: 'NO_TOKEN',
      },
    });
  }

  const token = authHeader.substring(7); // Remove "Bearer " prefix

  try {
    const decoded = jwt.verify(token, SECRET_KEY);
    req.user = decoded;
    next();
  } catch (err) {
    const status = err.name === 'TokenExpiredError' ? 401 : 403;
    return res.status(status).json({
      error: {
        message: status === 401 ? 'Token expired' : 'Invalid token',
        code: status === 401 ? 'TOKEN_EXPIRED' : 'INVALID_TOKEN',
      },
    });
  }
};

// ============================================================================
// 7. PROTECTED HEALTH ENDPOINT (No auth required but logged)
// ============================================================================
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// ============================================================================
// 8. LOGIN ENDPOINT (Token generation)
// ============================================================================
app.post('/login', authLimiter, (req, res) => {
  try {
    // In production, validate credentials against a database
    const username = req.body?.username;

    if (!username || typeof username !== 'string' || username.length === 0) {
      return res.status(400).json({
        error: {
          message: 'Invalid username',
          code: 'INVALID_USERNAME',
        },
      });
    }

    // Create JWT token (expires in 1 hour)
    const token = jwt.sign(
      { id: 1, username },
      SECRET_KEY,
      { expiresIn: '1h' }
    );

    res.json({
      token,
      expiresIn: 3600, // seconds
    });
  } catch (err) {
    res.status(500).json({
      error: {
        message: 'Internal server error',
        code: 'INTERNAL_ERROR',
      },
    });
  }
});

// ============================================================================
// 9. PROTECTED USERS ENDPOINT (With input validation)
// ============================================================================
app.get('/users',
  authMiddleware,
  query('id').optional().isInt().toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: {
          message: 'Invalid query parameters',
          code: 'VALIDATION_ERROR',
          details: errors.array(),
        },
      });
    }

    const { id, limit = 10 } = req.query;

    // Return only non-sensitive fields
    let users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    // Filter by ID if provided
    if (id) {
      users = users.filter(u => u.id === id);
    }

    // Apply limit
    users = users.slice(0, limit);

    res.json({
      data: users,
      count: users.length,
    });
  }
);

// ============================================================================
// 10. 404 HANDLER
// ============================================================================
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Not found',
      code: 'NOT_FOUND',
      path: req.path,
    },
  });
});

// ============================================================================
// 11. GLOBAL ERROR HANDLER (Must be last)
// ============================================================================
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal Server Error',
      code: err.code || 'INTERNAL_ERROR',
      status: err.status || 500,
      ...(isDevelopment && { stack: err.stack }),
    },
  });
});

// ============================================================================
// 12. HTTPS SETUP (In production)
// ============================================================================
const PORT = process.env.PORT || 3000;

if (process.env.NODE_ENV === 'production') {
  const https = require('https');
  const fs = require('fs');

  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH),
  };

  https.createServer(options, app).listen(PORT, () => {
    console.log(`Secure server running on port ${PORT}`);
  });
} else {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

