# Security Migration Guide: From Vulnerable to Secure

## Overview
This guide provides step-by-step instructions to migrate the current `app.js` to a secure implementation with minimal downtime.

---

## Phase 1: Preparation (Before deployment)

### Step 1: Set up Environment
```bash
# Create .env file
cat > .env << 'ENVEND'
NODE_ENV=production
PORT=3000
JWT_SECRET=$(openssl rand -base64 32)
ALLOWED_ORIGINS=https://yourdomain.com
ENVEND

# Keep the secret safe - never commit to version control
```

### Step 2: Install Dependencies
```bash
npm install helmet cors express-rate-limit express-validator jsonwebtoken morgan dotenv
npm audit

# Fix any vulnerabilities
npm audit fix
npm audit fix --force (if needed, use cautiously)
```

### Step 3: Update package.json
```json
{
  "scripts": {
    "start": "NODE_ENV=production node app.js",
    "dev": "NODE_ENV=development nodemon app.js",
    "test": "jest",
    "audit": "npm audit",
    "audit:fix": "npm audit fix"
  }
}
```

---

## Phase 2: Migration (Step-by-step code changes)

### Step 1: Load Environment Variables
**Add to top of app.js:**
```javascript
require('dotenv').config();
```

### Step 2: Import Required Modules
```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
```

### Step 3: Create App Instance
```javascript
const app = express();
```

### Step 4: Add Security Middleware (in order)
```javascript
// 1. Security headers
app.use(helmet());

// 2. Logging
app.use(morgan(':remote-addr - :user-id [:date[clf]] ":method :url" :status'));

// 3. CORS
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3001'],
  credentials: true,
};
app.use(cors(corsOptions));

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' }));

// 5. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);
```

### Step 5: Create Authentication Middleware
```javascript
const SECRET_KEY = process.env.JWT_SECRET;

const authMiddleware = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token provided' });
  }

  const token = authHeader.substring(7);

  try {
    const decoded = jwt.verify(token, SECRET_KEY);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};
```

### Step 6: Add Health Endpoint (No auth required)
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

### Step 7: Add Login Endpoint (NEW)
```javascript
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
});

app.post('/login', authLimiter, (req, res) => {
  try {
    const { username } = req.body;

    if (!username || typeof username !== 'string') {
      return res.status(400).json({ error: 'Invalid username' });
    }

    // In production, validate against database
    const token = jwt.sign(
      { id: 1, username },
      SECRET_KEY,
      { expiresIn: '1h' }
    );

    res.json({ token, expiresIn: 3600 });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

### Step 8: Update Users Endpoint (CHANGED)
```javascript
// BEFORE (VULNERABLE):
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// AFTER (SECURE):
app.get('/users',
  authMiddleware,
  query('id').optional().isInt().toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { id, limit = 10 } = req.query;

    // No email addresses exposed
    let users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    if (id) {
      users = users.filter(u => u.id === id);
    }

    users = users.slice(0, limit);

    res.json({ data: users, count: users.length });
  }
);
```

### Step 9: Add Error Handlers
```javascript
// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Error handler (MUST be last)
app.use((err, req, res, next) => {
  console.error(err);

  const isDev = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDev ? err.message : 'Internal Server Error',
    ...(isDev && { stack: err.stack })
  });
});
```

### Step 10: Update Server Startup
```javascript
// BEFORE:
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// AFTER:
const PORT = process.env.PORT || 3000;

if (process.env.NODE_ENV === 'production') {
  const https = require('https');
  const fs = require('fs');

  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH || './key.pem'),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH || './cert.pem'),
  };

  https.createServer(options, app).listen(PORT, () => {
    console.log(`Secure server running on port ${PORT}`);
  });
} else {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;
```

