GET /api/users?search={"$ne":null}
// Bypasses any filter logic
```

**Fix:**
```javascript
const validator = require('validator');

if (req.query.search) {
  if (!validator.isLength(req.query.search, { min: 1, max: 50 })) {
    return res.status(400).json({ error: 'Invalid search' });
