## SECURE APPLICATION CONFIGURATION

### app-with-secrets.js
```javascript
const express = require('express');
require('dotenv').config(); // For development only

async function initializeApp() {
  let secrets;

  if (process.env.NODE_ENV === 'production') {
    // Use AWS Secrets Manager in production
    const { getSecrets } = require('./secrets-manager');
    secrets = await getSecrets();
  } else if (process.env.VAULT_ADDR) {
    // Use Vault if available
    const VaultClient = require('./vault-client');
    const vault = new VaultClient(
      process.env.VAULT_ADDR,
      process.env.VAULT_TOKEN
    );
    secrets = {
      databaseUrl: await vault.getSecret('secret/data/dev/database'),
      apiKey: await vault.getSecret('secret/data/dev/api-key')
    };
  } else {
    // Use environment variables (development only)
    secrets = {
      databaseUrl: process.env.DATABASE_URL,
      apiKey: process.env.API_KEY,
      awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
      awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      anthropicApiKey: process.env.ANTHROPIC_API_KEY,
      stripeSecretKey: process.env.STRIPE_SECRET_KEY,
      logfireToken: process.env.LOGFIRE_TOKEN
    };

    // Validate secrets exist in development
    if (!secrets.databaseUrl) {
      throw new Error('Missing required secret: DATABASE_URL');
    }
  }

  const app = express();

  // Store secrets in app.locals (not in middleware)
  app.locals.secrets = secrets;

  // Add security headers
  app.use((req, res, next) => {
    // Never expose secrets in response headers
    res.set('X-Content-Type-Options', 'nosniff');
    next();
  });

  // Example: Use secrets for database connection
  app.get('/health', (req, res) => {
    // Validate secrets are loaded
    if (!app.locals.secrets.databaseUrl) {
      return res.status(500).json({ 
        error: 'Configuration error',
        details: 'Secrets not loaded'
      });
    }

    res.json({ status: 'ok' });
  });

  return app;
}

// DO NOT do this:
// ❌ app.use(express.json({
//   verify: (req, res, buf) => {
//     console.log(JSON.stringify(buf)); // Logs request body with secrets!
//   }
// }));

// DO NOT do this:
// ❌ res.json({ secret: process.env.API_KEY }); // Never expose secrets!

// DO NOT do this:
// ❌ console.log('API_KEY:', process.env.API_KEY); // Logs to stdout!

if (require.main === module) {
  initializeApp().then(app => {
    app.listen(3000, () => console.log('Server running'));
  });
}

module.exports = initializeApp;
```

