// secrets-manager.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager();

async function getSecrets() {
  const secrets = {};

  const services = [
    'prod/database/url',
    'prod/aws/access-key',
    'prod/aws/secret-key',
    'prod/anthropic/api-key',
    'prod/stripe/secret-key',
    'prod/logfire/token'
