// Secured version of app.js with security best practices applied

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const cors = require('cors');
const validator = require('validator');
require('dotenv').config();

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE - Applied in order of importance
// ============================================================================

// 1. HELMET: Sets various HTTP headers for security
app.use(helmet());

// 2. CORS: Restrict cross-origin requests
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 3. RATE LIMITING: Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  store: null, // Consider using redis store in production
  skip: (req) => {
    // Don't rate limit health checks (optional)
    return req.path === '/health';
  }
});
app.use(limiter);

// 4. BODY PARSER with size limits: Prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. DATA SANITIZATION Against NoSQL Injection
app.use(mongoSanitize({
  replaceWith: '_',
  onSanitize: ({ req, key }) => {
    console.warn(`Potential injection detected in ${key}`);
  },
}));

// 6. DATA SANITIZATION Against XSS
app.use(xss());

// 7. PARAMETER POLLUTION PROTECTION (HPP)
app.use(hpp({
  whitelist: ['sort', 'fields', 'filter'] // Only these params can be repeated
}));

// ============================================================================
// REQUEST VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Validates request parameters and query strings
 * Implements input validation for common attack vectors
 */
const validateRequest = (req, res, next) => {
  // Validate no suspicious patterns in URL
  if (req.originalUrl.includes('..') || req.originalUrl.includes('//')) {
    return res.status(400).json({ error: 'Invalid URL pattern' });
  }
  next();
};

app.use(validateRequest);

// ============================================================================
// AUTHENTICATION MIDDLEWARE (Example - implement based on your needs)
// ============================================================================

/**
 * Simple authentication middleware
 * In production, use JWT, OAuth2, or similar
 */
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    return res.status(401).json({ error: 'Authorization header missing' });
  }

  // Validate Bearer token format
  if (!authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Invalid authorization format' });
  }

  const token = authHeader.slice(7);

  // SECURITY: Validate token format before processing
  if (!validator.isJWT(token)) {
    return res.status(401).json({ error: 'Invalid token format' });
  }

  // TODO: Implement actual JWT verification
  // const decoded = jwt.verify(token, process.env.JWT_SECRET);
  // req.user = decoded;

  next();
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Prevents information disclosure through error messages
 */
const errorHandler = (err, req, res, next) => {
  console.error(err);

  // Never expose internal error details to client
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    // In production, use error codes instead of messages
    code: err.code || 'INTERNAL_ERROR'
  });
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * PUBLIC endpoint (no auth required)
 * Returns minimal information
 */
app.get('/health', (req, res) => {
  // SECURITY: Only return necessary information
  res.json({ 
    status: 'ok',
    timestamp: new Date().toISOString(),
    // Don't expose version, server info, etc.
  });
});

/**
 * Users endpoint
 * PROTECTED endpoint (requires authentication)
 * Validates output to prevent data leakage
 */
app.get('/users', authenticate, (req, res) => {
  // SECURITY: Filter sensitive data before returning
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Sanitize output - remove sensitive fields if applicable
  const sanitizedUsers = users.map(user => ({
    id: user.id,
    name: validator.trim(user.name), // Validate and trim
    // Don't expose email without proper authorization
    email: user.email
  }));

  res.json(sanitizedUsers);
});

/**
 * Example route with input validation
 * Demonstrates proper parameter validation
 */
app.get('/users/:id', authenticate, (req, res) => {
  const { id } = req.params;

  // SECURITY: Validate input type and range
  if (!validator.isInt(id, { min: 1, max: 999999 })) {
    return res.status(400).json({ 
      error: 'Invalid user ID format',
      details: 'User ID must be a positive integer'
    });
  }

  // Simulated user lookup (in production, query database with parameterized queries)
  const users = {
    1: { id: 1, name: 'Alice' },
    2: { id: 2, name: 'Bob' }
  };

  const user = users[id];

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  res.json(user);
});

/**
 * Example POST route with comprehensive validation
 */
app.post('/users', authenticate, (req, res) => {
  const { name, email } = req.body;

  // SECURITY: Validate all inputs
  const errors = [];

  // Check for required fields
  if (!name || !email) {
    errors.push('Name and email are required');
  }

  // Validate name
  if (name && !validator.isLength(name, { min: 1, max: 100 })) {
    errors.push('Name must be between 1 and 100 characters');
  }

  if (name && !validator.matches(name, /^[a-zA-Z\s'-]+$/)) {
    errors.push('Name contains invalid characters');
  }

  // Validate email
  if (email && !validator.isEmail(email)) {
    errors.push('Invalid email format');
  }

  // Return validation errors
  if (errors.length > 0) {
    return res.status(400).json({ errors });
  }

  // SECURITY: Sanitize inputs before use
  const sanitizedName = validator.trim(validator.escape(name));
  const sanitizedEmail = validator.normalizeEmail(email);

  // TODO: Implement database save with parameterized queries
  // const newUser = await User.create({ 
  //   name: sanitizedName, 
  //   email: sanitizedEmail 
  // });

  res.status(201).json({
    id: 3,
    name: sanitizedName,
    email: sanitizedEmail
  });
});

// ============================================================================
// SECURITY HEADERS - Additional custom headers
// ============================================================================

app.use((req, res, next) => {
  // Prevent browsers from MIME-sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Enable XSS protection in older browsers
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Control referrer information
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Content Security Policy - adjust based on your needs
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; font-src 'self'"
  );

  // Don't cache sensitive responses
  res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
  res.setHeader('Pragma', 'no-cache');
  res.setHeader('Expires', '0');

  next();
});

// ============================================================================
// 404 HANDLER
// ============================================================================

app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

// ============================================================================
// ERROR HANDLER
// ============================================================================

app.use(errorHandler);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

