// Example: Secure route implementation with full validation and error handling
// This demonstrates all security best practices applied to a real endpoint

const express = require('express');
const validator = require('validator');
const Joi = require('joi');

const app = express();

// ============================================================================
// VALIDATION SCHEMAS - Using Joi for comprehensive input validation
// ============================================================================

const userSchema = Joi.object({
  name: Joi.string()
    .alphanum()
    .min(2)
    .max(100)
    .required()
    .trim(),
  email: Joi.string()
    .email()
    .required()
    .lowercase(),
  age: Joi.number()
    .integer()
    .min(0)
    .max(150)
    .optional()
});

const userIdSchema = Joi.object({
  id: Joi.number()
    .integer()
    .positive()
    .required()
});

const paginationSchema = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(10)
});

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to validate request body
 */
const validateBody = (schema) => (req, res, next) => {
  const { error, value } = schema.validate(req.body, {
    abortEarly: false,
    stripUnknown: true // Remove unknown fields
  });

  if (error) {
    return res.status(400).json({
      error: 'Validation failed',
      details: error.details.map(e => ({
        field: e.path.join('.'),
        message: e.message
      }))
    });
  }

  // Replace req.body with validated/sanitized data
  req.body = value;
  next();
};

/**
 * Middleware to validate route parameters
 */
const validateParams = (schema) => (req, res, next) => {
  const { error, value } = schema.validate(req.params);

  if (error) {
    return res.status(400).json({
      error: 'Invalid parameters',
      details: error.details
    });
  }

  req.params = value;
  next();
};

/**
 * Middleware to validate query parameters
 */
const validateQuery = (schema) => (req, res, next) => {
  const { error, value } = schema.validate(req.query);

  if (error) {
    return res.status(400).json({
      error: 'Invalid query parameters',
      details: error.details
    });
  }

  req.query = value;
  next();
};

// ============================================================================
// SECURE ENDPOINT EXAMPLES
// ============================================================================

/**
 * GET /users/:id
 * 
 * Security features:
 * - Parameter validation with Joi
 * - Type checking (integer, positive)
 * - Authorization check
 * - Proper error handling
 */
app.get('/users/:id', 
  authenticate,
  validateParams(userIdSchema),
  async (req, res, next) => {
    try {
      const { id } = req.params;

      // Authorization: Users can only see their own data
      if (req.user.id !== parseInt(id) && !req.user.isAdmin) {
        return res.status(403).json({ 
          error: 'Forbidden',
          code: 'INSUFFICIENT_PERMISSIONS'
        });
      }

      // Simulated database query (use parameterized queries in real code)
      const user = await User.findById(id);

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      // Sanitize sensitive fields before returning
      const sanitized = {
        id: user.id,
        name: user.name,
        email: user.email
        // Don't include password hash, tokens, etc.
      };

      res.json(sanitized);
    } catch (error) {
      next(error); // Pass to error handler
    }
  }
);

/**
 * POST /users
 * 
 * Security features:
 * - Body validation with Joi
 * - Email format validation
 * - Length limits
 * - Duplicate detection
 * - Async error handling
 */
app.post('/users',
  authenticate,
  validateBody(userSchema),
  async (req, res, next) => {
    try {
      const { name, email, age } = req.body;

      // Check if user already exists
      const existingUser = await User.findOne({ email });
      if (existingUser) {
        return res.status(409).json({ 
          error: 'User already exists',
          code: 'DUPLICATE_EMAIL'
        });
      }

      // Create new user with sanitized data
      const newUser = await User.create({
        name: validator.trim(name),
        email: validator.normalizeEmail(email),
        age,
        createdBy: req.user.id // Track who created this user
      });

      // Return sanitized response
      res.status(201).json({
        id: newUser.id,
        name: newUser.name,
        email: newUser.email,
        createdAt: newUser.createdAt
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * GET /users
 * 
 * Security features:
 * - Query parameter validation
 * - Pagination to prevent data dumps
 * - Filtering by authorized fields only
 * - Sorting sanitization
 */
app.get('/users',
  authenticate,
  validateQuery(paginationSchema),
  async (req, res, next) => {
    try {
      const { page, limit } = req.query;
      const skip = (page - 1) * limit;

      // Only allow filtering on whitelisted fields
      const allowedFilters = ['name', 'email'];
      const filter = {};

      for (const key in req.query) {
        if (allowedFilters.includes(key)) {
          // Sanitize filter values to prevent injection
          filter[key] = validator.trim(req.query[key]);
        }
      }

      // Only allow sorting on whitelisted fields
      let sort = {};
      if (req.query.sort) {
        const sortField = req.query.sort.replace(/^-/, '');
        if (['name', 'createdAt', 'id'].includes(sortField)) {
          sort[sortField] = req.query.sort.startsWith('-') ? -1 : 1;
        }
      }

      // Query with limits to prevent abuse
      const users = await User.find(filter)
        .sort(sort)
        .skip(skip)
        .limit(limit)
        .select('-password -tokens'); // Exclude sensitive fields

      const total = await User.countDocuments(filter);

      res.json({
        data: users,
        pagination: {
          page,
          limit,
          total,
          pages: Math.ceil(total / limit)
        }
      });
    } catch (error) {
      next(error);
    }
  }
);

/**
 * PUT /users/:id
 * 
 * Security features:
 * - PATCH for partial updates (better than PUT)
 * - Ownership verification
 * - Field whitelisting
 * - Audit logging
 */
app.patch('/users/:id',
  authenticate,
  validateParams(userIdSchema),
  validateBody(Joi.object({
    name: Joi.string().alphanum().min(2).max(100).optional(),
    email: Joi.string().email().optional()
  })),
  async (req, res, next) => {
    try {
      const { id } = req.params;
      const updateData = req.body;

      // Ownership check: users can only update their own data
      if (req.user.id !== parseInt(id) && !req.user.isAdmin) {
        return res.status(403).json({ error: 'Forbidden' });
      }

      // Whitelist updatable fields
      const allowedFields = ['name', 'email'];
      const sanitizedUpdate = {};

      for (const field of allowedFields) {
        if (field in updateData) {
          if (field === 'name') {
            sanitizedUpdate[field] = validator.trim(updateData[field]);
          } else if (field === 'email') {
            sanitizedUpdate[field] = validator.normalizeEmail(updateData[field]);
          }
        }
      }

      // Check for email uniqueness if email is being updated
      if (sanitizedUpdate.email) {
        const existing = await User.findOne({ 
          email: sanitizedUpdate.email,
          _id: { $ne: id }
        });
        if (existing) {
          return res.status(409).json({ error: 'Email already in use' });
        }
      }

      const updatedUser = await User.findByIdAndUpdate(
        id,
        sanitizedUpdate,
        { new: true, runValidators: true }
      ).select('-password -tokens');

      // Log the update for audit purposes
      auditLog.create({
        userId: req.user.id,
        action: 'UPDATE_USER',
        targetId: id,
        changes: sanitizedUpdate
      });

      res.json(updatedUser);
    } catch (error) {
      next(error);
    }
  }
);

/**
 * DELETE /users/:id
 * 
 * Security features:
 * - Ownership verification
 * - Soft delete (data recovery)
 * - Audit logging
 */
app.delete('/users/:id',
  authenticate,
  validateParams(userIdSchema),
  async (req, res, next) => {
    try {
      const { id } = req.params;

      // Only admins or the user themselves can delete
      if (req.user.id !== parseInt(id) && !req.user.isAdmin) {
        return res.status(403).json({ error: 'Forbidden' });
      }

      // Perform soft delete instead of hard delete
      const user = await User.findByIdAndUpdate(
        id,
        { 
          deletedAt: new Date(),
          deletedBy: req.user.id
        },
        { new: true }
      );

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      // Log the deletion
      auditLog.create({
        userId: req.user.id,
        action: 'DELETE_USER',
        targetId: id
      });

      res.status(204).send();
    } catch (error) {
      next(error);
    }
  }
);

