/**
 * SECURE SECRETS MANAGEMENT IMPLEMENTATION
 * 
 * Demonstrates proper secrets handling using AWS Secrets Manager
 * Replace dotenv with production-grade secrets management
 */

// ============================================================================
// OPTION 1: AWS SECRETS MANAGER (Recommended for Production)
// ============================================================================

class AWSSecretsManager {
  constructor() {
    const AWS = require('aws-sdk');
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  /**
   * Get secret from AWS Secrets Manager
   * Caches results to avoid excessive API calls
   * Implements automatic rotation support
   */
  async getSecret(secretName) {
    const cacheKey = `secret_${secretName}`;
    const cached = this.cache[cacheKey];

    // Return cached secret if still valid
    if (cached && cached.expiresAt > Date.now()) {
      console.log(`[CACHE HIT] Retrieved secret from cache: ${secretName}`);
      return cached.value;
    }

    try {
      console.log(`[AWS] Fetching secret: ${secretName}`);
      const response = await this.client
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        // Handle binary secret
        secret = Buffer.from(response.SecretBinary, 'base64').toString();
      }

      // Cache the secret
      this.cache[cacheKey] = {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL,
        timestamp: new Date().toISOString()
      };

      return secret;
    } catch (error) {
      console.error(`[ERROR] Failed to fetch secret ${secretName}:`, error.message);
      throw error;
    }
  }

  /**
   * Get multiple secrets efficiently
   */
  async getSecrets(...secretNames) {
    const secrets = {};

    for (const name of secretNames) {
      secrets[name] = await this.getSecret(name);
    }

    return secrets;
  }

  /**
   * Refresh secret from AWS (skip cache)
   * Useful after rotation
   */
  async refreshSecret(secretName) {
    const cacheKey = `secret_${secretName}`;
    delete this.cache[cacheKey];
    return this.getSecret(secretName);
  }

  /**
   * Clear all cached secrets
   */
  clearCache() {
    this.cache = {};
    console.log('[CACHE] All secrets cleared');
  }
}

// ============================================================================
// OPTION 2: HashiCorp Vault (Alternative for Production)
// ============================================================================

class VaultSecretsManager {
  constructor(vaultUrl, token) {
    const axios = require('axios');
    this.client = axios.create({
      baseURL: vaultUrl,
      headers: {
        'X-Vault-Token': token
      }
    });
    this.cache = {};
    this.cacheTTL = 3600000;
  }

  /**
   * Get secret from Vault
   */
  async getSecret(secretPath) {
    const cacheKey = `vault_${secretPath}`;
    const cached = this.cache[cacheKey];

    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const response = await this.client.get(`/v1/${secretPath}`);
      const secret = response.data.data.data;

      this.cache[cacheKey] = {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL
      };

      return secret;
    } catch (error) {
      console.error(`Failed to fetch secret from Vault: ${secretPath}`, error.message);
      throw error;
    }
  }

  /**
   * Rotate secret in Vault
   */
  async rotateSecret(secretPath, newSecretData) {
    try {
      const response = await this.client.post(`/v1/${secretPath}`, {
        data: newSecretData
      });

      // Clear cache after rotation
      delete this.cache[`vault_${secretPath}`];

      return response.data;
    } catch (error) {
      console.error(`Failed to rotate secret: ${secretPath}`, error.message);
      throw error;
    }
  }
