    validation: (value) => value.startsWith('sk_live_')
  },
  'prod/aws-access-key': {
    description: 'AWS access key',
    pattern: /^AKIA/,
    validation: (value) => value.startsWith('AKIA') && value.length === 20
  },
  'prod/aws-secret-key': {
    description: 'AWS secret access key',
    minLength: 40,
    validation: (value) => value.length >= 40
  }
};

/**
 * Validate a secret meets requirements
 */
function validateSecret(name, value, config) {
  const errors = [];

  if (!value) {
    errors.push(`Secret ${name} is empty`);
    return errors;
  }

  if (config.minLength && value.length < config.minLength) {
    errors.push(
      `Secret ${name} is too short (min ${config.minLength} chars, got ${value.length})`
    );
  }

  if (config.pattern && !config.pattern.test(value)) {
    errors.push(`Secret ${name} does not match required format`);
  }

  if (config.validation && !config.validation(value)) {
    errors.push(`Secret ${name} failed validation: ${config.description}`);
  }

  return errors;
}

