  console.log(`[INIT] Loading secrets from AWS Secrets Manager...`);

  for (const [secretName, config] of Object.entries(REQUIRED_SECRETS)) {
    try {
      const secretValue = await secretsManager.getSecret(secretName);

      // Validate the secret
      const validationErrors = validateSecret(secretName, secretValue, config);
      if (validationErrors.length > 0) {
        errors.push(...validationErrors);
        continue;
      }

      secrets[secretName] = secretValue;
      console.log(`✓ Loaded and validated: ${secretName}`);
    } catch (error) {
      errors.push(`Failed to load ${secretName}: ${error.message}`);
    }
  }

