  if (errors.length > 0) {
    console.error('\n❌ SECRET VALIDATION FAILED:');
    errors.forEach(err => console.error(`  - ${err}`));
    process.exit(1);
  }

  console.log(`\n✓ All secrets loaded and validated successfully\n`);
  return secrets;
}

