  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// 3. Request size limiting (OWASP A6 - DoS Prevention)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Data sanitization against NoSQL injection (OWASP A3 - Injection)
app.use(mongoSanitize());

// 5. Data sanitization against XSS (OWASP A7 - Cross-site Scripting)
app.use(xssClean());

// 6. Rate limiting (OWASP A6 - DoS Prevention)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again after 15 minutes.',
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE (OWASP A1 & A7)
// ============================================================================

/**
 * Verify JWT token
 * Usage: app.get('/protected', authenticateToken, handler);
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn('Access attempt without token', { ip: req.ip });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn('Invalid token attempt', { ip: req.ip, error: err.message });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

/**
 * Role-based access control middleware
 */
const authorize = (allowedRoles = []) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      logger.warn('Unauthorized access attempt', {
        userId: req.user.id,
        requiredRole: allowedRoles,
        userRole: req.user.role,
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Validation error handler
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation error', { errors: errors.array() });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================================================
// ENDPOINTS
// ============================================================================

/**
 * Health check endpoint
 * No authentication required (public endpoint)
 * 
 * ✓ Input validation on optional parameters
 * ✓ Sanitized response
 * ✓ Logged for monitoring
 */
app.get('/health',
  query('format').optional().isIn(['json', 'text']),
  handleValidationErrors,
  (req, res) => {
    const format = req.query.format || 'json';

    logger.info('Health check', {
      format,
      userAgent: req.get('user-agent'),
    });

    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    if (format === 'text') {
      res.type('text/plain').send(`Status: ${healthData.status}`);
    } else {
      res.json(healthData);
    }
  }
);

/**
 * Get users endpoint
 * 
 * ✓ Authentication required (JWT token)
 * ✓ Authorization required (admin role)
 * ✓ Input validation
 * ✓ Query parameter validation
 * ✓ Proper error handling
 * ✓ Audit logging
 */
app.get('/users',
  authenticateToken,
  authorize(['admin', 'user_manager']),
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
  handleValidationErrors,
  (req, res) => {
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = parseInt(req.query.offset) || 0;

    logger.info('Users endpoint accessed', {
      userId: req.user.id,
      userRole: req.user.role,
      limit,
      offset,
    });

    // In production, fetch from database with proper pagination
    // This is mock data for example purposes
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users.slice(offset, offset + limit),
      pagination: {
        limit,
        offset,
        total: users.length,
      },
    });
  }
);

/**
 * Login endpoint
 * 
 * ✓ Input validation (email, password format)
 * ✓ Rate limited (brute force protection)
 * ✓ Secure password comparison (use bcrypt in production)
 * ✓ JWT token generation
 * ✓ Audit logging of authentication attempts
 */
app.post('/login',
  authLimiter,
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }),
  handleValidationErrors,
  (req, res) => {
    const { email, password } = req.body;

    logger.info('Login attempt', { email });

    // In production:
    // 1. Query database for user
    // 2. Use bcrypt.compare() for password verification
    // 3. Never return user password
    // 4. Implement account lockout after N failed attempts

    // Mock authentication
    if (email === 'admin@example.com' && password === 'SecurePass123!') {
      const token = jwt.sign(
        {
          id: 1,
          email: email,
          role: 'admin',
        },
        process.env.JWT_SECRET,
        { expiresIn: '1h' }
      );

      logger.info('Successful login', { email, userId: 1 });

      return res.json({
        token,
        expiresIn: '1h',
      });
    }

    logger.warn('Failed login attempt', { email });
    res.status(401).json({ error: 'Invalid credentials' });
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * 404 handler
 */
app.use((req, res) => {
  logger.warn('Route not found', { method: req.method, path: req.path });
  res.status(404).json({ error: 'Endpoint not found' });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });

  // Don't expose internal error details to client
  const status = err.status || 500;
  res.status(status).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message,
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} environment`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

