# Security Vulnerabilities & Code Examples

## 1. SQL/NoSQL INJECTION

### ❌ VULNERABLE CODE
```javascript
app.get('/user/:id', (req, res) => {
  // Direct string concatenation - vulnerable to injection
  const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
  db.query(query, (err, result) => {
    res.json(result);
  });
});

// Attack: GET /user/1 OR 1=1
// Query becomes: SELECT * FROM users WHERE id = 1 OR 1=1
// Returns ALL users!
```

### ✓ SECURE CODE
```javascript
const { param, validationResult } = require('express-validator');

app.get('/user/:id',
  param('id').isInt().toInt(), // Validate and convert to integer
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Parameterized query - injection-proof
    const query = 'SELECT * FROM users WHERE id = ?';
    db.query(query, [req.params.id], (err, result) => {
      res.json(result);
    });
  }
);
```

