  // Direct rendering of user input - XSS vulnerability
  res.send(`<h1>Search results for: ${searchTerm}</h1>`);

  // Attack: GET /search?q=<img src=x onerror="alert('XSS')">
  // User sees alert box
});
```

### ✓ SECURE CODE
```javascript
const xssClean = require('xss-clean');
const { query, validationResult } = require('express-validator');

app.use(xssClean()); // Middleware sanitization

app.get('/search',
  query('q').trim().escape(), // Escape special characters
  (req, res) => {
