## 5. MISSING RATE LIMITING / BRUTE FORCE

### ❌ VULNERABLE CODE
```javascript
app.post('/login', (req, res) => {
  // No rate limiting - attacker can try unlimited passwords
  const { username, password } = req.body;
  authenticateUser(username, password);
});

app.get('/api/data', (req, res) => {
  // No rate limiting - attacker can scrape all data
  res.json(getAllData());
});
```

### ✓ SECURE CODE
```javascript
const rateLimit = require('express-rate-limit');

// General API rate limit
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests'
});

// Stricter limit for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts
  skipSuccessfulRequests: true // Don't count successful logins
});

app.post('/login', authLimiter, (req, res) => {
  // Protected from brute force
});

app.get('/api/data', generalLimiter, (req, res) => {
  // Protected from scraping
});
```

---

## 6. MISSING AUTHORIZATION / BROKEN ACCESS CONTROL

### ❌ VULNERABLE CODE
```javascript
app.get('/admin/users', (req, res) => {
  // Anyone can access - no authorization check
  res.json(db.getAllUsers());
});

app.delete('/user/:id', (req, res) => {
  // User can delete any other user
  db.deleteUser(req.params.id);
  res.json({ success: true });
});

app.get('/reports/:id', (req, res) => {
  // User can view anyone's reports
  const report = db.getReport(req.params.id);
  res.json(report);
});
```

### ✓ SECURE CODE
```javascript
// Authentication middleware
const authenticateToken = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

// Authorization middleware (role-based)
const authorize = (allowedRoles) => (req, res, next) => {
  if (!allowedRoles.includes(req.user.role)) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  next();
};

// Admin only endpoint
app.get('/admin/users',
  authenticateToken,
  authorize(['admin']),
  (req, res) => {
    res.json(db.getAllUsers());
  }
);

// User can only delete themselves
app.delete('/user/:id',
  authenticateToken,
  (req, res) => {
    if (req.user.id !== parseInt(req.params.id)) {
      return res.status(403).json({ error: 'Cannot delete other users' });
    }
    db.deleteUser(req.params.id);
    res.json({ success: true });
  }
);

// User can only view their own reports
app.get('/reports/:id',
  authenticateToken,
  (req, res) => {
    const report = db.getReport(req.params.id);

    // Verify ownership
    if (report.userId !== req.user.id) {
      return res.status(403).json({ error: 'Not authorized' });
    }

    res.json(report);
  }
);
```

