## 7. MISSING SECURITY HEADERS

### ❌ VULNERABLE CODE
```javascript
const express = require('express');
const app = express();

// No security headers configured
app.listen(3000);
```

### ✓ SECURE CODE
```javascript
const express = require('express');
const helmet = require('helmet');
const app = express();

// Enable all helmet protections
app.use(helmet());

// Or customize individual headers
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", "data:", "https:"],
  },
}));

app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));

app.use(helmet.frameguard({ action: 'deny' }));
app.use(helmet.noSniff());
app.use(helmet.xssFilter());

app.listen(3000);
```

---

## 8. INSECURE DESERIALIZATION

### ❌ VULNERABLE CODE
```javascript
const pickle = require('pickle'); // Unsafe deserialization

app.post('/data', (req, res) => {
  // Deserializing untrusted data - Code Execution!
  const obj = pickle.loads(req.body.data);
  res.json(obj);
});
```

### ✓ SECURE CODE
```javascript
app.post('/data', express.json(), (req, res) => {
  // JSON parse is safe (no code execution)
  // JSON already parsed by express.json() middleware
  const obj = req.body;

  // Validate structure
  if (!obj.field1 || typeof obj.field1 !== 'string') {
    return res.status(400).json({ error: 'Invalid data' });
  }

  res.json(obj);
});
```

---

## 9. COMMAND INJECTION

### ❌ VULNERABLE CODE
```javascript
const { exec } = require('child_process');

app.get('/convert', (req, res) => {
  const filename = req.query.file;

  // Concatenating user input into shell command - CRITICAL!
  exec(`convert ${filename} output.jpg`, (err, stdout) => {
    res.send(stdout);
  });
});

// Attack: GET /convert?file=input.jpg; rm -rf /
// Command executed: convert input.jpg; rm -rf / output.jpg
```

### ✓ SECURE CODE
```javascript
const { execFile } = require('child_process');
const path = require('path');

app.get('/convert',
  query('file').matches(/^[\w\-\.]+$/), // Whitelist alphanumeric, dash, dot
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const filename = path.basename(req.query.file); // Remove path traversal

    // Use execFile with array of arguments (no shell injection)
    execFile('convert', [filename, 'output.jpg'], (err, stdout) => {
      if (err) return res.status(500).json({ error: 'Conversion failed' });
      res.send(stdout);
    });
  }
);
```

---

## 10. SECURITY LOGGING & MONITORING FAILURES

### ❌ VULNERABLE CODE
```javascript
app.post('/login', (req, res) => {
  const { username, password } = req.body;

  // No logging - can't detect attacks
  if (authenticate(username, password)) {
    res.json({ success: true });
  }
});
```

### ✓ SECURE CODE
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

app.post('/login',
  body('username').isAlphanumeric(),
  body('password').isLength({ min: 8 }),
  async (req, res) => {
    const { username, password } = req.body;
    const clientIp = req.ip;

    logger.info('Login attempt', {
      username,
      ip: clientIp,
      timestamp: new Date().toISOString(),
      userAgent: req.get('user-agent')
    });

    try {
      if (await authenticate(username, password)) {
        logger.info('Successful login', { username, ip: clientIp });
        res.json({ success: true });
      } else {
        logger.warn('Failed login', { username, ip: clientIp });
        res.status(401).json({ error: 'Invalid credentials' });
      }
    } catch (err) {
      logger.error('Login error', {
        username,
        error: err.message,
        ip: clientIp
      });
      res.status(500).json({ error: 'Server error' });
    }
  }
);
```

