## 5. MISSING RATE LIMITING / BRUTE FORCE

### ❌ VULNERABLE CODE
```javascript
app.post('/login', (req, res) => {
  // No rate limiting - attacker can try unlimited passwords
  const { username, password } = req.body;
  authenticateUser(username, password);
});

app.get('/api/data', (req, res) => {
  // No rate limiting - attacker can scrape all data
  res.json(getAllData());
});
```

### ✓ SECURE CODE
```javascript
const rateLimit = require('express-rate-limit');

// General API rate limit
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests'
});

// Stricter limit for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts
  skipSuccessfulRequests: true // Don't count successful logins
});

app.post('/login', authLimiter, (req, res) => {
  // Protected from brute force
});

app.get('/api/data', generalLimiter, (req, res) => {
  // Protected from scraping
});
```

