// secretsManager.js - Abstraction layer for secrets management
// Supports AWS Secrets Manager, local env, or other backends

const AWS = require('aws-sdk');

let secretsCache = {};
const CACHE_TTL = 3600000; // 1 hour cache

class SecretsManager {
  constructor(backend = 'env') {
    this.backend = backend;

    if (backend === 'aws') {
      this.client = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1',
      });
    }
  }

  /**
   * Get secret from configured backend
   * @param {string} secretName - Name of the secret
   * @param {boolean} useCache - Whether to use cached value
   * @returns {Promise<string|object>}
   */
  async getSecret(secretName, useCache = true) {
    // Check cache first
    if (useCache && secretsCache[secretName]) {
      const cached = secretsCache[secretName];
      if (Date.now() - cached.timestamp < CACHE_TTL) {
        console.debug(`[SecretsManager] Cache hit for ${secretName}`);
        return cached.value;
      }
    }

    let secret;

    try {
      if (this.backend === 'aws') {
        secret = await this.getFromAWS(secretName);
      } else if (this.backend === 'env') {
        secret = this.getFromEnv(secretName);
      } else {
        throw new Error(`Unknown backend: ${this.backend}`);
      }

      // Cache the secret
      secretsCache[secretName] = {
        value: secret,
        timestamp: Date.now(),
      };

      return secret;
    } catch (error) {
      console.error(`[SecretsManager] Failed to get secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Get secret from AWS Secrets Manager
   */
  async getFromAWS(secretName) {
    try {
      const data = await this.client.getSecretValue({
        SecretId: secretName,
      }).promise();

      if ('SecretString' in data) {
        try {
          return JSON.parse(data.SecretString);
        } catch {
          return data.SecretString;
        }
      } else {
        return Buffer.from(data.SecretBinary, 'base64').toString('utf-8');
      }
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw error;
    }
  }

  /**
   * Get secret from environment variables
   */
  getFromEnv(secretName) {
    const secret = process.env[secretName];

    if (!secret) {
      throw new Error(`Secret not found in environment: ${secretName}`);
    }

    try {
      return JSON.parse(secret);
    } catch {
      return secret;
    }
  }

  /**
   * Verify secret exists (without retrieving it)
   */
  async secretExists(secretName) {
    try {
      if (this.backend === 'aws') {
        await this.client.describeSecret({
          SecretId: secretName,
        }).promise();
        return true;
      } else if (this.backend === 'env') {
        return !!process.env[secretName];
      }
    } catch (error) {
      return false;
    }
  }

  /**
   * Clear cache (useful for testing)
   */
  clearCache(secretName = null) {
    if (secretName) {
      delete secretsCache[secretName];
    } else {
      secretsCache = {};
    }
  }
}

module.exports = SecretsManager;

