### ✅ Solution 2: Secrets Manager Abstraction

**File: `secretsManager.js`**
```javascript
const AWS = require('aws-sdk');

class SecretsManager {
  constructor(backend = 'env') {
    this.backend = backend;
    this.cache = {};

    if (backend === 'aws') {
      this.client = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1',
      });
    }
  }

  async getSecret(secretName, useCache = true) {
    // Check cache first
    if (useCache && this.cache[secretName]) {
      return this.cache[secretName];
    }

    let secret;

    if (this.backend === 'aws') {
      secret = await this.getFromAWS(secretName);
    } else {
      secret = process.env[secretName];
    }

    this.cache[secretName] = secret;
    return secret;
  }

  async getFromAWS(secretName) {
    const data = await this.client.getSecretValue({
      SecretId: secretName,
    }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }
    return Buffer.from(data.SecretBinary, 'base64').toString();
  }
}

module.exports = SecretsManager;
```

**Benefits:**
- ✅ Abstraction layer for flexibility
- ✅ Supports multiple backends
- ✅ Built-in caching
- ✅ Error handling
- ✅ Easy to switch providers

