const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const config = require('./config');
const SecretsManager = require('./secretsManager');

const app = express();

// Security headers
app.use(helmet());

// CORS
app.use(cors(config.cors));

// Rate limiting
const limiter = rateLimit(config.rateLimit);
app.use(limiter);

// Authentication
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    const user = jwt.verify(token, config.secrets.jwt.secret);
    req.user = user;
    next();
  } catch (error) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },  // No email exposed
    { id: 2, name: 'Bob' },
  ]);
});

// Startup verification
async function start() {
  try {
    if (config.app.environment === 'production') {
      const secretsManager = new SecretsManager('aws');

      // Verify all required secrets
      for (const secret of ['DATABASE_URL', 'JWT_SECRET']) {
        const exists = await secretsManager.secretExists(secret);
        if (!exists) {
          throw new Error(`Required secret not found: ${secret}`);
        }
      }
    }

    app.listen(config.app.port, () => {
      console.log(`✅ Server running on port ${config.app.port}`);
    });
  } catch (error) {
    console.error('❌ Failed to start:', error.message);
    process.exit(1);
  }
}

start();

module.exports = app;
```

