/**
 * AWS Secrets Manager Configuration
 * Recommended approach for AWS environments
 * 
 * Prerequisites:
 * - npm install aws-sdk
 * - IAM role with secretsmanager:GetSecretValue permission
 * - Secret created in AWS Secrets Manager with name: prod/app/secrets
 */

const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

/**
 * Fetch secrets from AWS Secrets Manager
 * Secrets should be stored as JSON:
 * {
 *   "JWT_SECRET": "your-secret-key",
 *   "DATABASE_URL": "postgres://...",
 *   "STRIPE_SECRET_KEY": "sk_live_...",
 *   "ANTHROPIC_API_KEY": "sk-ant-..."
 * }
 */
async function getSecretsFromAWS() {
  try {
    const secretId = process.env.SECRETS_MANAGER_ID || 'prod/app/secrets';

    console.log(`Fetching secrets from AWS Secrets Manager: ${secretId}`);

    const response = await secretsManager.getSecretValue({
      SecretId: secretId
    }).promise();

    let secrets;

    // Handle binary secrets
    if ('SecretBinary' in response) {
      secrets = JSON.parse(Buffer.from(response.SecretBinary, 'base64').toString('ascii'));
    } 
    // Handle string secrets
    else if ('SecretString' in response) {
      secrets = JSON.parse(response.SecretString);
    }

    // Validate required secrets
    validateRequiredSecrets(secrets);

    return secrets;
  } catch (error) {
    if (error.code === 'ResourceNotFoundException') {
      console.error('Secret not found in AWS Secrets Manager');
    } else if (error.code === 'InvalidParameterException') {
      console.error('Invalid parameter when calling AWS Secrets Manager');
    } else if (error.code === 'DecryptionFailure') {
      console.error('Failed to decrypt secret');
    } else if (error.code === 'InternalServiceError') {
      console.error('Internal service error when calling AWS Secrets Manager');
    } else {
      console.error('Failed to retrieve secrets from AWS:', error.message);
    }

    throw new Error('Unable to load secrets from AWS Secrets Manager');
  }
}

/**
 * Validate that all required secrets are present
 */
function validateRequiredSecrets(secrets) {
  const required = [
    'JWT_SECRET',
    'DATABASE_URL',
    'NODE_ENV'
  ];

  const missing = required.filter(key => !secrets[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }
}

/**
 * Initialize secrets at application startup
 * Call this from main app.js before starting server
 */
async function initializeSecrets() {
  try {
    const secrets = await getSecretsFromAWS();

    // Load into environment
    Object.keys(secrets).forEach(key => {
      process.env[key] = secrets[key];
    });

    console.log('✓ Secrets successfully loaded from AWS Secrets Manager');
    return secrets;
  } catch (error) {
    console.error('✗ Failed to initialize secrets:', error.message);
    process.exit(1);
  }
}

module.exports = { 
  getSecretsFromAWS,
  initializeSecrets,
  validateRequiredSecrets
};

// Usage in app.js:
// const { initializeSecrets } = require('./config-aws-secrets-manager');
// await initializeSecrets();

/**
 * HashiCorp Vault Configuration
 * Enterprise-grade secrets management
 * 
 * Prerequisites:
 * - npm install node-vault
 * - Vault server running
 * - Environment variables:
 *   - VAULT_ADDR: http://vault.example.com:8200
 *   - VAULT_TOKEN: hvs.xxxxx or authenticate via method
 *   - VAULT_PATH: secret/data/prod/app (for KV v2)
 */

const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN
});

/**
 * Retrieve secrets from Vault (KV v2)
 * Expected Vault secret structure:
 * {
 *   "data": {
 *     "data": {
 *       "JWT_SECRET": "...",
 *       "DATABASE_URL": "...",
 *       ...
 *     }
 *   }
 * }
 */
async function getSecretsFromVault() {
  try {
    const vaultPath = process.env.VAULT_PATH || 'secret/data/prod/app';

    console.log(`Fetching secrets from Vault: ${vaultPath}`);

    const secret = await vault.read(vaultPath);
    const secrets = secret.data.data;

    // Validate required secrets
    validateRequiredSecrets(secrets);

    return secrets;
  } catch (error) {
    if (error.statusCode === 403) {
      console.error('Vault authentication failed - invalid token or insufficient permissions');
    } else if (error.statusCode === 404) {
      console.error('Secret not found in Vault at specified path');
    } else {
      console.error('Failed to retrieve secrets from Vault:', error.message);
    }

    throw new Error('Unable to load secrets from Vault');
  }
}

/**
 * Authenticate to Vault using AppRole method
 * Useful for automated deployments
 */
async function authenticateVaultAppRole() {
  try {
    const roleId = process.env.VAULT_ROLE_ID;
    const secretId = process.env.VAULT_SECRET_ID;

    if (!roleId || !secretId) {
      throw new Error('VAULT_ROLE_ID and VAULT_SECRET_ID required for AppRole auth');
    }

    const result = await vault.userpassLogin({
      username: roleId,
      password: secretId,
      mount_point: 'approle'
    });

    process.env.VAULT_TOKEN = result.auth.client_token;
    console.log('✓ Successfully authenticated to Vault with AppRole');

    return result.auth.client_token;
  } catch (error) {
    console.error('Failed to authenticate to Vault:', error.message);
    throw error;
  }
}

/**
 * Validate required secrets are present
 */
function validateRequiredSecrets(secrets) {
  const required = [
    'JWT_SECRET',
    'DATABASE_URL',
    'NODE_ENV'
  ];

  const missing = required.filter(key => !secrets[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }
}

/**
 * Renew Vault token before expiration
 * Vault tokens have TTLs - this extends the lease
 */
async function renewVaultToken() {
  try {
    const result = await vault.tokenRenewSelf();
    console.log(`✓ Vault token renewed. New TTL: ${result.auth.lease_duration}s`);
    return result;
  } catch (error) {
    console.error('Failed to renew Vault token:', error.message);
    throw error;
  }
}

/**
 * Setup periodic token renewal
 * Keeps token valid by renewing before expiration
 */
function setupTokenRenewal(renewalIntervalSeconds = 3600) {
  setInterval(async () => {
    try {
      await renewVaultToken();
    } catch (error) {
      console.error('Token renewal failed:', error.message);
      // Optionally restart application or alert
    }
  }, renewalIntervalSeconds * 1000);

  console.log(`✓ Token renewal set up for every ${renewalIntervalSeconds}s`);
}

/**
 * Initialize secrets at application startup
 */
async function initializeSecrets() {
  try {
    // Authenticate if needed
    if (!process.env.VAULT_TOKEN && process.env.VAULT_ROLE_ID) {
      await authenticateVaultAppRole();
    }

    const secrets = await getSecretsFromVault();

    // Load into environment
    Object.keys(secrets).forEach(key => {
      process.env[key] = secrets[key];
    });

    // Setup token renewal
    setupTokenRenewal();

    console.log('✓ Secrets successfully loaded from Vault');
    return secrets;
  } catch (error) {
    console.error('✗ Failed to initialize secrets:', error.message);
    process.exit(1);
  }
}

module.exports = {
  getSecretsFromVault,
  authenticateVaultAppRole,
  renewVaultToken,
  setupTokenRenewal,
  initializeSecrets,
  validateRequiredSecrets
};

// Usage in app.js:
// const { initializeSecrets } = require('./config-vault');
// await initializeSecrets();

