/**
 * Azure Key Vault Configuration
 * For applications deployed on Azure
 * 
 * Prerequisites:
 * - npm install @azure/identity @azure/keyvault-secrets
 * - Managed Identity or Service Principal credentials
 * - Environment variables:
 *   - KEY_VAULT_NAME: your-keyvault-name
 *   - AZURE_TENANT_ID (optional, for service principal)
 *   - AZURE_CLIENT_ID (optional, for service principal)
 *   - AZURE_CLIENT_SECRET (optional, for service principal)
 */

const { DefaultAzureCredential, ClientSecretCredential } = require("@azure/identity");
const { SecretClient } = require("@azure/keyvault-secrets");

let client;

/**
 * Initialize Azure Key Vault client
 * Uses DefaultAzureCredential which tries multiple auth methods:
 * 1. Environment variables
 * 2. Managed Identity
 * 3. Azure CLI
 * 4. Visual Studio
 */
function initializeKeyVaultClient() {
  const keyVaultName = process.env.KEY_VAULT_NAME;

  if (!keyVaultName) {
    throw new Error('KEY_VAULT_NAME environment variable is required');
  }

  const keyVaultUrl = `https://${keyVaultName}.vault.azure.net/`;

  let credential;

  // Use service principal if credentials provided
  if (process.env.AZURE_CLIENT_ID && process.env.AZURE_CLIENT_SECRET) {
    credential = new ClientSecretCredential(
      process.env.AZURE_TENANT_ID,
      process.env.AZURE_CLIENT_ID,
