/**
 * SECURE APP.JS - Properly handles secrets from external sources
 * 
 * This version demonstrates best practices:
 * 1. Loads secrets from external secrets manager (not .env files)
 * 2. Validates secrets at startup
 * 3. Never logs sensitive information
 * 4. Implements authentication and authorization
 * 5. Includes comprehensive security headers
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

// Choose your secrets manager:
// const { initializeSecrets: initSecretsAWS } = require('./config-aws-secrets-manager');
// const { initializeSecrets: initSecretsVault } = require('./config-vault');
// const { initializeSecrets: initSecretsAzure } = require('./config-azure-keyvault');

const app = express();

// ========================================
// INITIALIZATION - Call before starting server
// ========================================

/**
 * Initialize application with secrets
 * This should be called BEFORE starting the server
 */
async function initializeApp() {
  try {
    // Load secrets from your chosen secrets manager
    // Example: await initSecretsAWS();
    // Or: await initSecretsVault();
    // Or: await initSecretsAzure();

    // For development only - use .env but only with non-sensitive values
    require('dotenv').config();

    // Validate all required secrets are present
    validateSecrets();

    console.log('✓ Application initialized successfully');
    console.log(`✓ Environment: ${process.env.NODE_ENV}`);

    return true;
  } catch (error) {
    console.error('✗ Failed to initialize application:', error.message);
    process.exit(1);
  }
}

/**
 * Validate that all required secrets are configured
 */
function validateSecrets() {
  const requiredSecrets = [
    'JWT_SECRET',
    'NODE_ENV'
  ];

  const optionalSecrets = [
    'DATABASE_URL',
    'STRIPE_SECRET_KEY',
    'ANTHROPIC_API_KEY'
  ];

  // Check required secrets
  const missingRequired = requiredSecrets.filter(secret => !process.env[secret]);
  if (missingRequired.length > 0) {
    throw new Error(`Missing required secrets: ${missingRequired.join(', ')}`);
  }

  // Verify test secrets aren't in production
  if (process.env.NODE_ENV === 'production') {
    const testSecrets = requiredSecrets.filter(
      secret => process.env[secret]?.toLowerCase().includes('test')
    );

    if (testSecrets.length > 0) {
      throw new Error(`Test secrets found in production: ${testSecrets.join(', ')}`);
    }
  }

  console.log(`✓ All required secrets validated`);
  console.log(`✓ Using ${optionalSecrets.filter(s => process.env[s]).length} optional secrets`);
}

// ========================================
// SECURITY MIDDLEWARE
// ========================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  frameguard: { action: 'deny' },
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  noSniff: true,
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));

// Data sanitization
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(xss()); // Prevent XSS attacks

// CORS - restrict to trusted origins
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400,
};
app.use(cors(corsOptions));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Skip health checks
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later.',
});

app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Request logging (sanitized - no secrets)
const morganFormat = ':remote-addr - [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] - :response-time ms';
app.use(morgan(morganFormat, {
  skip: (req) => req.path === '/health',
  stream: process.stderr
}));

// Sanitize request headers before logging
app.use((req, res, next) => {
  // Never log Authorization header or sensitive headers
  const sensitiveHeaders = ['authorization', 'cookie', 'x-api-key'];
  sensitiveHeaders.forEach(header => {
    if (req.headers[header]) {
      delete req.headers[header];
    }
  });
  next();
});

// ========================================
// AUTHENTICATION MIDDLEWARE
// ========================================

/**
 * Authenticate JWT token
 * Expected header: Authorization: Bearer <token>
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    // Log security event without exposing details
    console.warn(`[SECURITY] Missing auth token - ${req.method} ${req.path} from ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      console.warn(`[SECURITY] Invalid token - ${req.method} ${req.path} from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    req.user = user;
    next();
  });
}

/**
 * Authorize based on user role
 */
function authorize(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      console.warn(`[SECURITY] Unauthorized access attempt - User: ${req.user.id}, Role: ${req.user.role}, Path: ${req.path}`);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
}

// ========================================
// ROUTES
// ========================================

/**
 * Health check endpoint
 * No authentication required - for monitoring/load balancers
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV,
  });
});

/**
 * Protected endpoint - requires authentication
 */
app.get('/users', authenticateToken, authorize('admin'), (req, res) => {
  // Only admin users can access this endpoint
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

/**
 * Login endpoint - issues JWT token
 */
app.post('/login', strictLimiter, express.json(), (req, res) => {
  try {
    // Validate input
    const { username, password } = req.body;

    if (!username || !password) {
      return res.status(400).json({ error: 'Username and password required' });
    }

    // TODO: Verify credentials against database
    // WARNING: This is pseudo-code - use proper authentication

    const user = {
      id: 1,
      username: username,
      role: 'user'
    };

    // Issue JWT token
    const token = jwt.sign(user, process.env.JWT_SECRET, { expiresIn: '1h' });

    res.json({ token });
  } catch (error) {
    console.error('[ERROR] Login error:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ========================================
// ERROR HANDLING
// ========================================

/**
 * 404 handler
 */
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';
  const status = err.status || err.statusCode || 500;

  // Log error details securely
  console.error({
    timestamp: new Date().toISOString(),
    status,
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    // Only include stack trace in development
    stack: isDevelopment ? err.stack : undefined,
  });

  // Send generic error response (don't expose details to client)
  res.status(status).json({
    error: isDevelopment ? err.message : 'Internal server error',
    requestId: req.id || 'unknown',
  });
});

// ========================================
// SERVER STARTUP
// ========================================

const PORT = process.env.PORT || 3000;

async function start() {
  try {
    // Initialize app with secrets
    await initializeApp();

    // Start server
    const server = app.listen(PORT, () => {
      console.log(`✓ Server running on port ${PORT}`);
      console.log(`✓ Environment: ${process.env.NODE_ENV}`);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('SIGTERM received, shutting down gracefully');
      server.close(() => {
        console.log('Server closed');
        process.exit(0);
      });
    });

    process.on('SIGINT', () => {
      console.log('SIGINT received, shutting down gracefully');
      server.close(() => {
        console.log('Server closed');
        process.exit(0);
      });
    });
  } catch (error) {
    console.error('Failed to start server:', error.message);
    process.exit(1);
  }
}

// Start application
if (require.main === module) {
  start();
}

module.exports = app;
