```javascript
const express = require('express');
const AWS = require('aws-sdk');
const helmet = require('helmet');

const app = express();
const secretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION });
const logger = console; // Use proper logger in production

// Secrets cache (with TTL)
const secretsCache = {
  data: {},
  expiresAt: 0,
  TTL: 3600000, // 1 hour
};

async function getCachedSecret(secretName) {
  const now = Date.now();

  // Return from cache if not expired
  if (secretsCache.data[secretName] && secretsCache.expiresAt > now) {
    logger.info(`Cache hit for secret: ${secretName}`);
    return secretsCache.data[secretName];
  }

  // Fetch from Secrets Manager
  try {
    logger.info(`Fetching secret from Secrets Manager: ${secretName}`);
    const data = await secretsManager
      .getSecretValue({ SecretId: secretName })
      .promise();

    const secretValue = 'SecretString' in data 
      ? JSON.parse(data.SecretString)
      : Buffer.from(data.SecretBinary, 'base64').toString('utf-8');

    // Cache the secret
    secretsCache.data[secretName] = secretValue;
    secretsCache.expiresAt = now + secretsCache.TTL;

    return secretValue;
  } catch (error) {
    logger.error(`Failed to retrieve secret ${secretName}:`, error.message);

    // Return from cache even if expired (failover)
    if (secretsCache.data[secretName]) {
      logger.warn(`Using expired cached secret for: ${secretName}`);
      return secretsCache.data[secretName];
    }

    throw new Error(`Failed to load required secret: ${secretName}`);
  }
}

// Initialize secrets on startup
let secrets = {};

async function initializeSecrets() {
  try {
    logger.info('Initializing secrets...');

    secrets = {
      database: await getCachedSecret('production/database'),
      aws: await getCachedSecret('production/aws-credentials'),
      anthropic: await getCachedSecret('production/anthropic-api'),
      stripe: await getCachedSecret('production/stripe-keys'),
      logfire: await getCachedSecret('production/logfire-token'),
    };

    logger.info('Secrets loaded successfully');
  } catch (error) {
    logger.error('Failed to initialize secrets:', error);
    process.exit(1); // Fail fast if secrets unavailable
  }
}

// Verify required environment variables
function validateEnvironment() {
  const required = ['AWS_REGION', 'NODE_ENV'];
  const missing = required.filter(v => !process.env[v]);

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
}

// Middleware: Secrets rotation checker
app.use((req, res, next) => {
  // Optionally refresh secrets if cache expired
  const now = Date.now();
  if (secretsCache.expiresAt < now) {
    logger.info('Secrets cache expired, will refresh on next access');
    secretsCache.data = {}; // Clear cache
  }
  next();
});

// Security headers
app.use(helmet());

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Access secrets securely
  const dbUrl = secrets.database.DATABASE_URL;
  // Use dbUrl to connect to database

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Error handling
app.use((err, req, res, next) => {
  logger.error('Error:', err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// Startup
const PORT = process.env.PORT || 3000;

async function start() {
  try {
    validateEnvironment();
    await initializeSecrets();

    app.listen(PORT, () => {
      logger.info(`Server running on port ${PORT}`);
    });
  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
}

start();

module.exports = app;
```

