## PART 2: SECURE SECRETS MANAGEMENT SOLUTIONS

### SOLUTION 1: AWS Secrets Manager (Production - Recommended)

```javascript
// config/secrets.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

class SecretsManager {
  constructor() {
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
    this.cacheTimestamps = {};
  }

  async getSecret(secretName) {
    // Check cache
    if (this.cache[secretName] && this.isCacheValid(secretName)) {
      console.log(`Using cached secret: ${secretName}`);
      return this.cache[secretName];
    }

    try {
      const params = { SecretId: secretName };
      const data = await secretsManager.getSecretValue(params).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache[secretName] = secret;
      this.cacheTimestamps[secretName] = Date.now();

      return secret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  isCacheValid(secretName) {
    const timestamp = this.cacheTimestamps[secretName];
    return timestamp && (Date.now() - timestamp) < this.cacheTTL;
  }

  invalidateCache(secretName) {
    delete this.cache[secretName];
    delete this.cacheTimestamps[secretName];
  }
}

module.exports = new SecretsManager();
```

