// Secure version of app.js with security best practices
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const { query, validationResult } = require('express-validator');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ===== LOGGING SETUP =====
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ===== SECURITY MIDDLEWARE =====

// 1. Helmet - Security headers
app.use(helmet());

// 2. HTTPS Enforcement (production only)
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure && req.get('x-forwarded-proto') !== 'https') {
      logger.warn({
        event: 'insecure_request_detected',
        ip: req.ip,
        path: req.path,
      });
      return res.redirect('https://' + req.get('host') + req.url);
    }
    next();
  });
}

// 3. CORS Configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// 4. Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res, next, options) => {
    logger.warn({
      event: 'rate_limit_exceeded',
      ip: req.ip,
      path: req.path,
    });
    res.status(429).json({
      error: options.message,
    });
  },
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many requests for this endpoint',
});

app.use(limiter);

// 6. Audit Logging Middleware
const auditLog = (req, res, next) => {
  const startTime = Date.now();
  res.on('finish', () => {
    logger.info({
      method: req.method,
      path: req.path,
      status: res.statusCode,
      userId: req.user?.id,
      ip: req.ip,
      duration: Date.now() - startTime,
    });
  });
  next();
};
app.use(auditLog);

// ===== AUTHENTICATION MIDDLEWARE =====
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      event: 'authentication_failed',
      reason: 'missing_token',
      ip: req.ip,
      path: req.path,
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key', (err, user) => {
    if (err) {
      logger.warn({
        event: 'authentication_failed',
        reason: 'invalid_token',
        ip: req.ip,
        path: req.path,
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ===== VALIDATION MIDDLEWARE =====
const validateUserQuery = [
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('name').optional().trim().isLength({ min: 1, max: 100 }).escape(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({
        event: 'validation_failed',
        errors: errors.array(),
        ip: req.ip,
      });
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
];

// ===== ROUTES =====

// Health check (public)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
  });
});

// Get users (protected + validated + rate limited)
app.get('/users', authenticateToken, strictLimiter, validateUserQuery, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Filter sensitive data based on permissions
  const responseUsers = users.map(user => {
    if (req.user.role === 'admin' || req.user.id === user.id) {
      return user;
    }
    return {
      id: user.id,
      name: user.name,
      email: user.email.replace(/(.{2}).*(@.*)/, '$1***$2'),
    };
  });

  res.json(responseUsers);
});

// Login endpoint to get JWT (simplified for example)
app.post('/login', rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts',
}), (req, res) => {
  // In production, validate credentials against database
  const user = {
    id: 1,
    role: 'user',
  };

  const token = jwt.sign(user, process.env.JWT_SECRET || 'your-secret-key', {
    expiresIn: '1h',
  });

  logger.info({
    event: 'user_login',
    userId: user.id,
    ip: req.ip,
  });

  res.json({ token });
});

// ===== ERROR HANDLING =====

// 404 handler
app.use((req, res) => {
  logger.warn({
    event: 'not_found',
    path: req.path,
    method: req.method,
    ip: req.ip,
  });
  res.status(404).json({ error: 'Not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    ip: req.ip,
    userId: req.user?.id,
  });

  const isDevelopment = NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ===== SERVER START =====
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

module.exports = app;
EOF

