  origin: function(origin, callback) {
    const allowedOrigins = [
      'https://example.com',
      'https://app.example.com',
      'http://localhost:3000' // Only for development
    ];

    if (process.env.NODE_ENV === 'production' && !allowedOrigins.includes(origin)) {
