/**
 * AWS SECRETS MANAGER IMPLEMENTATION
 * ===================================
 * Secure secrets loading without .env files
 * 
 * Usage:
 *   const secrets = require('./aws_secrets_implementation');
 *   const app = require('./app_secure')(secrets);
 */

const AWS = require('aws-sdk');

// Configure AWS client
const secretsClient = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
});

/**
 * Cache for secrets (in-memory)
 * TTL: 5 minutes (rotate every 5 min from secrets manager)
 */
let secretsCache = {
  data: null,
  timestamp: null,
  TTL: 5 * 60 * 1000, // 5 minutes
};

/**
 * Fetch secrets from AWS Secrets Manager
 * @returns {Promise<Object>} Secrets object
 */
async function fetchSecrets() {
  try {
    // Check cache validity
    if (secretsCache.data && 
        Date.now() - secretsCache.timestamp < secretsCache.TTL) {
      console.log('✓ Using cached secrets');
      return secretsCache.data;
    }

    console.log('Fetching secrets from AWS Secrets Manager...');

    const secretName = process.env.SECRETS_ARN || 'app/production/secrets';

    const response = await secretsClient
      .getSecretValue({ SecretId: secretName })
      .promise();

    let secrets;

    // Handle different response types
    if ('SecretString' in response) {
      secrets = JSON.parse(response.SecretString);
    } else {
      // Binary secret
      const buff = Buffer.from(response.SecretBinary, 'base64');
      secrets = JSON.parse(buff.toString('ascii'));
    }

    // Update cache
    secretsCache.data = secrets;
    secretsCache.timestamp = Date.now();

    console.log('✓ Secrets loaded from AWS Secrets Manager');
    return secrets;

  } catch (error) {
    console.error('❌ Failed to fetch secrets from AWS:', error.message);

    // Don't fall back to .env or hardcoded values - fail fast!
    if (process.env.NODE_ENV === 'production') {
      throw new Error('CRITICAL: Cannot fetch secrets in production. Service cannot start.');
    }

    throw error;
  }
}

/**
 * Validate secrets format and required values
 * @param {Object} secrets - Secrets object
 * @returns {Boolean} true if valid
 */
function validateSecrets(secrets) {
  const required = [
    'JWT_SECRET',
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'STRIPE_SECRET_KEY',
  ];

  const optional = [
    'ANTHROPIC_API_KEY',
    'LOGFIRE_TOKEN',
    'ALLOWED_ORIGINS',
  ];

  // Check required secrets
  for (const key of required) {
    if (!secrets[key]) {
      throw new Error(`Missing required secret: ${key}`);
    }

    // Validate format (don't log values!)
    if (key === 'JWT_SECRET' && secrets[key].length < 32) {
      throw new Error(`${key} must be at least 32 characters`);
    }

    if (key === 'DATABASE_URL' && !secrets[key].startsWith('postgres://')) {
      throw new Error(`${key} must be a valid PostgreSQL connection string`);
    }

    if (key.includes('SECRET_KEY') && secrets[key].length < 20) {
      throw new Error(`${key} appears too weak (min 20 chars)`);
    }

    if (key === 'AWS_ACCESS_KEY_ID' && !secrets[key].startsWith('AKIA')) {
      console.warn(`⚠️  ${key} doesn't match expected AWS format`);
    }

    if (key === 'STRIPE_SECRET_KEY' && !secrets[key].startsWith('sk_')) {
      console.warn(`⚠️  ${key} doesn't match expected Stripe format`);
    }
  }

  // Check optional secrets
  for (const key of optional) {
    if (secrets[key]) {
      console.log(`✓ Optional secret configured: ${key}`);
    }
  }

  console.log(`✓ All ${required.length} required secrets validated`);
  return true;
}

/**
 * Initialize secrets - fetch and validate
 * Call this once at application startup
 */
async function initialize() {
  console.log('=== Secrets Manager Initialization ===');

  try {
    const secrets = await fetchSecrets();
    validateSecrets(secrets);
    console.log('✓ Secrets initialized successfully\n');
    return secrets;
  } catch (error) {
    console.error('✗ Secrets initialization failed:', error.message);
    process.exit(1);
  }
}

/**
 * Get a specific secret (with validation)
 * @param {String} key - Secret key
 * @returns {String} Secret value
 */
function getSecret(key) {
  if (!secretsCache.data) {
    throw new Error('Secrets not initialized. Call initialize() first.');
  }

  if (!secretsCache.data[key]) {
    throw new Error(`Secret not found: ${key}`);
  }

  return secretsCache.data[key];
}

/**
 * Check if secret exists
 * @param {String} key - Secret key
 * @returns {Boolean}
 */
function hasSecret(key) {
  return secretsCache.data && key in secretsCache.data;
}

/**
 * Trigger manual cache refresh
 * Useful for testing secret rotation
 */
async function refreshSecrets() {
  console.log('Refreshing secrets from AWS Secrets Manager...');
  secretsCache.timestamp = 0; // Force refresh
  return fetchSecrets();
}

/**
 * Get all secrets (CAREFUL - only use for logging/monitoring)
 * Do NOT log actual values!
 * @returns {Object} Object with keys only (values masked)
 */
function getSecretsMetadata() {
  if (!secretsCache.data) {
    return null;
  }

  return Object.keys(secretsCache.data).reduce((acc, key) => {
    acc[key] = '***REDACTED***';
    return acc;
  }, {});
}

module.exports = {
  initialize,
  getSecret,
  hasSecret,
  refreshSecrets,
  getSecretsMetadata,
  fetchSecrets, // For testing only
  validateSecrets, // For testing only
};

// ===== USAGE EXAMPLE =====
/*
// In your app.js or main entry point:

const secretsManager = require('./aws_secrets_implementation');

async function startApp() {
  // Initialize secrets before anything else
  const secrets = await secretsManager.initialize();

  // Use secrets throughout app
  const JWT_SECRET = secretsManager.getSecret('JWT_SECRET');
  const DATABASE_URL = secretsManager.getSecret('DATABASE_URL');

  // Pass to app factory
  const app = require('./app_secure_with_secrets')(secrets);

  app.listen(3000, () => {
    console.log('✓ App started with secrets from AWS');
    console.log('✓ Available secrets:', 
      Object.keys(secretsManager.getSecretsMetadata())
    );
  });
}

startApp().catch(error => {
  console.error('Failed to start app:', error);
  process.exit(1);
});
*/
EOF
