  const required = [...requiredSecrets.all, ...requiredSecrets[env]];

  const missing = required.filter(secret => !process.env[secret]);

  if (missing.length > 0) {
    logger.error('Missing required environment variables', { missing });
    throw new Error(`Missing secrets: ${missing.join(', ')}`);
  }
