# Quick Security Implementation Guide

## Step-by-Step Remediation

### Step 1: Install Dependencies (5 minutes)

```bash
npm install express helmet cors express-rate-limit jsonwebtoken express-validator uuid dotenv

# Optional: for development
npm install --save-dev nodemon
```

### Step 2: Create Environment File (2 minutes)

```bash
cp .env.example .env
```

Edit `.env` and add your values:
```bash
JWT_SECRET=$(node -e "console.log(require('crypto').randomBytes(32).toString('hex'))")
echo "JWT_SECRET=$JWT_SECRET" > .env
echo "NODE_ENV=development" >> .env
echo "PORT=3000" >> .env
echo "ALLOWED_ORIGINS=http://localhost:3000,http://localhost:3001" >> .env
```

### Step 3: Implement Authentication (15 minutes)

Create `middleware/auth.js`:
```javascript
const jwt = require('jsonwebtoken');

const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(403).json({ error: 'Invalid or expired token' });
  }
};

module.exports = authMiddleware;
```

### Step 4: Add Security Middleware (10 minutes)

Update `app.js`:
```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { v4: uuidv4 } = require('uuid');
const authMiddleware = require('./middleware/auth');

const app = express();

// Request tracking
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// Security headers
app.use(helmet());

// CORS
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || '').split(','),
  credentials: true,
}));

// Rate limiting
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
}));

// JSON parser
app.use(express.json({ limit: '1mb' }));

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authMiddleware, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// Error handling
app.use((err, req, res, next) => {
  console.error(`[${req.id}] Error:`, err);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message,
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server on port ${PORT}`));

module.exports = app;
```

### Step 5: Add Input Validation (10 minutes)

Create `middleware/validators.js`:
```javascript
const { query, validationResult } = require('express-validator');

const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1 })
    .toInt()
    .withMessage('ID must be a positive integer'),
];

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

module.exports = { validateUserQuery, handleValidationErrors };
```

### Step 6: Test Security (5 minutes)

```bash
# Start server
npm start

# In another terminal, run tests
chmod +x security_tests.sh
./security_tests.sh
```

### Step 7: Generate Valid JWT for Testing (2 minutes)

```bash
node -e "
const jwt = require('jsonwebtoken');
require('dotenv').config();
const token = jwt.sign(
  { userId: 1, role: 'admin' }, 
  process.env.JWT_SECRET,
  { expiresIn: '1h' }
);
console.log('Valid token:', token);
"
```

Use the token:
```bash
