const express = require('express');
const AWS = require('aws-sdk');
const logger = require('./logger');

const app = express();

// Initialize AWS Secrets Manager client
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'eu-west-1'
});

// Cache for secrets to avoid repeated API calls
const secretsCache = new Map();
const CACHE_TTL = 3600000; // 1 hour

/**
 * Fetch secret from AWS Secrets Manager with caching
 * @param {string} secretName - Name of the secret in Secrets Manager
 * @returns {Promise<object>} - Parsed secret value
 */
async function getSecret(secretName) {
  // Check cache first
  const cached = secretsCache.get(secretName);
  if (cached && cached.expiresAt > Date.now()) {
    logger.debug(`Using cached secret: ${secretName}`);
    return cached.value;
  }

  try {
    const params = { SecretId: secretName };
    const response = await secretsManager.getSecretValue(params).promise();

    // Parse secret (could be JSON)
    let secretValue;
    if ('SecretString' in response) {
      secretValue = JSON.parse(response.SecretString);
    } else {
      secretValue = Buffer.from(response.SecretBinary, 'base64').toString();
    }

    // Cache the secret
    secretsCache.set(secretName, {
      value: secretValue,
      expiresAt: Date.now() + CACHE_TTL
    });

    logger.info(`Successfully retrieved secret: ${secretName}`);
    return secretValue;
  } catch (error) {
    logger.error(`Failed to retrieve secret ${secretName}:`, error);
    throw new Error(`Could not retrieve secret: ${secretName}`);
  }
}

/**
 * Initialize secrets at application startup
 */
let secrets = {};

