const logger = require('./logger');

const app = express();

// Initialize Vault client
const vault = new VaultClient({
  endpoint: process.env.VAULT_ADDR || 'http://vault:8200',
  token: process.env.VAULT_TOKEN
});

// Cache for secrets
const secretsCache = new Map();
const CACHE_TTL = 3600000; // 1 hour

/**
 * Fetch secret from Vault with caching
 * @param {string} path - Path to secret in Vault (e.g., 'secret/data/app/database')
 * @returns {Promise<object>} - Secret value
 */
async function getVaultSecret(path) {
  // Check cache
  const cached = secretsCache.get(path);
  if (cached && cached.expiresAt > Date.now()) {
    logger.debug(`Using cached secret from Vault: ${path}`);
    return cached.value;
  }

  try {
    const secret = await vault.read(path);
    const secretValue = secret.data.data; // Vault KV v2 returns data.data

    // Cache it
    secretsCache.set(path, {
      value: secretValue,
      expiresAt: Date.now() + CACHE_TTL
    });

    logger.info(`Successfully retrieved secret from Vault: ${path}`);
    return secretValue;
  } catch (error) {
    logger.error(`Failed to retrieve secret from Vault (${path}):`, error);
    throw new Error(`Could not retrieve secret: ${path}`);
  }
}

/**
 * Refresh secrets periodically
 */
async function setupSecretRefresh() {
  const REFRESH_INTERVAL = 30 * 60 * 1000; // 30 minutes

  setInterval(async () => {
    try {
      logger.info('Refreshing secrets from Vault');
      secretsCache.clear(); // Force refresh on next access
    } catch (error) {
      logger.error('Error during secret refresh:', error);
    }
  }, REFRESH_INTERVAL);
}

/**
 * Handle Vault token renewal
 */
async function setupTokenRenewal() {
  // If using AppRole or other auth, implement token renewal
  setInterval(async () => {
    try {
      await vault.token.renew();
      logger.debug('Vault token renewed');
    } catch (error) {
      logger.error('Failed to renew Vault token:', error);
    }
  }, 30 * 60 * 1000); // Renew every 30 minutes
}

let secrets = {};

async function initializeSecrets() {
  try {
    // Load database credentials
    const dbSecret = await getVaultSecret('secret/data/app/production/database');

    // Load API keys
    const apiKeysSecret = await getVaultSecret('secret/data/app/production/api-keys');

    // Load encryption keys
    const encryptionSecret = await getVaultSecret('secret/data/app/production/encryption');

    secrets = {
      database: dbSecret,
      apiKeys: apiKeysSecret,
      encryption: encryptionSecret
    };

    logger.info('Secrets initialized successfully from Vault');
    setupSecretRefresh();
    setupTokenRenewal();

    return secrets;
  } catch (error) {
    logger.error('Failed to initialize secrets from Vault:', error);
    process.exit(1);
  }
}

// ==================== ROUTES ====================

