## **SOLUTION 1: AWS Secrets Manager (Best for AWS-heavy apps)**

### Implementation:

```javascript
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Singleton pattern to cache secrets
let cachedSecrets = null;
let cacheExpiry = null;

async function getSecrets() {
  // Cache for 1 hour to reduce API calls
  if (cachedSecrets && cacheExpiry > Date.now()) {
    return cachedSecrets;
  }

  try {
    const data = await secretsManager.getSecretValue({
      SecretId: `${process.env.NODE_ENV}/app/secrets`
    }).promise();

    let secrets;
    if ('SecretString' in data) {
      secrets = JSON.parse(data.SecretString);
    } else {
      secrets = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }

    cachedSecrets = secrets;
    cacheExpiry = Date.now() + (60 * 60 * 1000); // 1 hour cache
    return secrets;
  } catch (error) {
    console.error('Failed to fetch secrets:', error);
    throw new Error('Secret retrieval failed');
  }
}

// Usage in app.js
