const fs = require('fs');
const crypto = require('crypto');
const dotenv = require('dotenv');

// Encryption key should come from secure source (not committed)
const encryptionKey = Buffer.from(process.env.ENV_ENCRYPTION_KEY, 'hex');

function decryptEnvFile(filePath) {
  const encrypted = fs.readFileSync(filePath, 'utf8');

  // Extract IV (first 32 chars of hex = 16 bytes)
  const iv = Buffer.from(encrypted.slice(0, 32), 'hex');
  const encryptedData = Buffer.from(encrypted.slice(32), 'hex');

  const decipher = crypto.createDecipheriv('aes-256-cbc', encryptionKey, iv);
  let decrypted = decipher.update(encryptedData);
  decrypted = Buffer.concat([decrypted, decipher.final()]);

  return decrypted.toString('utf8');
}

// Usage
const decryptedEnv = decryptEnvFile('.env.test.enc');
dotenv.parse(decryptedEnv);
