#### **Option A: AWS Secrets Manager** (Production)
```javascript
const AWS = require('aws-sdk');

const secretsClient = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

class SecretsManager {
  constructor() {
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    const now = Date.now();

    // Return cached secret if still valid
    if (this.cache[secretName] && (now - this.cache[secretName].timestamp) < this.cacheTTL) {
      return this.cache[secretName].value;
    }

    try {
      const response = await secretsClient.getSecretValue({
        SecretId: secretName
      }).promise();

      const secretValue = response.SecretString 
        ? JSON.parse(response.SecretString)
        : response.SecretBinary;

      // Cache the secret
      this.cache[secretName] = {
        value: secretValue,
        timestamp: now
      };

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getSecrets(secretNames) {
    return Promise.all(secretNames.map(name => this.getSecret(name)));
  }
}

module.exports = new SecretsManager();
```

