class EnvironmentValidator {
  static validateSecrets(requiredSecrets) {
    const missing = [];
    const unsafe = [];

    requiredSecrets.forEach(secret => {
      if (!process.env[secret]) {
        missing.push(secret);
      }

      // Warn if secret is empty string or placeholder
      if (process.env[secret] === '' || process.env[secret]?.includes('PLACEHOLDER')) {
        unsafe.push(secret);
      }
    });

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    if (unsafe.length > 0) {
      throw new Error(`Unsafe/placeholder secrets detected: ${unsafe.join(', ')}`);
    }

    return true;
  }
}

