const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

class RotationLogger {
  async logRotation(rotationEvent) {
    // Store metadata in secure audit database, NOT files
    const auditRecord = {
      timestamp: new Date().toISOString(),
      secretArn: rotationEvent.SecretId,
      rotationId: rotationEvent.RotationId,
      clientRequestToken: rotationEvent.ClientRequestToken,
      step: rotationEvent.Step, // createSecret, setSecret, testSecret, finishSecret
      status: 'success' // or 'failure'
    };

    // Store in DynamoDB or secure database
    await this.auditDatabase.put(auditRecord);

    // NEVER return actual secret values
    return {
      rotationId: rotationEvent.RotationId,
      status: 'logged',
      timestamp: auditRecord.timestamp
    };
  }

  async getRotationHistory(secretName) {
    // Retrieve only metadata
    const records = await this.auditDatabase.query({
      secretArn: secretName
    });

    return records.map(r => ({
      timestamp: r.timestamp,
      step: r.step,
      status: r.status,
      rotationId: r.rotationId
      // NEVER include: secret_value, preview, hash, or any credential info
    }));
  }
}

module.exports = new RotationLogger();
