const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

class SecretManager {
  constructor() {
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
    this.lastRotationCheck = {};
  }

  async getSecret(secretName) {
    const now = Date.now();

    // Check if cached and not expired
    if (this.cache[secretName] && 
        (now - this.lastRotationCheck[secretName]) < this.cacheTTL) {
      return this.cache[secretName];
    }

    try {
      const result = await secretsManager.getSecretValue({
        SecretId: secretName
      }).promise();

      const secret = result.SecretString ? 
        JSON.parse(result.SecretString) : 
        result.SecretBinary;

      // Cache the secret
      this.cache[secretName] = secret;
      this.lastRotationCheck[secretName] = now;

      return secret;
    } catch (error) {
      console.error(`Failed to fetch secret ${secretName}:`, error);

      // Return cached version if fetch fails
      if (this.cache[secretName]) {
        console.warn(`Using cached version of ${secretName}`);
        return this.cache[secretName];
      }

      throw error;
    }
  }

  // Listen for rotation events
  onSecretRotation(secretName, callback) {
    // In production, set up EventBridge to listen for rotation events
    secretsManager.on('SecretRotationEvent', (event) => {
      if (event.SecretId === secretName) {
        console.log(`Secret ${secretName} was rotated`);
        // Clear cache to force refresh
        delete this.cache[secretName];
        delete this.lastRotationCheck[secretName];
        callback();
      }
    });
  }
}

