```javascript
// lib/secrets.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION
});

const secretCache = {};
const CACHE_TTL = 3600000; // 1 hour

async function getSecret(secretName) {
  // Return cached secret if valid
  if (secretCache[secretName]?.expiry > Date.now()) {
    return secretCache[secretName].value;
  }

  try {
    const result = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    const secretValue = result.SecretString 
      ? JSON.parse(result.SecretString) 
      : result.SecretBinary;

    // Cache the secret
    secretCache[secretName] = {
      value: secretValue,
      expiry: Date.now() + CACHE_TTL
    };

    return secretValue;
  } catch (error) {
    console.error(`Failed to retrieve secret ${secretName}:`, error.message);

    // Try to use cached value if fetch fails
    if (secretCache[secretName]?.value) {
      console.warn(`Using stale cached secret for ${secretName}`);
      return secretCache[secretName].value;
    }

    throw new Error(`Critical: Cannot load secret ${secretName}`);
