/**
 * SECURED APPLICATION - SECRETS MANAGEMENT BEST PRACTICES
 * 
 * This file demonstrates proper secrets management patterns
 * replacing direct .env file loading with a secrets manager
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { v4: uuidv4 } = require('uuid');

// ============================================================================
// SECRETS LOADING - MULTIPLE STRATEGIES
// ============================================================================

/**
 * Strategy 1: AWS Secrets Manager (Recommended for AWS)
 */
class AWSSecretsManager {
  constructor() {
    const AWS = require('aws-sdk');
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();
      const secret = data.SecretString ? JSON.parse(data.SecretString) : data.SecretBinary;

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret: ${secretName}`, error);
      throw new Error(`Failed to load secret: ${secretName}`);
    }
  }
}

/**
 * Strategy 2: HashiCorp Vault (Recommended for multi-cloud)
 */
class VaultSecretsManager {
  constructor() {
    const vault = require('node-vault');
    this.client = vault({
      endpoint: process.env.VAULT_ADDR || 'http://vault:8200',
      token: process.env.VAULT_TOKEN
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(path) {
    const cached = this.cache.get(path);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const secret = await this.client.read(path);
      const data = secret.data.data;

      this.cache.set(path, {
        value: data,
        expiresAt: Date.now() + this.cacheTTL
      });

      return data;
    } catch (error) {
      console.error(`Failed to retrieve secret from Vault: ${path}`, error);
      throw new Error(`Failed to load secret from Vault: ${path}`);
    }
  }
}

/**
 * Strategy 3: GCP Secret Manager (Recommended for GCP)
 */
class GCPSecretsManager {
  constructor() {
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
    this.client = new SecretManagerServiceClient();
    this.projectId = process.env.GCP_PROJECT_ID;
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const name = this.client.secretVersionPath(this.projectId, secretName, 'latest');
      const [version] = await this.client.accessSecretVersion({ name });
      const secret = version.payload.data.toString('utf8');

      const data = JSON.parse(secret);
      this.cache.set(secretName, {
        value: data,
        expiresAt: Date.now() + this.cacheTTL
      });

      return data;
    } catch (error) {
      console.error(`Failed to retrieve secret from GCP: ${secretName}`, error);
      throw new Error(`Failed to load secret from GCP: ${secretName}`);
    }
  }
}

/**
 * Strategy 4: Azure Key Vault (Recommended for Azure)
 */
class AzureKeyVaultManager {
  constructor() {
    const { SecretClient } = require("@azure/keyvault-secrets");
    const { DefaultAzureCredential } = require("@azure/identity");
    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(
      `https://${process.env.AZURE_KEYVAULT_NAME}.vault.azure.net/`,
      credential
    );
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    const cached = this.cache.get(secretName);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const secret = await this.client.getSecret(secretName);
      const data = JSON.parse(secret.value);

      this.cache.set(secretName, {
        value: data,
        expiresAt: Date.now() + this.cacheTTL
      });

      return data;
    } catch (error) {
      console.error(`Failed to retrieve secret from Azure Key Vault: ${secretName}`, error);
      throw new Error(`Failed to load secret from Azure Key Vault: ${secretName}`);
    }
  }
}

/**
 * Unified Secrets Manager Interface
 */
class SecretsManager {
  constructor() {
    const provider = process.env.SECRETS_PROVIDER || 'vault'; // aws, vault, gcp, azure, local

    switch (provider) {
      case 'aws':
        this.manager = new AWSSecretsManager();
        break;
      case 'gcp':
        this.manager = new GCPSecretsManager();
        break;
      case 'azure':
        this.manager = new AzureKeyVaultManager();
        break;
      case 'vault':
        this.manager = new VaultSecretsManager();
        break;
      case 'local':
        // Only for development - loads from .env.local (git-ignored)
        if (process.env.NODE_ENV === 'production') {
          throw new Error('Local secrets provider cannot be used in production');
        }
        this.manager = new LocalSecretsManager();
        break;
      default:
        throw new Error(`Unknown secrets provider: ${provider}`);
    }
  }

  async getSecret(path) {
    return this.manager.getSecret(path);
  }
}

/**
 * Local Provider (Development Only)
 */
class LocalSecretsManager {
  constructor() {
    require('dotenv').config({ path: '.env.local' });
    this.secrets = process.env;
  }

  async getSecret(key) {
    const value = this.secrets[key];
    if (!value) {
      throw new Error(`Secret not found: ${key}`);
    }
    return { [key]: value };
  }
}

// ============================================================================
// SECRETS VALIDATION AND INITIALIZATION
// ============================================================================

class SecretsValidator {
  static async validateSecrets(secretsManager, requiredSecrets) {
    const missing = [];
    const loaded = {};

    for (const secretName of requiredSecrets) {
      try {
        loaded[secretName] = await secretsManager.getSecret(secretName);
      } catch (error) {
        missing.push(secretName);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    return loaded;
  }

  static validateSecretFormat(secrets) {
    const validations = {
      DATABASE_URL: (val) => /^postgres:\/\//.test(val),
      AWS_ACCESS_KEY_ID: (val) => /^AKIA/.test(val),
      AWS_SECRET_ACCESS_KEY: (val) => val && val.length > 20,
      ANTHROPIC_API_KEY: (val) => /^sk-ant-/.test(val),
      STRIPE_SECRET_KEY: (val) => /^sk_live_|^sk_test_/.test(val),
      LOGFIRE_TOKEN: (val) => val && val.length > 10
    };

    for (const [key, validator] of Object.entries(validations)) {
      if (secrets[key] && !validator(secrets[key])) {
        throw new Error(`Invalid format for secret: ${key}`);
      }
    }
  }
}

// ============================================================================
// APPLICATION INITIALIZATION
// ============================================================================

async function initializeApp() {
  try {
    // Initialize secrets manager
    const secretsManager = new SecretsManager();

    // Define required secrets
    const requiredSecrets = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN',
      'JWT_SECRET'
    ];

    // Load and validate secrets
    const secrets = await SecretsValidator.validateSecrets(secretsManager, requiredSecrets);
    SecretsValidator.validateSecretFormat(secrets);

    // Store secrets in secure context (not in global process.env)
    global.appSecrets = secrets;

    console.log('[INFO] Secrets loaded successfully from', process.env.SECRETS_PROVIDER);
    return secrets;
  } catch (error) {
    console.error('[CRITICAL] Failed to initialize secrets:', error.message);
    process.exit(1);
  }
}

// ============================================================================
// EXPRESS APPLICATION
// ============================================================================

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ============================================================================
// ROUTES
// ============================================================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    requestId: req.id
  });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' }
  ]);
});

// Error handling
app.use((err, req, res, next) => {
  console.error('[ERROR]', {
    requestId: req.id,
    message: err.message,
    stack: err.stack
  });

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message,
    requestId: req.id
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

async function start() {
  try {
    await initializeApp();

    app.listen(PORT, () => {
      console.log(`[INFO] Server running on port ${PORT}`);
      console.log(`[INFO] Secrets provider: ${process.env.SECRETS_PROVIDER}`);
      console.log(`[INFO] Environment: ${process.env.NODE_ENV}`);
    });
  } catch (error) {
    console.error('[CRITICAL] Failed to start server:', error);
    process.exit(1);
  }
}

start();

module.exports = app;

