const express = require('express');
const rateLimit = require('express-rate-limit');

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});

app.use(limiter);

// Data masking utility
const maskEmail = (email) => {
  const [localPart, domain] = email.split('@');
  const masked = localPart.substring(0, 2) + '*'.repeat(localPart.length - 2);
  return `${masked}@${domain}`;
};

// Secure endpoint with filtered data
app.get('/users', authenticateToken, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Filter based on authorization level
  const filteredUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    // Only expose full email if admin
    email: req.user.role === 'admin' ? user.email : maskEmail(user.email),
  }));

  res.json(filteredUsers);
});
```

---

#### **3. MISSING INPUT VALIDATION (OWASP #5 - Broken Access Control)**

**Severity: HIGH**

**Issue:**
- No query parameter validation
- No request body validation
- Vulnerable to malformed requests
- No parameter type checking

**Current Vulnerability:**
```javascript
// These requests would be accepted without validation:
// /users?id=<script>alert('xss')</script>
// /users?sort=../../../../etc/passwd
// /users?limit=-1&offset=999999999
```

**Recommendation:**
Implement comprehensive input validation:

```javascript
const { query, validationResult } = require('express-validator');

// Validation middleware
const validateUserQuery = [
  query('id').optional().isInt().toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  query('sort').optional().isIn(['id', 'name', 'email']),
];

app.get('/users', authenticateToken, validateUserQuery, (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { limit = 10, offset = 0, sort = 'id' } = req.query;

  // Safely query users
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const filtered = users.slice(offset, offset + limit);
  res.json(filtered);
});
```

---

#### **4. MISSING SECURITY HEADERS (OWASP #5 - Broken Access Control / #6 - Security Misconfiguration)**

**Severity: HIGH**

**Issue:**
- No Content Security Policy (CSP)
- No X-Frame-Options header
- No X-Content-Type-Options header
- Missing HSTS header
- No protection against clickjacking or MIME type sniffing

**Recommendation:**
Add security headers middleware:

```javascript
const helmet = require('helmet');

// Use helmet for security headers
app.use(helmet());

// Additional custom headers
app.use((req, res, next) => {
  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Enable XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Content Security Policy
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'self'; script-src 'self'; object-src 'none'"
  );

  // HSTS (HTTP Strict Transport Security)
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  next();
});
```

---

#### **5. NO HTTPS ENFORCEMENT (OWASP #2 - Cryptographic Failures)**

**Severity: CRITICAL**

**Issue:**
- Application runs on HTTP (port 3000)
- No HTTPS enforcement
- Data transmitted in plaintext
- Vulnerable to man-in-the-middle (MITM) attacks

**Recommendation:**
Enforce HTTPS in production:

```javascript
const https = require('https');
const fs = require('fs');

const app = express();

// Redirect HTTP to HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure) {
      return res.redirect(`https://${req.headers.host}${req.url}`);
    }
    next();
  });
}

if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH),
  };
  https.createServer(options, app).listen(443);
} else {
  app.listen(3000);
}
```

