// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

#### **7. MISSING CORS CONFIGURATION (OWASP #5 - Broken Access Control)**

**Severity: MEDIUM**

**Issue:**
- No CORS policy configured
- Application will either reject cross-origin requests or allow all origins
- Vulnerable to cross-site request forgery (CSRF)

**Recommendation:**
Configure CORS properly:

```javascript
const cors = require('cors');

// Configure CORS with whitelist
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 3600,
};

app.use(cors(corsOptions));

// CSRF protection for state-changing requests
const csrf = require('csurf');
const cookieParser = require('cookie-parser');

app.use(cookieParser());
app.use(csrf({ cookie: false }));
```

---

#### **8. NO LOGGING & MONITORING (OWASP #9 - Insufficient Logging & Monitoring)**

**Severity: MEDIUM**

**Issue:**
- No request logging
- No security event monitoring
- Impossible to audit access patterns
- Can't detect suspicious activity

