// Initialize client
const secretsClient = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

/**
 * Fetch secrets from AWS Secrets Manager
 * Implements caching to reduce API calls
 */
class AWSSecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour in milliseconds
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      console.log(`[CACHE HIT] Retrieved ${secretName} from cache`);
      return cached.value;
    }

    try {
      console.log(`[AWS SECRETS] Fetching ${secretName}...`);
      const data = await secretsClient.getSecretValue({
        SecretId: secretName,
      }).promise();

      let secretValue;
      if ('SecretString' in data) {
        secretValue = JSON.parse(data.SecretString);
      } else {
        secretValue = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      console.log(`[AWS SECRETS] Successfully loaded ${secretName}`);
      return secretValue;
    } catch (error) {
      console.error(`[ERROR] Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error(`Secrets Manager access denied for ${secretName}`);
    }
  }

  invalidateCache(secretName) {
    this.cache.delete(secretName);
  }

  invalidateAllCache() {
    this.cache.clear();
  }
}

