cat > secrets-manager.js << 'EOF'
/**
 * AWS Secrets Manager Integration
 * 
 * For production environments, retrieve secrets from AWS Secrets Manager
 * instead of environment files.
 * 
 * Features:
 * - Caching with TTL
 * - Automatic rotation support
 * - Error handling and fallback
 * - Development/testing modes
 */

const AWS = require('aws-sdk');

const logger = require('./logger');

class SecretsManager {
  constructor() {
    this.secretsClient = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  /**
   * Get secret from AWS Secrets Manager or cache
   * @param {string} secretName - Name of the secret in AWS
   * @returns {Promise<string>} Secret value
   */
  async getSecret(secretName) {
    // Check cache first
    if (this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        logger.debug(`Secret retrieved from cache: ${secretName}`);
        return cached.value;
      }
      this.cache.delete(secretName);
    }

    try {
      logger.debug(`Fetching secret from AWS: ${secretName}`);
      const response = await this.secretsClient.getSecretValue({
        SecretId: secretName,
      }).promise();

      let secretValue;
      if (response.SecretString) {
        secretValue = response.SecretString;
      } else if (response.SecretBinary) {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      } else {
        throw new Error(`Invalid secret format for ${secretName}`);
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now(),
      });

      logger.info(`Secret retrieved successfully: ${secretName}`);
      return secretValue;
    } catch (error) {
      logger.error(`Failed to retrieve secret: ${secretName}`, {
        error: error.message,
        code: error.code,
      });
      throw error;
    }
  }

  /**
   * Get secret as JSON object (for complex secrets like DB credentials)
   */
  async getSecretJson(secretName) {
    const secretString = await this.getSecret(secretName);
    try {
      return JSON.parse(secretString);
    } catch (error) {
      logger.error(`Failed to parse secret as JSON: ${secretName}`);
      throw error;
    }
  }

  /**
   * Get multiple secrets in parallel
   */
  async getSecrets(secretNames) {
    const promises = secretNames.map(name => 
      this.getSecret(name).catch(error => ({
        name,
        error,
      }))
    );

    const results = await Promise.all(promises);

    const secrets = {};
    const errors = [];

    results.forEach((result, index) => {
      if (result.error) {
        errors.push(result);
      } else {
        secrets[secretNames[index]] = result;
      }
    });

    if (errors.length > 0) {
      logger.warn(`Failed to retrieve ${errors.length} of ${secretNames.length} secrets`);
    }

    return secrets;
  }

  /**
   * Clear cache (useful for testing or manual rotation)
   */
  clearCache() {
    this.cache.clear();
    logger.info('Secrets cache cleared');
  }

  /**
   * Invalidate specific secret in cache
   */
  invalidate(secretName) {
    if (this.cache.has(secretName)) {
      this.cache.delete(secretName);
      logger.info(`Secret cache invalidated: ${secretName}`);
    }
  }
}

// Export singleton instance
module.exports = new SecretsManager();
EOF
