cat > logger.js << 'EOF'
/**
 * Secure Logger
 * 
 * Prevents secrets from being logged by:
 * - Redacting common secret patterns
 * - Filtering sensitive fields
 * - Not logging stack traces in production
 */

const winston = require('winston');

// List of sensitive field names to redact
const SENSITIVE_FIELDS = [
  'password',
  'token',
  'secret',
  'apiKey',
  'api_key',
  'accessKey',
  'access_key',
  'secretKey',
  'secret_key',
  'authorization',
  'credit_card',
  'creditCard',
  'ssn',
  'databaseUrl',
  'database_url',
  'connectionString',
  'connection_string',
  'stripe_secret_key',
  'aws_secret_access_key',
];

// Regex patterns for secrets
const SECRET_PATTERNS = [
  /([a-zA-Z0-9_-]*[Ss]ecret[a-zA-Z0-9_-]*)\s*=\s*['"]?([^'"]*)/g,
  /([a-zA-Z0-9_-]*[Tt]oken[a-zA-Z0-9_-]*)\s*=\s*['"]?([^'"]*)/g,
  /([a-zA-Z0-9_-]*[Pp]assword[a-zA-Z0-9_-]*)\s*=\s*['"]?([^'"]*)/g,
  /[Ss]k_[a-zA-Z0-9_]{20,}/g, // Stripe keys
  /AKIA[0-9A-Z]{16}/g, // AWS access key IDs
];

/**
 * Redact sensitive data from log messages
 */
function redactSensitiveData(data) {
  if (typeof data === 'string') {
    let redacted = data;
    SECRET_PATTERNS.forEach(pattern => {
      redacted = redacted.replace(pattern, '***REDACTED***');
    });
    return redacted;
  }

  if (typeof data !== 'object' || data === null) {
    return data;
  }

  if (Array.isArray(data)) {
    return data.map(redactSensitiveData);
  }

  const redacted = {};
  Object.keys(data).forEach(key => {
    const lowerKey = key.toLowerCase();

    if (SENSITIVE_FIELDS.some(field => lowerKey.includes(field))) {
      redacted[key] = '***REDACTED***';
    } else {
      redacted[key] = redactSensitiveData(data[key]);
    }
  });

  return redacted;
}

/**
 * Custom format for logs
 */
const customFormat = winston.format.combine(
  winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
  winston.format.errors({ stack: true }),
  winston.format.splat(),
  winston.format.printf(({ timestamp, level, message, stack, ...meta }) => {
    // Redact sensitive data from meta
    const safeMeta = redactSensitiveData(meta);
    const metaStr = Object.keys(safeMeta).length 
      ? JSON.stringify(safeMeta) 
      : '';

    let output = `${timestamp} [${level.toUpperCase()}] ${message}`;
    if (metaStr) {
      output += ` ${metaStr}`;
    }
    if (stack) {
      output += `\n${stack}`;
    }
    return output;
  })
);

/**
 * Create logger instance
 */
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: customFormat,
  transports: [
    // Console output
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        customFormat
      ),
    }),

    // File output for all logs
    new winston.transports.File({
      filename: 'logs/app.log',
      maxsize: 10485760, // 10MB
      maxFiles: 10,
    }),

    // File output for errors only
    new winston.transports.File({
      filename: 'logs/error.log',
      level: 'error',
      maxsize: 10485760, // 10MB
      maxFiles: 10,
    }),
  ],
});

/**
 * Override console methods to use logger
 */
const originalLog = console.log;
const originalError = console.error;
const originalWarn = console.warn;

if (process.env.NODE_ENV === 'production') {
  console.log = (...args) => logger.info(args.join(' '));
  console.error = (...args) => logger.error(args.join(' '));
  console.warn = (...args) => logger.warn(args.join(' '));
}

module.exports = logger;
module.exports.redactSensitiveData = redactSensitiveData;
EOF
