```

### 2. Setup Script for New Developers

```bash
#!/bin/bash
# scripts/setup-dev.sh

set -e

echo "Setting up development environment..."

# Create .env.local if it doesn't exist
if [ ! -f .env.local ]; then
  cp .env.example .env.local
  echo "✓ Created .env.local from .env.example"
  echo "⚠️  Please fill in .env.local with your development credentials"
  echo "⚠️  NEVER commit .env.local to git"
  exit 1
else
  echo "✓ .env.local already exists"
fi

# Install dependencies
npm install

# Verify .env.local has required vars
required_vars=("JWT_SECRET" "DATABASE_URL" "STRIPE_SECRET_KEY")
for var in "${required_vars[@]}"; do
  if ! grep -q "$var=" .env.local; then
    echo "✗ Missing $var in .env.local"
    exit 1
  fi
done

echo "✓ Development environment ready!"
```

### 3. Pre-commit Hook

```bash
#!/bin/bash
# .git/hooks/pre-commit

# Prevent accidental commits of sensitive files
SENSITIVE_FILES=(".env" ".env.local" ".env.*.local" "*.key" "*.pem")

for file in "${SENSITIVE_FILES[@]}"; do
  if git diff --cached --name-only | grep -E "^$file"; then
    echo "❌ ERROR: Attempting to commit sensitive file: $file"
    echo "This file is in .gitignore and should not be committed"
    exit 1
  fi
done

exit 0
```

