```javascript
// config/rotate-secrets.js
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function rotateSecrets() {
  const secretsToRotate = [
    'prod/app/jwt-secret',
    'prod/app/stripe-key',
    'prod/app/api-keys'
  ];

  for (const secretId of secretsToRotate) {
    try {
      await secretsManager.rotateSecret({
        SecretId: secretId,
        RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN,
        RotationRules: {
          AutomaticallyAfterDays: 30
        }
      }).promise();

      console.log(`Rotation configured for ${secretId}`);
    } catch (error) {
      console.error(`Failed to configure rotation for ${secretId}:`, error);
    }
  }
}

module.exports = { rotateSecrets };
```

