// ============================================

class AWSSecretsProvider {
  constructor() {
    this.secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cachedSecrets = null;
    this.lastFetch = null;
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecrets() {
    // Return cached secrets if still valid
    if (this.cachedSecrets && (Date.now() - this.lastFetch) < this.cacheTTL) {
      return this.cachedSecrets;
    }

    try {
      const secretId = process.env.SECRETS_ARN || 'prod/app/secrets';

      const data = await this.secretsManager.getSecretValue({
        SecretId: secretId
      }).promise();

      let secretsString;
      if ('SecretString' in data) {
        secretsString = data.SecretString;
      } else {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secretsString = buff.toString('ascii');
      }

      this.cachedSecrets = JSON.parse(secretsString);
      this.lastFetch = Date.now();

      console.log(`[SECRETS] Loaded from AWS Secrets Manager (${secretId})`);

      return this.cachedSecrets;
