      console.error('[SECRETS] Failed to retrieve from AWS Secrets Manager:', error);
      throw new Error('Failed to load secrets from AWS Secrets Manager');
    }
  }

  // Setup automatic cache invalidation
  setupCacheRefresh() {
    setInterval(() => {
      this.cachedSecrets = null;
      console.log('[SECRETS] Cache invalidated, will refresh on next access');
    }, this.cacheTTL);
  }
}

// ============================================
// MAIN EXPORT
// ============================================

let secretsProvider = null;

async function getSecrets() {
  const nodeEnv = process.env.NODE_ENV || 'development';

  if (nodeEnv === 'production') {
    if (!secretsProvider) {
      secretsProvider = new AWSSecretsProvider();
