// Define what fields are safe to expose based on user role
const getSafeUserData = (user, currentUser) => {
  const safeData = {
    id: user.id,
    name: user.name,
  };

  // Only include email if user is admin or viewing themselves
  if (currentUser.role === 'admin' || currentUser.id === user.id) {
    safeData.email = user.email;
  }

  return safeData;
};

app.get('/users', authenticateToken, (req, res) => {
