NODE_ENV=development
PORT=3000
JWT_SECRET=
DATABASE_URL=
API_KEY=
ALLOWED_ORIGINS=
LOG_LEVEL=debug
```

**Step 3: Configure .gitignore**
```bash
# .gitignore
.env
.env.local
.env.*.local
.env*.pem
node_modules/
dist/
logs/
*.log
.DS_Store
```

**Step 4: Load configuration safely**
```javascript
// Load .env file
require('dotenv').config();

// Validate required secrets exist
const requiredSecrets = ['JWT_SECRET', 'DATABASE_URL', 'API_KEY'];

for (const secret of requiredSecrets) {
  if (!process.env[secret]) {
    throw new Error(`Missing required environment variable: ${secret}`);
  }
}

// Use secrets from environment
