## 3. Secrets Manager Integration (Production Recommended)

For production deployments, use dedicated secrets managers:

### AWS Secrets Manager
```javascript
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

async function getSecrets(secretName) {
  try {
    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    } else {
      return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }
  } catch (error) {
    console.error('Error fetching secret:', error);
    throw error;
  }
}

// Usage
const secrets = await getSecrets('myapp/production');
const jwtSecret = secrets.JWT_SECRET;
const dbUrl = secrets.DATABASE_URL;
```

### HashiCorp Vault
```javascript
const vault = require('node-vault');

const client = vault({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN,
});

async function getSecretsFromVault(path) {
  try {
    const result = await client.read(path);
    return result.data.data;
  } catch (error) {
    console.error('Error reading from Vault:', error);
    throw error;
  }
}

// Usage
const secrets = await getSecretsFromVault('secret/data/myapp/production');
```

### Google Cloud Secret Manager
```javascript
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

const client = new SecretManagerServiceClient();

async function getSecret(projectId, secretId, version = 'latest') {
  const name = client.secretVersionPath(projectId, secretId, version);

  const [{ payload }] = await client.accessSecretVersion({ name });

  return payload.data.toString('utf8');
}

// Usage
const jwtSecret = await getSecret('my-project', 'jwt-secret');
const dbUrl = await getSecret('my-project', 'database-url');
```

### Azure Key Vault
```javascript
const { SecretClient } = require("@azure/keyvault-secrets");
const { DefaultAzureCredential } = require("@azure/identity");

const credential = new DefaultAzureCredential();
const client = new SecretClient(
  `https://${process.env.VAULT_NAME}.vault.azure.net`,
  credential
);

async function getSecret(secretName) {
  try {
    const secret = await client.getSecret(secretName);
    return secret.value;
  } catch (error) {
    console.error('Error reading secret:', error);
    throw error;
  }
}

// Usage
const jwtSecret = await getSecret('jwt-secret');
const dbUrl = await getSecret('database-url');
```

