// ============================================================
// 1. JWT SECRET ROTATION STRATEGY
// ============================================================

/**
 * Problem: If you change JWT_SECRET, all existing tokens become invalid
 * Solution: Support multiple active keys during rotation period
 */

const secretRotationConfig = {
  // Current active secret
  currentSecret: process.env.JWT_SECRET,

  // Previous secret (for accepting old tokens during rotation)
  previousSecret: process.env.JWT_SECRET_PREVIOUS,

  // Rotation period (hours before old secret is invalidated)
  rotationPeriodHours: 24,

  // Tokens issued after this time should use new secret
  rotationStartTime: new Date('2024-01-15T00:00:00Z'),
};

/**
 * JWT verification with rotation support
 */
function verifyTokenWithRotation(token) {
  try {
    // Try current secret first
    return jwt.verify(token, process.env.JWT_SECRET);
  } catch (err) {
    if (err.name === 'JsonWebTokenError' && process.env.JWT_SECRET_PREVIOUS) {
      try {
        // Fallback to previous secret during rotation period
        const decoded = jwt.verify(token, process.env.JWT_SECRET_PREVIOUS);

        // Log that we're using old secret (for monitoring rotation progress)
        console.log(`[SECRET_ROTATION] Token verified with previous secret: ${decoded.sub}`);

        return decoded;
      } catch (previousErr) {
        throw err; // Throw original error
      }
    }
    throw err;
  }
}

