};

/**
 * Rotate API key with zero downtime
 */
async function rotateApiKey() {
  console.log('[API_KEY_ROTATION] Starting rotation...');

  // Step 1: Provider should create new key and mark it as active
  const newKey = await externalProvider.generateNewApiKey();

  // Step 2: Update standby key
  process.env.API_KEY_STANDBY = newKey;
  console.log('[API_KEY_ROTATION] New key prepared as standby');

  // Step 3: Run tests with new key
  const testResult = await testApiKey(newKey);
  if (!testResult.success) {
    console.error('[API_KEY_ROTATION] New key test failed, aborting');
    return false;
  }

  // Step 4: Move current key to legacy
  process.env.API_KEY_LEGACY = process.env.API_KEY;

  // Step 5: Promote standby to active
  process.env.API_KEY = process.env.API_KEY_STANDBY;
  process.env.API_KEY_STANDBY = null;

  console.log('[API_KEY_ROTATION] API key rotated successfully');

  // Step 6: Schedule removal of legacy key after grace period
  setTimeout(async () => {
    console.log('[API_KEY_ROTATION] Removing old API key...');
    await externalProvider.revokeApiKey(process.env.API_KEY_LEGACY);
    process.env.API_KEY_LEGACY = null;
  }, 24 * 60 * 60 * 1000); // 24 hours
}

