/**
 * Strategy for rotating SSL certificates
 */

const fs = require('fs');
const https = require('https');

async function rotateSslCertificate() {
  const certPath = process.env.CERT_PATH;
  const keyPath = process.env.KEY_PATH;
  const newCertPath = `${certPath}.new`;
  const newKeyPath = `${keyPath}.new`;

  // Step 1: Download/generate new certificate
  const newCert = await getCertificateFromProvider();
  fs.writeFileSync(newCertPath, newCert.cert);
  fs.writeFileSync(newKeyPath, newCert.key);
  console.log('[CERT_ROTATION] New certificate downloaded');

  // Step 2: Validate new certificate
  try {
    https.createSecureContext({
      cert: fs.readFileSync(newCertPath),
      key: fs.readFileSync(newKeyPath),
    });
    console.log('[CERT_ROTATION] New certificate validated');
  } catch (err) {
    console.error('[CERT_ROTATION] Certificate validation failed:', err);
    return false;
  }

  // Step 3: Update HTTPS server with new certificate
  // This can be done without restarting by updating the secure context
  global.httpsServer.setSecureContext({
    cert: fs.readFileSync(newCertPath),
    key: fs.readFileSync(newKeyPath),
  });

  // Step 4: Backup old certificate
  fs.renameSync(certPath, `${certPath}.backup`);
  fs.renameSync(keyPath, `${keyPath}.backup`);

  // Step 5: Move new certificate to active
  fs.renameSync(newCertPath, certPath);
  fs.renameSync(newKeyPath, keyPath);

  console.log('[CERT_ROTATION] SSL certificate rotated successfully');
}

