/**
 * Monitor secret expiration and alert before rotation needed
 */

class SecretExpirationMonitor {
  constructor() {
    this.secrets = {
      jwt_secret: {
        rotationIntervalDays: 90,
        lastRotated: new Date(process.env.JWT_LAST_ROTATED || Date.now()),
      },
      db_password: {
        rotationIntervalDays: 180,
        lastRotated: new Date(process.env.DB_PASSWORD_LAST_ROTATED || Date.now()),
      },
      api_key: {
        rotationIntervalDays: 365,
        lastRotated: new Date(process.env.API_KEY_LAST_ROTATED || Date.now()),
      },
      ssl_cert: {
        rotationIntervalDays: 89, // Before 90-day cert expires
        lastRotated: new Date(process.env.CERT_LAST_ROTATED || Date.now()),
      },
    };
  }

  check() {
    const now = new Date();
    const alerts = [];

    for (const [name, config] of Object.entries(this.secrets)) {
      const daysSinceRotation = Math.floor(
        (now - config.lastRotated) / (1000 * 60 * 60 * 24)
      );

      // Alert if within 7 days of rotation needed
      if (daysSinceRotation > config.rotationIntervalDays - 7) {
        const daysUntilRequired = config.rotationIntervalDays - daysSinceRotation;

        alerts.push({
          severity: daysUntilRequired <= 0 ? 'CRITICAL' : 'WARNING',
          message: `${name} rotation needed in ${Math.max(0, daysUntilRequired)} days`,
          lastRotated: config.lastRotated,
          dueDate: new Date(
            config.lastRotated.getTime() + config.rotationIntervalDays * 24 * 60 * 60 * 1000
          ),
        });
      }
    }

    if (alerts.length > 0) {
      this.sendAlerts(alerts);
    }

    return alerts;
  }

  sendAlerts(alerts) {
    // Send to monitoring system (e.g., Datadog, New Relic, PagerDuty)
    console.warn('[SECURITY_ALERT] Secret rotation required:', alerts);

    // Could also send email, Slack message, etc.
    // notificationService.send({
    //   channel: 'ops-alerts',
    //   severity: 'high',
    //   message: `${alerts.length} secrets need rotation`,
    // });
  }
}

