/**
 * Helper to fetch secrets from AWS Secrets Manager
 */
async function loadSecretsFromAWS(secretName, region = 'us-east-1') {
  const AWS = require('aws-sdk');
  const client = new AWS.SecretsManager({ region });

  try {
    const data = await client
      .getSecretValue({ SecretId: secretName })
      .promise();

    if ('SecretString' in data) {
      console.log('✓ Secrets loaded from AWS Secrets Manager');
      return JSON.parse(data.SecretString);
    } else {
      const buff = Buffer.from(data.SecretBinary, 'base64');
      return JSON.parse(buff.toString('ascii'));
    }
  } catch (error) {
    console.error('✗ Failed to load secrets from AWS:', error.message);
    throw error;
  }
}

/**
 * Helper to fetch secrets from Vault
 */
async function loadSecretsFromVault(secretPath) {
  const vault = require('node-vault');

  const client = vault({
    endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
    token: process.env.VAULT_TOKEN,
  });

  try {
    const result = await client.read(secretPath);
    console.log('✓ Secrets loaded from HashiCorp Vault');
    return result.data.data;
  } catch (error) {
    console.error('✗ Failed to load secrets from Vault:', error.message);
    throw error;
  }
}

/**
 * Helper to fetch secrets from Google Cloud Secret Manager
 */
async function loadSecretsFromGCP(projectId, secretName, version = 'latest') {
  const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

  const client = new SecretManagerServiceClient();
  const name = client.secretVersionPath(projectId, secretName, version);

  try {
    const [{ payload }] = await client.accessSecretVersion({ name });
    const secretString = payload.data.toString('utf8');
    console.log('✓ Secrets loaded from Google Cloud Secret Manager');
    return JSON.parse(secretString);
  } catch (error) {
    console.error('✗ Failed to load secrets from GCP:', error.message);
    throw error;
  }
}

/**
 * Universal secrets loader (detects environment)
 */
async function loadSecrets() {
  const env = process.env.NODE_ENV || 'development';

  // Development: Load from .env file
  if (env === 'development') {
    require('dotenv').config();
    console.log('✓ Environment: Development (using .env file)');
    return process.env;
  }

  // Production: Detect and use appropriate secrets manager
  const secretsManager = process.env.SECRETS_MANAGER || 'auto';

  if (secretsManager === 'aws' || !secretsManager) {
    const secrets = await loadSecretsFromAWS(
      process.env.AWS_SECRET_NAME || 'production/myapp/secrets'
    );
    Object.assign(process.env, secrets);
    console.log(`✓ Environment: ${env} (AWS Secrets Manager)`);
    return process.env;
  }

  if (secretsManager === 'vault') {
    const secrets = await loadSecretsFromVault(
      process.env.VAULT_SECRET_PATH || `secret/data/${env}/myapp`
    );
    Object.assign(process.env, secrets);
    console.log(`✓ Environment: ${env} (HashiCorp Vault)`);
    return process.env;
  }

  if (secretsManager === 'gcp') {
    const secrets = await loadSecretsFromGCP(
      process.env.GCP_PROJECT_ID,
      `myapp-${env}-secrets`
    );
    Object.assign(process.env, secrets);
    console.log(`✓ Environment: ${env} (Google Cloud Secret Manager)`);
    return process.env;
  }

  throw new Error(`Unknown secrets manager: ${secretsManager}`);
}

