// ============================================================================

// Parse JSON with size limit (prevents DOS attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection (OWASP A03:2021 - Injection)
app.use(mongoSanitize());

