  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);

  // Validate HTTP method whitelist
  const allowedMethods = ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS', 'HEAD'];
  if (!allowedMethods.includes(req.method)) {
    return res.status(405).json({ error: 'Method Not Allowed' });
  }

  next();
});

// ============================================================================
// SECURITY MIDDLEWARE - LAYER 3: INPUT VALIDATION
// ============================================================================

// Middleware for validating and sanitizing query parameters
const validateQueryParams = (req, res, next) => {
  for (const key in req.query) {
    if (typeof req.query[key] === 'string') {
      // Check for suspicious patterns
      if (req.query[key].length > 1000) {
        return res.status(400).json({ error: 'Invalid query parameter length' });
      }

      // Sanitize the parameter
      req.query[key] = validator.escape(req.query[key]);
    }
  }
  next();
};

// ============================================================================
// ROUTES - SECURE VERSION
// ============================================================================

/**
 * Health Check Endpoint
 * SECURITY MEASURES:
 * - No sensitive data exposed
 * - Simple response format
 * - No database queries
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    service: 'app-api'
  });
});

/**
 * Users Endpoint - WITH SECURITY
 * SECURITY MEASURES:
 * - Input validation on query parameters
 * - Rate limiting (inherited from global limiter)
 * - No sensitive data in response (no internal IDs if possible)
 * - Response pagination to prevent information disclosure
 * - Proper error handling
 */
app.get('/users', validateQueryParams, (req, res) => {
  try {
    // Input validation for query parameters
    const limit = Math.min(parseInt(req.query.limit) || 10, 100); // Default 10, max 100
    const offset = Math.max(parseInt(req.query.offset) || 0, 0); // Default 0
    const search = validator.escape(req.query.search || '');

    // Validate pagination parameters
    if (!Number.isInteger(limit) || !Number.isInteger(offset) || limit < 1 || offset < 0) {
      return res.status(400).json({ 
        error: 'Invalid pagination parameters',
        details: 'limit must be 1-100, offset must be >= 0'
      });
    }

    // In production, this would come from a database with parameterized queries
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filtering if search parameter provided
    let filteredUsers = users;
    if (search && search.length > 0) {
      filteredUsers = users.filter(user =>
        user.name.toLowerCase().includes(search.toLowerCase()) ||
        user.email.toLowerCase().includes(search.toLowerCase())
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: filteredUsers.length,
        limit,
        offset,
        hasMore: offset + limit < filteredUsers.length
      },
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * Example POST endpoint with proper input validation
 * Demonstrates secure data handling
 */
app.post('/users', authLimiter, (req, res) => {
  try {
    const { name, email } = req.body;

    // INPUT VALIDATION
    if (!name || !email) {
      return res.status(400).json({
        error: 'Missing required fields',
        required: ['name', 'email']
      });
    }

    // Type validation
    if (typeof name !== 'string' || typeof email !== 'string') {
      return res.status(400).json({ error: 'Invalid data types' });
    }

    // Length validation
    if (name.length < 2 || name.length > 100) {
      return res.status(400).json({ error: 'Name must be 2-100 characters' });
    }

    // Email validation using validator library
    if (!validator.isEmail(email)) {
      return res.status(400).json({ error: 'Invalid email format' });
    }

    // Sanitize inputs
    const sanitizedName = validator.escape(name.trim());
    const sanitizedEmail = validator.normalizeEmail(email);

    // In production, use parameterized queries for database operations
    const newUser = {
      id: 3, // Should be generated by database
      name: sanitizedName,
      email: sanitizedEmail
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });

  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * 404 Handler - No information leakage
 */
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

/**
 * Global Error Handler
 * SECURITY: Prevents stack trace exposure in production
 */
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  const isProduction = process.env.NODE_ENV === 'production';
  const message = isProduction ? 'Internal server error' : err.message;
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { details: err.stack })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

