/**
 * SECURE SECRETS MANAGER
 * 
 * This module provides a secure way to load and manage secrets from external sources
 * instead of hardcoding them in .env files or environment variables.
 * 
 * CRITICALITY: CRITICAL SECURITY ISSUE FOUND
 * The .env.test file contains REAL production secrets in plaintext!
 */

const AWS = require('aws-sdk');

/**
 * Configuration for different secret backends
 */
const SUPPORTED_BACKENDS = {
  AWS_SECRETS_MANAGER: 'aws-secrets-manager',
  AWS_PARAMETER_STORE: 'aws-parameter-store',
  VAULT: 'vault',
  ENV_VARS: 'environment-variables' // Fallback only
};

class SecretsManager {
  constructor(backend = SUPPORTED_BACKENDS.AWS_SECRETS_MANAGER) {
    this.backend = backend;
    this.secretsCache = new Map();
    this.cacheTTL = 3600000; // 1 hour cache
    this.cacheTimestamps = new Map();

    if (backend === SUPPORTED_BACKENDS.AWS_SECRETS_MANAGER) {
      this.client = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    } else if (backend === SUPPORTED_BACKENDS.AWS_PARAMETER_STORE) {
      this.client = new AWS.SSM({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    }
  }

  /**
   * Get a secret from AWS Secrets Manager
   * Implements caching with TTL
   */
  async getSecretFromAWSSecretsManager(secretName) {
    // Check cache first
    if (this.secretsCache.has(secretName)) {
      const timestamp = this.cacheTimestamps.get(secretName);
      if (Date.now() - timestamp < this.cacheTTL) {
        console.log(`[CACHE HIT] Retrieved cached secret: ${secretName}`);
        return this.secretsCache.get(secretName);
      }
    }

    try {
      const data = await this.client.getSecretValue({ SecretId: secretName }).promise();
      let secret;

      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.secretsCache.set(secretName, secret);
      this.cacheTimestamps.set(secretName, Date.now());

      console.log(`[SECRET MANAGER] Retrieved secret from AWS Secrets Manager: ${secretName}`);
      return secret;
    } catch (error) {
      console.error(`[ERROR] Failed to retrieve secret from AWS Secrets Manager: ${secretName}`, error);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Get a parameter from AWS Parameter Store
   */
  async getSecretFromParameterStore(parameterName) {
    // Check cache first
    if (this.secretsCache.has(parameterName)) {
      const timestamp = this.cacheTimestamps.get(parameterName);
      if (Date.now() - timestamp < this.cacheTTL) {
        console.log(`[CACHE HIT] Retrieved cached parameter: ${parameterName}`);
        return this.secretsCache.get(parameterName);
      }
    }

    try {
      const data = await this.client.getParameter({
        Name: parameterName,
        WithDecryption: true // For SecureString parameters
      }).promise();

      const secret = data.Parameter.Value;

      // Cache the parameter
      this.secretsCache.set(parameterName, secret);
      this.cacheTimestamps.set(parameterName, Date.now());

      console.log(`[PARAMETER STORE] Retrieved parameter: ${parameterName}`);
      return secret;
    } catch (error) {
      console.error(`[ERROR] Failed to retrieve parameter from Parameter Store: ${parameterName}`, error);
      throw new Error(`Failed to retrieve parameter: ${parameterName}`);
    }
  }

  /**
   * Get a secret from HashiCorp Vault
   */
  async getSecretFromVault(secretPath) {
    const vaultAddr = process.env.VAULT_ADDR;
    const vaultToken = process.env.VAULT_TOKEN;

    if (!vaultAddr || !vaultToken) {
      throw new Error('VAULT_ADDR and VAULT_TOKEN environment variables are required');
    }

    // Check cache first
    if (this.secretsCache.has(secretPath)) {
      const timestamp = this.cacheTimestamps.get(secretPath);
      if (Date.now() - timestamp < this.cacheTTL) {
        console.log(`[CACHE HIT] Retrieved cached Vault secret: ${secretPath}`);
        return this.secretsCache.get(secretPath);
      }
    }

    try {
      const fetch = await import('node-fetch');
      const response = await fetch(
        `${vaultAddr}/v1/${secretPath}`,
        {
          headers: {
            'X-Vault-Token': vaultToken
          }
        }
      );

      if (!response.ok) {
        throw new Error(`Vault returned status ${response.status}`);
      }

      const data = await response.json();
      const secret = data.data.data; // Vault KV v2 returns nested data

      // Cache the secret
      this.secretsCache.set(secretPath, secret);
      this.cacheTimestamps.set(secretPath, Date.now());

      console.log(`[VAULT] Retrieved secret from Vault: ${secretPath}`);
      return secret;
    } catch (error) {
      console.error(`[ERROR] Failed to retrieve secret from Vault: ${secretPath}`, error);
      throw new Error(`Failed to retrieve secret from Vault: ${secretPath}`);
    }
  }

  /**
   * Unified get method that routes to appropriate backend
   */
  async get(secretName) {
    if (this.backend === SUPPORTED_BACKENDS.AWS_SECRETS_MANAGER) {
      return this.getSecretFromAWSSecretsManager(secretName);
    } else if (this.backend === SUPPORTED_BACKENDS.AWS_PARAMETER_STORE) {
      return this.getSecretFromParameterStore(secretName);
    } else if (this.backend === SUPPORTED_BACKENDS.VAULT) {
      return this.getSecretFromVault(secretName);
    } else if (this.backend === SUPPORTED_BACKENDS.ENV_VARS) {
      // FALLBACK ONLY - Not recommended for production
      console.warn('[WARNING] Using environment variables for secrets - NOT recommended for production');
      return process.env[secretName];
    }

    throw new Error(`Unsupported backend: ${this.backend}`);
  }

  /**
   * Clear the secrets cache
   */
  clearCache() {
    this.secretsCache.clear();
    this.cacheTimestamps.clear();
    console.log('[CACHE CLEARED] Secrets cache has been cleared');
  }

  /**
   * Rotate cache entry (useful for periodic refresh)
   */
  rotateSecret(secretName) {
    this.secretsCache.delete(secretName);
    this.cacheTimestamps.delete(secretName);
    console.log(`[CACHE ROTATED] Secret rotated: ${secretName}`);
  }
}

module.exports = {
  SecretsManager,
  SUPPORTED_BACKENDS
};

/**
 * SECURE CONFIGURATION LOADER
 * 
 * This module loads application configuration from secure sources
 * and validates all required secrets are available.
 * 
 * Usage:
 *   const config = require('./lib/configLoader');
 *   const dbUrl = await config.getSecret('database_url');
 */

const { SecretsManager, SUPPORTED_BACKENDS } = require('./secretsManager');
const path = require('path');

class ConfigLoader {
  constructor() {
    this.env = process.env.NODE_ENV || 'development';
    this.backend = process.env.SECRETS_BACKEND || SUPPORTED_BACKENDS.AWS_SECRETS_MANAGER;
    this.secretsManager = new SecretsManager(this.backend);
    this.validatedConfig = null;
  }

  /**
   * Define required secrets for the application
   * Add any new secrets here for validation
   */
  getRequiredSecrets() {
    return {
      development: [
        // Only non-critical secrets for dev
      ],
      staging: [
        'database_url',
        'jwt_secret',
        'api_key'
      ],
      production: [
        'database_url',
        'jwt_secret',
        'api_key',
        'stripe_secret_key',
        'aws_access_key_id',
        'aws_secret_access_key',
        'anthropic_api_key',
        'logfire_token'
      ]
    };
  }

  /**
   * Get a secret with validation
   */
  async getSecret(secretName) {
    try {
      const secret = await this.secretsManager.get(secretName);

      if (!secret) {
        throw new Error(`Secret '${secretName}' is empty or not found`);
      }

      return secret;
    } catch (error) {
      console.error(`[CONFIG ERROR] Failed to load secret: ${secretName}`, error.message);

      // In production, fail fast
      if (this.env === 'production') {
        throw error;
      }

      // In development, log warning but continue
      console.warn(`[CONFIG WARNING] Proceeding without secret: ${secretName}`);
      return null;
    }
  }

  /**
   * Validate all required secrets are available
   */
  async validateSecrets() {
    const requiredSecrets = this.getRequiredSecrets()[this.env] || [];
    const missingSecrets = [];

    console.log(`[CONFIG] Validating ${requiredSecrets.length} required secrets for ${this.env} environment`);

    for (const secret of requiredSecrets) {
      try {
        await this.getSecret(secret);
        console.log(`[CONFIG] ✓ Secret available: ${secret}`);
      } catch (error) {
        missingSecrets.push(secret);
        console.error(`[CONFIG] ✗ Secret missing: ${secret}`);
      }
    }

    if (missingSecrets.length > 0 && this.env === 'production') {
      throw new Error(
        `Missing required secrets in ${this.env}: ${missingSecrets.join(', ')}`
      );
    }

    return {
      validated: true,
      environment: this.env,
      totalRequired: requiredSecrets.length,
      missingCount: missingSecrets.length,
      missingSe crets: missingSecrets
    };
  }

  /**
   * Load full application config
   * Returns an object with all configuration values
   */
  async loadConfig() {
    if (this.validatedConfig) {
      return this.validatedConfig;
    }

    // Validate secrets first
    await this.validateSecrets();

    // Load all secrets
    const config = {
      env: this.env,
      server: {
        port: parseInt(process.env.PORT || '3000'),
        host: process.env.HOST || 'localhost'
      },
      database: {
        url: await this.getSecret('database_url')
      },
      security: {
        jwtSecret: await this.getSecret('jwt_secret'),
        apiKey: await this.getSecret('api_key'),
        corsOrigins: (process.env.CORS_ORIGINS || 'http://localhost:3000').split(','),
        rateLimit: {
          windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000'), // 15 mins
          maxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100')
        }
      },
      thirdParty: {
        stripe: {
          secretKey: await this.getSecret('stripe_secret_key')
        },
        aws: {
          accessKeyId: await this.getSecret('aws_access_key_id'),
          secretAccessKey: await this.getSecret('aws_secret_access_key'),
          region: process.env.AWS_REGION || 'us-east-1'
        },
        anthropic: {
          apiKey: await this.getSecret('anthropic_api_key')
        },
        logfire: {
          token: await this.getSecret('logfire_token')
        }
      }
    };

    // Cache the loaded config
    this.validatedConfig = config;
    console.log('[CONFIG] Configuration loaded successfully');

    return config;
  }

  /**
   * Get a specific config value with dot notation support
   * Example: config.getValue('thirdParty.stripe.secretKey')
   */
  getValue(path) {
    if (!this.validatedConfig) {
