/**
 * SECURE SECRETS MANAGEMENT IMPLEMENTATION
 * Shows 4 approaches: AWS Secrets Manager, HashiCorp Vault, Azure Key Vault, and Local Encrypted
 */

const express = require('express');

// ============================================================
// APPROACH 1: AWS SECRETS MANAGER (Recommended for AWS deployments)
// ============================================================

const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: 'us-east-1' });

async function getSecretsFromAWS() {
  try {
    const response = await client.getSecretValue({ 
      SecretId: 'app/production/secrets' 
    }).promise();

    return JSON.parse(response.SecretString);
  } catch (error) {
    console.error('Failed to retrieve secrets from AWS:', error);
    process.exit(1);
  }
}

// ============================================================
// APPROACH 2: HASHICORP VAULT (Recommended for multi-cloud)
// ============================================================

const vault = require('node-vault');

async function getSecretsFromVault() {
  const client = vault({
    endpoint: process.env.VAULT_ADDR || 'https://vault.example.com',
    token: process.env.VAULT_TOKEN, // From OIDC or service account
  });

  try {
    const secret = await client.read('secret/data/app/production');
    return secret.data.data;
  } catch (error) {
    console.error('Failed to retrieve secrets from Vault:', error);
    process.exit(1);
  }
}

// ============================================================
// APPROACH 3: AZURE KEY VAULT (For Azure deployments)
// ============================================================

const { SecretClient } = require("@azure/keyvault-secrets");
const { DefaultAzureCredential } = require("@azure/identity");

async function getSecretsFromAzure() {
  const credential = new DefaultAzureCredential();
  const client = new SecretClient(
    process.env.AZURE_VAULT_URL,
    credential
  );

  try {
    const databaseUrl = await client.getSecret("database-url");
    const apiKey = await client.getSecret("api-key");

    return {
      DATABASE_URL: databaseUrl.value,
      API_KEY: apiKey.value,
    };
  } catch (error) {
    console.error('Failed to retrieve secrets from Azure:', error);
    process.exit(1);
  }
}

// ============================================================
// APPROACH 4: LOCAL ENCRYPTED SECRETS (Development only)
// ============================================================

const crypto = require('crypto');
const fs = require('fs');

function loadEncryptedSecrets(encryptionKey) {
  try {
    const encrypted = fs.readFileSync('.env.encrypted', 'utf8');
    const [iv, authTag, encryptedData] = encrypted.split(':');

    const decipher = crypto.createDecipheriv(
      'aes-256-gcm',
      Buffer.from(encryptionKey, 'hex'),
      Buffer.from(iv, 'hex')
    );

    decipher.setAuthTag(Buffer.from(authTag, 'hex'));

    let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return JSON.parse(decrypted);
  } catch (error) {
    console.error('Failed to decrypt secrets:', error);
    process.exit(1);
  }
}

// ============================================================
// UNIFIED SECRET LOADER
// ============================================================

class SecretsManager {
  constructor(provider = 'aws') {
    this.provider = provider;
    this.secrets = null;
  }

  async load() {
    switch (this.provider) {
      case 'aws':
        this.secrets = await getSecretsFromAWS();
        break;
      case 'vault':
        this.secrets = await getSecretsFromVault();
        break;
      case 'azure':
        this.secrets = await getSecretsFromAzure();
        break;
      case 'encrypted':
        this.secrets = loadEncryptedSecrets(process.env.ENCRYPTION_KEY);
        break;
      default:
        throw new Error(`Unknown secrets provider: ${this.provider}`);
    }

    this.validateSecrets();
    return this.secrets;
  }

  validateSecrets() {
    const required = [
      'DATABASE_URL',
      'API_KEY',
      'JWT_SECRET',
    ];

    for (const key of required) {
      if (!this.secrets[key]) {
        throw new Error(`Required secret ${key} is missing`);
      }
    }
  }

  get(key, defaultValue = null) {
    return this.secrets[key] ?? defaultValue;
  }
}

// ============================================================
// APPLICATION SETUP
// ============================================================

async function createApp() {
  // Determine which secrets provider to use
  const provider = process.env.SECRETS_PROVIDER || 'aws';
  const secretsManager = new SecretsManager(provider);

  // Load secrets
  await secretsManager.load();

  const app = express();

  // Middleware
  app.use(express.json());

  // Never log secrets
  app.use((req, res, next) => {
    if (req.body && req.body.password) {
      req.body.password = '[REDACTED]';
    }
    next();
  });

  // Routes using secrets securely
  app.get('/health', (req, res) => {
    res.json({ status: 'ok' });
  });

  app.get('/config', (req, res) => {
    // Only expose non-sensitive config
    res.json({
      environment: process.env.NODE_ENV,
      // Don't expose: DATABASE_URL, API_KEY, etc.
    });
  });

  // Error handler - never expose secrets in errors
  app.use((err, req, res, next) => {
    console.error('Error:', err.message);
    // Never include secrets in error response
    res.status(500).json({
      error: 'Internal server error',
      // Don't include: err.message if it contains secrets
    });
  });

  return app;
}

// ============================================================
// STARTUP
// ============================================================

if (require.main === module) {
  createApp()
    .then(app => {
      app.listen(3000, () => {
        console.log('Server running on port 3000');
      });
    })
    .catch(error => {
      console.error('Failed to start application:', error);
      process.exit(1);
    });
}

module.exports = { createApp, SecretsManager };
