  const missing = requiredSecrets.filter(secret => !process.env[secret]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }
}

module.exports = {
  validateSecretsLoaded,
  getSecret: (key) => {
    const value = process.env[key];
    if (!value) {
      throw new Error(`Secret ${key} not found in environment`);
    }
    return value;
  }
};
```

### Strategy 4: Secure Environment Setup

```bash
