/**
 * AWS Secrets Manager Integration
 * Secure secret retrieval with caching and rotation support
 */

const AWS = require('aws-sdk');

class AWSSecretsManager {
  constructor(options = {}) {
    this.secretsManager = new AWS.SecretsManager({
      region: options.region || process.env.AWS_REGION || 'us-east-1',
    });

    // In-memory cache with TTL
    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 3600000; // 1 hour default

    // Track refresh in progress to avoid thundering herd
    this.refreshPromises = new Map();
  }

  /**
   * Get secret value with caching
   * @param {string} secretName - Secret identifier in AWS Secrets Manager
   * @returns {Promise<Object|string>} Parsed secret or raw value
   */
  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    // Prevent thundering herd - return existing refresh promise
    if (this.refreshPromises.has(secretName)) {
      return this.refreshPromises.get(secretName);
    }

    // Fetch secret
    const refreshPromise = this._fetchSecret(secretName);
    this.refreshPromises.set(secretName, refreshPromise);

    try {
      const secret = await refreshPromise;
      return secret;
    } finally {
      this.refreshPromises.delete(secretName);
    }
  }

  /**
   * Internal method to fetch from AWS
   * @private
   */
  async _fetchSecret(secretName) {
    try {
      const data = await this.secretsManager
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secret;

      // Handle both string and binary secrets
      if ('SecretString' in data) {
        try {
          // Try to parse as JSON
          secret = JSON.parse(data.SecretString);
        } catch {
          // Return as plain string if not JSON
          secret = data.SecretString;
        }
      } else if ('SecretBinary' in data) {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      } else {
        throw new Error(`Invalid secret format for ${secretName}`);
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL,
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, {
        errorCode: error.code,
        message: error.message,
        timestamp: new Date().toISOString(),
      });

      // Log without exposing secret details
      throw new Error(`Failed to retrieve secret: ${error.code}`);
    }
  }

  /**
   * Get nested secret value (for JSON secrets)
   * @param {string} secretName - Secret identifier
   * @param {string} key - JSON key path (supports dot notation)
   * @returns {Promise<any>} Secret value
   */
  async getSecretValue(secretName, key) {
    const secret = await this.getSecret(secretName);

    if (typeof secret === 'string') {
      throw new Error(`Cannot access nested key ${key} on string secret`);
    }

    // Support dot notation for nested access
    const keys = key.split('.');
    let value = secret;

    for (const k of keys) {
      if (value === null || value === undefined) {
        throw new Error(`Key ${key} not found in secret ${secretName}`);
      }
      value = value[k];
    }

    return value;
  }

  /**
   * Invalidate cache to force refresh
   * @param {string} secretName - Secret identifier
   */
  invalidateCache(secretName) {
    this.cache.delete(secretName);
  }

  /**
   * Clear all cache
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Get cache statistics (for monitoring)
   * @returns {Object} Cache stats
   */
  getCacheStats() {
    const stats = {
      cachedSecrets: this.cache.size,
      entries: [],
    };

    for (const [name, entry] of this.cache.entries()) {
      stats.entries.push({
        name,
        expiresAt: new Date(entry.expiresAt).toISOString(),
        isExpired: entry.expiresAt < Date.now(),
      });
    }

    return stats;
  }

  /**
   * Validate that required secrets exist
   * @param {string[]} secretNames - Array of secret names to validate
   * @returns {Promise<boolean>} True if all secrets accessible
   */
  async validateSecrets(secretNames) {
    const results = await Promise.allSettled(
      secretNames.map(name => this.getSecret(name))
    );

    const failed = results
      .map((result, index) => ({
        name: secretNames[index],
        result,
      }))
      .filter(({ result }) => result.status === 'rejected');

    if (failed.length > 0) {
      throw new Error(
        `Failed to validate secrets: ${failed.map(f => f.name).join(', ')}`
      );
    }

    return true;
  }
}

// Export singleton instance
module.exports = new AWSSecretsManager();

/**
 * HashiCorp Vault Integration
 * Multi-cloud secrets management with rotation support
 */

const vault = require('node-vault');
const logger = require('./logger');

class VaultSecretsManager {
  constructor(options = {}) {
    this.client = vault({
      endpoint: options.endpoint || process.env.VAULT_ADDR || 'http://localhost:8200',
      token: options.token || process.env.VAULT_TOKEN,
      apiVersion: 'v1',
    });

    this.cache = new Map();
    this.cacheTTL = options.cacheTTL || 3600000; // 1 hour
    this.mountPoint = options.mountPoint || 'secret';
    this.refreshPromises = new Map();
  }

  /**
   * Get secret from Vault
   * @param {string} path - Secret path in Vault (e.g., 'database/production')
   * @returns {Promise<Object>} Secret data
   */
  async getSecret(path) {
    // Validate cache
    const cached = this.cache.get(path);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    // Prevent thundering herd
    if (this.refreshPromises.has(path)) {
      return this.refreshPromises.get(path);
    }

    const refreshPromise = this._fetchFromVault(path);
    this.refreshPromises.set(path, refreshPromise);

    try {
      const secret = await refreshPromise;
      return secret;
    } finally {
      this.refreshPromises.delete(path);
    }
  }

  /**
   * Fetch secret from Vault with error handling
   * @private
   */
  async _fetchFromVault(path) {
    try {
      const response = await this.client.read(`${this.mountPoint}/data/${path}`);

      if (!response.data || !response.data.data) {
        throw new Error(`Invalid response format for path ${path}`);
      }

      const secret = response.data.data;

      // Cache with TTL
      this.cache.set(path, {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL,
        metadata: response.data.metadata,
      });

      return secret;
    } catch (error) {
      logger.error('Vault secret retrieval failed', {
        path,
        error: error.message,
        statusCode: error.statusCode,
      });

      // Provide helpful error messages without exposing internals
      if (error.statusCode === 404) {
        throw new Error(`Secret not found at path: ${path}`);
      } else if (error.statusCode === 403) {
        throw new Error('Insufficient permissions to access secret');
      } else {
        throw new Error('Failed to retrieve secret from Vault');
      }
    }
  }

  /**
   * Get nested secret value with dot notation
   * @param {string} path - Secret path
   * @param {string} key - Nested key path (e.g., 'database.password')
   * @returns {Promise<any>} Secret value
   */
  async getSecretValue(path, key) {
    const secret = await this.getSecret(path);
    const keys = key.split('.');
    let value = secret;

    for (const k of keys) {
      if (value === null || value === undefined) {
        throw new Error(`Key ${key} not found in secret ${path}`);
      }
      value = value[k];
    }

    return value;
  }

  /**
   * Create a new secret in Vault
   * @param {string} path - Secret path
   * @param {Object} data - Secret data
   * @returns {Promise<Object>} Response from Vault
   */
  async createSecret(path, data) {
    try {
      const response = await this.client.write(`${this.mountPoint}/data/${path}`, {
        data,
      });

      // Invalidate cache
      this.cache.delete(path);

      logger.info('Secret created', { path });
      return response;
    } catch (error) {
      logger.error('Failed to create secret', { path, error: error.message });
      throw error;
    }
  }

  /**
   * Update an existing secret
   * @param {string} path - Secret path
   * @param {Object} updates - Fields to update
   * @returns {Promise<Object>} Updated secret
   */
  async updateSecret(path, updates) {
    try {
      // Get current secret
      const current = await this.getSecret(path);

      // Merge with updates
      const updated = { ...current, ...updates };

      // Write back
      await this.client.write(`${this.mountPoint}/data/${path}`, {
        data: updated,
      });

      // Invalidate cache
      this.cache.delete(path);

      logger.info('Secret updated', { path });
      return updated;
    } catch (error) {
      logger.error('Failed to update secret', { path, error: error.message });
      throw error;
    }
  }

  /**
   * Delete a secret
   * @param {string} path - Secret path
   * @returns {Promise<void>}
   */
  async deleteSecret(path) {
    try {
      await this.client.delete(`${this.mountPoint}/data/${path}`);
      this.cache.delete(path);
      logger.info('Secret deleted', { path });
    } catch (error) {
      logger.error('Failed to delete secret', { path, error: error.message });
      throw error;
    }
  }

  /**
   * Get database secret (uses Vault DB engine)
   * @param {string} role - Database role name
   * @returns {Promise<{username: string, password: string}>} DB credentials
   */
  async getDatabaseCredentials(role) {
    try {
      const response = await this.client.read(`database/static-creds/${role}`);

      if (!response.data || !response.data.data) {
        throw new Error(`Invalid database credentials response for role ${role}`);
      }

      return {
        username: response.data.data.username,
        password: response.data.data.password,
      };
    } catch (error) {
      logger.error('Failed to get database credentials', {
        role,
        error: error.message,
      });
      throw error;
    }
  }

  /**
   * Get dynamic database credentials (rotated)
   * @param {string} role - Database role name
   * @returns {Promise<{username: string, password: string}>} Temporary DB credentials
   */
  async getDynamicDatabaseCredentials(role) {
    try {
      const response = await this.client.read(`database/creds/${role}`);

      if (!response.data || !response.data.data) {
        throw new Error(`Invalid dynamic credentials response for role ${role}`);
      }

      return {
        username: response.data.data.username,
        password: response.data.data.password,
        ttl: response.lease_duration,
      };
    } catch (error) {
      logger.error('Failed to get dynamic database credentials', {
        role,
        error: error.message,
      });
      throw error;
    }
  }

  /**
   * Get PKI certificate
   * @param {string} role - Certificate role
   * @param {Object} options - Certificate options (common_name, alt_names, etc.)
   * @returns {Promise<{certificate: string, private_key: string}>} Certificate data
   */
  async getCertificate(role, options = {}) {
    try {
      const response = await this.client.write(`pki/issue/${role}`, options);

      return {
        certificate: response.data.certificate,
        privateKey: response.data.private_key,
        ca: response.data.ca_chain,
        serialNumber: response.data.serial_number,
        ttl: response.lease_duration,
      };
    } catch (error) {
      logger.error('Failed to get certificate', {
        role,
        error: error.message,
      });
      throw error;
    }
  }

  /**
   * Invalidate cache for a secret
   * @param {string} path - Secret path
   */
  invalidateCache(path) {
    this.cache.delete(path);
  }

  /**
   * Clear all cache
   */
  clearCache() {
    this.cache.clear();
  }

  /**
   * Get cache statistics
   * @returns {Object} Cache stats
   */
  getCacheStats() {
    const stats = {
      cachedSecrets: this.cache.size,
      entries: [],
    };

    for (const [path, entry] of this.cache.entries()) {
      stats.entries.push({
        path,
        expiresAt: new Date(entry.expiresAt).toISOString(),
        isExpired: entry.expiresAt < Date.now(),
        version: entry.metadata?.version,
      });
    }

    return stats;
  }

  /**
   * Validate Vault connection and permissions
   * @returns {Promise<boolean>}
   */
  async validateConnection() {
    try {
      // Try to read health endpoint
      await this.client.status();
      logger.info('Vault connection validated');
      return true;
    } catch (error) {
      logger.error('Vault connection failed', { error: error.message });
      throw error;
    }
  }

  /**
   * Validate that required secrets exist
   * @param {string[]} paths - Array of secret paths
   * @returns {Promise<boolean>}
   */
  async validateSecrets(paths) {
    const results = await Promise.allSettled(
      paths.map(path => this.getSecret(path))
    );

    const failed = results
      .map((result, index) => ({
        path: paths[index],
        result,
      }))
      .filter(({ result }) => result.status === 'rejected');

    if (failed.length > 0) {
      throw new Error(
        `Failed to validate secrets: ${failed.map(f => f.path).join(', ')}`
      );
    }

    return true;
  }
}

