#### 3. **Missing Authentication & Authorization**
**Severity:** CRITICAL
**Issue:** `/users` endpoint exposes sensitive user data without authentication
**OWASP Category:** A01:2021 – Broken Access Control, A07:2021 – Authentication Failures

**Problem:**
```javascript
// Current - ANYONE can access user data
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:**
```javascript
const jwt = require('jsonwebtoken');

// Middleware for authentication
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

#### 4. **No Input Validation**
**Severity:** HIGH
**Issue:** Query parameters and request bodies are not validated
**OWASP Category:** A03:2021 – Injection

**Problem:** Any endpoint accepting input is vulnerable to injection attacks

**Recommendation:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/search', [
  query('q')
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape()
    .withMessage('Search query must be 1-100 characters'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { q, limit } = req.query;
  // Safe to use q and limit now
  res.json({ query: q, limit: limit || 10 });
});
```

