```javascript
// lib/secrets-rotation.js
const NodeCache = require('node-cache');

const ROTATION_INTERVAL = 24 * 60 * 60 * 1000; // 24 hours

class SecretsRotation {
  constructor(secretsProvider) {
    this.secretsProvider = secretsProvider;
    this.cache = new NodeCache();
    this.rotationTimers = new Map();
  }

  async getSecretWithRotation(secretName, rotationInterval = ROTATION_INTERVAL) {
    const cached = this.cache.get(secretName);
    if (cached) return cached;

    // Load secret
    const secret = await this.secretsProvider.getSecret(secretName);
    this.cache.set(secretName, secret);

    // Schedule rotation
    if (!this.rotationTimers.has(secretName)) {
      const timer = setTimeout(() => {
        console.log(`Rotating secret: ${secretName}`);
        this.cache.del(secretName);
        this.rotationTimers.delete(secretName);
      }, rotationInterval);

      this.rotationTimers.set(secretName, timer);
    }

    return secret;
  }
}

module.exports = SecretsRotation;
