const AWS = require('aws-sdk');
const NodeCache = require('node-cache');
const logger = require('./logger');

class AWSSecretsManager {
  constructor(options = {}) {
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.client = new AWS.SecretsManager({ region: this.region });

    // Cache secrets for 1 hour (3600 seconds) by default
    this.cache = new NodeCache({ 
      stdTTL: options.cacheTTL || 3600,
      checkperiod: 60
    });

    this.maxRetries = options.maxRetries || 3;
  }

  /**
   * Get secret with automatic retry and caching
   * @param {string} secretName - Name of secret in AWS Secrets Manager
   * @returns {Promise<object>} Parsed secret value
   */
  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached) {
      logger.debug(`Secret retrieved from cache: ${secretName}`);
      return cached;
    }

    // Retrieve from AWS with retry logic
    const secret = await this._retrieveWithRetry(secretName);

    // Cache the result
    this.cache.set(secretName, secret);

    return secret;
  }

  /**
   * Retrieve secret with exponential backoff retry
   * @private
   */
  async _retrieveWithRetry(secretName, attempt = 1) {
    try {
      const response = await this.client
        .getSecretValue({ SecretId: secretName })
        .promise();

      logger.info({
        event: 'secret_retrieved',
        secretName: secretName,
        source: 'aws_secrets_manager'
      });

      // Parse JSON if it's a string
      if ('SecretString' in response) {
        try {
          return JSON.parse(response.SecretString);
        } catch {
          return response.SecretString;
        }
      }

      // Handle binary secrets
      if ('SecretBinary' in response) {
        return Buffer.from(response.SecretBinary, 'base64');
      }

      throw new Error('Secret has no SecretString or SecretBinary');
    } catch (error) {
      if (attempt < this.maxRetries) {
        const backoffMs = Math.pow(2, attempt) * 1000;
        logger.warn({
          event: 'secret_retrieval_retry',
          secretName: secretName,
          attempt: attempt,
          backoffMs: backoffMs,
          error: error.message
        });

        await new Promise(resolve => setTimeout(resolve, backoffMs));
        return this._retrieveWithRetry(secretName, attempt + 1);
      }

      logger.error({
        event: 'secret_retrieval_failed',
        secretName: secretName,
        error: error.message,
        attempts: attempt
      });

      throw error;
    }
  }

  /**
   * Invalidate cache for a secret (useful after rotation)
   */
  invalidateCache(secretName) {
    this.cache.del(secretName);
    logger.info(`Secret cache invalidated: ${secretName}`);
  }

  /**
   * Clear all cached secrets
   */
  clearCache() {
    this.cache.flushAll();
    logger.info('All secret cache cleared');
  }

  /**
   * Get multiple secrets in parallel
   */
  async getSecrets(secretNames) {
    const promises = secretNames.map(name => this.getSecret(name));
    return Promise.all(promises);
  }
}

module.exports = AWSSecretsManager;
