const app = express();

// Determine which secrets manager to use
let secretsManager;
const SECRETS_PROVIDER = process.env.SECRETS_PROVIDER || 'vault';

if (SECRETS_PROVIDER === 'aws') {
  const AWSSecretsManager = require('./secrets-manager-aws');
  secretsManager = new AWSSecretsManager({
    region: process.env.AWS_REGION,
    cacheTTL: 3600 // 1 hour
  });
