  const VaultSecretsManager = require('./secrets-manager-vault');
  secretsManager = new VaultSecretsManager({
    endpoint: process.env.VAULT_ADDR,
    token: process.env.VAULT_TOKEN,
    cacheTTL: 3600
  });
} else {
  throw new Error(`Unknown secrets provider: ${SECRETS_PROVIDER}`);
}

// ============ STORE LOADED SECRETS ============
let secrets = {
  database: null,
  stripe: null,
  anthropic: null,
  logfire: null
};

