      [secrets.database, secrets.stripe, secrets.anthropic, secrets.logfire] = 
        await secretsManager.getSecrets([
          'prod/database',
          'prod/stripe',
          'prod/anthropic',
          'prod/logfire'
        ]);
    } else if (SECRETS_PROVIDER === 'vault') {
      [secrets.database, secrets.stripe, secrets.anthropic, secrets.logfire] = 
        await secretsManager.getSecrets([
          'secret/prod/database',
          'secret/prod/stripe',
          'secret/prod/anthropic',
          'secret/prod/logfire'
        ]);

      // Set up rotation every 24 hours
      secretsManager.setupRotation('secret/prod/database', 24);
      secretsManager.setupRotation('secret/prod/stripe', 24);
    }

    logger.info('All secrets loaded successfully');
  } catch (error) {
    logger.error('Failed to load secrets:', error);
    process.exit(1);
  }
}

