  }

  if (process.env.SECRETS_PROVIDER === 'vault') {
    if (!process.env.VAULT_ADDR || !process.env.VAULT_TOKEN) {
      throw new Error('VAULT_ADDR and VAULT_TOKEN required when using Vault');
    }
  }

  if (process.env.SECRETS_PROVIDER === 'aws') {
    if (!process.env.AWS_REGION) {
      throw new Error('AWS_REGION required when using AWS Secrets Manager');
    }
  }
}

/**
 * Handle graceful shutdown
 */
function setupGracefulShutdown() {
  process.on('SIGTERM', async () => {
    logger.warn('SIGTERM received, shutting down gracefully');
    server.close(async () => {
      logger.info('HTTP server closed');
      if (secretsManager.clearCache) {
        secretsManager.clearCache();
      }
      process.exit(0);
    });
  });

  process.on('unhandledRejection', (reason, promise) => {
    logger.error('Unhandled Rejection:', reason);
    process.exit(1);
  });
}

/**
 * Start server
 */
async function start() {
  try {
    validateEnvironment();
    await initializeSecrets();

    const PORT = process.env.PORT || 3000;
    const NODE_ENV = process.env.NODE_ENV;

    const server = app.listen(PORT, () => {
      logger.info(`Server running on port ${PORT} (${NODE_ENV})`);
      logger.info(`Secrets provider: ${SECRETS_PROVIDER}`);
    });

    setupGracefulShutdown();

    return server;
  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
}

// Start if this is the main module
if (require.main === module) {
  start();
}

module.exports = app;
