### **Solution 1: Implement AWS Secrets Manager**

**Best for AWS deployments:**

```javascript
// install: npm install aws-sdk
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: 'us-east-1' });

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheExpiry = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName) {
    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && cached.expiry > Date.now()) {
      return cached.value;
    }

    try {
      const response = await client.getSecretValue({ SecretId: secretName }).promise();

      let secretValue;
      if ('SecretString' in response) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        expiry: Date.now() + this.cacheExpiry
      });

      return secretValue;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error);
      throw error;
    }
  }

  async getMultipleSecrets(secretNames) {
    const secrets = {};
    for (const name of secretNames) {
      secrets[name] = await this.getSecret(name);
    }
    return secrets;
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new SecretsManager();
```

**Usage in app.js:**
```javascript
