### **Solution 2: HashiCorp Vault Integration**

**Best for multi-cloud deployments:**

```javascript
// install: npm install node-vault
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN
});

class VaultSecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000;
  }

  async getSecret(path) {
    const cached = this.cache.get(path);
    if (cached && cached.expiry > Date.now()) {
      return cached.value;
    }

    try {
      const secret = await vault.read(path);
      const data = secret.data.data;

      this.cache.set(path, {
        value: data,
        expiry: Date.now() + this.cacheTTL,
        leaseDuration: secret.lease_duration
      });

      return data;
    } catch (error) {
      console.error(`Error retrieving secret from Vault at ${path}:`, error);
      throw error;
    }
  }

  async listSecrets(path) {
    try {
      return await vault.list(path);
    } catch (error) {
      console.error(`Error listing secrets at ${path}:`, error);
      throw error;
    }
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new VaultSecretsManager();
```

