**Create a secure audit log instead:**

```javascript
// audit-log.js - Track rotation events without storing secrets

const logger = require('winston');

class SecretRotationAudit {
  logRotation(secretName, status) {
    // Log ONLY metadata, never the actual secret
    logger.info({
      event: 'SECRET_ROTATION',
      secretName: secretName,
      status: status,
      timestamp: new Date().toISOString(),
      rotatedBy: process.env.USER || 'automation',
      // Hash to verify but not expose
      secretHash: this.hashSecret(secretName)
    });
  }

  hashSecret(secretName) {
    // Create a consistent hash for verification purposes only
    const crypto = require('crypto');
    return crypto
      .createHash('sha256')
      .update(secretName)
      .digest('hex')
      .substring(0, 8);
  }

  generateRotationReport() {
    // Generate report of WHEN secrets were rotated, not WHAT they are
    return {
      rotationDate: new Date().toISOString(),
      secretsRotated: [
        'prod/database/url',
        'prod/jwt/secret',
        'prod/aws/credentials',
        'prod/stripe/key',
        'prod/anthropic/key',
        'prod/logfire/token'
      ],
      nextScheduledRotation: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
      status: 'completed'
    };
  }
}

module.exports = new SecretRotationAudit();
