## **Recommended: Secure Secrets Management Architecture**

### **Option 1: AWS Secrets Manager (Recommended for AWS Users)**

**Benefits:**
- ✅ Centralized secret storage
- ✅ Automatic rotation
- ✅ Audit logging
- ✅ Fine-grained IAM permissions
- ✅ Encryption at rest and in transit

**Implementation:**

```javascript
// ✅ SECURE - Load from AWS Secrets Manager
const AWS = require('aws-sdk');
const secretsClient = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

class SecretsManager {
  constructor() {
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache[secretName] && this.cache[secretName].expiresAt > Date.now()) {
      return this.cache[secretName].value;
    }

    try {
      const data = await secretsClient.getSecretValue({ SecretId: secretName }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache[secretName] = {
        value: secret,
        expiresAt: Date.now() + this.cacheTTL
      };

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error(`Cannot access required secret: ${secretName}`);
    }
  }

  async getAllSecrets() {
    const secrets = {};
    const requiredSecrets = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN'
    ];

    for (const secretName of requiredSecrets) {
      try {
        secrets[secretName] = await this.getSecret(secretName);
      } catch (err) {
        console.error(`Missing critical secret: ${secretName}`);
        throw err;
      }
    }

    return secrets;
  }
}

module.exports = new SecretsManager();
```

