// ✅ SECURE - Load from HashiCorp Vault
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'https://vault.example.com',
  token: process.env.VAULT_TOKEN
});

class VaultSecretsManager {
  async getSecret(path) {
    try {
      const response = await vault.read(path);
      return response.data.data; // Vault KV2 format
    } catch (error) {
      console.error(`Failed to retrieve secret from Vault: ${path}`, error);
      throw error;
    }
  }

  async initializeSecrets() {
    const secrets = {};

    try {
      // Read database credentials
      const dbSecret = await this.getSecret('secret/data/database/prod');
      secrets.DATABASE_URL = dbSecret.connection_string;

      // Read payment processor key
      const paymentSecret = await this.getSecret('secret/data/stripe/live');
      secrets.STRIPE_SECRET_KEY = paymentSecret.key;

      // Read API keys
      const apiKeys = await this.getSecret('secret/data/external-apis');
      secrets.ANTHROPIC_API_KEY = apiKeys.anthropic;
      secrets.LOGFIRE_TOKEN = apiKeys.logfire;

      return secrets;
    } catch (error) {
      console.error('Failed to initialize secrets from Vault');
      throw error;
    }
  }
}

module.exports = new VaultSecretsManager();
