## Recommended Solutions

### SOLUTION 1: AWS Secrets Manager (Cloud-Native)

**Best for:** AWS deployments

```javascript
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: 'us-east-1' });

async function getSecret(secretName) {
  try {
    const data = await client.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    } else {
      return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }
  } catch (err) {
    console.error('Error retrieving secret:', err);
    throw err;
  }
}

// Usage
(async () => {
  const secrets = await getSecret('prod/app-secrets');
  const jwtSecret = secrets.JWT_SECRET;
  const dbUrl = secrets.DATABASE_URL;
})();
```

**Benefits:**
✅ Encrypted at rest and in transit
✅ Audit trail (CloudTrail)
✅ Automated rotation support
✅ IAM-based access control
✅ No local .env files

**Setup:**
```bash
# Store secrets
aws secretsmanager create-secret \
  --name prod/app-secrets \
  --secret-string '{
    "JWT_SECRET":"your-secret",
    "DATABASE_URL":"postgres://..."
  }'

# Grant EC2/Lambda role access via IAM policy
```

---

### SOLUTION 2: HashiCorp Vault (Multi-Cloud)

**Best for:** Multi-cloud, on-premises, complex requirements

```javascript
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN,
});

async function getVaultSecrets() {
  try {
    const response = await vault.read('secret/data/production/app');
    return response.data.data; // Vault stores data nested
  } catch (err) {
    console.error('Vault error:', err);
    throw err;
  }
}

// Initialize secrets at startup
let appSecrets = {};

(async () => {
  appSecrets = await getVaultSecrets();
  const jwtSecret = appSecrets.JWT_SECRET;
})();
```

**Benefits:**
✅ Multi-cloud support
✅ Dynamic secrets generation
✅ Advanced access control
✅ Encryption key management
✅ Audit logging

