/**
 * AWS Secrets Manager Implementation
 * Best for: AWS environments (EC2, Lambda, ECS, etc.)
 */

const AWS = require('aws-sdk');
const cache = require('node-cache');

// Configure AWS client
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Simple in-memory cache with TTL
const secretCache = new cache({ stdTTL: 3600 }); // 1 hour

/**
 * Retrieve secret from AWS Secrets Manager
 * @param {string} secretName - Secret name/ARN
 * @returns {Promise<Object>} Decrypted secret
 */
async function getSecret(secretName) {
  // Check cache first
  const cached = secretCache.get(secretName);
  if (cached) {
    console.log(`[CACHE HIT] Secret: ${secretName}`);
    return cached;
  }

  try {
    console.log(`[FETCHING] Secret: ${secretName}`);

    const data = await secretsManager
      .getSecretValue({ SecretId: secretName })
      .promise();

    let secret;

    // Secrets Manager returns either SecretString or SecretBinary
    if ('SecretString' in data) {
      secret = JSON.parse(data.SecretString);
    } else {
      secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }

    // Cache the secret
    secretCache.set(secretName, secret);

    console.log(`[SUCCESS] Retrieved secret: ${secretName}`);
    return secret;
  } catch (err) {
    console.error(`[ERROR] Failed to retrieve secret: ${secretName}`, err);
    throw new Error(`Unable to retrieve secret: ${secretName}`);
  }
}

/**
 * Rotate a secret (typically called by AWS Lambda rotation function)
 * @param {string} secretId - Secret ID
 * @param {string} clientRequestToken - Rotation token
 * @param {string} step - Rotation step (createSecret, setSecret, testSecret, finishSecret)
 */
async function rotateSecret(secretId, clientRequestToken, step) {
  console.log(`[ROTATE] Secret: ${secretId}, Step: ${step}`);

  try {
    // Invalidate cache on rotation
    secretCache.del(secretId);

    switch (step) {
      case 'createSecret':
        await createSecretVersion(secretId, clientRequestToken);
        break;
      case 'setSecret':
        await setSecretVersion(secretId, clientRequestToken);
        break;
      case 'testSecret':
        await testSecretVersion(secretId, clientRequestToken);
        break;
      case 'finishSecret':
        await finishSecretVersion(secretId, clientRequestToken);
        break;
      default:
        throw new Error(`Unknown rotation step: ${step}`);
    }
  } catch (err) {
    console.error(`[ERROR] Rotation failed at step ${step}:`, err);
    throw err;
  }
}

async function createSecretVersion(secretId, clientRequestToken) {
  // Generate new secret version
  // This is implemented in AWS Lambda rotation function
  console.log(`Creating new version for ${secretId}`);
}

async function setSecretVersion(secretId, clientRequestToken) {
  // Apply new secret to actual resource (e.g., update DB password)
  console.log(`Setting new version for ${secretId}`);
}

async function testSecretVersion(secretId, clientRequestToken) {
  // Test new secret works
  console.log(`Testing new version for ${secretId}`);
}

async function finishSecretVersion(secretId, clientRequestToken) {
  // Mark new version as current
  console.log(`Finishing rotation for ${secretId}`);
}

/**
 * Get multiple secrets efficiently
 */
async function getSecrets(...secretNames) {
  const results = {};

  for (const name of secretNames) {
    try {
      results[name] = await getSecret(name);
    } catch (err) {
      console.error(`Failed to retrieve ${name}:`, err);
      results[name] = null;
    }
  }

  return results;
}

/**
 * Store a new secret
 */
async function createSecret(secretName, secretValue) {
  try {
    console.log(`[CREATE] Secret: ${secretName}`);

    const params = {
      Name: secretName,
      SecretString: typeof secretValue === 'string' 
        ? secretValue 
        : JSON.stringify(secretValue),
      Tags: [
        { Key: 'Application', Value: 'SecureApp' },
        { Key: 'CreatedAt', Value: new Date().toISOString() }
      ]
    };

    await secretsManager.createSecret(params).promise();
    console.log(`[SUCCESS] Created secret: ${secretName}`);
  } catch (err) {
    console.error(`[ERROR] Failed to create secret:`, err);
    throw err;
  }
}

/**
 * Update an existing secret
 */
async function updateSecret(secretName, secretValue) {
  try {
    console.log(`[UPDATE] Secret: ${secretName}`);

    // Invalidate cache
    secretCache.del(secretName);

    const params = {
      SecretId: secretName,
      SecretString: typeof secretValue === 'string'
        ? secretValue
        : JSON.stringify(secretValue)
    };

    await secretsManager.updateSecretValue(params).promise();
    console.log(`[SUCCESS] Updated secret: ${secretName}`);
  } catch (err) {
    console.error(`[ERROR] Failed to update secret:`, err);
    throw err;
  }
