 */
async function deleteSecret(secretName, recoveryDays = 7) {
  try {
    console.log(`[DELETE] Secret: ${secretName} (recovery: ${recoveryDays} days)`);

    secretCache.del(secretName);

    await secretsManager.deleteSecret({
