/**
 * HashiCorp Vault Implementation
 * Best for: Multi-cloud, on-premises, complex requirements
 */

const vault = require('node-vault');
const cache = require('node-cache');

// Initialize Vault client
const vaultClient = vault({
  endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
  token: process.env.VAULT_TOKEN,
  timeout: 1000,
  requestOptions: {
    strictSSL: process.env.NODE_ENV === 'production'
  }
});

// Cache secrets with TTL
const secretCache = new cache({ stdTTL: 3600 }); // 1 hour

/**
 * Authenticate to Vault
 * Supports multiple auth methods
 */
async function authenticateVault() {
  try {
    const authMethod = process.env.VAULT_AUTH_METHOD || 'token';

    switch (authMethod) {
      case 'token':
        // Token-based auth (set VAULT_TOKEN env var)
        console.log('[VAULT] Authenticated with token');
        return;

      case 'approle':
        // AppRole auth (recommended for applications)
        const roleId = process.env.VAULT_ROLE_ID;
        const secretId = process.env.VAULT_SECRET_ID;

        const result = await vaultClient.appRole({
          role_id: roleId,
          secret_id: secretId
        });

        vaultClient.token = result.auth.client_token;
        console.log('[VAULT] Authenticated with AppRole');
        break;

      case 'kubernetes':
        // Kubernetes auth
        const jwt = require('fs').readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8');

        const k8sResult = await vaultClient.kubernetesLogin({
          role: process.env.VAULT_K8S_ROLE,
          jwt: jwt
        });

        vaultClient.token = k8sResult.auth.client_token;
        console.log('[VAULT] Authenticated with Kubernetes auth');
        break;

      default:
        throw new Error(`Unknown auth method: ${authMethod}`);
    }
  } catch (err) {
    console.error('[ERROR] Vault authentication failed:', err);
    throw err;
  }
}

/**
 * Read secret from Vault KV v2
 * Path format: secret/data/path/to/secret
 */
async function readSecret(path) {
  const cacheKey = `vault:${path}`;

  // Check cache
  const cached = secretCache.get(cacheKey);
  if (cached) {
    console.log(`[CACHE HIT] Vault secret: ${path}`);
    return cached;
  }

  try {
    console.log(`[FETCHING] Vault secret: ${path}`);

    // Read from KV v2
    const secret = await vaultClient.read(path);

    // KV v2 stores data nested under data.data
    const secretData = secret.data.data;

    // Cache it
    secretCache.set(cacheKey, secretData);

    console.log(`[SUCCESS] Retrieved secret: ${path}`);
    return secretData;
  } catch (err) {
    console.error(`[ERROR] Failed to read secret from Vault: ${path}`, err);
    throw new Error(`Unable to read secret: ${path}`);
  }
}

/**
 * Read multiple secrets
 */
async function readSecrets(...paths) {
  const results = {};

  for (const path of paths) {
    try {
      results[path] = await readSecret(path);
    } catch (err) {
      console.error(`Failed to read ${path}:`, err);
      results[path] = null;
    }
  }

  return results;
}

/**
 * Write secret to Vault
 */
async function writeSecret(path, secretData) {
  try {
    console.log(`[WRITE] Vault secret: ${path}`);

    // Invalidate cache
    secretCache.del(`vault:${path}`);

    await vaultClient.write(path, secretData);

    console.log(`[SUCCESS] Wrote secret: ${path}`);
  } catch (err) {
    console.error(`[ERROR] Failed to write secret:`, err);
    throw err;
  }
}

/**
 * Delete secret from Vault
 */
async function deleteSecret(path) {
  try {
    console.log(`[DELETE] Vault secret: ${path}`);

    secretCache.del(`vault:${path}`);

    await vaultClient.delete(path);

    console.log(`[SUCCESS] Deleted secret: ${path}`);
  } catch (err) {
    console.error(`[ERROR] Failed to delete secret:`, err);
    throw err;
  }
}

