 */
async function generateDatabaseCredentials(roleName) {
  try {
    console.log(`[GENERATE] Database credentials for role: ${roleName}`);

    const creds = await vaultClient.read(`database/creds/${roleName}`);

    console.log(`[SUCCESS] Generated credentials for: ${roleName}`);
    return {
      username: creds.data.username,
      password: creds.data.password,
