 */
async function encryptData(transitKey, plaintext) {
  try {
    const encrypted = await vaultClient.write(`transit/encrypt/${transitKey}`, {
      plaintext: Buffer.from(plaintext).toString('base64')
    });

    return encrypted.data.ciphertext;
  } catch (err) {
    console.error('[ERROR] Encryption failed:', err);
    throw err;
  }
}

/**
 * Decrypt data using Vault Transit engine
 */
async function decryptData(transitKey, ciphertext) {
  try {
    const decrypted = await vaultClient.write(`transit/decrypt/${transitKey}`, {
      ciphertext: ciphertext
    });

    return Buffer.from(decrypted.data.plaintext, 'base64').toString('utf8');
  } catch (err) {
    console.error('[ERROR] Decryption failed:', err);
    throw err;
  }
}

