/**
 * SECURE VERSION OF app.js
 * Implements security best practices and OWASP Top 10 mitigations
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
require('dotenv').config();

const app = express();

// ============================================================================
// SECURITY: Logging Configuration
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// ============================================================================
// SECURITY: HTTPS Enforcement
// ============================================================================

app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(307, `https://${req.hostname}${req.url}`);
  }
  next();
});

// ============================================================================
// SECURITY: Security Headers (Helmet)
// ============================================================================

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
}));

// ============================================================================
// SECURITY: CORS Configuration
// ============================================================================

const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn({ event: 'CORS_VIOLATION', origin });
      callback(new Error('CORS policy violation'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
}));

// ============================================================================
// SECURITY: Body Parser with Size Limits
// ============================================================================

app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================================
// SECURITY: Request Logging Middleware
// ============================================================================

app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userId: req.user?.id,
      userRole: req.user?.role
    });
  });
  next();
});

// ============================================================================
// SECURITY: Rate Limiting
// ============================================================================

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: (req, res) => {
    // Admins get higher limits
    return req.user?.role === 'admin' ? 1000 : 100;
  },
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => process.env.NODE_ENV === 'development', // Skip rate limiting in development
  handler: (req, res, next, options) => {
    logger.warn({
      event: 'RATE_LIMIT_EXCEEDED',
      ip: req.ip,
      path: req.path
    });
    res.status(options.statusCode).json({ error: options.message });
  }
});

app.use('/api/', limiter);

// ============================================================================
// SECURITY: Authentication Middleware
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn({
      event: 'MISSING_AUTH_TOKEN',
      ip: req.ip,
      path: req.path
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'dev-secret', (err, user) => {
    if (err) {
      logger.warn({
        event: 'INVALID_TOKEN',
        ip: req.ip,
        error: err.message
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// SECURITY: Authorization Middleware
// ============================================================================

const authorizeRole = (roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.user?.role)) {
      logger.warn({
        event: 'UNAUTHORIZED_ACCESS',
        userId: req.user?.id,
        requiredRoles: roles,
        userRole: req.user?.role,
        path: req.path
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// ============================================================================
// SECURITY: Input Validation Functions
// ============================================================================

const validateUserId = query('id')
  .optional()
  .isInt({ min: 1 })
  .withMessage('User ID must be a positive integer')
  .toInt();

const validateLimit = query('limit')
  .optional()
  .isInt({ min: 1, max: 100 })
  .withMessage('Limit must be between 1 and 100')
  .toInt();

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn({
      event: 'VALIDATION_ERROR',
      ip: req.ip,
      errors: errors.array()
    });
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ============================================================================
// MOCK DATA (Replace with database in production)
