  });
});

// ============================================================================
// ROUTES: Get Users (Protected and Validated)
// ============================================================================

app.get('/api/users',
  authenticateToken,
  validateUserId,
  validateLimit,
  handleValidationErrors,
  (req, res) => {
    try {
      const { id, limit = 50 } = req.query;

      // Authorization: Users can only see their own data, admins see all
      let result = users;

      if (req.user.role !== 'admin') {
        result = result.filter(u => u.id === req.user.id);
      }

      if (id) {
        result = result.filter(u => u.id === id);
      }

      // Apply pagination
      result = result.slice(0, limit);

      logger.info({
        event: 'USERS_RETRIEVED',
        userId: req.user.id,
        count: result.length
      });

      res.json(result);
    } catch (error) {
      logger.error({
        event: 'ERROR_RETRIEVING_USERS',
        userId: req.user.id,
        error: error.message
      });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============================================================================
// ROUTES: Get Single User (Protected)
// ============================================================================

app.get('/api/users/:id',
  authenticateToken,
  (req, res) => {
    try {
      const userId = parseInt(req.params.id, 10);

      // Input validation
      if (isNaN(userId) || userId < 1) {
        return res.status(400).json({ error: 'Invalid user ID' });
      }

