          userId: req.user.id,
          targetUserId: userId
        });
        return res.status(403).json({ error: 'You can only view your own profile' });
      }

      logger.info({
        event: 'USER_RETRIEVED',
        userId: req.user.id,
        targetUserId: userId
      });

      res.json(user);
    } catch (error) {
      logger.error({
        event: 'ERROR_RETRIEVING_USER',
        error: error.message
      });
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// ============================================================================
// ERROR HANDLING: 404 Handler
// ============================================================================

app.use((req, res) => {
  logger.warn({
    event: 'NOT_FOUND',
    ip: req.ip,
    method: req.method,
    path: req.path
  });
