#### **Option 1: AWS Secrets Manager (Recommended for Production)**

```javascript
const express = require('express');
const AWS = require('aws-sdk');

const app = express();

// Initialize Secrets Manager
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let secretCache = {};

/**
 * Retrieve secrets from AWS Secrets Manager
 * Implements caching to reduce API calls and improve performance
 */
async function getSecret(secretName) {
  // Check cache first (cache for 1 hour)
  if (secretCache[secretName] && secretCache[secretName].expiresAt > Date.now()) {
    return secretCache[secretName].value;
  }

  try {
    const response = await secretsManager.getSecretValue({ SecretId: secretName }).promise();

    let secret;
    if ('SecretString' in response) {
      secret = JSON.parse(response.SecretString);
    } else {
      secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    // Cache the secret
    secretCache[secretName] = {
      value: secret,
      expiresAt: Date.now() + (60 * 60 * 1000) // 1 hour
    };

    return secret;
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error);
    throw new Error(`Failed to retrieve secret: ${secretName}`);
  }
}

/**
 * Initialize application with secrets
 */
async function initializeApp() {
  try {
    // Load all required secrets
    const dbSecret = await getSecret('prod/database');
    const apiSecret = await getSecret('prod/api-keys');
    const awsSecret = await getSecret('prod/aws-credentials');

    // Store in process.env or app locals (never expose globally)
    app.locals.secrets = {
      database: dbSecret,
      apiKeys: apiSecret,
      aws: awsSecret
    };

    console.log('Secrets loaded successfully from AWS Secrets Manager');
  } catch (error) {
    console.error('Failed to initialize application:', error);
    process.exit(1);
  }
}

// Middleware to access secrets safely
app.use((req, res, next) => {
  req.secrets = app.locals.secrets;
  next();
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
