#### **SOLUTION 1: AWS Secrets Manager (RECOMMENDED FOR PRODUCTION)**

```javascript
// config/secrets.js
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache
    if (this.cache[secretName] && 
        Date.now() - this.cache[secretName].timestamp < this.cacheTTL) {
      return this.cache[secretName].value;
    }

    try {
      const data = await this.client.getSecretValue({ 
        SecretId: secretName 
      }).promise();

      let secret = data.SecretString 
        ? JSON.parse(data.SecretString) 
        : data.SecretBinary;

      // Cache the secret
      this.cache[secretName] = {
        value: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  async getDatabaseUrl() {
    const secret = await this.getSecret('prod/database');
    return `postgresql://${secret.username}:${secret.password}@${secret.host}:${secret.port}/${secret.dbname}`;
  }

  async getAwsCredentials() {
    return await this.getSecret('prod/aws');
  }

  async getApiKeys() {
    return await this.getSecret('prod/api-keys');
  }
}

module.exports = new SecretsManager();
```

