// config/vault.js
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN
});

class VaultSecretsManager {
  async getSecret(path) {
    try {
      const result = await vault.read(path);
      return result.data.data;
    } catch (error) {
      console.error(`Vault error reading ${path}:`, error);
      throw error;
    }
  }

  async getDatabaseCredentials() {
    return await this.getSecret('secret/data/database');
  }

  async getApiCredentials(service) {
    return await this.getSecret(`secret/data/api/${service}`);
  }

  // Dynamic credentials (short-lived tokens)
  async getDynamicDatabaseCredentials(role = 'app') {
    try {
      const creds = await vault.read(`database/creds/${role}`);
      return {
        username: creds.data.username,
        password: creds.data.password,
        ttl: creds.lease_duration
      };
    } catch (error) {
      console.error('Failed to get dynamic credentials:', error);
      throw error;
    }
  }
}

module.exports = new VaultSecretsManager();
