// verification.js - The RIGHT way to verify rotation

const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function verifyRotation(secretName) {
  try {
    // Get secret metadata (NOT the value)
    const secret = await secretsManager.describeSecret({
      SecretId: secretName
    }).promise();

    console.log(`✅ Secret: ${secretName}`);
