      verified: true,
      lastRotated: secret.LastRotatedDate,
      versionCount: Object.keys(secret.VersionIdsToStages).length,
      status: 'rotation_detected'
    };
  } catch (error) {
    console.error(`❌ Verification failed: ${error.message}`);
    return {
      secretName,
      verified: false,
      error: error.message
    };
  }
}

// Test new credentials work without displaying them
async function testCredentialValidity(secretName) {
  try {
    const secret = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    // Parse without logging
