    }

    return { secretName, valid: true };
  } catch (error) {
    console.error(`❌ Credential test failed: ${error.message}`);
    return { secretName, valid: false, error: error.message };
  }
}

// Generate rotation report (safe)
async function generateRotationReport(secretNames) {
  const report = {
    generatedAt: new Date().toISOString(),
    verifications: []
  };

  for (const name of secretNames) {
    const verification = await verifyRotation(name);
    const validity = await testCredentialValidity(name);

