/**
 * SECURE VERSION OF app.js
 * Implements all recommended security fixes
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
require('dotenv').config({
  path: process.env.NODE_ENV === 'test' ? '.env.test' : '.env.local'
});

const app = express();

// ============================================================================
// LOGGING CONFIGURATION
// ============================================================================
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security headers via helmet
app.use(helmet());

// 2. Additional CSP configuration
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'"],
    imgSrc: ["'self'", "data:", "https:"],
    connectSrc: ["'self'"],
    frameSrc: ["'none'"],
    objectSrc: ["'none'"]
  }
}));

// 3. HSTS for HTTPS enforcement
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));

// 4. Request size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. CORS configuration with whitelist
const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
const corsOptions = {
  origin: function(origin, callback) {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn({ message: 'CORS rejection', origin });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 600,
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));

// 6. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  handler: (req, res) => {
    logger.warn({ message: 'Rate limit exceeded', ip: req.ip });
    res.status(429).json({ error: 'Too many requests' });
  }
});

app.use(limiter);

// 7. Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();

  // Log response when finished
  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      url: req.url,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      timestamp: new Date().toISOString()
    });
  });

  next();
});

// 8. Security context: Add request ID for tracking
app.use((req, res, next) => {
  req.id = require('crypto').randomUUID();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn({ message: 'Missing auth token', ip: req.ip, requestId: req.id });
    return res.status(401).json({ error: 'Access token required' });
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    logger.error({ message: 'JWT_SECRET not configured' });
    return res.status(500).json({ error: 'Server configuration error' });
  }

  jwt.verify(token, secret, (err, user) => {
    if (err) {
      logger.warn({ message: 'Invalid token', error: err.message, ip: req.ip, requestId: req.id });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    req.user = user;
    next();
  });
};

// ============================================================================
// AUTHORIZATION MIDDLEWARE
// ============================================================================

const requireRole = (roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!roles.includes(req.user.role)) {
      logger.warn({
        message: 'Unauthorized access attempt',
        user: req.user.id,
        requiredRole: roles,
        userRole: req.user.role,
        requestId: req.id
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1, max: 2147483647 })
    .withMessage('ID must be a positive integer'),
  query('name')
    .optional()
    .isLength({ min: 1, max: 100 })
    .trim()
    .matches(/^[a-zA-Z\s\-']*$/)
    .withMessage('Name must contain only letters, spaces, hyphens, and apostrophes'),
  query('email')
    .optional()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
];

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn({
      message: 'Validation error',
      errors: errors.array(),
      ip: req.ip,
      requestId: req.id
    });
    return res.status(400).json({
      error: 'Invalid request parameters',
      details: errors.array().map(e => ({ field: e.param, message: e.msg }))
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint (public)
 * Minimal information exposure
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

/**
 * Get users endpoint (authenticated, authorized)
 * Supports filtering with validated query parameters
 */
app.get(
  '/users',
  authenticateToken,
  requireRole(['admin', 'user']),
  validateUserQuery,
  handleValidationErrors,
  (req, res) => {
    try {
      // Mock user data - in production, this would come from a database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' }
      ];

      // Apply query filters (all validated)
      let filteredUsers = allUsers;

      if (req.query.id) {
        filteredUsers = filteredUsers.filter(u => u.id === parseInt(req.query.id));
      }

      if (req.query.name) {
        filteredUsers = filteredUsers.filter(u =>
          u.name.toLowerCase().includes(req.query.name.toLowerCase())
        );
      }

      if (req.query.email) {
        filteredUsers = filteredUsers.filter(u =>
          u.email.toLowerCase() === req.query.email.toLowerCase()
        );
      }

      // Apply pagination
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = parseInt(req.query.offset) || 0;

      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      // Set secure headers
      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.setHeader('X-Content-Type-Options', 'nosniff');

      res.json({
        data: paginatedUsers,
        pagination: {
          total: filteredUsers.length,
          limit,
          offset,
          returned: paginatedUsers.length
        }
      });

      logger.info({
        message: 'Users retrieved',
        count: paginatedUsers.length,
        userId: req.user.id,
        requestId: req.id
      });
    } catch (error) {
      logger.error({
        message: 'Error retrieving users',
        error: error.message,
        requestId: req.id
      });
      res.status(500).json({
        error: 'Internal server error',
        requestId: req.id
      });
    }
  }
);

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// 404 handler
app.use((req, res) => {
  logger.warn({
    message: '404 Not Found',
    method: req.method,
    url: req.url,
    ip: req.ip,
    requestId: req.id
  });
  res.status(404).json({
    error: 'Endpoint not found',
    requestId: req.id
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error({
    message: 'Unhandled error',
    error: err.message,
    stack: err.stack,
    method: req.method,
    url: req.url,
    ip: req.ip,
    requestId: req.id
  });

  // Don't expose internal error details to client
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: 'Internal server error',
    requestId: req.id
  });
});

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error({
    type: 'uncaughtException',
    error: error.message,
    stack: error.stack
  });
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    type: 'unhandledRejection',
    reason: reason instanceof Error ? reason.message : String(reason),
    stack: reason instanceof Error ? reason.stack : undefined
  });
  process.exit(1);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// HTTPS in production
if (process.env.NODE_ENV === 'production') {
  const https = require('https');
  const fs = require('fs');

  const sslKeyPath = process.env.SSL_KEY_PATH;
  const sslCertPath = process.env.SSL_CERT_PATH;

  if (!sslKeyPath || !sslCertPath) {
    logger.error({
      message: 'SSL certificates not configured for production'
    });
    process.exit(1);
  }

  try {
    const options = {
      key: fs.readFileSync(sslKeyPath),
      cert: fs.readFileSync(sslCertPath)
    };

    https.createServer(options, app).listen(443, HOST, () => {
      logger.info({
        message: 'Server running on HTTPS',
        port: 443,
        host: HOST,
        environment: process.env.NODE_ENV
      });
    });
  } catch (error) {
    logger.error({
      message: 'Failed to start HTTPS server',
      error: error.message
    });
    process.exit(1);
  }
} else {
  // HTTP for development only
  app.listen(PORT, HOST, () => {
    logger.info({
      message: 'Server running on HTTP (development only)',
      port: PORT,
      host: HOST,
      environment: process.env.NODE_ENV || 'development'
    });
  });
}

module.exports = app;

