const express = require('express');
const AWS = require('aws-sdk');

const app = express();

// Initialize AWS Secrets Manager client
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
});

// Cache for secrets (with TTL)
let secretsCache = {};
const CACHE_TTL = 3600000; // 1 hour in milliseconds
let cacheFetchTime = 0;

/**
 * Fetch secrets from AWS Secrets Manager
 * Includes caching to reduce API calls
 */
async function getSecret(secretName) {
  const now = Date.now();

  // Return cached secret if fresh
  if (secretsCache[secretName] && (now - cacheFetchTime) < CACHE_TTL) {
    console.log(`[Cache HIT] Secret: ${secretName}`);
    return secretsCache[secretName];
  }

  try {
    const data = await secretsManager.getSecretValue({
      SecretId: secretName,
    }).promise();

    let secret;

    if ('SecretString' in data) {
      secret = JSON.parse(data.SecretString);
    } else {
      secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }

    // Cache the secret
    secretsCache[secretName] = secret;
    cacheFetchTime = now;

    console.log(`[Cache MISS] Fetched secret: ${secretName}`);
    return secret;
  } catch (err) {
    console.error(`Error fetching secret ${secretName}:`, err);
    throw new Error(`Failed to retrieve secret: ${secretName}`);
  }
}

// Initialize secrets on startup
async function initializeSecrets() {
  try {
    // Fetch database credentials
    const dbSecret = await getSecret('prod/database');
    process.env.DATABASE_URL = `postgresql://${dbSecret.username}:${dbSecret.password}@${dbSecret.host}:${dbSecret.port}/${dbSecret.dbname}`;

