const express = require('express');
const vault = require('node-vault');

const app = express();

// Initialize Vault client
const vaultClient = vault({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN,
});

/**
 * Fetch secrets from Vault with retry logic
 */
async function getSecretFromVault(secretPath) {
  const maxRetries = 3;
  let attempt = 0;

  while (attempt < maxRetries) {
    try {
      const response = await vaultClient.read(secretPath);
      console.log(`✓ Retrieved secret from: ${secretPath}`);
      return response.data.data; // Vault KV v2 stores data in .data.data
    } catch (err) {
      attempt++;
      console.warn(`Vault read attempt ${attempt} failed:`, err.message);

      if (attempt === maxRetries) {
        throw new Error(`Failed to retrieve secret after ${maxRetries} attempts: ${secretPath}`);
      }

      // Exponential backoff
      await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 1000));
    }
  }
}

/**
 * Renew token before expiration
 */
async function renewVaultToken() {
  try {
    await vaultClient.tokenRenew();
    console.log('✓ Vault token renewed');

    // Schedule next renewal (before expiration)
    setTimeout(renewVaultToken, 300000); // Every 5 minutes
  } catch (err) {
    console.error('Failed to renew Vault token:', err);
    process.exit(1);
  }
}

/**
 * Initialize secrets from Vault
 */
async function initializeSecrets() {
  try {
    // Fetch database credentials
    const dbSecret = await getSecretFromVault('secret/data/prod/database');
    process.env.DATABASE_URL = 
      `postgresql://${dbSecret.username}:${dbSecret.password}@${dbSecret.host}:${dbSecret.port}/${dbSecret.dbname}`;

    // Fetch API keys
    const apiKeys = await getSecretFromVault('secret/data/prod/api-keys');
    process.env.ANTHROPIC_API_KEY = apiKeys.anthropic;
    process.env.STRIPE_SECRET_KEY = apiKeys.stripe;
    process.env.JWT_SECRET = apiKeys.jwt;

    // Start token renewal
    renewVaultToken();

    console.log('✓ All secrets loaded from Vault');
  } catch (err) {
    console.error('Failed to initialize secrets from Vault:', err);
    process.exit(1);
  }
}

