/**
 * SECURE IMPLEMENTATION OF app.js
 * This file demonstrates security best practices for Express.js applications
 */

require('dotenv').config();
const express = require('express');
const jwt = require('jsonwebtoken');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const winston = require('winston');
const https = require('https');
const fs = require('fs');

// ============================================================================
// CONFIGURATION & VALIDATION
// ============================================================================

// Validate environment variables
const requiredEnvVars = ['JWT_SECRET'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    throw new Error(`Missing required environment variable: ${envVar}`);
  }
});

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    ...(NODE_ENV === 'development' ? [new winston.transports.Console()] : []),
  ],
});

// ============================================================================
// EXPRESS APP INITIALIZATION
// ============================================================================

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet.js - Set security HTTP headers
app.use(helmet());

// 2. CORS - Configure cross-origin resource sharing
const corsOptions = {
  origin: ALLOWED_ORIGINS,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// 3. Body Parser - Limit payload size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 4. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV === 'development', // Skip in development
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later.',
});

app.use('/api/', limiter);

// 5. Additional Security Headers
app.use((req, res, next) => {
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});

// ============================================================================
// LOGGING MIDDLEWARE
// ============================================================================

// Request/Response logging
app.use((req, res, next) => {
  const requestId = req.headers['x-request-id'] || Math.random().toString(36).substr(2, 9);
  req.requestId = requestId;

  res.on('finish', () => {
    const logData = {
      requestId,
      method: req.method,
      path: req.path,
      status: res.statusCode,
      ip: req.ip,
      userAgent: req.get('user-agent'),
      responseTime: `${Date.now() - res.locals.startTime}ms`,
      ...(req.user && { userId: req.user.id }),
    };

    if (res.statusCode >= 500) {
      logger.error(logData);
    } else if (res.statusCode >= 400) {
      logger.warn(logData);
    } else {
      logger.info(logData);
    }
  });

  res.locals.startTime = Date.now();
  next();
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

/**
 * JWT Authentication middleware
 * Validates Bearer token from Authorization header
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      event: 'auth_failed',
      reason: 'no_token',
      ip: req.ip,
      path: req.path,
    });
    return res.status(401).json({ error: 'Access denied. No token provided.' });
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET, {
      algorithms: ['HS256'], // Restrict to specific algorithm
    });
    req.user = decoded;
    next();
  } catch (err) {
    logger.error({
      event: 'auth_failed',
      reason: 'invalid_token',
      ip: req.ip,
      path: req.path,
      error: err.message,
    });
    return res.status(403).json({ error: 'Invalid or expired token.' });
  }
};

/**
 * Role-based authorization middleware
 */
const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      logger.warn({
        event: 'authorization_failed',
        userId: req.user?.id,
        requiredRole: allowedRoles,
        userRole: req.user?.role,
        path: req.path,
      });
      return res.status(403).json({ error: 'Forbidden. Insufficient permissions.' });
    }
    next();
  };
};

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Handle validation errors from express-validator
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health Check Endpoint
 * Public endpoint - no authentication required
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: NODE_ENV,
    });
  } catch (err) {
    logger.error({ event: 'health_check_error', error: err.message });
    res.status(500).json({ error: 'Health check failed' });
  }
});

/**
 * Get Users Endpoint
 * Protected - requires authentication and admin role
 * Returns sanitized user data (no sensitive fields)
 */
app.get('/api/users', authenticateToken, authorize('admin'), (req, res) => {
  try {
    // Simulated database query - in real app, would query database
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    logger.info({
      event: 'users_retrieved',
      userId: req.user.id,
      userCount: users.length,
    });

    res.json({
      data: users,
      count: users.length,
    });
  } catch (err) {
    logger.error({ event: 'get_users_error', error: err.message });
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

/**
 * Create User Endpoint
 * Protected - requires authentication and admin role
 * Includes comprehensive input validation
 */
app.post('/api/users',
  authenticateToken,
  authorize('admin'),
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .escape(),
  body('email')
    .isEmail()
    .withMessage('Invalid email address')
    .normalizeEmail(),
  body('role')
    .isIn(['user', 'admin'])
    .withMessage('Role must be either user or admin'),
  handleValidationErrors,
  (req, res) => {
    try {
      const { name, email, role } = req.body;

      // Simulated database insert
      const newUser = {
        id: Math.random().toString(36).substr(2, 9),
        name,
        email,
        role,
        createdAt: new Date().toISOString(),
      };

      logger.info({
        event: 'user_created',
        createdBy: req.user.id,
        newUserId: newUser.id,
      });

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
      });
    } catch (err) {
      logger.error({ event: 'create_user_error', error: err.message });
      res.status(500).json({ error: 'Failed to create user' });
    }
  }
);

/**
 * Login Endpoint
 * Issues JWT token for authentication
 * Rate limited to prevent brute force attacks
 */
app.post('/api/login',
  authLimiter,
  body('username')
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape(),
  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters'),
  handleValidationErrors,
  (req, res) => {
    try {
      const { username, password } = req.body;

      // IMPORTANT: This is a placeholder. In production:
      // 1. Use bcrypt to hash passwords
      // 2. Query database for user
      // 3. Compare hashed password with bcrypt
      // 4. Never store plain text passwords

      // Simulate credential validation
      if (username === 'admin' && password === 'secure-password') {
        const token = jwt.sign(
          {
            id: '1',
            username: 'admin',
            role: 'admin',
          },
          JWT_SECRET,
          {
            algorithm: 'HS256',
            expiresIn: '1h', // Token expires in 1 hour
            issuer: 'secure-api',
            audience: 'secure-app',
          }
        );

        logger.info({
          event: 'login_success',
          username,
        });

        res.json({
          message: 'Login successful',
          token,
          expiresIn: '1h',
        });
      } else {
        logger.warn({
          event: 'login_failed',
          username,
          reason: 'invalid_credentials',
        });

        res.status(401).json({ error: 'Invalid credentials' });
      }
    } catch (err) {
      logger.error({ event: 'login_error', error: err.message });
      res.status(500).json({ error: 'Login failed' });
    }
  }
);

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    path: req.path,
    method: req.method,
  });
});

/**
 * Global Error Handler
 * Must be defined last
 */
app.use((err, req, res, next) => {
  logger.error({
    event: 'unhandled_error',
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't expose stack traces in production
  const isDevelopment = NODE_ENV === 'development';
  const statusCode = err.statusCode || 500;
  const message = isDevelopment ? err.message : 'Internal server error';

  res.status(statusCode).json({
    error: message,
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const startServer = () => {
  if (NODE_ENV === 'production') {
    // Use HTTPS in production
    const options = {
      key: fs.readFileSync(process.env.SSL_KEY_PATH || 'path/to/key.pem'),
      cert: fs.readFileSync(process.env.SSL_CERT_PATH || 'path/to/cert.pem'),
    };
    https.createServer(options, app).listen(PORT, () => {
      logger.info(`Secure HTTPS server running on port ${PORT}`);
    });
  } else {
    // Use HTTP in development
    app.listen(PORT, () => {
      logger.info(`Development server running on port ${PORT}`);
    });
  }
};

// Handle graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  process.exit(0);
});

startServer();

module.exports = app;

