## 3. COMMAND INJECTION

VULNERABLE CODE:
```javascript
const { exec } = require('child_process');

app.post('/convert', (req, res) => {
  const filename = req.body.filename;
  // DANGER: User input in shell command
  exec(`convert ${filename} output.png`, (err, stdout) => {
    res.json({ result: stdout });
  });
});
```

ATTACK EXAMPLE:
POST /convert
{ "filename": "image.jpg; rm -rf /" }

SECURE FIX:
```javascript
const { execFile } = require('child_process');

app.post('/convert', (req, res) => {
  const filename = req.body.filename;
  // Use execFile with arguments array (no shell interpretation)
  execFile('convert', [filename, 'output.png'], (err, stdout) => {
    if (err) res.status(500).json({ error: 'Conversion failed' });
    res.json({ result: stdout });
  });
});
```

