## 4. BROKEN AUTHENTICATION

VULNERABLE CODE:
```javascript
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  // DANGER: No password hashing, storing plaintext
  const user = db.query(`SELECT * FROM users WHERE username='${username}' AND password='${password}'`);
  if (user) {
    // DANGER: Storing user ID in plain session
    res.cookie('userId', user.id);
    res.json({ success: true });
  }
});
```

SECURITY ISSUES:
- Plaintext passwords stored
- No rate limiting on login attempts
- Weak session storage
- SQL injection vulnerability

SECURE FIX:
```javascript
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

app.post('/login', loginLimiter,
  body('username').trim().isLength({ min: 1, max: 100 }),
  body('password').isLength({ min: 8 }),
  (req, res) => {
    const { username, password } = req.body;

    // Query with parameterization
    const user = db.query('SELECT * FROM users WHERE username = ?', [username]);

    if (user && bcrypt.compareSync(password, user.passwordHash)) {
      // Use JWT instead of simple cookies
      const token = jwt.sign(
        { userId: user.id, role: user.role },
        process.env.JWT_SECRET,
        { expiresIn: '1h', algorithm: 'HS256' }
      );

      res.json({ token, expiresIn: '1h' });
    } else {
      res.status(401).json({ error: 'Invalid credentials' });
    }
  }
);
```

