## 5. INSECURE DIRECT OBJECT REFERENCES (IDOR)

VULNERABLE CODE:
```javascript
app.get('/users/:id', authenticateToken, (req, res) => {
  const userId = req.params.id;
  // DANGER: No authorization check, any authenticated user can view anyone
  const user = db.query('SELECT * FROM users WHERE id = ?', [userId]);
  res.json(user);
});
```

ATTACK EXAMPLE:
- Login as user with ID 1
- Access GET /users/2 to view user 2's data

SECURE FIX:
```javascript
app.get('/users/:id', authenticateToken, (req, res) => {
  const userId = req.params.id;

  // Option 1: Only allow users to view their own profile
  if (req.user.id !== parseInt(userId)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const user = db.query('SELECT * FROM users WHERE id = ?', [userId]);
  res.json(user);
});

// Option 2: Use role-based authorization
const authorize = (...roles) => (req, res, next) => {
  if (!roles.includes(req.user.role)) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  next();
};

app.get('/admin/users/:id', authenticateToken, authorize('admin'), (req, res) => {
  const userId = req.params.id;
  const user = db.query('SELECT * FROM users WHERE id = ?', [userId]);
  res.json(user);
});
```

