## 6. SENSITIVE DATA EXPOSURE

VULNERABLE CODE:
```javascript
app.get('/users', (req, res) => {
  // DANGER: No HTTPS, all data in plaintext
  // DANGER: Exposing sensitive user information
  const users = db.query('SELECT * FROM users');
  res.json(users); // Returns passwords, emails, etc.
});
```

SECURE FIX:
```javascript
const https = require('https');
const fs = require('fs');

// Enable HTTPS
const options = {
  key: fs.readFileSync('key.pem'),
  cert: fs.readFileSync('cert.pem'),
};

https.createServer(options, app).listen(3000);

// Only return necessary fields
app.get('/users', authenticateToken, authorize('admin'), (req, res) => {
  const users = db.query('SELECT id, name, email FROM users');

  // Further sanitize
  const sanitized = users.map(u => ({
    id: u.id,
    name: u.name,
    // email should only be visible to admins
  }));

  res.json(sanitized);
});

// Set security headers
app.use(helmet());
app.use((req, res, next) => {
  res.setHeader('Strict-Transport-Security', 'max-age=31536000');
  next();
});
```

