## 10. XXE INJECTION

VULNERABLE CODE:
```javascript
const xml2js = require('xml2js');

app.post('/xml', (req, res) => {
  const xmlData = req.body;
  // DANGER: XXE attacks possible
  xml2js.parseString(xmlData, (err, result) => {
    res.json(result);
  });
});
```

SECURE FIX:
```javascript
const xml2js = require('xml2js');

app.post('/xml', (req, res) => {
  const xmlData = req.body;

  const parser = new xml2js.Parser({
    // Disable external entity processing
    strict: true,
    resolveNonAbsoluteURL: false,
    // DTD processing disabled
    dtdHandler: false,
  });

  parser.parseString(xmlData, (err, result) => {
    if (err) {
      return res.status(400).json({ error: 'Invalid XML' });
    }
    res.json(result);
  });
});
```

---

## 11. BRUTE FORCE ATTACKS

VULNERABLE CODE:
```javascript
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  // DANGER: No rate limiting, unlimited login attempts
  const user = authenticateUser(username, password);
  res.json(user);
});
```

SECURE FIX:
```javascript
const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true, // Don't count successful logins
  keyGenerator: (req, res) => {
    // Rate limit by username AND IP
    return `${req.body.username}:${req.ip}`;
  },
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many login attempts, try again later' });
  },
});

app.post('/login', loginLimiter, (req, res) => {
  const { username, password } = req.body;
  const user = authenticateUser(username, password);
  res.json(user);
});
```

---

## 12. MISCONFIGURED SECURITY HEADERS

VULNERABLE CODE:
```javascript
app.use(express.json());
// DANGER: No security headers
app.get('/', (req, res) => {
  res.send('Hello');
});
```

SECURE FIX:
```javascript
const helmet = require('helmet');

app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));

app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});
```

---

## Best Practices Summary

1. ALWAYS validate and sanitize user input
2. Use parameterized queries for database operations
3. Implement authentication and authorization
4. Use HTTPS/TLS only
5. Never store sensitive data in plaintext
6. Implement rate limiting
7. Use security headers (Helmet.js)
8. Log security events
9. Handle errors gracefully (no stack trace leaks)
10. Keep dependencies updated and scan for vulnerabilities

