 * Retrieve secrets from AWS Secrets Manager
 * Called once at startup
 */
async function loadSecrets() {
  try {
    logger.info('Loading secrets from AWS Secrets Manager');

    const secretName = process.env.SECRET_NAME || 'prod/app/secrets';

    const data = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    let secrets;
    if ('SecretString' in data) {
      secrets = JSON.parse(data.SecretString);
    } else {
      // Binary secrets (e.g., SSL certificates)
      const buff = Buffer.from(data.SecretBinary, 'base64');
      secrets = JSON.parse(buff.toString('ascii'));
    }

    logger.info('Secrets loaded successfully', { 
      secretKeys: Object.keys(secrets) 
    });

    return secrets;
  } catch (err) {
    logger.error('Failed to load secrets from AWS', { 
      error: err.message,
      secretName: process.env.SECRET_NAME 
    });
    throw new Error('Cannot start application without secrets');
  }
}

