  const required = [
    'JWT_SECRET',
    'DB_PASSWORD',
    'DB_USER',
    'ENCRYPTION_KEY'
  ];

  const missing = required.filter(key => !secrets[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }

  logger.info('All required secrets validated');
}

/**
 * Refresh secrets periodically (every 24 hours by default)
 */
async function scheduleSecretRefresh(intervalMs = 24 * 60 * 60 * 1000) {
  setInterval(async () => {
    try {
      logger.info('Refreshing secrets from AWS Secrets Manager');
      appSecrets = await loadSecrets();
      validateSecrets(appSecrets);
      logger.info('Secrets refreshed successfully');
    } catch (err) {
