#!/usr/bin/env node

/**
 * SECURE SECRET ROTATION SCRIPT
 * 
 * This script rotates secrets WITHOUT viewing or displaying them.
 * All operations happen server-side in Secrets Manager.
 */

const AWS = require('aws-sdk');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

// Logger that never logs actual secret values
const logger = {
  info: (msg, data = {}) => console.log(`[INFO] ${msg}`, sanitize(data)),
  warn: (msg, data = {}) => console.warn(`[WARN] ${msg}`, sanitize(data)),
  error: (msg, data = {}) => console.error(`[ERROR] ${msg}`, sanitize(data)),
};

/**
 * Remove sensitive data before logging
 */
function sanitize(data) {
  if (typeof data !== 'object') return data;
  const cleaned = { ...data };
  Object.keys(cleaned).forEach(key => {
    if (key.includes('secret') || key.includes('password') || key.includes('key')) {
      cleaned[key] = '[REDACTED]';
    }
  });
  return cleaned;
}

/**
 * Generate new secret without viewing it
 * Returns only the secret ID, not the value
 */
async function generateNewSecret(secretName, secretType = 'password') {
  try {
    logger.info(`Generating new secret for: ${secretName}`);

    let newSecretValue;

    switch (secretType) {
      case 'password':
        // Generate cryptographically secure password
        newSecretValue = crypto.randomBytes(32).toString('base64');
        break;
      case 'api-key':
        // Generate API key format
        newSecretValue = crypto.randomBytes(24).toString('hex');
        break;
      case 'token':
        // Generate token
        newSecretValue = crypto.randomBytes(32).toString('base64');
        break;
      default:
        newSecretValue = crypto.randomBytes(32).toString('base64');
    }

    // Create new version in Secrets Manager
    const result = await secretsManager.putSecretValue({
      SecretId: secretName,
      SecretString: newSecretValue,
      Description: `Auto-rotated on ${new Date().toISOString()}`
    }).promise();

    logger.info(`New secret version created (not displayed for security)`);
    logger.info(`Secret ID: ${secretName}`);
    logger.info(`Version ID: ${result.VersionId}`);

    return result.VersionId; // Return ID only, not value
  } catch (err) {
    logger.error(`Failed to generate new secret`, { 
      error: err.message,
      secretName 
    });
    throw err;
  }
}

/**
 * Verify new secret works WITHOUT viewing it
 */
async function verifyNewSecret(secretName) {
  try {
    logger.info(`Verifying new secret for: ${secretName}`);

    // Get metadata only, not the value
    const metadata = await secretsManager.describeSecret({
      SecretId: secretName
    }).promise();

    const latestVersion = metadata.VersionIdsToStages[Object.keys(metadata.VersionIdsToStages)[0]];

    if (latestVersion.includes('AWSCURRENT')) {
      logger.info(`✓ New secret is set as AWSCURRENT`);
      return true;
    }

    logger.warn(`Secret is not yet marked as AWSCURRENT`);
    return false;
  } catch (err) {
    logger.error(`Failed to verify secret`, { error: err.message });
    throw err;
  }
}

/**
 * Clean up old secret versions
 */
async function cleanupOldVersions(secretName, keepVersions = 3) {
  try {
    logger.info(`Cleaning up old versions of: ${secretName} (keeping ${keepVersions})`);

    const metadata = await secretsManager.describeSecret({
      SecretId: secretName
    }).promise();

    const versions = Object.keys(metadata.VersionIdsToStages);

    if (versions.length <= keepVersions) {
      logger.info(`Only ${versions.length} versions exist, cleanup not needed`);
      return;
    }

    const versionsToDelete = versions.slice(keepVersions);

    logger.info(`Preparing to delete ${versionsToDelete.length} old versions`);

    for (const versionId of versionsToDelete) {
      await secretsManager.updateSecretVersionStage({
        SecretId: secretName,
        VersionStage: 'DEPRECATED',
        MoveToVersionId: versionId,
        RemoveFromVersionId: Object.keys(metadata.VersionIdsToStages).find(
          v => metadata.VersionIdsToStages[v].includes('DEPRECATED')
        ) || undefined
      }).promise();
    }

    logger.info(`✓ Old versions cleaned up`);
  } catch (err) {
    logger.error(`Failed to cleanup old versions`, { error: err.message });
    throw err;
  }
}

/**
 * Rotate a single secret
 */
async function rotateSecret(secretName, secretType = 'password') {
  try {
    logger.info(`\n=== Starting rotation for: ${secretName} ===`);

    // Step 1: Generate new secret
    const versionId = await generateNewSecret(secretName, secretType);

    // Step 2: Verify (without viewing)
    const verified = await verifyNewSecret(secretName);
    if (!verified) {
      throw new Error('Secret verification failed');
    }

    // Step 3: Cleanup old versions
    await cleanupOldVersions(secretName);

    logger.info(`✓ Rotation complete for: ${secretName}`);
    return {
      secretName,
      versionId,
      timestamp: new Date().toISOString(),
      status: 'success'
    };
  } catch (err) {
    logger.error(`✗ Rotation failed for: ${secretName}`, { error: err.message });
    return {
      secretName,
      timestamp: new Date().toISOString(),
      status: 'failed',
      error: err.message
    };
  }
}

/**
 * Rotate all secrets in batch
 */
async function rotateAllSecrets(secretsList) {
  const results = [];

  for (const secret of secretsList) {
    const result = await rotateSecret(secret.name, secret.type);
    results.push(result);

    // Small delay between rotations
    await new Promise(resolve => setTimeout(resolve, 1000));
  }

  return results;
}

/**
 * Generate rotation report WITHOUT displaying values
 */
async function generateRotationReport(results) {
  const report = {
    timestamp: new Date().toISOString(),
    totalSecrets: results.length,
    successful: results.filter(r => r.status === 'success').length,
    failed: results.filter(r => r.status === 'failed').length,
    details: results.map(r => ({
      secretName: r.secretName,
      status: r.status,
      timestamp: r.timestamp,
      versionId: r.versionId, // ID only, not value
      ...(r.error && { error: r.error })
    }))
  };

  // Save report
  const reportPath = path.join(process.cwd(), `rotation-report-${Date.now()}.json`);
  fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));

  logger.info(`\n=== ROTATION REPORT ===`);
  logger.info(`Total Secrets: ${report.totalSecrets}`);
  logger.info(`Successful: ${report.successful}`);
  logger.info(`Failed: ${report.failed}`);
  logger.info(`Report saved to: ${reportPath}`);

  return report;
}

/**
 * Main execution
 */
async function main() {
  try {
    logger.info('Starting secure secret rotation process\n');

    // Define secrets to rotate
    const secretsList = [
      { name: 'prod/jwt-secret', type: 'token' },
      { name: 'prod/db-password', type: 'password' },
      { name: 'prod/encryption-key', type: 'token' },
      { name: 'prod/smtp-password', type: 'password' },
    ];

    // Rotate all secrets
    const results = await rotateAllSecrets(secretsList);

    // Generate report
    await generateRotationReport(results);

    logger.info('\n✓ Secret rotation process complete');

  } catch (err) {
    logger.error('Fatal error during rotation', { error: err.message });
    process.exit(1);
  }
}

// Run if called directly
if (require.main === module) {
  main().catch(err => {
    logger.error('Unhandled error', { error: err.message });
    process.exit(1);
  });
}

module.exports = {
  generateNewSecret,
  verifyNewSecret,
  cleanupOldVersions,
  rotateSecret,
  rotateAllSecrets,
  generateRotationReport
};

