# Quick Fix Guide - Apply Fixes in Minutes

If you want to quickly add security to your existing app.js, follow this progressive approach.

---

## Step 1: Install Core Dependencies (2 minutes)

```bash
npm install helmet cors express-rate-limit express-validator jsonwebtoken morgan
```

---

## Step 2: Add Security Headers & Middleware (5 minutes)

Replace your app.js content with this minimal secure version:

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Security headers
app.use(helmet());

// CORS - restrict to your domain
app.use(cors({
  origin: ['http://localhost:3000'],
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Request size limits
app.use(express.json({ limit: '10mb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);

// Public endpoint (stays same)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected endpoint
app.get('/users', (req, res) => {
  // For now, add a simple check
  const auth = req.headers.authorization;
  if (!auth) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => console.log('Server on port 3000'));
module.exports = app;
```

**Security improvement:** ✅ Headers, CORS, Rate limiting, Auth check

---

## Step 3: Add JWT Authentication (5 minutes)

Add this to your app:

```javascript
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET || 'secret-key';

// Auth middleware
const auth = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Token required' });

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

// Login endpoint
app.post('/login', express.json(), (req, res) => {
  const { username, password } = req.body;

  // TODO: Verify against database with bcrypt
  if (username === 'alice' && password === 'pass123') {
    const token = jwt.sign({ id: 1, username }, JWT_SECRET, { expiresIn: '1h' });
    return res.json({ token });
  }

  res.status(401).json({ error: 'Invalid credentials' });
});

// Use auth middleware on protected routes
app.get('/users', auth, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Security improvement:** ✅ JWT authentication with expiration

---

## Step 4: Add Input Validation (5 minutes)

```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  auth,
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),

  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);
```

**Security improvement:** ✅ Input validation prevents injection attacks

---

## Step 5: Add Logging (5 minutes)

```javascript
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Create logs directory
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) fs.mkdirSync(logsDir);

// HTTP logging
const accessLogStream = fs.createWriteStream(path.join(logsDir, 'access.log'), { flags: 'a' });
app.use(morgan('combined', { stream: accessLogStream }));

// Error handler
app.use((err, req, res, next) => {
  console.error(err.message);
  res.status(500).json({ error: 'Internal server error' });
});
```

**Security improvement:** ✅ Audit trail for security incidents

---

## Step 6: Add Stricter Rate Limiting for Auth (2 minutes)

```javascript
// Stricter limit for login attempts
const loginLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

app.post('/login', loginLimiter, express.json(), (req, res) => {
  // ... existing login logic
});
```

**Security improvement:** ✅ Prevents brute-force attacks

---

## Step 7: Environment Variables (2 minutes)

Create `.env` file:
```
NODE_ENV=production
JWT_SECRET=your-random-secret-key-here-change-this
ALLOWED_ORIGINS=http://localhost:3000,http://app.example.com
PORT=3000
```

Update app.js to use them:
```javascript
require('dotenv').config();

const JWT_SECRET = process.env.JWT_SECRET;
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

app.use(cors({ origin: ALLOWED_ORIGINS }));
```

**Security improvement:** ✅ Secrets not hardcoded

---

## Testing Your Fixes

### Test 1: Security Headers
```bash
curl -v http://localhost:3000/health | grep -i "x-frame-options\|x-content-type\|strict-transport"
# Should see headers
```

### Test 2: Authentication Required
```bash
curl http://localhost:3000/users
# Should get: {"error":"Token required"} (401)

# Get token
TOKEN=$(curl -s -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"username":"alice","password":"pass123"}' | jq -r '.token')

# Use token
curl -H "Authorization: Bearer $TOKEN" http://localhost:3000/users
# Should get user data
```

### Test 3: Rate Limiting
```bash
# Try 150 requests rapidly
for i in {1..150}; do curl http://localhost:3000/health &>/dev/null && echo $i || break; done
# After ~100, should get rate limit errors
```

### Test 4: Input Validation
```bash
TOKEN=$(curl -s -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"username":"alice","password":"pass123"}' | jq -r '.token')

# Invalid limit
curl -H "Authorization: Bearer $TOKEN" "http://localhost:3000/users?limit=9999"
# Should get validation error (400)
```

### Test 5: Logging
```bash
cat logs/access.log
# Should see HTTP requests logged with timestamps
```

---

## Next Steps (Advanced)

After these quick fixes:

1. **Add HTTPS** - Generate certificates and enable TLS
2. **Add Password Hashing** - Install `bcrypt`, hash passwords
3. **Add Database** - Connect to PostgreSQL/MongoDB with parameterized queries
4. **Add 2FA** - Two-factor authentication for sensitive accounts
5. **Add Monitoring** - Sentry for error tracking
6. **Add CSRF Protection** - For form-based applications

---

## Summary of Improvements

| Issue | Fix | Time | Impact |
|-------|-----|------|--------|
| No security headers | Helmet | 1 min | Prevents XSS, clickjacking |
| No auth | JWT | 3 min | Prevents unauthorized access |
| No validation | express-validator | 2 min | Prevents injection attacks |
| No rate limit | express-rate-limit | 1 min | Prevents brute-force, DoS |
| No CORS config | cors | 1 min | Prevents data exfiltration |
| No logging | morgan | 2 min | Security audit trail |
| No env secrets | dotenv | 1 min | Prevents secret leaks |

**Total implementation time: ~25 minutes**

