cat > BEFORE_AFTER_COMPARISON.md << 'EOF'
# Before & After Security Comparison

## Visual Comparison

### BEFORE (Insecure)
```javascript
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

**Issues:**
- ❌ No security headers
- ❌ No authentication
- ❌ No input validation
- ❌ No rate limiting
- ❌ No CORS configuration
- ❌ No request size limits
- ❌ No logging
- ❌ No HTTPS enforcement

---

### AFTER (Secure)
```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

const JWT_SECRET = process.env.JWT_SECRET || 'change-this';
const app = express();

// Security headers
app.use(helmet());

// CORS - whitelist origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Request limits
app.use(express.json({ limit: '10mb' }));

// Rate limiting
const limiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 100 });
const loginLimiter = rateLimit({ windowMs: 60 * 1000, max: 5 });
app.use(limiter);

// Logging
const accessLogStream = fs.createWriteStream(path.join(__dirname, 'logs', 'access.log'), { flags: 'a' });
app.use(morgan('combined', { stream: accessLogStream }));

// Auth middleware
const auth = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Token required' });
  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

// Login endpoint
app.post('/login', loginLimiter, express.json(), (req, res) => {
  const { username, password } = req.body;
  if (username === 'alice' && password === 'pass123') {
    const token = jwt.sign({ id: 1, username }, JWT_SECRET, { expiresIn: '1h' });
    return res.json({ token });
  }
  res.status(401).json({ error: 'Invalid credentials' });
});

// Public endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected endpoint with validation
app.get('/users',
  auth,
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// Error handling
app.use((err, req, res, next) => {
  res.status(500).json({ error: 'Internal server error' });
});

app.listen(3000, () => console.log('Secure server on port 3000'));
module.exports = app;
```

**Improvements:**
- ✅ Security headers with Helmet
- ✅ JWT authentication
- ✅ Input validation
- ✅ Rate limiting (general + login)
- ✅ CORS whitelist
- ✅ Request size limits
- ✅ HTTP request logging
- ✅ HTTPS redirect support
- ✅ Error handling

---

## Feature Comparison Table

| Feature | Before | After | Impact |
|---------|--------|-------|--------|
| **Security Headers** | ❌ None | ✅ Helmet | Prevents XSS, clickjacking, MIME sniffing |
| **Authentication** | ❌ None | ✅ JWT (1h expiry) | Prevents unauthorized access |
| **Input Validation** | ❌ None | ✅ express-validator | Prevents injection attacks |
| **Rate Limiting** | ❌ Unlimited | ✅ 100/15min, 5/min login | Prevents brute-force, DoS |
| **CORS** | ❌ Open | ✅ Whitelist | Prevents data theft from 3rd-party sites |
| **Request Limits** | ❌ Unbounded | ✅ 10MB | Prevents memory exhaustion |
| **Logging** | ❌ None | ✅ Morgan + custom | Security audit trail |
| **HTTPS** | ❌ HTTP only | ✅ Redirect support | Encrypts data in transit |
| **Error Handling** | ❌ Exposes details | ✅ Generic messages | Prevents info disclosure |
| **Suspicious Request Detection** | ❌ None | ✅ Path traversal, SQL injection | Detects attacks |

---

## Request/Response Examples

### GET /users - BEFORE (Insecure)
```bash
# No authentication required - anyone can access
curl http://localhost:3000/users

# Response: 200 OK
[
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' }
]

# Headers
HTTP/1.1 200 OK
Content-Type: application/json
# ❌ No security headers present
```

### GET /users - AFTER (Secure)
```bash
# Without token - REJECTED
curl http://localhost:3000/users

# Response: 401 Unauthorized
{ "error": "Token required" }

# With token - Validated and returned
curl -H "Authorization: Bearer eyJhbGc..." \
  http://localhost:3000/users?limit=10&offset=0

