const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Configuration from environment variables
const JWT_SECRET = process.env.JWT_SECRET || 'change-this-secret-in-production';
const NODE_ENV = process.env.NODE_ENV || 'development';
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];

const app = express();

// ============================================================================
// 1. SECURITY HEADERS MIDDLEWARE
// ============================================================================
app.use(helmet());

// ============================================================================
// 2. CORS CONFIGURATION
// ============================================================================
const corsOptions = {
  origin: ALLOWED_ORIGINS,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: false,
  maxAge: 86400,
};
app.use(cors(corsOptions));

// ============================================================================
// 3. REQUEST SIZE LIMITING
// ============================================================================
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// ============================================================================
// 4. LOGGING/MONITORING
// ============================================================================
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir);
}

const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);

morgan.token('user-id', (req) => req.user?.id || 'anonymous');
app.use(morgan(':remote-addr - :user-id [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] - :response-time ms', {
  stream: accessLogStream,
}));

// Custom logger
const logger = {
  info: (msg) => console.log(`[INFO] ${new Date().toISOString()} - ${msg}`),
  warn: (msg) => console.warn(`[WARN] ${new Date().toISOString()} - ${msg}`),
  error: (msg) => console.error(`[ERROR] ${new Date().toISOString()} - ${msg}`),
};

// ============================================================================
// 5. RATE LIMITING
// ============================================================================
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLoginLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later.',
});

app.use(generalLimiter);

// ============================================================================
// 6. AUTHENTICATION MIDDLEWARE
// ============================================================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`Unauthorized access attempt to ${req.path} from ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid token attempt from ${req.ip}: ${err.message}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// 7. SECURITY MIDDLEWARE - DETECT SUSPICIOUS REQUESTS
// ============================================================================
app.use((req, res, next) => {
  // Detect path traversal attempts
  if (req.path.includes('../') || req.path.includes('..\\') || req.path.includes('..%')) {
    logger.warn(`Path traversal attempt: ${req.path} from ${req.ip}`);
    return res.status(400).json({ error: 'Invalid request' });
  }

  // Detect SQL injection patterns in query string
  const suspiciousPatterns = /(union|select|insert|update|delete|drop|exec|execute|script|javascript|onerror|onclick)/i;
  if (suspiciousPatterns.test(JSON.stringify(req.query))) {
    logger.warn(`Potential SQL injection attempt: ${req.url} from ${req.ip}`);
    return res.status(400).json({ error: 'Invalid request' });
  }

  next();
});

