 * GET /users?limit=10&offset=0&filter=alice
 */
app.get('/users',
  authenticateToken,
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be 0 or greater'),
  query('filter')
    .optional()
    .trim()
    .isLength({ min: 1, max: 50 })
    .withMessage('Filter must be between 1 and 50 characters'),

  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn(`Validation error: ${JSON.stringify(errors.array())}`);
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array(),
      });
    }

    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;
    const filter = req.query.filter?.toLowerCase() || '';

    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply filter if provided
    if (filter) {
      users = users.filter(u =>
        u.name.toLowerCase().includes(filter) ||
        u.email.toLowerCase().includes(filter)
      );
    }

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    logger.info(`User list accessed by user ${req.user.id} (${limit} limit, ${offset} offset)`);

    res.json({
      data: paginatedUsers,
      total: users.length,
      limit,
      offset,
    });
  }
);

/**
 * Get single user - protected endpoint
 * GET /users/:id
 */
app.get('/users/:id', authenticateToken, (req, res) => {
  const userId = parseInt(req.params.id);

  if (isNaN(userId) || userId < 1) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  // TODO: Fetch from database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  logger.info(`User ${userId} accessed by user ${req.user.id}`);
  res.json(user);
});

// ============================================================================
// 9. ERROR HANDLING MIDDLEWARE
// ============================================================================
app.use((err, req, res, next) => {
  logger.error(`Unhandled error: ${err.message}`);

  res.status(500).json({
    error: 'Internal server error',
    // Don't expose internal error details in production
    ...(NODE_ENV !== 'production' && { message: err.message }),
  });
});

// ============================================================================
// 10. 404 HANDLER
// ============================================================================
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

// ============================================================================
// 11. HTTPS REDIRECT (if behind proxy in production)
// ============================================================================
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  }

