## Secrets Manager Implementation

### Option 1: AWS Secrets Manager (Recommended)
```javascript
const AWS = require('aws-sdk');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 60 * 60 * 1000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const result = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      const secretValue = JSON.parse(result.SecretString);

      // Cache with TTL
      this.cache.set(secretName, {
        value: secretValue,
        expiresAt: Date.now() + this.cacheTTL
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve ${secretName}:`, error.message);
      throw new Error(`Unable to load required secret: ${secretName}`);
    }
  }

  async rotateSecret(secretName) {
    // Only admin can trigger
    try {
      const result = await this.client.rotateSecret({
        SecretId: secretName,
        RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN
      }).promise();

      console.log(`Rotation started for ${secretName}: ${result.RotationId}`);

      // Clear cache to force reload
      this.cache.delete(secretName);

      return result;
    } catch (error) {
      console.error(`Rotation failed for ${secretName}:`, error.message);
      throw error;
    }
  }
}

module.exports = SecretsManager;
```

