/**
 * SECURE APP.JS - Production-Ready Implementation
 * This file demonstrates all security best practices applied
 */

require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const winston = require('winston');

// ==================== LOGGER SETUP ====================
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ==================== EXPRESS APP SETUP ====================
const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Helmet - Set security headers
app.use(helmet());

// 2. Custom security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});

// 3. CORS - Strict origin policy
const corsOptions = {
  origin: (origin, callback) => {
    const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400,
};

app.use(cors(corsOptions));

// 4. Rate limiting - General
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => process.env.NODE_ENV === 'development', // Skip rate limiting in development
});

app.use(limiter);

// 5. Rate limiting - Strict for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many login attempts, please try again later',
  skipSuccessfulRequests: true, // Don't count successful requests
});

// 6. HTTP request logging with Morgan
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim()),
  },
}));

// 7. Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ==================== AUTHENTICATION MIDDLEWARE ====================

/**
 * Authentication middleware - Validates JWT token
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn('Access attempt without token', { ip: req.ip, path: req.path });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'dev-secret', (err, user) => {
    if (err) {
      logger.warn('Invalid token attempt', { ip: req.ip, error: err.message });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    req.user = user;
    next();
  });
};

// ==================== INPUT VALIDATION ====================

/**
 * Validation middleware for /users endpoint
 */
const validateUserQuery = [
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('name').optional().trim().isLength({ min: 1, max: 100 }).escape(),
  query('email').optional().isEmail().normalizeEmail(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
];

/**
 * Middleware to handle validation results
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation errors', { errors: errors.array(), ip: req.ip });
    return res.status(400).json({ 
      error: 'Invalid input parameters',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ==================== ROUTES ====================

/**
 * Health check endpoint - Public
 * No authentication required for monitoring purposes
 * Rate limited but generous limits
 */
app.get('/health', (req, res) => {
  logger.debug('Health check');
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

/**
 * Users endpoint - Protected
 * Requires JWT authentication
 * Includes input validation
 */
app.get('/users', 
  authenticateToken, 
  validateUserQuery, 
  handleValidationErrors,
  (req, res) => {
    logger.info('Users endpoint accessed', { user: req.user.id });

    const { id, name, limit = 10 } = req.query;

    // Mock database query (in real app, would query DB)
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Filter by ID if provided
    if (id) {
      users = users.filter(u => u.id === id);
      if (users.length === 0) {
        return res.status(404).json({ error: 'User not found' });
      }
    }

    // Filter by name if provided
    if (name) {
      users = users.filter(u => u.name.toLowerCase().includes(name.toLowerCase()));
    }

    // Apply limit
    users = users.slice(0, limit);

    // Log successful request (without sensitive data)
    logger.debug('Users retrieved successfully', { count: users.length });

    res.json({
      data: users,
      count: users.length,
      timestamp: new Date().toISOString(),
    });
  }
);

/**
 * Mock login endpoint
 * In real app, would verify credentials against database
 */
app.post('/login', authLimiter, express.json(), (req, res) => {
  const { username, password } = req.body;

  // Input validation
  if (!username || !password) {
    logger.warn('Login attempt with missing credentials', { ip: req.ip });
    return res.status(400).json({ error: 'Username and password required' });
  }

  if (username.length > 100 || password.length > 100) {
    logger.warn('Login attempt with invalid input length', { ip: req.ip });
    return res.status(400).json({ error: 'Invalid credentials' });
  }

  // Mock user authentication (never log passwords!)
  logger.info('Login attempt', { username, ip: req.ip });

  if (username === 'admin' && password === 'secret123') {
    // In production, hash passwords with bcrypt!
    const token = jwt.sign(
      { id: 1, username: 'admin', role: 'admin' },
      process.env.JWT_SECRET || 'dev-secret',
      { expiresIn: '1h' }
    );

    logger.info('Successful login', { username });
    return res.json({ token, expiresIn: '1h' });
  }

  logger.warn('Failed login', { username, ip: req.ip });
  res.status(401).json({ error: 'Invalid credentials' });
});

// ==================== ERROR HANDLING ====================

/**
 * CORS error handler
 */
app.use((err, req, res, next) => {
  if (err.message === 'Not allowed by CORS') {
    logger.warn('CORS error', { origin: req.headers.origin, ip: req.ip });
    return res.status(403).json({ error: 'CORS policy violation' });
  }
  next(err);
});

/**
 * 404 handler
 */
app.use((req, res) => {
  logger.warn('404 - Route not found', { path: req.path, method: req.method });
  res.status(404).json({ error: 'Not found' });
});

/**
 * Global error handler - MUST be last
 */
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Don't expose stack traces in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info(`Server started`, {
    port: PORT,
    environment: NODE_ENV,
    timestamp: new Date().toISOString(),
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

