## Implementation Guide for Key Security Features

### Secure Password Hashing with Bcrypt

```javascript
const bcrypt = require('bcryptjs');

// Register/Create password
async function registerUser(username, password) {
  // Validate password strength first
  if (!isStrongPassword(password)) {
    throw new Error('Password does not meet security requirements');
  }

  const saltRounds = 12; // Higher = slower, safer
  const hashedPassword = await bcrypt.hash(password, saltRounds);

  // Store hashedPassword in database, never plain password
  await db.users.create({ username, password: hashedPassword });
}

// Verify password
async function authenticateUser(username, password) {
  const user = await db.users.findOne({ username });

  if (!user) {
    // Don't reveal if user exists
    throw new Error('Invalid credentials');
  }

  const isValid = await bcrypt.compare(password, user.password);

  if (!isValid) {
    throw new Error('Invalid credentials');
  }

  return user;
}

// Password strength validation
function isStrongPassword(password) {
  const regex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{12,}$/;
  return regex.test(password);
}
```

### Secure JWT Token Management

```javascript
const jwt = require('jsonwebtoken');

// Generate tokens with separate access and refresh tokens
function generateTokens(userId) {
  const accessToken = jwt.sign(
    { userId, type: 'access' },
    process.env.JWT_ACCESS_SECRET,
    { expiresIn: '15m' } // Short-lived
  );

  const refreshToken = jwt.sign(
    { userId, type: 'refresh' },
    process.env.JWT_REFRESH_SECRET,
    { expiresIn: '7d' } // Long-lived, stored securely
  );

  return { accessToken, refreshToken };
}

// Verify and refresh access token
function refreshAccessToken(refreshToken) {
  try {
    const decoded = jwt.verify(refreshToken, process.env.JWT_REFRESH_SECRET);

    if (decoded.type !== 'refresh') {
      throw new Error('Invalid token type');
    }

    return jwt.sign(
      { userId: decoded.userId, type: 'access' },
      process.env.JWT_ACCESS_SECRET,
      { expiresIn: '15m' }
    );
  } catch (err) {
    throw new Error('Invalid or expired refresh token');
  }
}
```

### SQL Injection Prevention

```javascript
// ❌ VULNERABLE - Never do this
const username = req.query.username;
const query = `SELECT * FROM users WHERE username = '${username}'`;

// ✅ SECURE - Use parameterized queries
const username = req.query.username;
const query = 'SELECT * FROM users WHERE username = $1';
const result = await db.query(query, [username]);

// For MongoDB with Mongoose
const user = await User.findOne({ username: sanitizeInput(username) });

// For multiple parameters
const query = 'SELECT * FROM users WHERE username = $1 AND email = $2';
const result = await db.query(query, [username, email]);
```

### XSS Prevention

```javascript
// ❌ VULNERABLE
res.json({ message: userInput });

// ✅ SECURE - Express validator escapes output
const { query, validationResult } = require('express-validator');

app.get('/search', query('q').trim().escape(), (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const safeQuery = req.query.q; // Already escaped
  res.json({ results: searchDatabase(safeQuery) });
});

// For HTML content, use DOMPurify or similar
const DOMPurify = require('isomorphic-dompurify');
const cleanHTML = DOMPurify.sanitize(userProvidedHTML);
```

### CSRF Protection

```javascript
const csrf = require('csurf');
const cookieParser = require('cookie-parser');

const csrfProtection = csrf({ cookie: false }); // Using session-based tokens

app.use(cookieParser());
app.use(csrf({ cookie: false }));

// Add CSRF token to forms
app.get('/form', csrfProtection, (req, res) => {
  res.json({ csrfToken: req.csrfToken() });
});

// Verify CSRF token on form submission
app.post('/submit', csrfProtection, (req, res) => {
  // CSRF token already validated by middleware
  res.json({ message: 'Form submitted successfully' });
});
```

### SQL Injection Detection & Prevention

```javascript
// Use parameterized queries and prepared statements
const pg = require('pg');
const client = new pg.Client();

// ✅ SAFE - Parameters are separated from query
const getUserById = async (userId) => {
  const query = 'SELECT * FROM users WHERE id = $1';
  const result = await client.query(query, [userId]);
  return result.rows[0];
};

// For ORMs like Sequelize
const user = await User.findByPk(userId);
const users = await User.findAll({
  where: { email: userEmail }
});

// Input validation as additional layer
const { query } = require('express-validator');

app.get('/user/:id',
  query('id').isInt().toInt(), // Ensure it's an integer
  (req, res) => {
    // Safe to use
    const userId = req.query.id;
    // ... fetch from database
  }
);
```

### Security Logging Best Practices

```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// ✅ GOOD - Log security events
logger.warn('Suspicious activity detected', {
  userId: user.id,
  action: 'failed_login_attempt',
  attempts: failCount,
  ipAddress: req.ip,
  timestamp: new Date(),
});

// ❌ BAD - Never log passwords, tokens, or secrets
logger.error('Login failed', {
  username: user.username,
  password: user.password, // NEVER!
  token: authToken, // NEVER!
});

// ✅ GOOD - Log only necessary info
logger.error('Database connection failed', {
  error: 'ECONNREFUSED',
  host: 'localhost', // Non-sensitive
  port: 5432,
  timestamp: new Date(),
});
```

### Rate Limiting Configuration

```javascript
const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');
const redis = require('redis');

const redisClient = redis.createClient();

// Strict limiter for authentication
const authLimiter = rateLimit({
  store: new RedisStore({
    client: redisClient,
    prefix: 'auth-limit:',
  }),
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 requests per window
  message: 'Too many login attempts, try again later',
  skipSuccessfulRequests: true, // Don't count successful attempts
  keyGenerator: (req) => `${req.ip}:${req.body.username}`, // Track by IP and username
});

// General API limiter
const apiLimiter = rateLimit({
  store: new RedisStore({
    client: redisClient,
    prefix: 'api-limit:',
  }),
  windowMs: 60 * 1000, // 1 minute
  max: 100, // 100 requests per minute
  standardHeaders: true,
  legacyHeaders: false,
});

// Strict limiter for password reset
const passwordResetLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 3, // 3 requests per hour
  message: 'Too many password reset attempts',
  skipSuccessfulRequests: true,
});

app.post('/login', authLimiter, handleLogin);
app.use('/api/', apiLimiter);
app.post('/password-reset', passwordResetLimiter, handlePasswordReset);
```

