const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({ region: 'us-east-1' });

class SecretsManagerService {
  constructor() {
    this.cache = null;
    this.cacheExpiry = null;
    this.cacheTTL = 5 * 60 * 1000; // 5 minute cache
  }

  async getSecret(secretName) {
    // Check if cached secret is still valid
    if (this.cache && this.cacheExpiry > Date.now()) {
      return this.cache;
    }

    try {
      const secretValue = await secretsManager.getSecretValue({
        SecretId: `${process.env.APP_ENV}/app/secrets`
      }).promise();

      let secret;
      if ('SecretString' in secretValue) {
        secret = JSON.parse(secretValue.SecretString);
      } else {
        secret = Buffer.from(secretValue.SecretBinary, 'base64').toString('ascii');
      }

      // Update cache
      this.cache = secret;
      this.cacheExpiry = Date.now() + this.cacheTTL;

      logger.info('Secrets loaded from AWS Secrets Manager', {
        secretName,
        cacheExpiry: new Date(this.cacheExpiry).toISOString()
      });

      return secret;
    } catch (error) {
      logger.error('Failed to retrieve secret from AWS', {
        secretName,
        error: error.message
      });
      throw new Error('Failed to load secrets');
    }
  }

  async rotateSecret() {
    // AWS can automatically rotate secrets
    logger.info('Initiating secret rotation');
    this.cache = null;
    this.cacheExpiry = null;
  }
}

