#### Secret Rotation Strategy

```javascript
class SecretRotationManager {
  constructor(secretsService) {
    this.service = secretsService;
    this.lastRotation = null;
    this.rotationInterval = 30 * 24 * 60 * 60 * 1000; // 30 days
  }

  async checkAndRotate() {
    const timeSinceLastRotation = Date.now() - (this.lastRotation || 0);

    if (timeSinceLastRotation > this.rotationInterval) {
      logger.warn('Secret rotation due', {
        daysSinceRotation: Math.floor(timeSinceLastRotation / (24 * 60 * 60 * 1000))
      });

      await this.rotateSecrets();
    }
  }

  async rotateSecrets() {
    try {
      // Generate new secrets
      const newJWT = this.generateRandomSecret(32);
      const newRefresh = this.generateRandomSecret(32);

      // Store new secrets
      await this.service.updateSecret({
        jwt_secret: newJWT,
        jwt_refresh_secret: newRefresh
      });

      this.lastRotation = Date.now();

      logger.info('Secrets rotated successfully', {
        timestamp: new Date().toISOString()
      });

      // Send notification (email, Slack, etc.)
      await this.notifyAdmins('Secrets rotated');

    } catch (error) {
      logger.error('Secret rotation failed', { error: error.message });
      await this.notifyAdmins('⚠️ SECRET ROTATION FAILED', error);
    }
  }

  generateRandomSecret(length = 32) {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
    let result = '';
    const cryptoRandom = require('crypto').randomBytes(length);
    for (let i = 0; i < length; i++) {
      result += chars[cryptoRandom[i] % chars.length];
    }
    return result;
  }

  async notifyAdmins(message, error = null) {
    // Send via Slack, email, PagerDuty, etc.
    logger.info('Admin notification sent', { message });
  }
}
