class SecretsManager {
  constructor(backend = 'aws') {
    this.backend = backend;
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async get(secretKey, options = {}) {
    const { useCache = true, ttl = this.cacheTTL } = options;

    // Check cache first
    if (useCache) {
      const cached = this.cache.get(secretKey);
      if (cached && Date.now() < cached.expiry) {
        return cached.value;
      }
    }

    let secretValue;
    try {
      if (this.backend === 'aws') {
        secretValue = await this._getFromAWS(secretKey);
      } else if (this.backend === 'vault') {
        secretValue = await this._getFromVault(secretKey);
      } else if (this.backend === 'env') {
        secretValue = this._getFromEnv(secretKey);
      }

      // Cache the secret
      if (useCache) {
        this.cache.set(secretKey, {
          value: secretValue,
          expiry: Date.now() + ttl
        });
      }

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret: ${secretKey}`, error);
      throw new Error(`Unable to load secret: ${secretKey}`);
    }
  }

  async _getFromAWS(secretKey) {
    const secretsManager = new AWS.SecretsManager();
    const data = await secretsManager.getSecretValue({
      SecretId: secretKey
    }).promise();

    return 'SecretString' in data ? 
      JSON.parse(data.SecretString) : 
      Buffer.from(data.SecretBinary, 'base64').toString();
  }

  async _getFromVault(secretKey) {
    const client = vault({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });
    const result = await client.read(`secret/data/${secretKey}`);
    return result.data.data;
  }

  _getFromEnv(secretKey) {
    const value = process.env[secretKey];
    if (!value) {
      throw new Error(`Environment variable not found: ${secretKey}`);
    }
    return value;
  }

  // Sanitize secrets from logs/strings
  sanitize(text) {
    const secretPatterns = [
      /postgres:\/\/\w+:\w+@[^\s]+/gi, // Database URLs
      /(AKIA[0-9A-Z]{16})/g, // AWS Access Keys
      /(sk_live_[a-zA-Z0-9]{20,})/g, // Stripe keys
      /(sk-ant-[a-zA-Z0-9_-]+)/g, // Anthropic keys
    ];

    let sanitized = text;
    secretPatterns.forEach(pattern => {
      sanitized = sanitized.replace(pattern, '[REDACTED]');
    });
    return sanitized;
  }

  // Clear cache
  clearCache(secretKey) {
    if (secretKey) {
      this.cache.delete(secretKey);
    } else {
      this.cache.clear();
    }
  }
}

