// Secure version of app.js with comprehensive security improvements
// This file demonstrates the recommended fixes for all identified vulnerabilities

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const cors = require('cors');
require('dotenv').config();

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE - OWASP Top 10 Protection
// ============================================================================

// 1. HELMET - Set security HTTP headers (A05:2021 – Security Misconfiguration)
app.use(helmet());

// 2. CORS - Restrict cross-origin requests (A01:2021 – Broken Access Control)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};
app.use(cors(corsOptions));

// 3. RATE LIMITING - Prevent brute force attacks (A07:2021 – Identification and Authentication Failures)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter limit for sensitive endpoints
  skipSuccessfulRequests: true,
});

app.use(limiter);

// 4. REQUEST PARSING with size limits (A03:2021 – Injection)
app.use(express.json({ limit: '10kb' })); // Prevent payload-based attacks
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 5. DATA SANITIZATION (A03:2021 – Injection)
app.use(mongoSanitize()); // Remove $ and . from user inputs
app.use(xss()); // Sanitize data to prevent XSS

// 6. PARAMETER POLLUTION PROTECTION (A07:2021 – Cross-Site Scripting)
app.use(hpp());

// ============================================================================
// INPUT VALIDATION & SANITIZATION UTILITIES
// ============================================================================

const validator = require('validator');

/**
 * Validate and sanitize string inputs
 * @param {string} input - The input to validate
 * @param {string} fieldName - Name of field for error messages
 * @param {number} maxLength - Maximum allowed length
 * @returns {string} - Sanitized string
 * @throws {Error} - If validation fails
 */
function validateString(input, fieldName, maxLength = 255) {
  if (typeof input !== 'string') {
    throw new Error(`${fieldName} must be a string`);
  }

  if (input.trim().length === 0) {
    throw new Error(`${fieldName} cannot be empty`);
  }

  if (input.length > maxLength) {
    throw new Error(`${fieldName} exceeds maximum length of ${maxLength}`);
  }

  // Remove any potentially dangerous characters
  return validator.escape(input.trim());
}

/**
 * Validate email address
 * @param {string} email - Email to validate
 * @returns {string} - Normalized email
 * @throws {Error} - If validation fails
 */
function validateEmail(email) {
  if (!validator.isEmail(email)) {
    throw new Error('Invalid email address');
  }
  return validator.normalizeEmail(email);
}

/**
 * Validate positive integer ID
 * @param {*} id - ID to validate
 * @returns {number} - Validated ID
 * @throws {Error} - If validation fails
 */
function validateId(id) {
  const parsed = parseInt(id, 10);
  if (!Number.isInteger(parsed) || parsed <= 0) {
    throw new Error('Invalid ID: must be a positive integer');
  }
  return parsed;
}

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
  }
}

const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================================================
// AUTHENTICATION & AUTHORIZATION (A01:2021, A07:2021)
// ============================================================================

/**
 * Mock authentication middleware
 * In production, validate JWT tokens here
 */
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    return res.status(401).json({ error: 'Missing authorization header' });
  }

  // Extract bearer token
  const parts = authHeader.split(' ');
  if (parts.length !== 2 || parts[0] !== 'Bearer') {
    return res.status(401).json({ error: 'Invalid authorization format' });
  }

  const token = parts[1];

  // In production: validate JWT
  // jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
  //   if (err) return res.status(401).json({ error: 'Invalid token' });
  //   req.user = decoded;
  //   next();
  // });

  // Mock: validate token format
  if (token.length < 10) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  req.user = { id: 1, role: 'user' };
  next();
}

/**
 * Authorization middleware - role-based access control
 */
function authorize(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
}

// ============================================================================
// ROUTES WITH SECURITY CONTROLS
// ============================================================================

/**
 * Health check endpoint - Public, no authentication required
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

/**
 * Get users endpoint - Protected endpoint
 * Security: Input validation, authentication, rate limiting
 * VULNERABILITIES FIXED:
 * - Added authentication requirement
 * - Added input validation for query parameters
 * - Added rate limiting on this endpoint
 * - Removed sensitive data from response (no emails)
 */
app.get('/users', strictLimiter, authenticate, asyncHandler(async (req, res) => {
  try {
    // Validate query parameters
    let page = 1;
    let limit = 10;

    if (req.query.page) {
      page = validateId(req.query.page);
    }

    if (req.query.limit) {
      limit = validateId(req.query.limit);

      // Prevent resource exhaustion
      if (limit > 100) {
        throw new AppError('Limit cannot exceed 100', 400);
      }
    }

    // Mock data - in production, this would query a database
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Implement pagination
    const start = (page - 1) * limit;
    const paginatedUsers = mockUsers.slice(start, start + limit);

    // Remove sensitive data before sending
    const safeUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name
      // email intentionally omitted unless user is admin
    }));

    res.json({
      data: safeUsers,
      pagination: {
        page,
        limit,
        total: mockUsers.length
      }
    });
  } catch (error) {
    if (error instanceof AppError) {
      return res.status(error.statusCode).json({ error: error.message });
    }
    throw error;
  }
}));

/**
 * Get user by ID endpoint
 * VULNERABILITIES FIXED:
 * - Input validation for ID parameter
 * - Authentication check
 * - No SQL injection possible (validated integer)
 */
app.get('/users/:id', authenticate, asyncHandler(async (req, res) => {
  try {
    const userId = validateId(req.query.id);

    // Mock database query (in production, use parameterized queries)
    const mockUsers = {
      1: { id: 1, name: 'Alice', email: 'alice@example.com' },
      2: { id: 2, name: 'Bob', email: 'bob@example.com' },
    };

    const user = mockUsers[userId];

    if (!user) {
      throw new AppError('User not found', 404);
    }

    res.json(user);
  } catch (error) {
    if (error instanceof AppError) {
      return res.status(error.statusCode).json({ error: error.message });
    }
    throw error;
  }
}));

/**
 * Create user endpoint
 * VULNERABILITIES FIXED:
 * - Input validation for all fields
 * - Sanitization of user inputs
 * - Authentication and authorization checks
 * - Payload size limit
 */
app.post('/users', authenticate, authorize('admin'), asyncHandler(async (req, res) => {
  try {
    const { name, email } = req.body;

    // Validate and sanitize inputs
    const validatedName = validateString(name, 'name', 100);
    const validatedEmail = validateEmail(email);

    // Mock: create user (in production, check for duplicates, hash passwords, etc.)
    const newUser = {
      id: 3,
      name: validatedName,
      email: validatedEmail
    };

    res.status(201).json(newUser);
  } catch (error) {
    if (error instanceof AppError) {
      return res.status(error.statusCode).json({ error: error.message });
    }
    return res.status(400).json({ error: error.message });
  }
}));

/**
 * Update user endpoint
 * VULNERABILITIES FIXED:
 * - Input validation
 * - Authentication and authorization
 * - Ownership verification (user can only update own profile)
 */
app.put('/users/:id', authenticate, asyncHandler(async (req, res) => {
  try {
    const userId = validateId(req.params.id);
    const { name, email } = req.body;

    // Authorization: users can only update their own profile
    if (req.user.id !== userId && req.user.role !== 'admin') {
      throw new AppError('Cannot update another user\'s profile', 403);
    }

    // Validate and sanitize inputs
    if (name) {
      validateString(name, 'name', 100);
    }
    if (email) {
      validateEmail(email);
    }

    res.json({ message: 'User updated successfully' });
  } catch (error) {
    if (error instanceof AppError) {
      return res.status(error.statusCode).json({ error: error.message });
    }
    return res.status(400).json({ error: error.message });
  }
}));

// ============================================================================
// GLOBAL ERROR HANDLER (A10:2021 – Logging and Monitoring Failures)
// ============================================================================

app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ============================================================================
// 404 HANDLER
// ============================================================================

app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Secure server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

