 * 4. Use this module to load secrets at application startup
 */

const AWS = require('aws-sdk');

class SecretsManagerClient {
  constructor(region = process.env.AWS_REGION || 'us-east-1') {
    this.secretsManager = new AWS.SecretsManager({ region });
    this.cache = new Map(); // In-memory cache with TTL
    this.cacheTTL = 300000; // 5 minutes
  }

  /**
   * Get a secret from AWS Secrets Manager with caching
   * @param {string} secretName - The name of the secret
   * @returns {Promise<Object>} - The secret value
   * @throws {Error} - If secret cannot be retrieved
   */
  async getSecret(secretName) {
    // Check cache first
    if (this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (cached.expiresAt > Date.now()) {
        console.log(`[SecretManager] Using cached secret: ${secretName}`);
        return cached.value;
      }
      this.cache.delete(secretName);
    }

    try {
      console.log(`[SecretManager] Retrieving secret: ${secretName}`);

      const data = await this.secretsManager
        .getSecretValue({ SecretId: secretName })
        .promise();

      // Parse secret value (could be JSON or plain text)
      let secretValue;
      if ('SecretString' in data) {
        secretValue = JSON.parse(data.SecretString);
      } else if ('SecretBinary' in data) {
        secretValue = Buffer.from(data.SecretBinary, 'base64');
      } else {
        throw new Error('Invalid secret format');
      }

      // Cache with TTL
      this.cache.set(secretName, {
        value: secretValue,
        expiresAt: Date.now() + this.cacheTTL
      });

      return secretValue;
    } catch (error) {
      console.error(`[SecretManager] Failed to retrieve secret: ${secretName}`, error);
      throw new Error(`Cannot retrieve secret ${secretName}: ${error.message}`);
    }
  }

  /**
   * Get multiple secrets efficiently
   * @param {string[]} secretNames - Array of secret names
   * @returns {Promise<Object>} - Object with secretName -> value mapping
   */
  async getSecrets(secretNames) {
    const results = {};
    const promises = secretNames.map(async (name) => {
      results[name] = await this.getSecret(name);
    });

    await Promise.all(promises);
    return results;
  }

  /**
   * Initialize all required secrets for the application
   * Call this at application startup
   * @returns {Promise<Object>} - All loaded secrets
   */
  async initializeAppSecrets() {
    const requiredSecrets = [
      'MyApp/Database/url',
      'MyApp/AWS/AccessKey',
      'MyApp/AWS/SecretKey',
      'MyApp/Stripe/SecretKey',
      'MyApp/API/AnthropicKey',
      'MyApp/Logging/FirebaseToken'
    ];

    try {
      console.log('[SecretManager] Loading application secrets...');
      const secrets = await this.getSecrets(requiredSecrets);

      // Validate that all required secrets were loaded
      for (const secretName of requiredSecrets) {
        if (!secrets[secretName]) {
          throw new Error(`Required secret not loaded: ${secretName}`);
        }
      }

      console.log('[SecretManager] ✓ All secrets loaded successfully');
      return secrets;
    } catch (error) {
      console.error('[SecretManager] ✗ Failed to initialize secrets', error);
      process.exit(1); // Fail fast if secrets cannot be loaded
    }
  }

  /**
   * Clear the cache (useful for testing or forcing refresh)
   */
  clearCache() {
    this.cache.clear();
    console.log('[SecretManager] Cache cleared');
  }
}

