/**
 * HashiCorp Vault Implementation
 * ================================================================================
 * Securely load secrets from HashiCorp Vault - on-premises and multi-cloud solution
 * 
 * ADVANTAGES:
 * ✓ Multi-cloud support (AWS, Azure, GCP, on-premises)
 * ✓ Dynamic secret generation
 * ✓ Secret rotation policies
 * ✓ Detailed audit logging
 * ✓ Fine-grained access control
 * ✓ High availability and disaster recovery
 * ✓ Encryption at rest and in transit
 * 
 * INSTALLATION:
 * npm install node-vault
 * 
 * VAULT SETUP:
 * 1. Start Vault server
 * 2. Authenticate with Vault (token or AppRole)
 * 3. Store secrets:
 *    vault kv put secret/myapp/database url=postgres://...
 *    vault kv put secret/myapp/aws access_key=... secret_key=...
 * 4. Set up AppRole for application authentication
 */

const vault = require('node-vault');

class VaultSecretsManager {
  constructor(options = {}) {
    this.endpoint = options.endpoint || process.env.VAULT_ADDR || 'http://127.0.0.1:8200';
    this.token = options.token || process.env.VAULT_TOKEN;
    this.role_id = options.role_id || process.env.VAULT_ROLE_ID;
    this.secret_id = options.secret_id || process.env.VAULT_SECRET_ID;
    this.namespace = options.namespace || process.env.VAULT_NAMESPACE || 'secret';

    this.client = vault({
      endpoint: this.endpoint,
      token: this.token
    });

    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
    this.authenticated = false;
  }

  /**
   * Authenticate with Vault using AppRole method
   * Recommended for production - no hardcoded tokens
   */
  async authenticateWithAppRole() {
    try {
      console.log('[Vault] Authenticating with AppRole...');

      const response = await this.client.appRole({
        role_id: this.role_id,
        secret_id: this.secret_id
      });

      this.client.token = response.auth.client_token;
      this.authenticated = true;

      console.log('[Vault] ✓ AppRole authentication successful');

      // Set token refresh timer (vault tokens expire)
      const ttl = response.auth.lease_duration;
      if (ttl) {
        setTimeout(() => this.authenticateWithAppRole(), ttl * 1000 * 0.8);
      }

      return response;
    } catch (error) {
      console.error('[Vault] AppRole authentication failed:', error.message);
      throw error;
    }
  }

  /**
   * Authenticate with Vault using static token
   * Less secure than AppRole - use only for development
   */
  async authenticateWithToken(token) {
    try {
      console.log('[Vault] Authenticating with static token...');

      this.client.token = token;

      // Verify token works
      const response = await this.client.auth.token.lookup(token);
      this.authenticated = true;

      console.log('[Vault] ✓ Token authentication successful');
      return response;
    } catch (error) {
      console.error('[Vault] Token authentication failed:', error.message);
      throw error;
    }
  }

  /**
   * Retrieve secret from Vault
   * @param {string} path - Secret path (e.g., 'myapp/database')
   * @param {boolean} useCache - Whether to use cached value
   * @returns {Promise<Object>} - Secret data
   */
  async getSecret(path, useCache = true) {
    // Check cache
    if (useCache && this.cache.has(path)) {
      const cached = this.cache.get(path);
      if (cached.expiresAt > Date.now()) {
        console.log(`[Vault] Using cached secret: ${path}`);
        return cached.value;
      }
      this.cache.delete(path);
    }

    try {
      if (!this.authenticated) {
        throw new Error('Not authenticated with Vault');
      }

      console.log(`[Vault] Retrieving secret: ${path}`);

      const secretPath = `${this.namespace}/${path}`;
      const response = await this.client.read(secretPath);

      const secretData = response.data.data || response.data;

      // Cache with TTL
      this.cache.set(path, {
        value: secretData,
        expiresAt: Date.now() + this.cacheTTL
      });

      console.log(`[Vault] ✓ Retrieved: ${path}`);
      return secretData;
    } catch (error) {
      console.error(`[Vault] Failed to retrieve ${path}:`, error.message);
      throw error;
    }
  }

  /**
   * Retrieve multiple secrets
   * @param {string[]} paths - Array of secret paths
   * @returns {Promise<Object>} - Object mapping paths to secrets
   */
  async getSecrets(paths) {
    const results = {};
    const promises = paths.map(async (path) => {
      results[path] = await this.getSecret(path);
    });

    await Promise.all(promises);
    return results;
  }

  /**
   * Generate dynamic credentials from Vault
   * Useful for database credentials that rotate automatically
   * @param {string} role - Vault role name
   * @returns {Promise<Object>} - Generated credentials
   */
  async generateDynamicCredentials(role) {
    try {
      console.log(`[Vault] Generating dynamic credentials for role: ${role}`);

      const response = await this.client.read(`database/creds/${role}`);

      console.log(`[Vault] ✓ Generated credentials (lease: ${response.lease_duration}s)`);

      return {
        username: response.data.username,
        password: response.data.password,
        lease_id: response.lease_id,
        lease_duration: response.lease_duration
      };
    } catch (error) {
      console.error('[Vault] Failed to generate credentials:', error.message);
      throw error;
    }
  }

  /**
   * Initialize all required secrets for application
   * Call at application startup
   * @param {Object} secretPaths - Object mapping secret names to paths
   * @returns {Promise<Object>} - All loaded secrets
   */
  async initializeAppSecrets(secretPaths = {}) {
    const defaultPaths = {
      database: 'myapp/database',
      aws: 'myapp/aws',
      stripe: 'myapp/stripe',
      anthropic: 'myapp/anthropic',
      logging: 'myapp/logging'
    };

    const pathsToLoad = { ...defaultPaths, ...secretPaths };

    try {
      console.log('[Vault] Loading application secrets...');

      // Ensure authenticated
      if (!this.authenticated) {
        await this.authenticateWithAppRole();
      }

      const secrets = await this.getSecrets(Object.values(pathsToLoad));

      console.log('[Vault] ✓ All secrets loaded successfully');

      return secrets;
    } catch (error) {
      console.error('[Vault] Failed to initialize secrets:', error);
      process.exit(1); // Fail fast
    }
  }

  /**
   * Refresh token before expiration
   */
  async refreshToken() {
    try {
      const response = await this.client.auth.token.renew();
      console.log('[Vault] ✓ Token refreshed');
      return response;
    } catch (error) {
      console.error('[Vault] Token refresh failed:', error.message);
      // Re-authenticate if refresh fails
      await this.authenticateWithAppRole();
    }
  }

  /**
   * Clear cache and force reload next time
   */
  clearCache() {
    this.cache.clear();
    console.log('[Vault] Cache cleared');
  }

  /**
   * Logout and revoke token
   */
  async logout() {
    try {
      await this.client.auth.token.revoke();
      this.authenticated = false;
      console.log('[Vault] ✓ Token revoked, logged out');
    } catch (error) {
      console.error('[Vault] Logout failed:', error.message);
    }
  }
}

