/**
 * Encrypted .env File Implementation
 * ================================================================================
 * Fallback solution for simpler deployments where full secrets manager is not viable
 * Use encryption to protect .env files instead of storing plaintext secrets
 * 
 * This is NOT a replacement for proper secrets managers but better than plaintext
 * 
 * ADVANTAGES:
 * ✓ Better than plaintext .env files
 * ✓ Secrets encrypted at rest
 * ✓ No external service dependency
 * ✓ Easy to set up
 * 
 * LIMITATIONS:
 * ✗ Still stores encryption key (manage separately)
 * ✗ No rotation capability
 * ✗ No audit logging
 * ✗ Manual decryption at startup
 * 
 * USE FOR: Development, staging, or small deployments only
 * USE AWS SECRETS MANAGER or VAULT for production
 * 
 * INSTALLATION:
 * npm install dotenv node-encryptor
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class EncryptedSecretsManager {
  /**
   * Generate encryption key for local use
   * IMPORTANT: This key should be stored securely (e.g., AWS Secrets Manager)
   * or rotated regularly
   */
  static generateKey() {
    const key = crypto.randomBytes(32);
    console.log('Generated encryption key (base64):');
    console.log(key.toString('base64'));
    console.log('\nStore this safely - you\'ll need it to decrypt secrets!');
    return key;
  }

  /**
   * Encrypt a plaintext .env file
   * @param {string} envFilePath - Path to plaintext .env file
   * @param {Buffer} encryptionKey - Encryption key
   * @param {string} outputPath - Where to save encrypted file
   */
  static encryptEnvFile(envFilePath, encryptionKey, outputPath) {
    try {
      console.log(`[SecretManager] Encrypting ${envFilePath}...`);

      // Read plaintext file
      const content = fs.readFileSync(envFilePath, 'utf8');

      // Validate that it contains secrets before encrypting
      if (!content.includes('=')) {
        throw new Error('Invalid .env file format');
      }

      // Generate IV (initialization vector) for this encryption
      const iv = crypto.randomBytes(16);

      // Create cipher
      const cipher = crypto.createCipheriv('aes-256-cbc', encryptionKey, iv);

      // Encrypt content
      let encrypted = cipher.update(content, 'utf8', 'hex');
      encrypted += cipher.final('hex');

      // Combine IV and encrypted data
      const result = iv.toString('hex') + ':' + encrypted;

      // Write encrypted file
      fs.writeFileSync(outputPath, result, 'utf8');

      console.log(`[SecretManager] ✓ Encrypted file saved to: ${outputPath}`);
      console.log(`[SecretManager] Delete the plaintext file: rm ${envFilePath}`);

      return result;
    } catch (error) {
      console.error('[SecretManager] Encryption failed:', error.message);
      throw error;
    }
  }

  /**
   * Decrypt an encrypted .env file
   * @param {string} encryptedFilePath - Path to encrypted file
   * @param {Buffer} encryptionKey - Encryption key
   * @returns {string} - Decrypted plaintext content
   */
  static decryptEnvFile(encryptedFilePath, encryptionKey) {
    try {
      console.log(`[SecretManager] Decrypting ${encryptedFilePath}...`);

      // Read encrypted file
      const content = fs.readFileSync(encryptedFilePath, 'utf8');

      // Extract IV and encrypted data
      const parts = content.split(':');
      if (parts.length !== 2) {
        throw new Error('Invalid encrypted file format');
      }

      const iv = Buffer.from(parts[0], 'hex');
      const encrypted = parts[1];

      // Create decipher
      const decipher = crypto.createDecipheriv('aes-256-cbc', encryptionKey, iv);

      // Decrypt
      let decrypted = decipher.update(encrypted, 'hex', 'utf8');
      decrypted += decipher.final('utf8');

      console.log('[SecretManager] ✓ File decrypted successfully');

      return decrypted;
    } catch (error) {
      console.error('[SecretManager] Decryption failed:', error.message);
      throw error;
    }
  }

  /**
   * Initialize environment from encrypted .env file
   * Call at application startup
   * @param {Buffer} encryptionKey - Encryption key
   * @param {string} envFilePath - Path to encrypted .env file
   */
  static loadEncryptedEnv(encryptionKey, envFilePath = '.env.encrypted') {
    try {
      // Check if encrypted file exists
      if (!fs.existsSync(envFilePath)) {
        console.warn(`[SecretManager] ⚠ Encrypted file not found: ${envFilePath}`);
        console.warn('[SecretManager] Falling back to process.env');
        return;
      }

      // Decrypt file
      const decrypted = this.decryptEnvFile(envFilePath, encryptionKey);

      // Parse and load into process.env
      const lines = decrypted.split('\n');
      for (const line of lines) {
        // Skip empty lines and comments
        if (!line.trim() || line.trim().startsWith('#')) {
          continue;
        }

        const [key, ...valueParts] = line.split('=');
        const value = valueParts.join('=');

        if (key && value) {
          process.env[key.trim()] = value.trim();
        }
      }

      console.log('[SecretManager] ✓ Environment loaded from encrypted file');
    } catch (error) {
      console.error('[SecretManager] Failed to load encrypted env:', error.message);
      throw error;
    }
  }

  /**
   * Get encryption key from AWS Secrets Manager
   * This is the recommended way to store the encryption key
   * @param {string} secretName - Secret name in AWS
   * @returns {Promise<Buffer>} - Encryption key
   */
  static async getKeyFromAwsSecretsManager(secretName) {
    try {
      const AWS = require('aws-sdk');
      const secretsManager = new AWS.SecretsManager();

      const data = await secretsManager
        .getSecretValue({ SecretId: secretName })
        .promise();

      const key = Buffer.from(data.SecretString, 'base64');
      console.log('[SecretManager] ✓ Encryption key loaded from AWS Secrets Manager');

      return key;
    } catch (error) {
      console.error('[SecretManager] Failed to get key from AWS:', error.message);
      throw error;
    }
  }
}

