const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const winston = require('winston');

// ============================================================================
// CONFIGURATION & SETUP
// ============================================================================

require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Logger setup
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet - Security headers
app.use(helmet());

// 2. Additional security headers
app.use((req, res, next) => {
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// 3. CORS configuration
const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || [
      'https://app.example.com',
      'https://www.example.com'
    ];

    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn('CORS rejected:', { origin });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};

app.use(cors(corsOptions));

// 4. Body size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => {
    // Skip rate limiting for health check
    return req.path === '/health';
  }
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  keyGenerator: (req) => req.user?.id || req.ip
});

app.use(limiter);

// 6. HTTP request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  },
  skip: (req) => req.path === '/health' // Don't log health checks
}));

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    logger.warn('Unauthorized access attempt:', { path: req.path, ip: req.ip });
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET || 'dev-secret');
    req.user = decoded;
    logger.debug('Token verified:', { userId: decoded.id });
    next();
  } catch (err) {
    logger.warn('Invalid token:', { ip: req.ip, error: err.message });
    res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// ============================================================================
// ROUTES
// ============================================================================

// Public endpoint - Health check
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

// Protected endpoint - Get users with input validation
app.get('/users',
  authenticate,
  query('id').optional().isInt().toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Validation error:', { errors: errors.array() });
      return res.status(400).json({
        error: 'Invalid input parameters',
        details: errors.array()
      });
    }

    // In production, fetch from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    logger.info('Users retrieved:', { userId: req.user.id, count: users.length });
    res.json(users);
  }
);

// Authentication endpoint example
app.post('/auth/login',
  authLimiter,
  express.json(),
  (req, res) => {
    const { username, password } = req.body;

    // Validate input
    if (!username || !password) {
      logger.warn('Login attempt with missing credentials', { ip: req.ip });
      return res.status(400).json({ error: 'Username and password required' });
    }

    // In production, verify against database with bcrypt
    if (username === 'admin' && password === 'demo') {
      const token = jwt.sign(
        { id: 1, username },
        process.env.JWT_SECRET || 'dev-secret',
        { expiresIn: '1h' }
      );

      logger.info('User logged in:', { username });
      return res.json({ token });
    }

    logger.warn('Failed login attempt:', { username, ip: req.ip });
    res.status(401).json({ error: 'Invalid credentials' });
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  logger.warn('404 Not Found:', { path: req.path, ip: req.ip });
  res.status(404).json({
    error: 'Not Found',
    message: `The path ${req.path} does not exist`
  });
});

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', {
    message: err.message,
    status: err.status || 500,
    path: req.path,
    ip: req.ip,
    stack: NODE_ENV === 'development' ? err.stack : undefined
  });

  const isDevelopment = NODE_ENV !== 'production';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;
