/**
 * SECURE VERSION OF app.js
 * This file demonstrates security best practices implementation
 */

const express = require('express');
const jwt = require('jsonwebtoken');
const helmet = require('helmet');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const crypto = require('crypto');

const app = express();

// ============================================================================
// CONFIGURATION
// ============================================================================

const JWT_SECRET = process.env.JWT_SECRET || crypto.randomBytes(32).toString('hex');
const JWT_EXPIRY = '1h';
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security headers using helmet
app.use(helmet());

// 2. Additional HSTS for HTTPS enforcement
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year in seconds
  includeSubDomains: true,
  preload: true,
}));

// 3. Content Security Policy
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));

// 4. Request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// 5. Body parser middleware with size limit
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 6. Enforce HTTPS in production
app.use((req, res, next) => {
  if (NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.header('host')}${req.url}`);
  }
  next();
});

// 7. Global rate limiter
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => NODE_ENV === 'development', // Skip in development
});

app.use(globalLimiter);

// 8. Strict rate limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Max 5 attempts
  message: 'Too many authentication attempts, please try again later.',
  skipSuccessfulRequests: true, // Don't count successful requests
  standardHeaders: true,
  legacyHeaders: false,
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

/**
 * Verify JWT token
 */
const authenticateToken = (req, res, next) => {
  try {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

    if (!token) {
      return res.status(401).json({
        error: 'Access token required',
        code: 'NO_TOKEN',
      });
    }

    jwt.verify(token, JWT_SECRET, (err, user) => {
      if (err) {
        const statusCode = err.name === 'TokenExpiredError' ? 401 : 403;
        return res.status(statusCode).json({
          error: 'Invalid or expired token',
          code: err.name,
        });
      }
      req.user = user;
      next();
    });
  } catch (error) {
    return res.status(500).json({
      error: 'Internal Server Error',
      requestId: req.id,
    });
  }
};

/**
 * Role-based access control middleware
 */
const authorize = (requiredRoles = []) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (requiredRoles.length && !requiredRoles.includes(req.user.role)) {
      return res.status(403).json({
        error: 'Insufficient permissions',
        code: 'FORBIDDEN',
      });
    }

    next();
  };
};

// ============================================================================
// DATA FILTERING & SANITIZATION
// ============================================================================

/**
 * Sanitize user data based on access control
 * Only return sensitive data if user has permission
 */
const sanitizeUser = (user, currentUser) => {
  const sanitized = {
    id: user.id,
    name: user.name,
  };

  // Only return email if:
  // 1. User is viewing their own profile, OR
  // 2. User is an admin
  if (currentUser && (currentUser.id === user.id || currentUser.role === 'admin')) {
    sanitized.email = user.email;
  }

  return sanitized;
};

// ============================================================================
// INPUT VALIDATION
// ============================================================================

/**
 * Validation rules for /users GET endpoint
 */
const validateGetUsers = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be >= 0')
    .toInt(),
  query('search')
    .optional()
    .trim()
    .isLength({ min: 1, max: 50 })
    .withMessage('Search must be between 1 and 50 characters'),
];

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint (public)
 * Does not require authentication
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
  });
});

/**
 * Login endpoint
 * Rate limited and implements validation
 */
app.post('/login', authLimiter, express.json(), (req, res) => {
  try {
    const { username, password } = req.body;

    // Input validation
    if (!username || !password) {
      return res.status(400).json({
        error: 'Username and password are required',
      });
    }

    if (typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({
        error: 'Invalid input types',
      });
    }

    // TODO: In production, verify against database with bcrypt
    // For demo, accept any non-empty credentials
    if (username.length < 3 || password.length < 6) {
      return res.status(401).json({
        error: 'Invalid credentials',
      });
    }

    // Create user object (in production, fetch from DB)
    const user = {
      id: 1,
      username: username,
      role: 'user',
    };

    // Generate JWT token
    const token = jwt.sign(user, JWT_SECRET, { expiresIn: JWT_EXPIRY });

    // Log authentication (in production, use structured logging)
    console.log(`[AUTH] User ${username} logged in at ${new Date().toISOString()}`);

    res.json({
      token,
      expiresIn: JWT_EXPIRY,
      user: {
        id: user.id,
        username: user.username,
        role: user.role,
      },
    });
  } catch (error) {
    console.error('[ERROR]', error);
    res.status(500).json({
      error: 'Internal Server Error',
      requestId: req.id,
    });
  }
});

/**
 * Get all users endpoint
 * Protected: requires authentication
 * Filtered: returns only accessible fields
 */
app.get('/users', authenticateToken, validateGetUsers, (req, res) => {
  try {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        errors: errors.array(),
      });
    }

    const limit = req.query.limit || 50;
    const offset = req.query.offset || 0;
    const search = req.query.search || '';

    // Sample data (in production, fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' },
    ];

    // Filter by search term (basic example)
    let filtered = allUsers;
    if (search) {
      filtered = allUsers.filter(u =>
        u.name.toLowerCase().includes(search.toLowerCase())
      );
    }

    // Apply pagination
    const paginated = filtered.slice(offset, offset + limit);

    // Sanitize output: remove sensitive data
    const sanitized = paginated.map(user => sanitizeUser(user, req.user));

    res.json({
      data: sanitized,
      pagination: {
        limit,
        offset,
        total: filtered.length,
      },
    });
  } catch (error) {
    console.error('[ERROR]', error);
    res.status(500).json({
      error: 'Internal Server Error',
      requestId: req.id,
    });
  }
});

/**
 * Get current user profile endpoint
 * Protected: requires authentication
 */
app.get('/users/profile', authenticateToken, (req, res) => {
  try {
    // In production, fetch from database
    const user = {
      id: req.user.id,
      username: req.user.username,
      role: req.user.role,
      email: 'user@example.com', // Only return own email
      createdAt: new Date(Date.now() - 86400000).toISOString(),
    };

    res.json(user);
  } catch (error) {
    console.error('[ERROR]', error);
    res.status(500).json({
      error: 'Internal Server Error',
      requestId: req.id,
    });
  }
});

/**
 * Admin-only endpoint
 * Protected: requires authentication AND admin role
 */
app.get('/admin/stats', authenticateToken, authorize(['admin']), (req, res) => {
  try {
    res.json({
      totalUsers: 3,
      activeUsers: 2,
      lastUpdated: new Date().toISOString(),
    });
  } catch (error) {
    console.error('[ERROR]', error);
    res.status(500).json({
      error: 'Internal Server Error',
      requestId: req.id,
    });
  }
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
  });
});

/**
 * Global error handler
 * Must be defined last and have 4 parameters
 */
app.use((err, req, res, next) => {
  // Log error details (in production, use proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    status: err.status || 500,
    message: err.message,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    ...(NODE_ENV === 'development' && { stack: err.stack }),
  });

  // Never expose error details in production
  const statusCode = err.status || 500;
  const response = {
    error: NODE_ENV === 'production'
      ? 'Internal Server Error'
      : err.message,
    requestId: req.id,
  };

  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`🔒 Secure server running on port ${PORT}`);
    console.log(`🌍 Environment: ${NODE_ENV}`);
    console.log(`⚙️  JWT Secret: ${JWT_SECRET.substring(0, 10)}...`);
  });
}

