PHASE 3: IMPLEMENT AUTHENTICATION (1-2 hours)
============================================================================

STEP 3.1: Create authentication middleware
```javascript
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET;

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};
```

STEP 3.2: Add login endpoint
```javascript
app.post('/login', express.json(), (req, res) => {
  const { username, password } = req.body;

  // TODO: Verify credentials with bcrypt against database
  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }

  const user = { id: 1, username, role: 'user' };
  const token = jwt.sign(user, JWT_SECRET, { expiresIn: '1h' });

  res.json({ token });
});
```

STEP 3.3: Protect endpoints with authentication
BEFORE:
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
});
```

AFTER:
```javascript
app.get('/users', authenticateToken, (req, res) => {
  res.json([...]);
});
```

STEP 3.4: Add role-based authorization
```javascript
const authorize = (requiredRoles = []) => {
  return (req, res, next) => {
    if (!requiredRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
};

// Usage:
app.get('/admin/stats', authenticateToken, authorize(['admin']), ...);
```

