const { query, body, validationResult } = require('express-validator');

const validateGetUsers = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .toInt(),
];
```

STEP 4.3: Apply validation to routes
```javascript
app.get('/users', authenticateToken, validateGetUsers, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Route handler
  res.json([...]);
});
```

STEP 4.4: Validate login credentials
```javascript
const validateLogin = [
  body('username')
    .trim()
    .isLength({ min: 3, max: 50 })
    .escape(),
  body('password')
    .isLength({ min: 6 })
    .notEmpty(),
];

app.post('/login', validateLogin, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Login logic
});
