const sanitizeUser = (user, currentUser) => {
  const sanitized = {
    id: user.id,
    name: user.name,
  };

  // Only return email if authorized
  if (currentUser && 
      (currentUser.id === user.id || currentUser.role === 'admin')) {
    sanitized.email = user.email;
  }

  return sanitized;
};
```

STEP 5.2: Apply sanitization to responses
