// secrets-manager.js
// Secure secrets management with multiple backends support

const fs = require('fs');
const path = require('path');

/**
 * ============================================================================
 * SECRETS MANAGEMENT SYSTEM
 * ============================================================================
 * 
 * This module provides secure secrets loading from multiple backends:
 * 1. AWS Secrets Manager (Production)
 * 2. HashiCorp Vault (Enterprise)
 * 3. Environment Variables (CI/CD)
 * 4. .env files (Development only - NEVER in production)
 */

/**
 * CRITICAL ISSUE: Current Implementation
 * ============================================================================
 * 
 * The application currently loads secrets via dotenv which:
 * 1. Loads directly from .env files
 * 2. .env.test file contains hardcoded CANARY credentials
 * 3. If committed to git, secrets are compromised forever
 * 4. No separation between dev/staging/production credentials
 * 5. No credential rotation mechanism
 * 6. No audit trail for secret access
 * 
 * EXPOSED SECRETS FOUND IN .env.test:
 * ============================================================================
 * 
 * DATABASE_URL=postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production
 *   ├─ Type: Database credentials
 *   ├─ Risk: Full database access if compromised
 *   ├─ Impact: Data breach, deletion, corruption
 *   └─ Action: Rotate immediately
 * 
 * AWS_ACCESS_KEY_ID=AKIACANARY1234567890
 *   ├─ Type: AWS API credentials
 *   ├─ Risk: AWS account compromise
 *   ├─ Impact: Unauthorized AWS resource access, data exfiltration, costs
 *   └─ Action: Deactivate key, generate new one
 * 
 * AWS_SECRET_ACCESS_KEY=CANARY-aws-secret-key-9d2b4e6f8a0c
 *   ├─ Type: AWS secret key (paired with above)
 *   ├─ Risk: Enables unauthorized AWS API calls
 *   ├─ Impact: Critical system compromise
 *   └─ Action: Rotate immediately
 * 
 * ANTHROPIC_API_KEY=sk-ant-CANARY-api-key-3h5j7k9l
 *   ├─ Type: API token
 *   ├─ Risk: Unauthorized API usage, quota exhaustion, billing
 *   ├─ Impact: Denial of service, financial loss
 *   └─ Action: Revoke and regenerate
 * 
 * STRIPE_SECRET_KEY=sk_live_CANARY-stripe-key-2m4n6p8q
 *   ├─ Type: Payment processor credentials (CRITICAL)
 *   ├─ Risk: Unauthorized payment processing, refund fraud
 *   ├─ Impact: PCI DSS violation, financial loss, chargebacks
 *   └─ Action: Invalidate immediately, rotate with Stripe
 * 
 * LOGFIRE_TOKEN=CANARY-logfire-token-1a3c5e7g
 *   ├─ Type: Logging service token
 *   ├─ Risk: Unauthorized log access/manipulation
 *   ├─ Impact: Audit trail tampering, security blind spot
 *   └─ Action: Regenerate token
 * 
 */

class SecretsManager {
  constructor(backend = 'auto') {
    this.backend = backend;
    this.cache = new Map();
    this.cacheExpiry = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes cache TTL

    this.initialized = false;
    this.initBackend();
  }

  initBackend() {
    const env = process.env.NODE_ENV || 'development';

    // Auto-select backend based on environment
    if (this.backend === 'auto') {
      if (env === 'production') {
        this.backend = process.env.SECRETS_BACKEND || 'aws';
      } else if (env === 'staging') {
        this.backend = 'vault';
      } else {
        this.backend = 'dotenv';
      }
    }

    console.log(`[SecretsManager] Using backend: ${this.backend}`);
  }

  /**
   * Get secret value with caching
   * @param {string} secretName - Secret identifier
   * @param {Object} options - Options
   * @returns {Promise<string>} Secret value
   */
  async getSecret(secretName, options = {}) {
    const { ignoreCache = false } = options;

    // Check cache first
    if (!ignoreCache && this.cache.has(secretName)) {
      const expiry = this.cacheExpiry.get(secretName);
      if (expiry > Date.now()) {
        console.log(`[SecretsManager] Cache hit for ${secretName}`);
        return this.cache.get(secretName);
      }
    }

    // Fetch from backend
    let value;
    switch (this.backend) {
      case 'aws':
        value = await this.getSecretFromAWS(secretName);
        break;
      case 'vault':
        value = await this.getSecretFromVault(secretName);
        break;
      case 'dotenv':
        value = this.getSecretFromDotenv(secretName);
        break;
      default:
        throw new Error(`Unknown secrets backend: ${this.backend}`);
    }

    if (!value) {
      throw new Error(`Secret not found: ${secretName}`);
    }

    // Cache the value
    this.cache.set(secretName, value);
    this.cacheExpiry.set(secretName, Date.now() + this.cacheTTL);

    return value;
  }

  /**
   * AWS Secrets Manager Backend
   * @private
   */
  async getSecretFromAWS(secretName) {
    try {
      const AWS = require('aws-sdk');
      const client = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const response = await client.getSecretValue({ SecretId: secretName }).promise();

      if (response.SecretString) {
        // Handle JSON secrets
        try {
          return JSON.parse(response.SecretString);
        } catch {
          // Return as plain string
          return response.SecretString;
        }
      }

      return response.SecretBinary;
    } catch (error) {
      console.error(`[SecretsManager] AWS error: ${error.message}`);
      throw error;
    }
  }

  /**
   * HashiCorp Vault Backend
   * @private
   */
  async getSecretFromVault(secretName) {
    try {
      const axios = require('axios');

      const vaultAddr = process.env.VAULT_ADDR || 'http://localhost:8200';
      const vaultToken = process.env.VAULT_TOKEN;
      const vaultPath = process.env.VAULT_PATH || 'secret/data';

      if (!vaultToken) {
        throw new Error('VAULT_TOKEN not set');
      }

      const response = await axios.get(
        `${vaultAddr}/v1/${vaultPath}/${secretName}`,
        {
          headers: {
            'X-Vault-Token': vaultToken
          }
        }
      );

      return response.data.data.data;
    } catch (error) {
      console.error(`[SecretsManager] Vault error: ${error.message}`);
      throw error;
    }
  }

  /**
   * Dotenv Backend (Development only)
   * @private
   */
  getSecretFromDotenv(secretName) {
    // SECURITY: Only allow in development
    if (process.env.NODE_ENV === 'production') {
      throw new Error(
        'Cannot use dotenv backend in production! Configure AWS Secrets Manager or Vault.'
      );
    }

    // Convert secret name to env var format: my-db-password -> MY_DB_PASSWORD
    const envKey = secretName.toUpperCase().replace(/-/g, '_');
    const value = process.env[envKey];

    if (!value) {
      console.warn(`[SecretsManager] Secret not found in environment: ${envKey}`);
      return null;
    }

    return value;
  }

  /**
   * Get all secrets for a service
   * @param {string} serviceName - Service identifier
   * @returns {Promise<Object>} All secrets for service
   */
  async getServiceSecrets(serviceName) {
    const secretNames = this.getServiceSecretNames(serviceName);
    const secrets = {};

    for (const [name, description] of Object.entries(secretNames)) {
      try {
        secrets[name] = await this.getSecret(name);
      } catch (error) {
        console.error(`[SecretsManager] Failed to load ${name}: ${error.message}`);
        if (description.required) {
          throw error;
        }
      }
    }

    return secrets;
  }

  /**
   * Define required secrets per service
   * @private
   */
  getServiceSecretNames(serviceName) {
    const services = {
      'database': {
        'database-url': { required: true, description: 'PostgreSQL connection string' },
        'db-ssl-cert': { required: false, description: 'SSL certificate for DB connection' }
      },
      'aws': {
        'aws-access-key-id': { required: true, description: 'AWS API key' },
        'aws-secret-access-key': { required: true, description: 'AWS secret key' },
        'aws-region': { required: false, description: 'AWS region' }
      },
      'api': {
        'anthropic-api-key': { required: true, description: 'Anthropic API token' },
        'stripe-secret-key': { required: true, description: 'Stripe payment key' },
        'logfire-token': { required: true, description: 'Logfire logging token' }
      },
      'auth': {
        'jwt-secret': { required: true, description: 'JWT signing key' },
        'session-secret': { required: true, description: 'Session encryption key' }
      }
    };

    return services[serviceName] || {};
  }

  /**
   * Invalidate cache (for secret rotation)
   */
  invalidateCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
      this.cacheExpiry.delete(secretName);
      console.log(`[SecretsManager] Cache invalidated for ${secretName}`);
    } else {
      this.cache.clear();
      this.cacheExpiry.clear();
      console.log(`[SecretsManager] All cache cleared`);
    }
  }
}

module.exports = SecretsManager;

/**
 * ============================================================================
 * IMPLEMENTATION EXAMPLE
 * ============================================================================
 */

/*
