/**
 * AWS Secrets Manager Integration
 * 
 * This file provides a complete example of integrating AWS Secrets Manager
 * with your Express.js application for secure credential management.
 */

const AWS = require('aws-sdk');

class AWSSecretsManagerClient {
  constructor(options = {}) {
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.client = new AWS.SecretsManager({ region: this.region });
    this.cache = new Map();
    this.cacheExpiry = new Map();
    this.cacheTTL = options.cacheTTL || 5 * 60 * 1000; // 5 minutes default
  }

  /**
   * Get a single secret by name
   * @param {string} secretName - Name/ARN of the secret
   * @param {Object} options - Additional options
   * @returns {Promise<string|Object>} Secret value
   */
  async getSecret(secretName, options = {}) {
    const { ignoreCache = false } = options;

    // Check cache first (if not ignored)
    if (!ignoreCache && this.isCached(secretName)) {
      console.log(`[AWS Secrets] Cache hit for ${secretName}`);
      return this.cache.get(secretName);
    }

    try {
      console.log(`[AWS Secrets] Fetching ${secretName} from AWS...`);
      const response = await this.client
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secretValue;
      if (response.SecretString) {
        try {
          // Try to parse as JSON
          secretValue = JSON.parse(response.SecretString);
        } catch {
          // Return as plain string
          secretValue = response.SecretString;
        }
      } else if (response.SecretBinary) {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

