   * @private
   */
  isCached(secretName) {
    if (!this.cache.has(secretName)) {
      return false;
    }

    const expiry = this.cacheExpiry.get(secretName);
    if (expiry < Date.now()) {
      this.cache.delete(secretName);
      this.cacheExpiry.delete(secretName);
      return false;
    }

    return true;
  }

  /**
   * Invalidate cache for a secret (useful after rotation)
   */
  invalidateCache(secretName) {
