```javascript
// secrets-manager.js
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let cachedSecrets = {};
const CACHE_DURATION = 3600000; // 1 hour

async function getSecrets() {
  // Return cached secrets if fresh
  if (cachedSecrets.timestamp && 
      Date.now() - cachedSecrets.timestamp < CACHE_DURATION) {
    return cachedSecrets.data;
  }

  try {
    const secretName = process.env.SECRET_ARN || 'prod/app/secrets';
    const response = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    const secrets = JSON.parse(response.SecretString);
    cachedSecrets = {
      data: secrets,
      timestamp: Date.now()
    };

    return secrets;
  } catch (error) {
    console.error('Failed to retrieve secrets:', error);
    throw new Error('Secrets retrieval failed');
  }
}

module.exports = { getSecrets };
```

