### **Step 3: Secure Secret Usage Patterns**

#### **3.1 Prevent Secrets in Logs**

```javascript
// logging-config.js
const winston = require('winston');

function redactSecrets(str) {
  const secretPatterns = [
    /password["\s:=]+([^\s"]+)/gi,
    /api[_-]?key["\s:=]+([^\s"]+)/gi,
    /token["\s:=]+([^\s"]+)/gi,
    /secret["\s:=]+([^\s"]+)/gi,
    /akias\w+/gi,
    /sk_live_\w+/gi,
    /sk-ant-\w+/gi,
  ];

  let redacted = str;
  secretPatterns.forEach(pattern => {
    redacted = redacted.replace(pattern, (match) => {
      return match.substring(0, 4) + '*'.repeat(Math.max(4, match.length - 8)) + 
             match.substring(match.length - 4);
    });
  });
  return redacted;
}

const logger = winston.createLogger({
  format: winston.format.printf(({ level, message, timestamp }) => {
    return `${timestamp} [${level}]: ${redactSecrets(JSON.stringify(message))}`;
  }),
  transports: [
    new winston.transports.File({ filename: 'app.log' })
  ]
});

module.exports = logger;
```

