### Using AWS Secrets Manager (Recommended):

```javascript
const express = require('express');
const helmet = require('helmet');
const AWS = require('aws-sdk');

// Initialize AWS Secrets Manager
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
});

// Cache for secrets (with TTL)
const secretsCache = new Map();
const CACHE_TTL = 3600000; // 1 hour

class SecretManager {
  async getSecret(secretName) {
    // Check cache
    if (secretsCache.has(secretName)) {
      const cached = secretsCache.get(secretName);
      if (Date.now() - cached.timestamp < CACHE_TTL) {
        return cached.value;
      }
    }

    try {
      const data = await secretsManager.getSecretValue({ 
        SecretId: secretName 
      }).promise();

      let secret;
      if ('SecretString' in data) {
        secret = JSON.parse(data.SecretString);
      } else {
        secret = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      secretsCache.set(secretName, {
        value: secret,
        timestamp: Date.now(),
      });

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret: ${secretName}`, error);
      throw error;
    }
  }

  // Clear cache on rotation
  invalidateCache(secretName) {
    secretsCache.delete(secretName);
  }

  // Clear all secrets from memory on logout/request complete
  clearSecret(secretName) {
    secretsCache.delete(secretName);
  }
}

const secretManager = new SecretManager();

// Initialize app
async function createApp() {
  const app = express();

  // Load secrets at startup
  let dbUrl, stripeKey, jwtSecret;

  try {
    const dbSecrets = await secretManager.getSecret('prod/database');
    dbUrl = dbSecrets.connection_string;

    const stripeSecrets = await secretManager.getSecret('prod/stripe');
    stripeKey = stripeSecrets.secret_key;

    const jwtSecrets = await secretManager.getSecret('prod/jwt');
    jwtSecret = jwtSecrets.secret;
  } catch (error) {
    console.error('Failed to load secrets on startup:', error);
    process.exit(1);
  }

  // Security middleware
  app.use(helmet());

  // Store in request-scoped manner (not global process.env)
  app.use((req, res, next) => {
    // Make available only to this request, not globally
    req.secrets = {
      jwtSecret,
      dbUrl,
      stripeKey,
    };
    next();
  });

  // Routes
  app.get('/health', (req, res) => {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  });

  app.get('/users', verifyToken, (req, res) => {
    // Use req.secrets instead of global process.env
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  });

  function verifyToken(req, res, next) {
    const token = req.headers['authorization']?.split(' ')[1];

    if (!token) {
      return res.status(401).json({ error: 'Access token required' });
    }

    try {
      // Use req.secrets.jwtSecret instead of process.env
      const decoded = jwt.verify(token, req.secrets.jwtSecret);
      req.user = decoded;
      next();
    } catch (error) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
  }

  // Error handler
  app.use((err, req, res, next) => {
    console.error(err);
    res.status(500).json({ error: 'Internal Server Error' });
  });

  return app;
}

// Start server
const PORT = process.env.PORT || 3000;
createApp().then(app => {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}).catch(error => {
  console.error('Failed to start server:', error);
  process.exit(1);
});

module.exports = createApp;
```

